// אינדקס חיפוש לחוברת ההכנה לשליחות (נוצר אוטומטית מהקובץ booklet-2022.pdf)
const BOOKLET = [{"p": 1, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 2, "t": "תוכן עניינים חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 3, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 4, "t": "א. ב. ג. ד. ה. ו. ז. ח. ט. י. יא. יב. א. ב. ג. ד. חברות באגודות מקצועיות בארץ (לדוגמא :אגודת ההנדסאים והטכנאים) ,הינה חלק 61 .. \"מענק יובל\" – עובד המדורג בדרוג חו\"ל ,אינו זכאי למענק יובל (דרוג חו\"ל אינו 61 ....."}, {"p": 4, "t": "השתתפות בשכ\"ל גן חובה ושכ\"ל בית ספר עד כיתה י\"ב כל הפרטים מופיעים בהוראת חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 5, "t": "זכויות ילדים מצטרפים לשליחות/נשארים בארץ ,פרוייקט גדנ\"ע/הכנה לצה\"ל /גיוס ,הגעת יג. יד. בן שליחי ם הוא מי שלפחות אחד מהוריו שעימו הוא שוהה בחו\"ל מייצג בחו\"ל גוף ישראלי כלשהוא ,ממשלתי, זכאות לילדים המצטרפים לשליחות לפני גיל גיוס בני שליחים ,שקיבלו אישור על פטור משירות ביטחון או דחיית שירות ,יכללו באסמכתת השליח ,עד לפני שמלאו להם גיל  19בלבד על כל המשתמע מכך (לדוג'  :לא"}, {"p": 5, "t": "יהיו זכאים להיכלל באסמכתא ולפיכך לא יהיו זכאים לחופשות ,השתתפות בעלות כרטיסי טיסה וכד') .לגבי ילדי שליחים ,שבמועד היציאה לשליחות יהיו מעל גיל  , 18חובה על השליח להציג ליחידה למשאבי אנוש ומנהל בחו\"ל את אישור צה\"ל על דחיית הגיוס או פטור משירות ביטחון ,במידה וניתן כזה .ללא אישורים אלה, טו."}, {"p": 5, "t": "טז. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 6, "t": "שילוב ימי עבודה במסגרת חופשה פרטית /מולדת/הבראה/מסובסדת – הזרמת אסמכתא: חופשת מיוחדת (מסובסדת/חופשת לונדון)  -הוראת שות\"ש  1.2.9.6ריכוז תנאים וסייגים 126 .. טבלה מרכזת של מימון כרטיס טיסה עבור שליח בחופשות מנוחה /חופשה פרטית/מולדת/הבראה/מיוחדת הודעת שות\"ש 1.2.9.8.1 -למעט שליחי צה\"ל חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 7, "t": "תרשים זרימה  -אישור שכ\"ד וחתימה על חוזה שכירות על ידי שליח( :בחוזה של דירת שרד חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 8, "t": "נישואי השליח :שליח שיצא לחו\"ל כרווק ונישא במהלך השליחות ,יעודכנו זכאויותיו בהתאם .על השליח לדווח בכתב על הנישואין למנהל כ\"א  /קצין המנהלה של הנציגות ולצרף להודעתו העתק מתעודת הנישואין .הנ\"ל יעביר דיווח כמקובל ליחידה למשאבי אנוש ומנהל בחו\"ל ,לצורך עדכון הרישומים במערכות הממוחשבות פרק מס'  – 19דמי ייצוג דמי ייצוג והחזר הוצאות אירוח (ראה נוהל דמי ייצוג פרק 179 ) 20"}, {"p": 8, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 9, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 10, "t": "הקדמה –מידע חשוב! שליח/ה יקר/ה, החוברת לשליח שלהלן נכתבה ונערכה במטרה להקנות הבנה וידע כלליים בנושא כללי העסקת שליחים בשירות המדינה ,לשם כך אוגדו עבורך דברי הסבר והנחיות עיקריים המפרטים את תנאי העסקתך בחו\"ל."}, {"p": 10, "t": "מודגש כי האמור בחוברת זו כפוף לדין ולשינויים כפי שיהיו מעת לעת ותוכנה אינו מחייב ואינו יוצר כל מצג שהוא כלפי השליח ו/או מי מטעמו. ההוראות המחייבות בעניין תנאי העסקתך הינן ההוראות שלהלן או כל הוראה המתייחסת לשליחות ,אשר יהיו בתוקף:"}, {"p": 10, "t": "• הוראות השות\"ש  -להלן לינק לאתר : https://www.gov.il/he/Departments/DynamicCollectors/hozrimtash?skip=0&limit=10 • הוראות תכ\"מ – להלן לינק לאתר : https://mof.gov.il/Takam • הוראות התקש\"יר  – -להלן לינק לאתר :"}, {"p": 10, "t": "https://archive.csc.gov.il/Takshir/Pages/default.aspx • דיני עבודה https://www.justice.gov.il/Units/MishpatIvri/MishpatIvriBapsika/Pages/Avoda.aspx • חוק שירות העבודה (גימלאות) -להלן לינק לאתר :"}, {"p": 10, "t": "https://www.nevo.co.il/law_html/law01/p221_001.htm מובהר כי ,בכל מקרה של סתירה בין מסמך זה לבין הוראות השות\"ש ,הוראות התכ\"מ, הנחיות נציב שירות המדינה ,דיני עבודה ,הם אלה שגוברים ולא האמור במסמך זה."}, {"p": 10, "t": "כמו-כן ,מודגש כי במקרה של סתירות בין גרסאות קודמות של השות\"ש ייגבר הנוסח המפורסם באותה עת. למען הסר ספק יובהר כי לא ניתן להסתמך על האמור בחוברת לשליח שלהלן כמקור ליצירת זכות כלשהי לשליח ."}, {"p": 10, "t": "התנאים המפורטים בחוברת נכתבו בלשון זכר מטעמי נוחות ,אך מיועדים לנשים וגברים כאחד. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 11, "t": "ברכת סמנכ\"ל וראש אמ\"ש שליחים יקרים, המעבר לחו\"ל והחיים במדינה אחרת פותח דלתות ,מרחיב אופקים ,מאתגר ומהווה מנוף אישי ומקצועי כאחד. מתוך הבנה ,שהצלחת השליח בתפקידו טמונה בנטרול \"רעשי הרקע\" הנובעים מהתאקלמות המשפחה במקום השירות ,שם לו המשרד למטרה ,לסייע ,לכוון ולהנגיש מידע ,תוך שימת דגש על מקצועיות ,יעילות ,רגישות וגמישות ,המתבקשים כשמדובר בטיפול במכלול"}, {"p": 11, "t": "המשפחתי כולו. הטיפול בשליח ומשפחתו מתחיל מרגע הבחירה לתפקיד ומסתיים לאחר החזרה לארץ בתום השליחות .המערך המטפל בשליח ,פועל בשיתוף פעולה מלא וכולל את צוות היחידה למשאבי אנוש ומנהל בחו\"ל ,ויחידות מקצועיות נוספות מאגפים שונים במשרד ובצה\"ל."}, {"p": 11, "t": "ברצוני לברך אתכם על המינוי לתפקיד ולאחל לכם דרך צלחה ושליחות מהנה ופורייה. בברכה, איתמר גרף סמנכ\"ל ור' אגף חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 12, "t": "ברכת ראש היחידה למשאבי אנוש ומנהל בחו\"ל שליח/ה יקר/ה ברכות על הצטרפותך למשפחת שליחי משרד הביטחון ואיחולי הצלחה בתפקיד. המשרד אליו נקלטת עוסק במשימות חשובות ואנשיו מתאפיינים בעשייה ערכית ,מחוייבות מקצועית ואישית גבוהה ,נתינה ומסירות למען השגת המטרות והיעדים של הארגון."}, {"p": 12, "t": "היציאה לשליחות בחו\"ל ,המעבר למדינה זרה ולתרבות שונה ,מצד אחד מהווה אתגר הן באופן אישי והן מבחינה מקצועית ,מאידך ,ההתמודדות עם קשיי הקליטה לשליח ,לבן/ת הזוג ,לילדים ולשילוב ביניהם לא קלה וזה טבעי."}, {"p": 12, "t": "היחידה למשאבי אנוש ומנהל בחו\"ל ,תלווה אותך ותטפל בך ובמשפחתך החל משלב הבחירה לתפקיד עד החזרה ארצה בתום השליחות. מניסיוננו ,הכנת השליח ובני המשפחה ,טרם היציאה לשליחות ,תסייע לקליטה ולהשתלבות באופן אפקטיבי במקום השירות .מלבד ההכנה התיאורטית ,הן מעיון בהוראות השות\"ש ובחוברת לשליח ,הן בתדרוך הפרטני והן בקורס שליחים ,אני ממליצה לנצל את הזמן שיש לכם עד ליציאה לשליחות ,לתמיכה ,לעשייה משותפת ,להתארגנות ,לריבוי אהבה וליצירת"}, {"p": 12, "t": "בסיס וביטחון אשר יסייעו לך כשליח ולכל המשפחה בפרט ,בהתמודדות עם קשיי התאקלמות ואי וודאות ואנו כמובן נשמח להיות לך לעזר בכל עת. כדי לסייע לך בהשתלבותך בשליחות מובא בפניך מידע חשוב המרוכז בחוברת לשליח אשר נועד להציג לך ולבני משפחתך ,על \"קצה המזלג\" את תנאי השירות והשכר במסגרת תפקידך כשליח המשרד."}, {"p": 12, "t": "תשומת ליבך כי המידע המפורט בחוברת מהווה את עיקרי התנאים בלבד ועל מנת להכיר את זכויותיך וחובותיך עליך לעיין בחוזרי שות\"ש ( -שכר ותנאי שירות בחוץ לארץ) המאוגדים באתר משרד האוצר – אגף השכר והסכמי עבודה – יישומים מקוונים – מערכת שכר ותנאי שירות בחוץ לארץ וכן הוראות התקש\"יר (תקנון שירות המדינה) באתר נציבות שרות המדינה."}, {"p": 12, "t": "נשמח לעמוד לרשותך בכל שאלה. בברכת הצלחה, קמי אוקונסקי ראש היחידה למשאבי אנוש ומינהל בחו\"ל חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 13, "t": "חוזרי שות\"ש –היכן מפורסמים? כיצד ניתן לאתרם? במסך חיפוש – גוגל – רושמים \"חוזרי שות\"ש\" נכנסים לחוזרי שות\"ש חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 14, "t": "בוחרים את הפרק הרצוי – נפתח סרגל עם הפרקים המופיעים בחוזרים בוחרים את ההוראה הרצויה חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 15, "t": "פרק  – 1מבוא כללי חוברת זו מיועדת לשליחים ,היוצאים לחו\"ל בתפקיד ,לתקופה העולה על  6חודשים. התנאים המפורטים בחוברת נכתבו בלשון זכר מטעמי נוחות ,אך מיועדת לנשים וגברים כאחד .ניתן למצוא עותק של החוברת בפורטל \"רימון\" ברשת הניהולית:"}, {"p": 15, "t": "דף הבית פורטל רימון > משאבי אנוש > משלחות בחו\"ל > חוברת לשליח היחידה למשאבי אנוש ומנהל בחו\"ל במשהב\"ט ,קובעת את הזכאויות ותנאי השירות של שליחי המערכת בחו\"ל ,על בסיס הוראות נציבות שירות המדינה ,המפורטות בקובץ התקשי\"ר והוראות הועדה הבין-משרדית לשכר ותנאי שירות בחו\"ל ,המפורטות בקובץ הוראות הנקרא :שות\"ש (\"שכר ותנאי שירות\")  ,המפורסם באתר משרד האוצר באינטרנט."}, {"p": 15, "t": "בנוסף ,קיימת הוראה משרד המ\"ב  ,64.14המפרטת הנחיות ייחודיות. בכל מקום במסמך זה ,שבו מצוין המונח\" :מנהל כ\"א  /קצ\"מ הנציגות/הנספחות \" ,הכוונה היא לגורם המטפל במנהלות השליחים והעובדים  -בנספחויות הקטנות ,יהא זה הנספח עצמו או עובד האית\"ן האחראי על הניהול הכספי של הנספחות."}, {"p": 15, "t": "הוראות השות\"ש: להלן קישור להוראות השות\"ש  0.0.0.1פרק ראשי -מבוא: https://www.gov.il/he/Departments/DynamicCollectors/hozrimtash?skip=0&limit=10&item_na me=%D7%9E%D7%91%D7%95%D7%90 .1הוראות השות\"ש (שכר ותנאי שירות) כוללות הנחיות לביצוע ,מקצועיות ועדכניות המחייבות את משרדי הממשלה ויחידות הסמך."}, {"p": 15, "t": ".2מקור ההוראות הינו בהחלטות הוועדה הבין משרדית לשכר ותנאי שירות בחו\"ל. .3הוועדה קובעת את השכר ותנאי השירות של כל סוגי המשרתים בחוץ לארץ מטעם מדינת ישראל. .4הוראות והחלטות הוועדה כפי שהן מתפרסמות מעת לעת והוראות השות\"ש יחד הן חלק בלתי נפרד מתנאי השירות בחוץ לארץ."}, {"p": 15, "t": ".5בראש הוועדה הבין משרדית עומד הממונה על השכר והסכמי עבודה במשרד האוצר. .6הוועדה מורכבת מנציגי אגפים ומשרדים הבאים :אגף שכר והסכמי עבודה .נציג זה משמש גם כמרכז הוועדה ,.אגף חשב כללי ,נציבות שירות המדינה[ אגף תקציבים ,משרד החוץ ,משרד הביטחון  ,משרד ראה\"מ ת\"א ,משרדים נוספים להם נציגים בחו\"ל."}, {"p": 15, "t": ".7במקרה של סתירות בין גרסאות קודמות של השות\"ש יקבע הנוסח הזה המעודכן. .8ההוראות כתובות בלשון זכר ,אך מיועדות לשני המינים. .9לשם פישוט הניסוח הוראות השות\"ש מנוסחות בלשון \"שליח ובן זוגו\"."}, {"p": 15, "t": "למען הסר ספק ,השליח מתבקש לעיין בסעיפים הרלוונטיים בתקשי\"ר ובאתר השות\"ש ולהתעמק בהוראות ובזכאויות. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 16, "t": "פרק  - 2לפני הכל קצת פסיכולוגיה פסיכולוגיה בואו נדבר על זה חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 17, "t": "כללי פרידה מבית וסביבת חיים ומעבר לארץ אחרת ,מלווה בתהליכים נפשיים מורכבים. הצורך להתמודד עם שינויים ,מחייב גיוס משאבים תוך אישיים ובין אישיים ,היכולת להתבסס על הכוחות הפנימיים ובמקביל המוכנות הרגשית להיעזר באחרים."}, {"p": 17, "t": "חוויית השליחות והשלכות משפחתיות היציאה לשליחות בחו\"ל הינה שינוי מהותי בחיים ,כמו כל שינוי בחיים ,היא עשויה להיחוות כתהליך של התפתחות וצמיחה או לחילופין ,כמשבר. מה שיקבע את האופן בו השינוי יחווה ,היא היכולת של כל בני המשפחה להתמודד עם הקשיים שהשינוי הזה מזמן .יכולת זו מושפעת מההיכרות של האדם עם המשאבים הפנימיים והחיצוניים שעומדים לרשותו."}, {"p": 17, "t": "יש חשיבות רבה להתבוננות פנימה להבנת המשמעות של השינוי ולזיהוי החששות שצצות, אך גם לאתר דפוסי חשיבה ,שאינם בהכרח תואמים את המציאות ,כמו המחשבה שכל הילדים יסתגלו במהירות וכד'."}, {"p": 17, "t": "המעבר למדינה אחרת טומן בתוכו אתגרים והתמודדויות לא פשוטות לשליח עצמו ,שנמצא בלחץ עקב הצורך להשתלב היטב ומהר במקום עבודה חדש ,עם שפה זרה ובתרבות אחרת. בנוסף ,קיימת הדאגה לשאר בני המשפחה ולהסתגלותם."}, {"p": 17, "t": "הכנת המשפחה לשליחות: לעשות מחקר מקדים על מדינת היעד ,מקום השירות –מחקר טוב יקל על הכרת המדינה והתרבות וינמיך את ה\"הלם\" הראשוני בהגעה לשליחות. לקבל החלטה איפה אנחנו רוצים לחיות ,עיר ,שכונה  -ישנם איזורים מוכרים יותר לישראלים איזורים עם קהילה יהודית ,קהילה ישראלית או איזור אחר שבו אנו רוצים לחוות את תרבות המקום ולהיטמע בקהילה המקומית."}, {"p": 17, "t": "ללמוד את הסביבה בה אנו מעוניינים לגור – להכיר את הסביבה טרם ההגעה ,לצלם את האיזור לשוחח עם מקומיים ,לשוחח עם שליחים אותם הינכם מחליפים ,שליחים קודמים שהיו ועוד. דברו עם משפחות שנמצאות שם כיום  -שעוברות את החוויה \" .דברים שרואים מכאן לא רואים משם\"."}, {"p": 17, "t": "לבנות תוכנית עם נתונים ועם לוח זמנים – לימים הראשונים ולחודשים הראשונים ,לא להעמיס על התוכנית כדי לא להיות לחוצים בהמשך אם לא תעמדו בה .חשוב ,לכתוב את התוכנית עם לו\"ז שעלול להשתנות כדי לא להתאכזב שלא עמדנו בתוכנית."}, {"p": 17, "t": "להנמיך ציפיות – על מנת שלא יהיו פערים בין הציפיות שלנו למה שיקרה בפועל. מפה  -ליצור מפה של העיר ,השכונה ,ביה\"ס עם נק' חשובות כגון :סופר ,בנק ,סניף דואר ,בי\"ס וכד'."}, {"p": 17, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 18, "t": ".7מזג האויר במקום השירות – להיערך למזג האוויר במקום השירות ,ביגוד מתאים ,ציוד נדרש (אין צורך לרכוש את כל הביגוד והציוד בישראל ,אפשר להצטייד בביגוד ראשוני ובהמשך לרכוש את היתר במקום השירות ,לרוב זה גם הרבה יותר זול."}, {"p": 18, "t": ".8אם יש קרוב משפחה שיכול להצטרף לנסיעה לשליחות (סבא/תא ,דוד/ה – לתמיכה ולהרגשה טובה יותר הן של השליח והן של המשפחה. חווית השליח לפרידה מבית וסביבת חיים ומעבר לארץ אחרת ,מלווה בתהליכים נפשיים מורכבים."}, {"p": 18, "t": "הצורך להתמודד עם שינויים ,מחייב גיוס משאבים תוך אישיים ובין אישיים ,היכולת להתבסס על הכוחות הפנימיים ובמקביל המוכנות הרגשית להיעזר באחרים. היכולת להתמודד עם השינוי כרוכה באומץ נפשי ,באמון שלנו בעצמנו  ,להאמין שאפשר להצליח לשדר לסביבה ביטחון."}, {"p": 18, "t": "חווית בן/ת הזוג הנלווה לשליח בן/ת הזוג הנלווה לשליחות ,חווה קשיים אחרים ,הקשורים בוויתור אישי ומקצועי ,ריחוק ממקורות התמיכה (המשפחה והחברים) והצורך להתמודד ,לרוב לבד ,עם קשיי היומיום בתקופת ההסתגלות וההתאקלמות במקום החדש .קושי בהתנהלות יומיומית בשפה זרה ולזה מתווסף כמובן ,קשיי ההסתגלות שכל המשפחה חווה (כולם ביחד וכל אחד לחוד) דבר המשליך גם על הזוגיות."}, {"p": 18, "t": "השינוי יכול להביא לקירבה רבה יותר בין בני הזוג ולשיפור היחסים .לחילופין ,עלול השינוי לגרום לריחוק בין בני הזוג ולהידרדרות בקשר. להלן מס' טיפים שיסייעו בהסתגלות והתאקלמות במקום השירות:"}, {"p": 18, "t": ".1מטרות – להציב מטרות אישיות שאני רוצה להשיג לעצמי; לימודים ,הכשרה מקצועית, עבודה ,מקצוע חדש ,טיולים ,תחביבים. Networking .2עם המקומיים מייד עם ההגעה לשליחות –ליצור מפגשים חברתיים לצאת מהבית לא להסתגר ,להסתובב באיזור המגורים ,להכיר ולהתייעץ עם המקומיים  ,היכן קונים מצרכים ,מה עושים הילדים וכד'."}, {"p": 18, "t": ".3מרכזים קהילתיים – להכיר את המרכזים הקהילתיים או ארגונים מהם אפשר ללמוד/להתנדב ,לתת משמעות לזמן בשליחות. לנסות להצטרף לקבוצות שונות וירטואליות או פיזית כמו  , JCCלבקר בבתי כנסת בחגים ."}, {"p": 18, "t": ".4תחב\"צ/נסיעות – להשתמש ולהכיר את התחב\"צ ,את דרכי הגישה לאיזור המגורים ברכב פרטי/תחב\"צ ,להכיר את חוקי הנסיעה ,תרבות הנהיגה. .5להתפנק – לפרגן לעצמך עם דברים שאוהבים ,להרגשה טובה ולא רק סביב הילדים/המשפחה."}, {"p": 18, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 19, "t": "שליחות עם ילדים – איך עושים את זה? .1הכנה את הזמן שיש לכם עד ליציאה לשליחות תנצלו ליצירת בסיס ביטחון לילד/ים ,בתמיכה , עשייה משותפת ,ולא רק בהשקעה ללמידת השפה האנגלית או כל שפה אחרת לפני ההגעה ,יש לקחת בחשבון שהוספת משתנה נוסף כמו למידת שפה יכול להלחיץ זכרו שאין דומה לימוד כזה ללימוד אמיתי בשטח שבשלב כלשהו קורה באופן טבעי .אפשר לחשוף קצת את הילדים לשפה אבל לא מתוך לחץ או הכרח -אם החלטתם לעשות זאת-"}, {"p": 19, "t": "נסו להכניס כיף ,שמחה והנאה מכך. .2האם וכמה לדבר על השליחות מראש ? אנו מאמינים בשיתוף מלא בהתאמה לרמה ולגיל הילד ,החל ממועד ההודעה על השליחות וכמובן בהמשך בהתממשות ההחלטה .מוצע לשתף ולהמחיש באמצעות תמונות ,סירטונים של מקום השירות ,צילום מבנה ביה\"ס  ,חוגי ספורט או חוגים שאוהבים ,היו קשובים לילדים ,לשאלות שלהם ,לא לתת מידע רב שלא ילחיץ אותם נסו למצוא את האיזון המתאים לכל אחד."}, {"p": 19, "t": ".3הכינו רשימות של מה חייב לעשות ,איספו רשמים מחברים ושליחים שהיו במקום השירות למה כדאי לעשות בימים הראשונים כדי להפוך את הזמן למשמעותי למשפחה שלכם. .4האמון שהילד יכול ויצליח להתמודד הוא נקודת מוצא שמוסיפה המון כח והופכת את הקושי למקפצה ולא למכשול .ההסתכלות על הקושי כטבעי  ,כחולף ,כהתמודדות חיובית ועל הילד כבעל כוחות ויכולות גדולים ,מגבירה את האמון של הילד בעצמו"}, {"p": 19, "t": "ומפחיתה את משך ההתמודדות ואת חוזקה. .5אל תדאגו! כשההורים שלמים עם ההחלטה שלהם ,עם הערכים שהם מאמינים בהם ועם הדעה שזה טוב לילדים ולמשפחה -זו תהיה נבואה שמגשימה את עצמה! סיכום בתהליך ההכנה לשליחות יש חשיבות גדולה לקיום הכנה טובה להורים ולילדים ,שתפחית חרדה והתמודדות בלתי יעילה ,תעזור בפיתוח אסטרטגיות התמודדות מיטביות ותביא לשיפור התפקוד האישי והמשפחתי לקראת המעבר ,במהלך השליחות ולקראת החזרה ארץ."}, {"p": 19, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 20, "t": "הכנה לשליחות תדרוך , אוריינטציה חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 21, "t": "פרק  - 3הכנה לשליחות  -כללי הוראה .1.1.11.1.מינוי והכנה לשליחות הוראה .1.1.11.2.הכנה והדרכה לפני שירות מבוא במסגרת מינוי שליחים למשרות בחוץ-לארץ מתבצעות הכנות עבור השליח ובני משפחתו הנלווים אליו עליהן אחראי המשרד."}, {"p": 21, "t": "תדרוך עובדי משהב\"ט ונספחי הגנה – יבוצע ע\"י המטה  -היחידה למשא\"נ ומינהל בחו\"ל. תדרוך שליחי זרועות ושליחים לומדים – יבוצע ע\"י קצין נסיעות זרועי להלן עיקרי הנושאים אשר יידונו במסגרת התדרוך וההכנה."}, {"p": 21, "t": "תקופת השליחות: תקופת ההעסקה המרבית של שליח (למעט לומדים) תהיה  4שנים והיא ניתנת להארכה בשנה אחת נוספת בכל פעם ,אך לא יותר מ  6שנים בסך הכל ,בהתאם למפורט להלן: .1הארכת תקופת שירות כללי:"}, {"p": 21, "t": "א .המנהל הכללי של המשרד יהיה רשאי להאריך את תקופת השירות של השליחים בחוץ-לארץ עד שנה נוספת ,לפי שיקול דעתו על בסיס אמות המידה הבאות: )1סיום לימודים של ילדי השליח )2מחלה או טיפול רפואי של השליח או בני משפחתו."}, {"p": 21, "t": ")3הארכת שירות שלא עפ\"י המפורט בסעיף  1ו 2-או הארכת שירות מעבר ל 5 -שנים טעונה אישור נציב שירות המדינה. .2תקופת השירות לשליח משהב\"ט תקופת השירות לשליח משהב\"ט הינה בדרך כלל  3שנים  +שנת אופציה (עד  4שנים) עפ\"י החלטת הנהלת המשרד  -העסקה המרבית של שליח תהיה  4שנים המנהל הכללי של המשרד יהיה רשאי להאריך את תקופת השירות של השליחים בחוץ-לארץ עד שנה נוספת  ,לפי שיקול דעתו  -הארכת שירות מעבר ל 5-שנים ,טעונה אישור נציב שירות"}, {"p": 21, "t": "המדינה אך ,סה\"כ תקופת השליחות לא תהא יותר מ  6שנים בסך הכל. .3תקופת השירות לנספח/שליח צה\"ל תקופת השירות לשליח צה\"ל הינה בדרך כלל שנתיים  +שנת אופציה (למעט שליח לומד אשר תקופת השירות הינה שנה או בהתאם לתקופת הלימודים) הארכת התקופה מעבר ל 3 -שנים ועד 5 -שנים טעונה אישור מינוי בצה\"ל וכן אישור הנהלת משהב\"ט הכל בהתאם לנסיבות המפורטות בסעיף  1לעיל ."}, {"p": 21, "t": "הארכת שירות מעבר ל 5-שנים ,טעונה אישור נציב שירות המדינה אך ,סה\"כ תקופת שליחות לא תהא יותר מ  6שנים בסך הכל. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 22, "t": "אסמכתא ליציאה לשליחות ולתקופת השליחות .1מהי אסמכתא לשליחות בחו\"ל ? א .ה\"אסמכתא\" היא האישור הפורמאלי של הדרגים המורשים ,ליציאת השליח לשליחות בה מפורטים הנתונים האישיים של השליח ובני משפחתו היוצאים עמו, התפקיד המיועד ,מועדי השליחות ,הכתובת התקציבית עליה יחולו הוצאות עמו, כספיות הקשורות לשליחות וכו'."}, {"p": 22, "t": "ב .האסמכתא מהווה בסיס לקביעת זכאויות השליח לתנאי שרות בחו\"ל לרבות תקופת שכירת הדירה במקום השירות – השליח יתאים את תקופת השכירות לתקופת האסמכתא לתפקיד ללא תקופת האופציה להארכה."}, {"p": 22, "t": "ג .האסמכתא תקיפה רק לאחר שנחתמה על ידי כל סבב הגורמים המוסמכים. .2תקופה ותוקף האסמכתא: א .תקופת האסמכתא תכלול את תקופת החפיפה וההתארגנות של השליח טרם המינוי לתפקיד ועד למועד סיום התפקיד."}, {"p": 22, "t": "ב .אסמכתא לשליח עובד משהב\"ט, האסמכתא נחתמת לתקופה של שלוש שנים ראשונות ברציפות בתום התקופה, בהתאם להחלטת מנכ\"ל המשרד ,מוארכת האסמכתא לשנה נוספת – שנה רביעית .כל הארכה נוספת תגובה באסמכתא בהתאם לאישור הגורמים המוסמכים להארכת השליחות."}, {"p": 22, "t": "ג .אסמכתא לשליח צה\"ל -נספח הגנה/נספח  /שליח זרועי, האסמכתא נחתמת לתקופה של שנתיים ברציפות בתום התקופה ,בהתאם להחלטת הגורמים המוסמכים בצה\"ל ,מוארכת האסמכתא לשנה נוספת – שנה שלישית .כל הארכה נוספת תגובה באסמכתא בהתאם לאישור הגורמים המוסמכים להארכת השליחות."}, {"p": 22, "t": ".3תקופת חפיפה: א .תקופת החפיפה מיועדת לחפיפה מקצועית ולהתארגנות אישית :הכרת סביבת המגורים ,מקום העבודה ,מוסדות חינוך של הילדים ,שכירת דירה ,פתיחת חשבון בנק וכו'."}, {"p": 22, "t": "ב .תקופת החפיפה של שליח יוצא נקבעת בהתאם לתקופות השליחות כדלהלן: )1עובד משהב\"ט – תקופת החפיפה באסמכתא תחל חודש ימים טרם הכניסה לתפקיד .לדוג' :שליח אשר השיבוץ לתפקיד יחל ב 1 -באוגוסט, תקופת האסמכתא תחל לכל המוקדם ב 1 -ביולי לתקופת חפיפה והתארגנות."}, {"p": 22, "t": ")2נספח הגנה – לראש נספחות תקופת החפיפה באסמכתא תחל לכל המוקדם עד שבועיים טרם הכניסה לתפקיד (מקרים חריגים לחפיפה ארוכה יותר חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 23, "t": "תטופל פרטנית ותאושר ע\"י קש\"ח וע\"י מטה משהב\"ט)  .לדוג' שליח אשר השיבוץ לתפקיד יחל ב 1 -באוגוסט ,תקופת האסמכתא תחל לכל המוקדם ב 15 -ביולי. )3שליח צה\"ל זרועי  -תקופת החפיפה משתנה משליח לשליח ומתפקיד לתפקיד ,בהתאם להחלטת הזרוע המשגרת ולכל המוקדם שבועיים טרם הכניסה לתפקיד."}, {"p": 23, "t": ")4שליח צה\"ל לומד/עמית מחקר – אין חפיפה אלא תקופת התארגנות לשליח לומד תחל  5ימים קלנדריים לפני תחילת הלימודים ו 5-ימים קלנדריים לאחר סיום הלימודים . ג .בתקופת החפיפה כאמור ,מוכפלת המשרה של השליח במקום השירות ,לצורך שיבוץ השליח הנכנס והשליח החוזר במשרה במשרד (במערכת הסאפ ) במקביל."}, {"p": 23, "t": "הכפלת המשרה מתבצעת באמצעות יח' התקינה במשרד לאחר פניית יח' משא\"נ ומינהל בחו\"ל אליהם. .4הגורמים המוסמכים להזרמת האסמכתא ולאישורה: א .לשליח משהב\"ט ולנספח הגנה -האסמכתא תוזרם ותעבור לסבב חתימות ע\"י יח' משא\"נ ומינהל בחו\"ל ותאושר על ידי מנכ\"ל משהב\"ט."}, {"p": 23, "t": "ב .לשליח צה\"ל זרועי/לומד ,האסמכתא תוזרם ותעבור לסבב חתימות ע\"י קצין נסיעות זרועי  -האסמכתא תאושר ע\"י הגורם המוסמך בצה\"ל וע\"י מנכ\"ל משהב\"ט. .5אישור אגף ביטחון על האסמכתא - כל שליח היוצא לשליחות בחו\"ל נדרש להכשר ביטחוני מתאים ולקבלת תדריך ביטחוני (במסגרת קורס השליחים או באופן פרטני הכל בהתאם להחלטת מלמ\"ב, היחידה לאבטחת מידע  .מובהר כי ,רק לאחר התדרוך וחתימת נציג אבטחת מידע ע\"ג"}, {"p": 23, "t": "האסמכתא ניתן יהיה לקבל את כרטיסי הטיסה באמצעות יח' נסיעות חו\"ל. לשליחים עובדי משהב\"ט ונספחי הגנה – התדרוך יתבצע ע\"י מלמ\"ב היח' לאבטחת מידע. לשליחי צה\"ל זרועיים לרבות שליחים לומדים התדרוך יתבצע ע\"י קב\"ט זרועי בהנחיית מלמ\"ב הנפקת דרכונים /ויזות יציאה לשליחות מודגש כי תנאי לקבלת כרטיסי הטיסה ליציאה לשליחות והדרכונים ,הינו אישור כל בעלי התפקידים המוסמכים לחתום ע\"ג האסמכתא לרבות חתימת מנכ\"ל משהב\"ט."}, {"p": 23, "t": "הנ\"ל נכון לגבי שליחי משהב\"ט/נספחים ושליחי צה\"ל כאחד. .1תחום הסדרי נסיעות חו\"ל  -הגורם המטפל במשרד: הנפקת דרכונים רשמיים ביומטריים (המונפקים ע\"י משרד החוץ  -בהתאם לתפקיד חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 24, "t": "הרלוונטי ועל פי נהלי משרד החוץ) והסדרת אשרות כניסה (ויזות) למדינות שיש צורך להנפיק עבורן אשרת כניסה מטופלים ע\"י תחום הסדרי נסיעות חו\"ל באכ\"ס .בנוסף, מטפלת היחידה בהסדרת דרכונים."}, {"p": 24, "t": ".2לו\"ז נדרש לפניה להנפקת הדרכונים ואשרות כניסה באחריות השליח: בשל הלו\"ז הנדרש לטיפול בתהליכים הנ\"ל על השליח לתאם פגישה אישית עם ר' תחום הסדרי נסיעות חו\"ל ,במידת האפשר לפחות שלושה חודשים לפני היציאה לשליחות .בפגישה יימסרו פרטים ספציפיים לגבי המסמכים /התהליכים הנדרשים."}, {"p": 24, "t": ".3סוגי דרכונים: א .דרכון לאומי דרכון לאומי של מדינת ישראל ,מונפק ע\"י משרד הפנים. על השליח לוודא כי לו ולבני משפחתו דרכונים לאומיים בתוקף לאורך כל תקופת השליחות וזאת ללא קשר לסוג הדרכון הרשמי ,שיונפק לו ע\"י המשרד לקראת יציאתו לשליחות במידה והתפקיד מחייב זאת המשרד ממליץ לשליח לדאוג כי בעת סיום השליחות ,יהיו כל הדרכונים הלאומיים שלו ושל בני משפחתו בתוקף לפחות לחצי שנה ממועד החזרה"}, {"p": 24, "t": "מהשליחות .האמור לעיל הינו באחריות השליח ועל חשבונו. ב .דרכון רשמי (דרכון דיפלומטי או דרכון שירות) דרכון רשמי ביומטרי ,המונפק על ידי משרד החוץ ,בהתאם לתאריכי האסמכתא והתפקיד בחו\"ל .דרכון רשמי יונפק לשליח ולבני משפחתו היוצאים אתו לשליחות ומופיעים באסמכתא."}, {"p": 24, "t": "ג .במקרה של אובדן דרכון (לאומי או רשמי) יש לפנות לקונסוליה הישראלית המקומית לקבלת הנחיות. .4החזרת דרכונים רשמיים בתום שליחות שליח אשר סיים שליחות ו/או בן משפחה ששב ארצה לפני מועד סיום התפקיד של השליח מחויב להחזיר לאכ\"ס  /ר' תחום הסדרי נסיעות חו\"ל ,את הדרכונים הרשמיים (דיפלומטיים או שירות) לצורך טיפול בביטולם האמור יבוצע ע\"י השליח לא יאוחר מ 30-יום ממועד חזרתו ארצה (ראה"}, {"p": 24, "t": "פרטים נוספים בחוברת לשליח החוזר). כרטיסי טיסה – יציאה לשליחות .1תחום הסדרי נסיעות חו\"ל באכ\"ס ,מטפל עבור השליח ובני משפחתו בהזמנת ורכישת כרטיסי טיסה להגעה לשליחות."}, {"p": 24, "t": ".2מסלול הטיסה למקום השירות נקבע על פי קריטריונים קבועים ונהלי עבודה. תאריכי הטיסה נקבעים על פי המועדים שבאסמכתא החתומה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 25, "t": ".3בכל מקרה בו השליח יבקש לעשות שינוי בתאריכי השליחות או בהרכב בני המשפחה היוצאים עימו לשליחות ,יהיה עליו לפנות ליח' למשאבי אנוש ומנהל בחו\"ל  /לקצין הנסיעות הזרועי ולקבל אישור לשינוי לפחות חודש מראש לפני מועד הנסיעה המתוכנן .השינוי יכנס לתוקף רק כאשר ייחתם עדכון לאסמכתא ע\"י כל סבב החותמים."}, {"p": 25, "t": ".4כרטיסי טיסה לשליחות ארוכה ניתנים בדרך כלל לכיוון אחד. .5כרטיסי טיסה זכאות למושב – יציאה לשליחות במהלך השליחות ובתום השליחות. א .מושב לתינוקות בטיסות ארוכות בטיסות טרנס אטלנטיות (לארה\"ב ,דרום-אמריקה ,למזרח הרחוק או יעדים אחרים רחוקים במיוחד) ,מאשר המשרד מושב בטיסה לתינוקות מגיל תשעה חודשים ומעלה (בטיסות קצרות ,מוקצה מושב לילד מגיל שנתיים ושעבורו המערכת משלמת כרטיס טיסה מלא)."}, {"p": 25, "t": "ב .נסיעות לשדה התעופה וממנו – החזר כספי .1ביציאה לשליחות  -המשרד מחזיר לשליח תמורת קבלות המעידות על ביצוע התשלום. .2את הקבלות יעביר השליח לקצ\"מ הנציגות  /לחשב האיזורי מייד עם הגעתו לשליחות בצירוף טופס הצהרה ג .החזר בגין ההוצאות ישולם במשכורת השליח יש לוודא ככל שניתן העברת הקבלות המקוריות בצירוף טופס הצהרה על ההוצאות המתייחסות לזכאויות שלהלן:"}, {"p": 25, "t": ".1עלות הנסיעה במונית או בתחבורה ציבורית מהבית או המלון בארץ לשדה התעופה. .2עלות הנסיעה משדה התעופה בחו\"ל למלון או לדירת הקבע החדשה. בדיקות רפואיות  -אישור רופא משפחה לפני היציאה לשליחות בהתאם להוראת השות\"ש  1.2.3.1שליח ובני משפחתו הנלווים אליו מחויבים לעבור בדיקה רפואית ולהמציא למשרד מסמך רפואי המעיד על מצבם בריאות עדכני לפני צאתם לשליחות .במקרה והתגלתה בעיה רפואית (של השליח ו/או של בני משפחתו הזכאים"}, {"p": 25, "t": "לצאת עימו לרבות קורה סמוך אם אושר) ,העשויה להשית על המדינה הוצאות משמעותיות ,תיבחן שליחותו של השליח בוועדה פנים משרדית שתשקול את יציאת המשפחה לשליחות. בהתאם לאמור ,כדי לוודא ,שמצב בריאותם של השליח ובני משפחתו הנלווים אליו מאפשר יציאתם לארץ השירות ,ועל מנת לאשר צירופם להסדר מתן שירותי רפואה במקום השירות, כמפורט בחוק ביטוח בריאות ממלכתי ,התשנ\"ד ,1994-עליהם לעבור בדיקות רפואיות (ע\"פ"}, {"p": 25, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 26, "t": "ההפניה של המשרד) או להביא אישור מרופא המשפחה ורופא הילדים לכל אחד מבני המשפחה המצטרפים. בדיקות אלה הכרחיות ,בהיותן תנאי להמשך ההכנות ליציאה .לפיכך יש לעשותן מוקדם ככל האפשר."}, {"p": 26, "t": "במקרים בהם קיימת בעיה רפואית של השליח ו/או בני המשפחה הנלווים על השליח יהיה להתייעץ עם רופא האמון של המשרד. המלצות בתחום הרפואי לפני היציאה לשליחות .1מומלץ לוודא ולרשום את סוג הדם של כל אחד מבני המשפחה."}, {"p": 26, "t": ".2יש לקחת לחו\"ל את כל הרישומים הרפואיים ,במיוחד רישומי חיסונים. .3אם מדובר במכתבי/המלצות רופאים ,רצוי לתרגמם. .4תרגום פנקסי חיסונים לילדים בבתי הספר בלבד ,ייעשה אם הדבר נדרש במסגרת תהליך הרישום לבית הספר."}, {"p": 26, "t": ".5מומלץ לדאוג לעותקים מצילומי רנטגן ,צילומי שיניים וכד' הנמצאים בתיק הרפואי. .6מומלץ להכין עותק ממרשם למשקפי ראייה. .7יש לוודא (במידת האפשר) כיצד נקראות בארץ השליחות התרופות המקבילות לתרופות שהשליח או בני משפחתו צורכים בארץ באופן קבוע."}, {"p": 26, "t": ".8מומלץ לבצע בדיקה וטיפולי שיניים מקיפים לכל בני המשפחה לפני היציאה לשליחות, .9שכן בחו\"ל אין מימון המערכת לטיפולי שיניים מכל סוג שהוא ,למעט טיפולי שיניים .10משמרים לילדים עד גיל  ,18בהתאם לרשימת הטיפולים המאושרת בסל הבריאות הישראלי הכנה לשליחות  -חיסונים לפני היציאה לשליחות למקומות שירות מסוימים ,על השליח לבצע חיסונים עבורו ועבור בני משפחתו היוצאים עמו לשליחות:"}, {"p": 26, "t": ".1באחריות השליח לבדוק מול הגורמים המוסמכים  ,כגון אתר משרד הבריאות ובמרפאות המטיילים בלשכות הבריאות ,האם היעד אליו הוא נוסע ,מחייב לקיחת חיסונים ותרופות ,טרם ההגעה אל היעד .את המידע ניתן לקבל באמצעות אתר משרד הבריאות באינטרנט שכתובתו > WWW.HEALTH.GOV.IL :מידע וחיסונים לנוסעים לחו\"ל, או במרפאות המטיילים בלשכות הבריאות."}, {"p": 26, "t": ".2על מנת להיות ערוך לנסיעה וכיוון שישנם חיסונים הניתנים כסדרה ,באחריות השליח לבדוק את הנ\"ל מספיק זמן מראש ,לפחות  6שבועות טרם הנסיעה ,או אם נאמר אחרת על ידי משרד הבריאות."}, {"p": 26, "t": ".3ההחזר הכספי בגין עלות החיסונים ,יינתן באמצעות השכר תמורת קבלות מקוריות, שיוגשו עם הגעת השליח לקצ\"מ/חשב איזורי לקבלת החזר. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 27, "t": ".4אנשי צבא יבצעו החיסונים במרפאה הייעודית בצריפין /מרפאות המטיילים בלשכות הבריאות ואילו בני משפחותיהם יחוסנו ע\"י לשכת הבריאות במקום מגוריהם. הדרכה מידע וקורסים לקראת שליחות לימודי שפה ידיעת השפה והכרת מקום השירות מהווים כלים חשובים לביצוע עבודתם של השליחים ,על כן מדינת ישראל משתתפת בהכנת השליח ובני משפחתו הנלווים אליו לשליחות ,לתפקיד בחוץ-לארץ ,טרם יציאתו לשליחות (עד  50שעות לשליח ולכל בן משפחה מצטרף החל מגיל"}, {"p": 27, "t": ".)5 תרגום מסמכים מעת לעת נדרשים שליחים לתרגם מסמכים שונים (לקראת היציאה לשליחות או במהלכה). המשרד/צה\"ל פועל בנושא זה עם חברת תרגום ,שזכתה במכרז. מודגש כי ,המשרד לא יממן תרגום מסמכים ,שייעשה ע\"י שליח באופן פרטי ועל חשבונו ולא באמצעות ההסדר שפורט לעיל."}, {"p": 27, "t": "שליחי משהב\"ט ונספחים –הבקשה לתרגום תועבר באמצעות יח' משא\"נ ומינהל בחו\"ל במסגרת ההתקשרות הקיימת ביחידה לתרגום מסמכים. שליחי צה\"ל כולל שליחים לומדים – הבקשה לתרגום תועבר באמצעות ק .הנסיעות הזרועי במסגרת התקשרות של החיל מול הספק הרלוונטי."}, {"p": 27, "t": "סוגי המסמכים המאושרים לתרגום .1תעודות בית ספר של הילדים (רק אם נדרש ע\"י ביה\"ס בתהליך הרישום). .2פנקסי חיסונים של הילדים (רק אם נדרש ע\"י ביה\"ס בתהליך הרישום). .3מסמכים רפואיים של בני המשפחה."}, {"p": 27, "t": ".4תעודות אקדמאיות של השליח (מתייחס ללומדים בלבד ורק אם נדרש ע\"י מוסד הלימודים בחו\"ל). .5תעודת נישואין של השליח ורעייתו (רק אם נדרש ע\"י המקומיים בחו\"ל) .6אבחונים של ילדים ,כדוגמת אבחון דידקטי ,פסיכולוגי ,קשב וריכוז ועוד (רק אם נדרש ע\"י ביה\"ס במקום השירות)."}, {"p": 27, "t": ".7תרגום מסמכים מסוג אחר שאינו מופיע ברשימה שלעיל ,טעון אישור מראש של היח' למשאבי אנוש ומנהל בחו\"ל. .8השירות כולל חתימת נוטריון לאישור התאמת התרגום למקור ,שימוש בשירות זו יאושר ע\"י היחידה למשאבי אנוש ומינהל בחו\"ל רק במקרים חריגים בהם יוכח כי מחויב אישור נוטריון כאמור לעיל."}, {"p": 27, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 28, "t": "שפות התרגום במסגרת ההסדר עם החברה ,יינתנו שירותי תרגום מסמכים מעברית לשפות זרות ולהיפך השפות הן :אנגלית ,גרמנית ,צרפתית ,ספרדית ,רוסית ,פורטוגזית ,איטלקית ,סינית ופולנית."}, {"p": 28, "t": "אופן הפעלת השירות לפני יציאה לשליחות הגורם המזמין: הגורם המזמין לעובדי משהב\"ט ונספחי הגנה  -היח' למשאבי אנוש ומנהל א. בחו\"ל. המזמין לנספחים ושליחי זרועות  -קצין הנסיעות הזרועי."}, {"p": 28, "t": "ב. .2השליח יקבל מהגורם המזמין טופס להזמנת עבודת תרגום ,ימלא אותו ויעבירו בחזרה לגורם המזמין בצירוף החומר אותו יש לתרגם. א .הגורם המזמין יבדוק תקינות הטופס והמסמכים (שהם תואמים את סוגי המסמכים המפורטים לעיל בלבד) ויעבירם במייל לנציג חברת התרגום."}, {"p": 28, "t": "ב .החברה תתרגם המסמכים ותשלח את התרגומים לגורם המזמין והגורם המזמין יעביר את המסמכים המתורגמים בחוזר לשליח. ג .במקביל ישלח נציג חברת התרגום חשבונית לגורם המזמין ,לצורך טיפול בתשלום."}, {"p": 28, "t": ".3במהלך השליחות א .שליח מכהן ,ימלא טופס להזמנת עבודת תרגום ,אותו יקבל ממנהל כ\"א של המשלחת או קצ\"מ הנספחות/הנספח. ב .מנהל כ\"א יבדוק תקינות הטופס ותקינות המסמכים (יוודא שהם תואמים את סוגי המסמכים המפורטים לעיל בלבד) ויעבירם במייל לגורם המזמין בארץ."}, {"p": 28, "t": "ג .הגורם המזמין יעביר המסמכים במייל לנציג חברת התרגום. ד .החברה תתרגם המסמכים ותשלח את התרגומים לגורם המזמין והגורם המזמין יעביר את המסמכים המתורגמים בחוזר לשליח."}, {"p": 28, "t": "ה .במקביל ישלח נציג חברת התרגום חשבונית לגורם המזמין ,לצורך טיפול בתשלום. ו .החברה תתרגם המסמכים ותשלח את תרגומם במייל ישירות לשליח ובמקביל תשלח את החשבונית לגורם המזמין בארץ לצורך טיפול בתשלום."}, {"p": 28, "t": "עבודה לבן/בת הזוג חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 29, "t": "המשרד מודע לצורך של בן/בת הזוג לעבוד במהלך תקופת השירות .המשרד יעשה ככל האפשר למצוא מקום עבודה מתאים לבן/בת הזוג בהתאם לאילוצים במקום השירות. יובהר כי אין המשרד מתחייב למצוא עבודה לבן  /בת הזוג ויש לקחת בחשבון שלעיתים לא תימצא משרה מיד בתחילת השליחות."}, {"p": 29, "t": "בן/ת זוג ,שירצה לעבוד כאית\"ן באחת מנציגויות המדינה בחו\"ל ,יצטרך לעבור לשם-כך תחקיר ביטחוני .את הטפסים ניתן לקבל ביחידה למשאבי אנוש ומנהל בחו\"ל או במלמ\"ב/ מחלקת מהימנות."}, {"p": 29, "t": "תהליך האישור הביטחוני אורך מספר חודשים ולכן ,רצוי להתחיל בו כבר בארץ  -מוקדם ככל האפשר. עבודת בן/בת זוג בכפיפות לשליח (לראש נספחות) ככלל הנציגות/הנספחות תימנע ככל שניתן מאיוש בני/ות זוג בתפקידי אית\"נ בכפיפות אשר עלולה לגרום לניגוד עניינים (ראה פרק בתקשיר – העסקת קרובי משפחה) ובהתאם לכך במסגרת שיתופי הפעולה עם משרד החוץ מעודד המשרד בחינת אפשרות לעבודת בן/בת זוג"}, {"p": 29, "t": "במשרד החוץ בהצרחה למול משרות אית\"נ של הנספחות ,לאמור; בן/בת הזוג של שליח משרד החוץ ישובץ במשרת אית\"נ של משהב\"ט ובן/בת הזוג של הנספח ישובץ במשרד החוץ במשרת אית\"נ."}, {"p": 29, "t": "בהתאם לאמור על הנספח המכהן /הקצ\"מ לוודא מול הקונסוליה באם קיים תקן למשרת אית\"נ על מנת לאיישה באמצעות בן/בת זוג הנספח המיועד להחליפו. בהינתן שלא ניתן לאייש תקן של משרד החוץ ,יבחן המשרד העסקת בן/ת זוג הנספח בכפיפות ישירה הכל בכפוף לאישור רח\"ט קש\"ח ואישור יועמ\"ש לאיתור חשש לניגוד עניינים ולאישור קב\"ט להכשר ביטחוני (על בן/בת הזוג למלא את הטופס הכשר ביטחוני אשר הועבר לנספחים"}, {"p": 29, "t": "היוצאים בתיק התדרוך ולאחר מכן יצטרך בן/בת הזוג לעבור תחקיר ביטחוני). תהליך האישור הביטחוני אורך מספר חודשים ולכן ,רצוי להתחיל בו כבר בארץ  -מוקדם ככל האפשר. עבודה פרטית של בן/בת הזוג במקום השירות:"}, {"p": 29, "t": "מובהר כי ,עבודת בן/בת הזוג במקום עבודה פרטי ,מחייבת אשרת עבודה והתאמה לחוקי המקום לפיכך ,באחריות השליח לבדוק ולוודא חוקי המקום עם מנהל משא\"נ/קצ\"מ/נספח במקום השירות ובמידת הנדרש עם נציגי השגרירות  /קונסוליה במקום השירות כמו-כן ,יש לקבל אישור הקב\"ט במקום השירות."}, {"p": 29, "t": "מודגש כי ,לאור ההליך הנדרש לקבלת אשרת עבודה כאמור ,ייתכנו פרקי זמן ארוכים עד לקבלת האשרה ,לפיכך ,מוצע כי בן/בת הזוג יבחן אפשרות להעסקה במעמד אית\"נ גם בתקופת גישור (מיועד בעיקר לשליחי מש\"נ) בכפוף להימצאות תקן פנוי בנציגות/נספחות."}, {"p": 29, "t": "על הנספח המכהן להציג בפני הנספח הנכנס את כל הכללים והחוקים לקבלת אשרת עבודה במקום השירות .הבדיקה תתבצע מול נציגי השגרירות  /קונסוליה במקום השירות וכן מול עו\"ד מקומי של הנספחות .במקביל ,הנספח הנכנס יוודא העברת כל המסמכים הנדרשים חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 30, "t": "לצורך בחינת אפשרות להעסקת בן/בת הזוג במקום עבודה פרטי ולקבל אישור הקב\"ט במקום השירות וכן במידת הצורך ובהתאם לסוג העבודה ומימשקי עבודה יידרש לאיתור חשש לניגוד עניינים באם העיסוק של בן/בת הזוג עלול להוביל לניגוד עניינים הן במסגרת העבודה והן במסגרת הפעילות של הנספח."}, {"p": 30, "t": "שמירת זכויות פנסיה לבן/בת זוג של שליח קיימת אפשרות שהמשרד ישתתף בשמירת זכויות פנסיה לבן/בת זוג של שליח ,שעבד בארץ לפני שליחותו ,מפריש כספים לטובת שמירת זכויות באופן עצמאי ואינו עובד (מנוע מלעבוד) בזמן שהותו בחו\"ל."}, {"p": 30, "t": "השתתפות המשרד אינה כוללת בן/בת זוג ,שהינו עובד משרד ממשלתי בפנסיה תקציבית, המשלם בגין שמירת זכויות סך של  6.2%משכרו .הסיבה הינה כי שיעור ההפרשה הנ\"ל לשמירת זכויות ,הינו לאחר הנחה שניתנה ע\"י משרדי הממשלה."}, {"p": 30, "t": "לצורך השתתפות המשרד בשמירת זכויות לבן/בת זוג של שליח ,צריכים להתקיים התנאים הבאים: • בן/בת הזוג מנוע/ה מלעבוד בתקופת השליחות בהתאם להגדרות ההוראה שלהלן: המשרד אסר עליהם לעבוד בשכראו שלא התקבלו לעבודה בנציגות ולא מחוץ לנציגות.• קיים רצף הפקדות של לפחות  6חודשים טרם היציאה לשליחות."}, {"p": 30, "t": "במידה ובן/בת הזוג עומד בתנאים המצטברים הנ\"ל ,ניתן לבצע השתתפות בשמירת זכויות פנסיה ובכפוף להצגת מסמכים נדרשים שיפורטו ע\"י יחידת השכר בהתאם לפניית השליח בבקשת ההשתתפות הנ\"ל."}, {"p": 30, "t": "ההחזר מתבצע בתלוש השכר של השליח והוא חייב במס עפ\"י חוק. את בקשת ההחזר יש להגיש לכל המוקדם כל רבעון ועד חצי שנה. לצורך השתתפות המשרד בשמירת זכויות לבן/בת זוג של שליח ,יש להעביר ליחידת השכר:"}, {"p": 30, "t": "• שכר אחרון של בן/בת הזוג בארץ. • אישור חברת הביטוח על גובה השכר המבוטח  /שכר פנסיוני וגובה ההפקדה הנדרש. • ביצוע תשלום בן/בת הזוג לתקופה המבוקשת. • הצהרה כי בן/בת הזוג מנוע לעבוד ,הכוללת תאריכים בהם אינו/ה עובד/ת והסיבה לאי העבודה ובאישור מנהל משא\"נ/קצ\"מ הנציגות/נספחות/קצ\"מ השגרירות שלא ניתן לאייש משרת אית\"נ בשגרירות/נציגות/נזפחות."}, {"p": 30, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 31, "t": "במקרה שבן הזוג לא עבד ערב היציאה לשליחות ,הזכאות לשמירת זכויות תיבחן ע\"י יחידת השכר ,כל מקרה לגופו. אתיקה וכללי התנהגות בחו\"ל (שימוש בזכויות דיפלומטיות) במהלך השליחות בחו\"ל ,משמש השליח גם כנציג מדינת ישראל."}, {"p": 31, "t": "המשרד מצפה מהשליח להתנהגות ההולמת את מעמדו ותפקידו ,תוך שימוש סביר ונאות בזכויות החסינות המוקנות לו ,בתואם את חוקי ומנהגי המדינה המארחת. איסור עבודה פרטית שליח או בן/בת זוגו אינם רשאים לעסוק בעבודה פרטית כלשהי במקום השירות."}, {"p": 31, "t": "בני משפחת שליח לא יעבדו מחוץ לנציגות אלא באישור מיוחד של המשרד בארץ שיתבסס על החלטת ועדת היתרים. לא יועסק ילד של שליח בנציגות ,אלא באישור מראש של ר' היחידה למשאבי אנוש ומנהל בחו\"ל."}, {"p": 31, "t": "רכישת מכונית במסגרת הזכויות לפטור ממכס ו/או מיסים אחרים המוענקות ע\"י מדינת השירות ,רשאי שליח במעמד דיפלומטי לרכוש בתקופת שליחותו מכונית אחת בלבד לשימושו או לשימוש בני משפחתו."}, {"p": 31, "t": "חובה על השליח לבטח באופן פרטי ביטוח צד שלישי לגבי כל מכונית שברשותו או ברשותו בני המשפחה. רכישת סחורות ומצרכים סחורות ומצרכים הנרכשים ע\"י שליח במסגרת הפטור ממכס ו/או מיסים אחרים ,יירכשו רק בכמויות סבירות לשימוש השליח ובני משפחתו."}, {"p": 31, "t": "חל איסור מוחלט לרכישת סחורות או מוצרים הפטורים ממכס ו/או מיסים עבור מי שאינו זכאי לכך עפ\"י החוק המקומי .אין למכור סחורות או מוצרים אלה למי שאינו זכאי לכך או למסרם לגורם אחר כתחליף לתשלום כלשהו."}, {"p": 31, "t": "חוקי מטבע מקומי על השליח לקיים את תקנות המטבע במדינת השירות או במדינות אחרות בהן יבקר ולא לעסוק בכל צורה שהיא בהעברה או סחר בכספים ,הנוגדים את דיני מדינת השירות או המדינה בה יבקר."}, {"p": 31, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 32, "t": "הלוואות פרטיות חל איסור מוחלט לקבל הלוואה פרטית בארץ השירות מכל גוף שהוא (המשרד מאפשר לשליח קבלת הלוואה בארץ – ראו פרק שכר). נספח ג' להמ\"ב  – 10.06כללי התנהגות לשליחים ועובדים מקומיים בחו\"ל מבוא .1העובדים בחו\"ל משמשים כנציגי מדינת ישראל במדינת שירותם .עובדים אלו מחויבים בשמירת כללי ההתנהגות המחייבים אותם בארץ ואלו של המדינה המארחת."}, {"p": 32, "t": "המושג \"עובדים בחו\"ל\" ,כוונתו בנספח זה היא לשליחי המשרד ועובדים מקומיים במשלחות משהב\"ט ,בנספחויות ,בנציגויות ,משתלמים בחו\"ל ,פרוייקטנטים בחו\"ל וקציני קישור (להלן \"עובדים בחו\"ל)."}, {"p": 32, "t": ".2בהמ\"ב  10.06מפורטים דפוסי התנהגות החלים על כל עובדי משהב\"ט בנושאים הבאים: העובד והשירות ,הפעלת שיקול דעת ,פעולה בגבולות הסמכות ,שימוש בתואר משרה תפקיד, טיפול בנושאים בעלי אופי משפטי ,התנהגות עניינית ושוויונית ,מענה לפניות הציבור ,ניגוד אינטרסים  /עניין אישי ,טובת הנאה ,קבלת מתנות ,מגעים חברתיים ,פגישות בענייני עבודה, מסירת מידע ,איסור העסקה או עשיית עסקים עם מתקשרים של משהב\"ט ,הגבלות לאחר"}, {"p": 32, "t": "פרישה ,עבודה פרטית ועבודה נוספת. כמו כן ,מפורטים כללי התנהגות בנהלים אגפיים. .3מסמך זה מפרט כללי התנהגות ,נורמות וכללי אתיקה נוספים לעובדים בחו\"ל ואינו בא לגרוע מחובתו של העובד בחו\"ל להתנהג על פי החיובים החוקיים והמנהליים המוטלים עליו בארץ."}, {"p": 32, "t": ".4נורמות ההתנהגות הציבורית שיפורטו מקורן בחקיקה האזרחית והפלילית ,בפסיקה, בהוראות התקשי\"ר ,בהוראות השות\"ש (הוראות שכר ותנאי שירות בחו\"ל הנקבעים ע\"י הוועדה הבין-משרדית) ,בהוראות התכ\"מ ,בהוראות המשרד ,בנהלים האגפיים ובכללי ההתנהגות הנובעים מאופי התפקיד."}, {"p": 32, "t": "על העובד בחו\"ל יחולו חוק שירות המדינה (משמעת) .תקנות שירות המדינה (משמעת) והוראות התקשי\"ר .העובד בחו\"ל יקפיד שלא לבצע כל עבירה משמעתית ובמידה ויעשה כן, הוא עלול להיות מועמד לדין משמעתי ככל עובד מדינה ,בבית הדין למשמעת של עובדי המדינה."}, {"p": 32, "t": ".5אין האמור להלן בא לגרוע מכללים שנקבעו או שיקבעו מעת לעת כאמור לעיל או בכללי האתיקה ,אלא להוסיף עליהם .בכל מקרה של סתירה או ספק ,גוברות הוראות הדין. .6בכל מקום בו נאמר \"מדינת השירות\" הכוונה היא גם למדינת האמנה (אם קיימת)."}, {"p": 32, "t": ".7בכל מקום שמעשה כפוף לאישור ממונים בהתאם לסמכותם ,יש לבחון זאת בכפוף להוראות המשרד הנוגעות לכל דבר ועניין. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 33, "t": ".8כל משלחת או נציגות תאמץ כללים אלו במסגרת הוראותיה. כללי יסוד .1העובד בחו\"ל ינהג במיומנות מקצועית ,בנאמנות ,בהוגנות וביושר במסגרת תפקידו וכלפי מקום העבודה ,הממונים עליו ועמיתיו לעבודה ,וייצג בכבוד את מדינת ישראל ואת מעהב\"ט."}, {"p": 33, "t": ".2העובד בחו\"ל יקפיד להתנהג באופן מושכל ,בהתאם לחוקי המקום .העובד ירחק מכל מעשה או מחדל שעלולים לסבכו בפלילים או בפגיעה בביטחון המדינה בה הוא שוהה. .3העובד בחו\"ל יקפיד על הפרדה מוחלטת בין כספו הפרטי לבין התקציב הציבורי העומד לרשותו או מטופל על ידו ויקפיד במיוחד על דיווח מדויק בהקשר להוצאותיו הכספיות (כגון:"}, {"p": 33, "t": "הוצאות נסיעה ,שכר דירה ,אש\"ל ,הוצאות רפואיות וכד'). .4חל איסור על עובד בחו\"ל לתבוע או לקבל טובות הנאה אישיות מגורמים הקשורים לעבודתו .חל איסור על העובד בחו\"ל לבקש תרומות לכל מטרה שהיא מגורמים הקשורים מסחרית בעבודתו."}, {"p": 33, "t": ".5העובד בחו\"ל יקפיד לפעול עפ\"י הוראות הביטחון המחייבות (כגון :בקביעת מקום המגורים ,כללי נשיאת נשק ,כללי טיפול בדואר ,דיווח על חריגים וכד'). לבוש והופעה העובד בחו\"ל יופיע לעבודתו ולכל מקום בו הוא ממלא את תפקידו או מייצג את מקום עבודתו ,בלבוש נאות המתאים לתפקידו עפ\"י נסיבות המקרה ועפ\"י המחיות הממונים."}, {"p": 33, "t": "שימוש במשאבי המשרד העובד בחו\"ל ימנע משימוש במשאבי המשרד לצרכיו הפרטיים (כגון :דואר ,דואר דיפלומטי, שימוש בטלפון ,שימוש ברכב המשרד ,צילום מסמכים וכד') ,למעט אם ניתן אישור בהוראות או אישור ספציפי ע\"י הממונים ,עפ\"י סמכותם."}, {"p": 33, "t": "שמירה על חוקי המקום .1העובד בחו\"ל יכבד בהתנהגותו את חוקי המקום ומנהגיו ויקפיד על מילוי כל הכללים ונורמות ההתנהגות המקובלים באזור מגוריו (כגון :יחסי שכנות ,מחזור אשפה ,ניקיון מדרכות וכד')."}, {"p": 33, "t": ".2העובד יקפיד על קיום תקנות התעבורה המקומית ,כולל תקנות החניה .אם עובד ייקנס בגין עבירה על תקנות חנייה ,עליו להימנע מניצול מעמדו הדיפלומטי (אם יש לו) וישלם את הקנס במועדו."}, {"p": 33, "t": "התנהגות מחייבת במדינת השירות .1העובד בחו\"ל יקפיד למלא אחר תקנות המטבע של מדינת ישראל ,של מדינת השירות ושל חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 34, "t": "מדינות האמנה (אם קיימות) ולא יעסוק בכל צורה שהיא בהעברה ו/או סחר בכספים הנוגדים את דיני אותן המדינות. .2העובד בחו\"ל רשאי לרכוש בתקופת שירותו רכב לשימושו ולשימוש בני משפחתו, במסגרת זכויותיו לפטור ממכס ו/או מיסים אחרים ,המוענקות ע\"י המדינה בה משרת ,ואך ורק עפ\"י תקנות אותה המדינה."}, {"p": 34, "t": ".3העובד בחו\"ל חייב לרכוש ביטוח חובה וביטוח צד שלישי לפחות לכל מכונית פרטית שברשותו או ברשות בני משפחתו. .4העובד בחו\"ל יקפיד על רכישת סחורות ומצרכים ,במסגרת הפטור ממכס ו/או מיסים אחרים ,רק בכמויות סבירות לשימושו ולשימוש בני משפחתו ,הסמוכים על שולחנו ולא למטרת מסחר."}, {"p": 34, "t": ".5העובד בחו\"ל אינו רשאי לקבל הלוואה במדינת השירות מכל גורם שהוא ,למעט הלוואות שאושרו ממקורות מעהב\"ט. .6בני משפחתו של העובד אינם רשאים לעבוד במקום עבודה שאינו נציגות של ממשלת ישראל ,אלא אם ניתן לכך מראש ובכתב אישור מאגף מנהל ומשאבי אנוש במשהב\"ט."}, {"p": 34, "t": ".7עובד ו/או בני משפחתו לא יפרסמו מאמרים בשכר וללא שכר ,בשמם הם או בעילום שם או בשם בדוי ,אלא אם קיבלו לכך אישור מקצועי מהממונה המקצועי ואישור ביטחוני מהקב\"ט. .8עובד ישתמש בחו\"ל בדרכונו הישראלי או בלבד (גם בתפקיד וגם באופן פרטי) .אם לעובד אזרחות נוספת ,השימוש בדרכון הנוסף יעשה אך ורק בכפוף להוראות הקב\"ט."}, {"p": 34, "t": "הכרת התפקיד תדרוך אישי לקראת שליחות .1השלב הראשון בתהליך השיגור הוא התדרוך האישי. א .שליח משהב\"ט ,ראש נציגות/נספחות – יקבל המסמכים ויתודרך באמצעות יח' משא\"נ ומינהל בחו\"ל."}, {"p": 34, "t": "ב .שליח צה\"ל  -יקבל המסמכים והתדרוך באמצעות ק' הנסיעות הזרועי. .2במסגרת פגישת התדרוך,על השליח לעדכן את היחידה למשאבי אנוש ומנהל בחו\"ל /קצין נסיעות זרועי בכל מידע חיוני כגון :בעיות בריאות מיוחדות ,ילדים הנשארים בארץ, תמיכה בהורים ,סטאטוס משפחתי מיוחד (ילדים מנישואים קודמים ,ידוע/ידועה בציבור וכד') .מסירת מידע זה מוקדם ככל האפשר ,תסייע לטיפול נכון ויעיל ותמנע עוגמת נפש"}, {"p": 34, "t": "וטרחה מיותרת במהלך השליחות. .3מודגש כי התנעת כל פעילות שיש בה משום התחייבות כספית של המשרד ושהינה בתחום טיפולם של בעלי התפקידים השונים במשרד ,תהיה אך ורק לאחר שהאסמכתא של השליח לשליחות הארוכה ,תסיים את סבב החתימות במלואו."}, {"p": 34, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 35, "t": "נסיעת אוריינטציה (\"נסיעת התארגנות\") הוראה .1.1.11.3.נסיעת התארגנות הוראת תכ\"מ \" - 13.10.0.1נסיעות לחוץ לארץ – קצובות שהייה ולינה ,החזרי הוצאות ומיסוי הוראת תכ\"מ \" - 13.10.0.2נסיעות לחוץ לארץ – קצובות שהייה ולינה ,החזרי הוצאות ומיסוי כחלק מתהליך ההכנה לשליחות ,מממן המשרד לשליח ,נסיעה מוקדמת למקום השירות."}, {"p": 35, "t": "נסיעה זו מכונה\" :נסיעת אוריינטציה\" (נסיעת התארגנות). • שליח יהא זכאי ,באישור המשרד לנסיעת התארגנות ליעד השליחות. • שליח יהיה רשאי לצרף לנסיעת ההתארגנות את בן  /בת הזוג שלו (מובהר כי במקרה כאמור ,הזכאות להשתתפות המשרד בעלויות בן/בת הזוג הינה לכרטיסי טיסה בלבד כל יתר ההוצאות יחולו על השליח)."}, {"p": 35, "t": "קורסי הכנה לשליחות באופן טבעי ,מתחיל תהליך ההכנה לשליחות בעננה של חוסר וודאות ,שמתפוגגת ונמוגה ככל שמתקרב מועד היציאה לשליחות. ככל שהכנת השליח ומשפחתו לשליחות נעשית בצורה יסודית ואפקטיבית יותר ,כך קליטת המשפחה והשתלבות השליח בחו\"ל תיעשה קלה יותר."}, {"p": 35, "t": "מתוך הכרה והבנה בחשיבות ההכנה לשליחות ,משקיע המשרד וצה\"ל מאמצים ותשומות רבות ומקיים קורסי הכנה לשליחים ומשפחותיהם. קורסי ההכנה לשליחות מקיפים את מירב המידע וההסתכלות על האספקטים השונים של המעבר לארץ זרה ,הן בהיבט האישי והן בהיבט המשפחתי .בנוסף ,מועברים בקורס נושאים מקצועיים הרלוונטיים לכלל המשתתפים."}, {"p": 35, "t": "במסגרת הקורס יקבל השליח כלים שיסייעו לו בהתמודדות כשליח המדינה בחו\"ל וכן מידע רלוונטי על תהליך השיגור והקליטה בחו\"ל. הקורסים כוללים ,סדנת התמודדות עם מעבר לארץ אחרת ,סדנת ילדים ,תרבות עסקית בחו\"ל ,תדמית ולבוש ,הרצאות של בעלי תפקידים המטפלים בתנאי השירות בחו\"ל ,לימוד שפת ארץ השירות ועוד .לרוב הפעילויות ניתן ורצוי לצרף את בן/בת הזוג."}, {"p": 35, "t": "השתתפות השליח בכל מפגשי הקורסים הינה חובה. א .קורס שליחי משהב\"ט הקורס מיועד לשליחים עובדי משהב\"ט .הקורס מתקיים במהלך התקופה שבין בחירת השליח לבין יציאתו לשליחות  -בדרך כלל החל מחודש מרץ עד -מאי."}, {"p": 35, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 36, "t": "ב .קורס נספחים הקורס מאורגן ע\"י אגא\"ס /חטיבת הקש\"ח והוא מיועד לנספחי ההגנה (אנשי צבא ואזרחים) ועוזריהם .הקורס מתקיים בדר\"כ החל מחודש מאי ,למשך כ 2 -חודשים רצופים) מועדי הקורס נקבעים ע\"י אגא\"ס/קש\"ח."}, {"p": 36, "t": "ג .יום תדרוך ב\"זום\" שליחים רב זרועי התדרוך מיועד לשליחי צה\"ל המשוגרים לחו\"ל מטעם הזרועות לאחר שהשליחים תודרכו באופן אישי ע\"י קצין נסיעות זרועי .יום התדרוך מועבר ב\"זום\"."}, {"p": 36, "t": "באחריות ק .נסיעות זרועי לזמן את השליחים מטעמם למועד התדרוך שייקבע ע\"י יח' משא\"נ ומינהל בחו\"ל  .התדרוך יועבר ע\"י ראש יח' משא\"נ ומינהל בחו\"ל או מי מטעמה ובהשתתפות הגורמים הרלוונטיים במשרד (יח' השינוע ,יחידת השכר) ."}, {"p": 36, "t": "התדרוך מתקיים בדר\"כ בחודש מרץ. מטרות הנסיעה חשיפה לתכולות התפקיד החדש והכרות עם הפונקציות ובעלי התפקידים המרכזיים, הנמצאים בממשק העבודה. להתרשם ממקום השירות ,אזורי המגורים ויוקר המחיה."}, {"p": 36, "t": "להתוודע למגוון מוסדות החינוך ולקבל החלטה לגבי רישום הילדים. לפתוח חשבון בנק במקום השירות (הנ\"ל מותנה בכך שבעת נסיעת האוריינטציה יהיה לשליח דרכון דיפלומטי  /שירות)."}, {"p": 36, "t": "אוריינטציה מתי? נסיעת האוריינטציה הינה למשך שבוע עבודה במקום השירות ,ללא \"חציית שבת\" (ימים ב'-ה' כולל). נסיעת אוריינטציה לשליחי משהב\"ט :שבוע האוריינטציה ייקבע במהלך חודש אפריל-מאי בהתאם לתאריך שיתואם עם הנציגות וייקבע כחלק ובמסגרת לו\"ז קורס השליחים."}, {"p": 36, "t": "נסיעת אוריינטציה לשליחי צה\"ל א .עפ\"י הנחיית ר' אכ\"א ,מאושרת נסיעת האוריינטציה רק לשליחי צה\"ל היוצאים לתקופה של למעלה משנה .הנסיעה תהיה לשבוע עבודה בחו\"ל - ללא חציית שבת (ימים ב'-ה' כולל)."}, {"p": 36, "t": "ב .שליחי צה\"ל יתאמו את מועדי הנסיעה עם השליח המכהן ,אותו הם אמורים להחליף והיחידה הצבאית המשלחת. יש להקפיד שנסיעת האוריינטציה לא תחול בחפיפה לתאריכים בהם מתקיים קורס הנספחים  /קורס השליחים הרב-זרועי או במועדים בהם הנציגות בחו\"ל אינה עובדת בשל חג מקומי או יהודי .לא תאושר היעדרות מהקורסים הללו לצורך מימוש נסיעת אוריינטציה."}, {"p": 36, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 37, "t": "א .נסיעת האוריינטציה תאושר עד 4 -חודשים לפחות לפני תאריך יציאת השליח לתפקיד .כל בקשה לנסיעה לאוריינטציה פחות מתקופה של  4חודשים מחייבת אישור יח' משא\"נ ומינהל בחו\"ל – באחריות ק' נסיעות זרועי ובאחריות השליח לוודא אישור כאמור."}, {"p": 37, "t": "ב .באירועים חריגים כגון :מגיפה/אירוע חירום/מלחמה ובהינתן שלא ניתן לקיים את נסיעת האוריינטציה ,תיבחן אפשרות לקיום הדרכה לאוריינטציה באמצעים דיגיטליים ( ZOOMוכד')."}, {"p": 37, "t": "אסמכתא לנסיעת האוריינטציה. לצורך מימוש נסיעת האוריינטציה המשרד/החיל המשלח נדרש להזרים אסמכתא (לשליחי המשרד ע\"י יח' משא\"נ ומינהל בחו\"ל ,לנספחים ע\"י אגא\"ס לשליחי צה\"ל ע\"י ק' נסיעות זרועי)."}, {"p": 37, "t": "לצורך אישור הנסיעה והוצאת אסמכתא ,יש להעביר ליחידה למשאבי אנוש ומנהל בחו\"ל /קצין הנסיעות הזרועי את הנתונים והמסמכים הבאים: א .מכתב ובו מועדי הנסיעה שסוכמו. ב .פירוט תכנית הנסיעה (על התוכנית לכלול חפיפה בנושאים מקצועיים וכן טיפול בנושאי פרט כגון רישום ילדים לבתי ספר ,חיפוש דירה וכד'."}, {"p": 37, "t": "ג .מכתב \"אישור הגעה\" מהמשלחת  /נספחות (למעט נסיעות למש\"ן ,וושינגטון ,הודו ונציגות משהב\"ט בגרמניה ,שלגביהן מתקבל אישור ההגעה באופן ממוחשב במסגרת תהליך חתימת האסמכתא."}, {"p": 37, "t": "ד .אישורי קב\"ט לביצוע תדריך התנהגות מונעת בעת נסיעה בתפקיד לחו\"ל: )1עובדי משהב\"ט – אישור מהקב\"ט האגפי (האישור מגיע ליח' נסיעות חו\"ל במסגרת סבב חתימת האסמכתא. )2שליחי צה\"ל  -אישור מהקב\"ט הזרועי (אישור זה יועבר ע\"י השליח לאכ\"ס  /נסיעות חו\"ל מספר ימים לפני הנסיעה .ללא אישור זה ,לא יונפק לנוסע כרטיס הטיסה)."}, {"p": 37, "t": "כרטיסי טיסה לנסיעת האוריינטציה: כרטיסי הטיסה לשליח ולבן/ת הזוג יתואמו ע\"י השליח עם תחום הסדרי נסיעות חו\"ל . השתתפות המשרד וזכאויות להוצאות בגין נסיעת האוריינטציה:"}, {"p": 37, "t": "שליח :במסגרת נסיעת האוריינטציה זכאי השליח לכרטיס טיסה ,מלון ודמי שהייה והחזרי רכב שכור  /נסיעה במוניות ,החזרי הוצאות הכל בהתאם להוראת השות\"ש והוראת התכ\"ם אשר תהיינה בתוקף באותה עת."}, {"p": 37, "t": "בן/בת הזוג :הזכאות הינה להשתתפות בעלות כרטיסי טיסה בלבד כל יתר העלויות (שהות ,לינה ,אש\"ל וכד') בגין הצטרפות בן/בת הזוג יחולו באופן פרטי על השליח. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 38, "t": "מלון בנסיעת האוריינטציה הנציגות/נספחות תזמין לשליח מלון במקום השירות לתקופת האסמכתא .כללי הכניסה והיציאה מהמלון יהיו בהתאם להוראות החשב הכללי (למידע נוסף ניתן לפנות לאכ\"ס  /נסיעות חו\"ל)."}, {"p": 38, "t": "זכאות לרכב שכור/הסעות במסגרת האוריינטציה. א .שליח יקבל בנסיעת האוריינטציה השתתפות במימון שכירת רכב או שימוש במוניות  /תחבורה ציבורית ,עד לתקרה של ( .200$במקרה של שינוי התקרה תחול התקרה המפורטת בהוראת השות\"ש) .כל העלויות מעבר לכך ,יחולו על השליח האמור לעיל מיועד לסייע לשליח ולהקל על הניידות לצורך איתור דירה ובחירת מוסדות חינוך .במקרה של שכירת רכב ,כולל הסכום הנ\"ל את עלות"}, {"p": 38, "t": "השכירות ,עלות הדלק ,חניות ,כבישי אגרה ,ביטוחים וכל הוצאה נוספת אחרת. ב .תשומת לב :אישור ההוצאה הנ\"ל מותנה בהצגת קבלות מקוריות עם החזרה ארצה ,יגיש השליח את הקבלות המקוריות לאכ\"ס  /חשבונות נסיעות חו\"ל ויקבל החזר כספי עד לתקרת ה 200-דולר."}, {"p": 38, "t": "ג .האמור לעיל אינו מבטל את זכאות השליח לקבלת החזר כספי בגין נסיעה במונית משדה התעופה למלון בחו\"ל (למעט אם שכר את הרכב בשדה התעופה) ומהמלון לשדה התעופה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 39, "t": "לימודי שפה לפני ובמהלך השליחות חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 40, "t": "פרק  - 4לימודי שפה הוראה 1.2.11.1.לימוד שפת מקום השירות במהלך השירות לימוד שפה טרם היציאה לשליחות שפה היא כלי ומפתח להתנהלות במקום השירות הן בתחום המקצועי והן בחיים הפרטיים."}, {"p": 40, "t": "המשרד רואה חשיבות רבה בהעמקת הידע בשפה הרלוונטית ובשל כך ,מאפשר לשליח ולבני משפחתו ללמוד בארץ את שפת המקום או אנגלית לפני היציאה לשליחות. הלימודים מתקיימים בשיעורים פרטיים/זום בבית השליח באמצעות בית ספר לשפות, הקשור בחוזה עם המשרד/צה\"ל  -רק במסגרת זו ניתן ללמוד שפה בארץ טרום השליחות במימון המשרד .מודגש כי ,לימודים בכל מסגרת אחרת ,יהיו על-חשבון השליח."}, {"p": 40, "t": "לימוד שפת מקום השירות הוא חובה המוטלת על השליח ומשפחתו טרם היציאה לשליחות. מומלץ להתחיל בלימודים מוקדם ככל האפשר. .1זכאים ללימודי שפה.: זכאים (שליח ובני משפחה לפני היציאה לשליחות הרשומים באסמכתא) במהלך השליחות* עד לתקופה של  18חודשים לכל היותר החל מיום ההגעה למקום השירות שליח ובן/ת הזוג 50שיעורים שפת המקום או אנגלית לכל אחד עד  100שיעורי שפת המקום או"}, {"p": 40, "t": "אנגלית לכל אחד ילדים (הרשומים באסמכתא) 50שיעורים לכל ילד מגיל חמש ומעלה אנגלית בלבד עד  100שיעורי אנגלית לכל ילד מגיל חמש ומעלה . מודגש כי ,ככלל לא תאושר תוספת שיעורים (בארץ ובמקום השירות) וכן לא תאושר החרגה ללימוד השפה מעבר ל 18-חודשים כמפורט לעיל."}, {"p": 40, "t": "מקרים חריגים ובנסיבות בלתי צפויות ומיוחדות יוגשו לבחינת ועדת חריגים. * עפ\"י הוראת השות\"ש השתתפות המשרד בלימודי שפה במקום השירות הינה בעלות שיעור לפי . ₪ 140עפ\"י הנחיית חשב העלות תשולם במסגרת השכר והשליח יידרש לזקיפת הטבה בגין עלות זו .יחד עם זאת ,בנושא זה מתקיימים דיונים במסגרת ועדת שות\"ש לשינוי ההנחיות לזקיפת הטבה וההחלטות שיתקבלו לאחר הדיונים הן שייקבעו ."}, {"p": 40, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 41, "t": ".2כיצד מתקיימים הלימודים? א .שליחי משהב\"ט ונספחי הגנה: השליחים ילמדו את השפה במסגרת קורס שליחי משהב\"ט /קורס )1 נספחים ובנוסף בשיעורים פרטיים. )2בני משפחת השליח ילמדו במסגרת שיעורים פרטיים בבי\"ס לשפות הקשור בהתקשרות עם המשרד  -הפניה ללימודי השפה במסגרת שיעורים פרטיים לעובדי המשרד תימסר לשליח במהלך התדרוך האישי ע\"י נציג יח' משא\"נ ומינהל בחו\"ל."}, {"p": 41, "t": "ב .שליחי צה\"ל זרועיים ושליחים לומדים: שליחים ובני המשפחה המשוגרים מטעם הזרועות ,ילמדו שפה בארץ ,במסגרת שיעורים פרטיים בבי\"ס לשפות הקשור בהתקשרות עם הזרוע – הפניה ללימודי השפה במסגרת שיעורים פרטיים תימסר לשליח במהלך התדרוך האישי ע\"י ק."}, {"p": 41, "t": "הנסיעות הזרועי במסגרת התקשרות שיבצע החיל למול גורמי הרכש הרלוונטיים במשרד. .3אופן קבלת השיעור: השיעורים הפרטיים מחולקים ליחידות לימוד של  45דקות. יחד עם זאת מודגש כי מורה שיגיע לבית שליח ,יעשה זאת למינימום שני שיעורים רצופים (שעה וחצי לפחות) .בקשות חריגות לשיעור בודד ,יובאו ע\"י השליח מראש לאישור היחידה למשאבי אנוש ומנהל בחו\"ל/ק .הנסיעות הזרועי זרועות."}, {"p": 41, "t": ".4אישור השליח לקבלת השירות לצורך התחשבנות עם נותן השירות מחוייב המורה להחתים את השליח על מימוש הזכאות בכל שיעור .באחריות השליח לוודא שחתם על קבלת השירות (חתימה ותאריך) חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 42, "t": "שינוע מטענים חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 43, "t": "פרק מס'  – 5שינוע מטענים ביציאה לשליחות הוראה  1.1.5.2שינוע מטענים מישראל ליעד השליחות לפני השירות הוראה  1.3.5.1נסיעות שליחים מיעד השליחות לישראל בסיום השליחות הוראה  15.1..1.3סיום תפקיד הוראת תכ\"ם\" ,טיסות ושירותים נלווים לנסיעה בתפקיד לחוץ-לארץ\" ,מס' 13.10.01 מדינת ישראל משתתפת בהוצאות שינוע המטענים וביטוחם עבור השליח ובני משפחתו הנלווים אליו לשליחות ,ממקום מגוריו בישראל ועד למקום שליחותו ,ו/או במעבר ממקום"}, {"p": 43, "t": "שירות אחד למשנהו. זכאות .1שליח יהא זכאי להובלת מטענו ומטענם של בני משפחתו הנלווים אליו מביתו בישראל ועד למקום מגוריו בחוץ-לארץ ,כמתואר בהוראת שות\"ש \"שינוע מטענים מישראל ליעד השליחות לפני השירות\" ,מס'  .1.1.5.2וכאמור בסעיפים שלהלן."}, {"p": 43, "t": "א .אריזת המכולה ומועד לשיגורה יתבצע בתיאום ועפ\"י הנחיית ר' תחום משגורי פרט יבוא ויצוא במנה\"ר. ב .שינוע החפצים האישיים יכלול את כל ההוצאות ,לרבות ביטוח שיוסדר ע\"י המשרד בהתאם לזכאות השליח."}, {"p": 43, "t": "השתתפות המשרד .1המשרד ישתתף בהוצאות משלוח חפציהם האישיים של השליח ושל בני משפחתו הנלווים אליו ,כמטען ימי /אווירי או יבשתי ,למעט רכב מנועי ,כלי שיט וכל ציוד פרטי הדורש הוצאות חריגות לרבות בעלי חיים."}, {"p": 43, "t": ".2סוגי המטענים האישיים הינם: א .מטען ימי – מכולה בגודל  20רגל או  40רגל. ב .מטען אווירי (בלתי מלווה) – במשקל  25ק\"ג ברוטו (כולל אריזה) לכל בן משפחה .אנו ממליצים לך לוותר על המטען האווירי ולקבל במקומו תוספת מזוודות ככבודה אישית."}, {"p": 43, "t": ".3להלן נתוני הזכאות בהתאם להרכב המשפחתי ( ראה ריכוז הנתונים בטבלה המפורטת בהמשך): א .שליח רווק או שליח נשוי  1+יהא זכאי להשתתפות בהוצאות מכולה בגודל של 20רגל וכן למטען אווירי בלתי מלווה עבורו ועבור כל אחד מבני משפחתו הנלווים אליו ( 25ק\"ג לאדם)."}, {"p": 43, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 44, "t": "ב .שליח עם  2ילדים ומעלה ,יהא זכאי להשתתפות בהוצאות מכולה בגודל  40רגל או מכולה בגודל של  20רגל  -במקרה שבחר במכולה של  20רגל יהיה זכאי למטען אווירי בלתי מלווה עבורו ועבור כל אחד מבני משפחתו הנלווים אליו ( 25ק\"ג לאדם)."}, {"p": 44, "t": "ג .שליח הזכאי למטען ימי בגודל של  20רגל ,יהא רשאי לוותר על הובלת המטען האווירי הבלתי מלווה ולהגדיל את המטען הימי למכולה בגודל של  40רגל ,וזאת בתנאי שיישא בהוצאות הכרוכות בהגדלת המטען הימי ,בניכוי השווי הכספי של הובלת המטען האווירי הבלתי מלווה ,שהיה זכאי לו אילולא ויתר כאמור."}, {"p": 44, "t": "ד .מודגש כי המכולה הינה אישית ואין להכניס לתוכה טובין שלא שייכים לשליח ומשפחתו. ה .במקרה של משלוח מטען במכולה של  40רגל ,הנפח העודף במכולה הוא רכוש המשרד ולשליח אין זכות לכלול בו מטען של גורם אחר כלשהו."}, {"p": 44, "t": "ו .המשרד ייצור קשר עם חברת השילוח ,שתטפל בשינוע ובשילוח המטען ובכלל זה תספק לשליח חומרי אריזה ,ארגזים וכדומה ,למעט מזוודות. ז .חברת השילוח תהא אחראית לטפל במטען השליח משליחתו מישראל ועד פריקתו בבית השליח בחוץ-לארץ .המשרד ישתתף בהוצאות בגין דמי הובלה מביתו של השליח בישראל ועד לביתו ביעד השירות (.)door to door ח .המטען הימי/יבשתי יישלח מישראל בבת אחת וייכלל בשטר מטען אחד בלבד."}, {"p": 44, "t": "במקרים שבהם השליח שלח מטען מפוצל (רק ובכפוף לאישור המטה) ,המשרד יישא בהוצאות של מטען אחד ,הגדול יותר ובתנאי ,שהמטען נשלח לישראל ולא חורג מהמכסה. ט .אם לצורך שחרור המטען יזמין סוכן המכס את השליח לנמל – יוחזרו לשליח ההוצאות הקשורות לנסיעתו מביתו לנמל ובחזרה ,וזאת כנגד קבלות."}, {"p": 44, "t": "שינוע מטען אווירי בלתי מלווה לאור תהליך מורכב בין היתר ייתכנו עיכובים במשלוח ,אנו ממליצים לך לוותר על המטען האווירי הבלתי מלווה. יחד עם זאת ,ניתן לבחון אפשרות להמרת המטען האווירי הבלתי מלווה ,לתוספת מזוודות הכל בכפוף לתיאום בחינה ואישור ראש תחום משגורי פרט יבוא ויצוא במנה\"ר וראש היח' להסדרי נסיעות חו\"ל ובהינתן שחב' התעופה תאפשר התוספת כאמור."}, {"p": 44, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 45, "t": ".1זכאות א .שליח אשר העביר מטען ימי או יבשתי במכולה בגודל של  20רגל (בלבד) ,יהא זכאי גם למטען אווירי בלתי מלווה ,עבורו ועבור כל אחד מבני משפחתו הנלווים אליו. ב .במקרים מיוחדים ,שבהם אין למשרד אפשרות לשלוח מטען ימי ,השליח יהא זכאי למטען אווירי בלתי מלווה מוגדל ,מובהר שאין הכוונה לפיצול בין מטען ימי למטען אווירי מכל סיבה שהיא אלא ,במקרה בו לא ניתן כלל להוביל מטען"}, {"p": 45, "t": "ימי הכל בתיאום ואישור ראש תחום משגורי פרט יבוא ויצוא במנה\"ר. .2השתתפות המשרד א .השליח יהא זכאי להעברת מטען אווירי בלתי מלווה במשקל של  25קילוגרמים לנפש. ב .שליח שבוחר לא להעביר מטען אווירי בלתי נלווה לא יהא זכאי לכסף או לכרטיסי טיסה בתמורה."}, {"p": 45, "t": "ג .במשלוח מטען אווירי בלתי מלווה ,חברות התעופה מחשבות את מחיר המטען על פי נפחו ומשקלו .אם המטען הוא בעל נפח גדול מהמקובל ,הרי שתחשיב המשקל שייערך על ידי חברת התעופה יכלול גם את רכיב הנפח."}, {"p": 45, "t": "ד .במקרים שבהם אין למשרד אפשרות לשלוח מטען ימי ,השליח יהא זכאי למטען אווירי בלתי מלווה עד  600קילוגרם עבורו ,עד  600קילוגרם עבור בן זוגו ועד  300קילוגרם עבור כל אחד מבני משפחתו הנלווים אליו."}, {"p": 45, "t": "שינוע מטען אווירי מלווה .1זכאות שליח יהא רשאי לקחת עמו לטיסה מטען אישי (מזוודה) עבורו ועבור כל אחד מבני משפחתו ,המצויד בכרטיס טיסה בהתאם לכללי חברת התעופה עימה הוא יוצא."}, {"p": 45, "t": "מובהר במפורש שהמשרד לא יממן עלויות חורגות מעבר למותר ע\"י חב' התעופה, למעט המפורט בסעיף שינוע מזוודות ותוספת מזוודות שלהלן. .2אופן קבלת ההשתתפות השתתפות המשרד בגין תוספת מזוודות תבוצע בכפוף להצגת קבלות בלבד."}, {"p": 45, "t": ".3מודגש כי התוספת כאמור הינה בגין המטען בלבד ואין המשרד מממן עלות המזוודה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 46, "t": "טבלת סיכום זכאות בגין שילוח המטען מצב אלטרנטיבה משפחתי יבשתית/ימית יבשתי/ימי אווירי מכולה של 20 מכולה של 40 רגל רגל השליח בוחר במכולה של 20 במימון המשרד לא זכאי רגל מטען בלתי מלווה מטען מלווה מזוודות 25ק\"ג לאדם - במימון המשרד השליח יישא בהוצאות השליח בוחר רווק/ במכולה של 40 עד נשוי1+ רגל הכרוכות בהגדלת המכולה בניכוי השווי הכספי של מטען אישי במשקל של"}, {"p": 46, "t": "המטען האווירי עד  20ק\"ג או בהתאם הבלתי מלווה לרשום בכרטיס הטיסה. כאשר אין אפשרות ליבשתי/ימי השליח בוחר במכולה של 20 במימון המשרד לא זכאי לא זכאי רגל 600ק\"ג לאדם בטיסות בהן מאשרת מבוגר 300 ,ק\"ג חברת התעופה להעביר לילד  -במימון מזוודה אחת בלבד לכל המשרד נוסע ,מסייע המשרד 25ק\"ג לאדם - במימון המשרד בתוספת מזוודות ראה פירוט בהערה שלהלן* השליח בוחר נשוי2 +"}, {"p": 46, "t": "במכולה של 40 ויותר רגל במימון המשרד 600ק\"ג לאדם כאשר אין אפשרות לא זכאי ליבשתי/ימי מבוגר 300 ,ק\"ג לילד  -במימון המשרד מטען מזוודות (מטען מלווה) ,תוספת מזוודות בטיסה ארצה בתום שליחות ,הנך זכאי לקחת עמך מזוודות כמספר הנוסעים ,בהתאם להוראות חברת התעופה וכמפורט בכרטיס הטיסה."}, {"p": 46, "t": "מובהר במפורש שהמשרד לא יממן עלויות חורגות מעבר למותר ע\"י חב' התעופה ,למעט המפורט להלן: חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 47, "t": ".1תוספת מזוודות השתתפות המשרד: המשרד משתתף בתוספת מזוודות כדלהלן: א .לשליח רווק ,תאושר מזוודה אחת נוספת בלבד ,מעבר לזו המאושרת ע\"י חברת התעופה ב .לשליח נשוי ולשליח עם ילדים ,יאושרו שתי מזוודות נוספות בלבד בסה\"כ לכל המשפחה ,מעבר לאלה המאושרת ע\"י חברת התעופה."}, {"p": 47, "t": ".2בהמשך לאמור לעיל ,יודגש כי המשרד מממן עלות משלוח המזוודות בלבד ,אך לא מממן עלות רכישת המזוודות עצמן. .3גובה השתתפות המשרד בעלות בגין המטען במזוודות הנוספות: א .בטיסה היוצאת ישירות לארץ ,תקבל החזר של עד  $ 100תמורת קבלות לכל מזוודה נוספת."}, {"p": 47, "t": "ב .בכל אחת מטיסות הפנים ( )Connectionועד להגעה ליעד ממנו יוצאת הטיסה הישירה לישראל ,תקבל החזר של עד  $ 50תמורת קבלות לכל מזוודה נוספת. .4אופן קבלת ההחזר הכספי: א .עליך להגיש קבלות מקוריות על תשלום בגין מזוודות נוספות וכן עותק מכרטיס הטיסה, הכולל פירוט מסלול הטיסה .ההחזר הכספי יועבר לשכרך במסגרת \"גמר החשבון\" בהתאם לקריטריונים כמפורט להלן."}, {"p": 47, "t": "• שליח עובד משהב\"ט ,יגיש הקבלות ליח' למשאבי אנוש ומנהל בחו\"ל. • נספח צה\"ל ,יגיש את הקבלות למדור מעבר חו\"ל בקש\"ח. • שליח צה\"ל ,יגיש הקבלה לקצין הנסיעות הזרועי. שיגור המטען המטען יישלח לחו\"ל בשיטת \" \" DOOR TO DOORוהשירות יכלול:"}, {"p": 47, "t": "א .ביקור מקדים של נציג חברת השילוח בבית השליח בתיאום מראש לצורך הערכת נפח ותכנון האריזה והשילוח. ב .פירוק רהיטים  -השירות הינו לפירוק רהיטים בסיסי בלבד הכולל :מיטות הורים, מיטות ילדים ,שולחן אוכל ומטבח ושולחנות עבודה."}, {"p": 47, "t": "ג .אריזת החפצים בבית השליח. ד .המכלת המטען במכולה. ה .הובלה יבשתית לנמל המוצא. ו .הובלה ימית עד נמל היעד בחו\"ל. ז .טיפול מול שלטונות המכס בחו\"ל. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 48, "t": "ח .הובלת המטען לבית השליח בחו\"ל ופריקתו. ט .הרכבת רהיטים בסיסית  -אין התחייבות של החברה להרכבת רהיטים חדשים ,אלא רק רהיטים שפורקו ע\"י האורזים בארץ ,בהתאם לרשימה שפורטה לעיל."}, {"p": 48, "t": "י .פינוי האריזות הריקות מבית השליח ביעד (פינוי חד פעמי) ,ייעשה עד שבועיים מיום הגעת התכולה לדירה ובהתאם להודעת השליח. יא .השליח יוודא כי ,במועד הגעת המטען לחו\"ל ,הוא ישהה במקום השירות וזאת לצורך מילוי הניירת הדרושה לשחרור המטען .עיכוב בשחרור המטען כתוצאה מכך שהשליח אינו במקום השירות ,עלול לגבות עלויות גבוהות אשר יושתו על השליח ובאחריותו."}, {"p": 48, "t": "תהליך שיגור המטען לחו\"ל היערכות לאריזה כ 4-חודשים טרם יציאתך לשליחות הינך נדרש לתאם פגישה עם ר' תחום משגורי פרט יבוא ויצוא (לאחר קבלת הפנייה מיחידת חשבונות חו\"ל בתיאום מראש."}, {"p": 48, "t": "בפגישה מקבלים תדרוך וקובעים תאריך לאריזה ימית ואווירית. א .תידרש למסור את הפרטים האישיים כמפורט להלן: ב .כתובת מגורים בישראל. ג .זכאות למטען ימי  /אווירי. ד .מועד מתוכנן לאריזה."}, {"p": 48, "t": "ה .מועד מתוכנן לעזיבת הבית בארץ. ו. כתובת הבית בחו\"ל (במידה וידוע) ז .טלפון נייד בחו\"ל. ח .טלפון נייד בישראל. ט .תאריך נחיתה בחו\"ל. י. כתובת מייל פרטית. ביצוע הערכת נפח א .נציג חברת השילוח יגיע לבית השליח בתיאום מראש לביצוע הערכת נפח לתכולת הבית וזאת לצורך בדיקת התאמה הזכאות של השליח ולמניעת חריגות."}, {"p": 48, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 49, "t": "ב .לביקור זה יביא עמו הספק כ 20-קרטונים בגדלים שונים כדי לאפשר לך לארוז בעצמך חפצים אישיים החשובים לך ולמשפחתך. בסיום האריזה יש להשאיר קרטונים אלה פתוחים לצורך רישום התכולה ע\"י צוות האריזה ביום האריזה המיועד."}, {"p": 49, "t": "ג .ארגזי תלייה – הנך זכאי לקבלת  2ארגזי תלייה ביום האריזה לפי דרישה מראש .יש לעדכן את נציג חברת השילוח בהתאם  -ארגזי התלייה נועדו לאריזת :שמלות ,חליפות וכדומה ומיועדים לשילוח במטען הימי בלבד."}, {"p": 49, "t": "ד .בביקור זה ייקבעו חומרי האריזה הדרושים לאריזת המטען ,פירוק ריהוט ובדיקת הגישה לבית. ה .הספק ימסור לשליח ולמשרד את הערכתו (בכתב). ו. הספק מחויב בקבלת אישור מראש מהמשרד בגין שירותים נוספים כגון :שאטל/ מרחק הליכה/מעלית חיצונית/מעלון .וזאת במידה וקיימת בעיית גישה כלשהי."}, {"p": 49, "t": "במקרה שיופעל שרות נוסף כאמור לעיל ,בעת האריזה בארץ והפריקה בחו\"ל השליח יידרש לחתום על אישור הביצוע בנספח שלהלן . אישור זה מהווה אסמכתא לאישור תשלום לספק בגין השירות שניתן בפועל."}, {"p": 49, "t": "ז .אין לחתום על שירות שלא בוצע בפועל. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 50, "t": "נספח Accessorial Form / טופס שירותים נוספים CLIENT MAME / שם שליח: his is to confirm that the following services were provided at the time of packing or delivery."}, {"p": 50, "t": "מסמך זה מאשר שהשירותים הבאים סופקו ללקוח בזמן אריזת המטען או .פריקתו חתימת השליח חתימת ראש צוות Client Crew Signature: Leader Service שירותים שסופקו Provided Signature:"}, {"p": 50, "t": "Shuttle שאטל External Elevator מנוף/ סולמון ________כמות שעות By hours_________ Long carry 30 מרחק הליכה מעל מטר must sign on each line which service done – **חובה לחתום בכל שורה שבה בוצע השירות –\" \"שאטל\" או \"מרחק הליכה: ** ניתן לספק רק סוג אחד של שרות באותו הזמן Only one type of service can be provided at the same time: Either \"Shuttle\" or \"Long carry\"."}, {"p": 50, "t": "הערות comments Client signature Crew leader sign חתימת השליח חתימת ראש הצוות Date: Date: :תאריך : תאריך ראש היחידה למשא\"נ ומינהל בחו\"ל-קמי אוקונסקי:  כתיבה ועריכה- 2022 חוברת לשליח מהדורה"}, {"p": 51, "t": "קביעת מועד לאריזת המטען .1משך זמן העברת המטען הימי משתנה מיעד ליעד .תכנון מועד אריזת המכולה ייעשה בינך לבין ר' תחום משגורי פרט יבוא יצוא  ,במסגרת קבלת התדריך. לשליחים היוצאים לארה\"ב וקנדה  -משך זמן העברת המטען הימי הינו כ5-7- שבועות ,מהאריזה בבית השליח ועד ההגעה לבית השליח בחו\"ל."}, {"p": 51, "t": "לשליחים היוצאים לשאר ארצות העולם  -משך זמן העברת המטען הימי משתנה מיעד ליעד. על מנת לקבוע את התאריך המיטבי אשר יצמצם את זמן המתנת השליח למטען בחו\"ל ו/או זמן המתנת המטען ,בעת תכנון מועד אריזת המכולה ,נדרש השליח לתכנן הזמנים כדלהלן:"}, {"p": 51, "t": "א .מועד עזיבת הדירה בארץ. ב .מועד ההגעה לחו\"ל אל מול מועד יציאת האונייה מנמל המוצא. .2תכנון הזמנים כמפורט לעיל נועד למנוע עלויות אחסון ו/או עלויות נלוות לאי התאמת זמן ההגעה וקבלת המכולה בחו\"ל."}, {"p": 51, "t": ".3אריזת המטען במכולה א. ביום האריזה אמור להגיע צוות של  3-5עובדים בהתאם לגודל התכולה. ב. צוות האריזה יבצע את כל האריזה הנדרשת והמכלת המטען למכולה. ג. רשימות אריזה – צוות האריזה יכין רשימת תכולה של המטען והקרטונים לצורכי המכס .הרשימות יחתמו על ידך ועל ידי ר' צוות האריזה .יש לקבל העתק מרשימת האריזה."}, {"p": 51, "t": "ד. הרשימות מוגשות לשלטונות המכס לאישור לפני שליחת מטענך לחו\"ל. ה. רשימה חתומה על ידי המכס בארץ מהווה אסמכתא להחזרת הטובין בגמר השירות. ו. כל מה שהוצאתם הנכם זכאים להחזיר ללא תשלום מכס."}, {"p": 51, "t": "ז. בסיום ההמכלה ,המכולה תיסגר בפני השליח בסגר מיוחד ,כאשר מספר הסגר יינתן לשליח לצורך אימות בעת הפריקה בחו\"ל. ח. לאחר נעילת המכולה ,המטען מועבר ישירות לנמל היציאה."}, {"p": 51, "t": "ט. המכולה הינה אישית -אין להכניס לתוכה טובין שלא שייכים לשליח ולמשפחתו. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 52, "t": "י. יודגש כי קיים איסור מבחינת שלטונות המכס ביעד לשלוח במכולה ובמטען האווירי דברי מזון ,שתייה (כולל יין) וחומרי ניקוי ויכול לגרום לעיכוב בשחרור המטענים ולהשמדת התכולה שאסורה ביבוא."}, {"p": 52, "t": "יא. נזק שיגרם למטען המבוטח כתוצאה ממשלוח של נוזלים נשפכים אינו נכלל בביטוח המטען האישי. נזק שנגרם לחפצי השליח בעת האריזה או בזמן הפריקה ,או כל נזק אחר שנגרם לרכוש בבית השליח ידווח מיידית ע\"י השליח לר' תחום משגורי פרט במנה\"ר."}, {"p": 52, "t": "שליחים המגיעים לארה\"ב ידווחו  -למש\"ן ) 212-551-0425 ( .7 על חברת ההובלה ,פועליה ועובדיה ,נאסר לבקש סכום כלשהוא מהשליח בכל הקשור באריזת המכולה .למרות זאת ,השליח – עפ\"י שיקול דעתו ,יכול לתת תשר (טיפ) לעובדי החברה ,כמקובל בענף זה."}, {"p": 52, "t": "יב. יג. כיצד לפעול בהגעה לחו\"ל? שליחים המגיעים לארה\"ב – יש לדווח למש\"ן  ( 7ראה מעלה ) על הגעתם. שליחים המגיעים לשאר העולם – הסוכן המקומי אמור ליצור קשר בעת הגעת המטען."}, {"p": 52, "t": "במידה ועברו  3ימי עבודה וטרם נוצר קשר ,יש לעדכן במיידי את ר' תחום משגורי פרט במנה\"ר. העברת המטען מהנמל לבית השליח בחו\"ל התחייבות חברת ההובלה הינה: )1פריקת תוכן המכולה והכנסת החפצים לדירת השליח ,לכל קומה שתידרש."}, {"p": 52, "t": ")2פריקת המכולה תיעשה באור יום בלבד. )3השירות כולל הרכבת רהיטים בסיסית הכוללת :מיטות הורים ,מיטות ילדים ,שולחן אוכל ומטבח ושולחנות עבודה .אין התחייבות של החברה להרכבת רהיטים חדשים, אלא רק רהיטים שפורקו ע\"י האורזים בארץ ,בהתאם לרשימה שפורטה לעיל .מודגש בזאת כי מדובר בהרכבה בסיסית ופשוטה אשר אינה דורשת מומחיות של נגר."}, {"p": 52, "t": ")4פינוי האריזות הריקות מבית השליח (פינוי חד פעמי) ,ייעשה עד שבועיים מיום העברת הציוד לביתו ,בהתאם לבקשתו. )5על חברת ההובלה ,פועליה ועובדיה ,נאסר לבקש כל סכום שהוא בכל הקשור בפריקת המכולה .למרות זאת ,השליח יוכל עפ\"י שיקול דעתו לתת לסבלים תשר ( טיפ ) כמקובל בענף זה."}, {"p": 52, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 53, "t": "בכל בעיה המתעוררת במהלך פריקת המכולה בבית השליח ,ניתן להיוועץ בר' תחום משגורי פרט במנה\"ר050-6299647 , 03-6976992 : מייל – NAVA_LIBERMAN@MOD.GOV.IL לשליחים המגיעים לארה\"ב  /קנדה – לנציג יחידת השינוע במש\"ן .7 הטסת חיות מחמד ביציאה לשליחות המשרד אינו מאשר זכאות להטסת חיות מחמד ."}, {"p": 53, "t": "שליח אשר יחליט להטיס חיית מחמד כל ההוצאות העלויות בגין הטסת חיית המחמד ושהייה בשליחות יחולו על השליח לרבות שהייה במלון או כל הוצאה טרם השליחות במהלך השליחות ובתום השליחות .בהמשך לאמור באחריות השליח לוודא תוספת העלויות הנדרשות בעבור הטסה והבאת חיית המחמד שכן המשרד לא ישא בעלויות."}, {"p": 53, "t": "ביטוח המטען וכיסוי חפצי ערך .4אחריות ביטוח ושנוע מטענים א .זכאות )1השליח יהא זכאי לביטוח של מטענו ומטענם של בני משפחתו הנלווים אליו. )2השליח הוא האחראי הבלעדי לטפל בכל טענה ,במקרה שתעלה ,ישירות מול חברת הביטוח ,הכול לפי העניין .כל עזרה לשליח מצד המשרד ,או מצד הנציגות ,בכל טיפול כאמור ,לא תטיל על המשרד אחריות נוספת כל שהיא מעל לנקוב במפורש בהוראות אלה."}, {"p": 53, "t": "ב .השתתפות המשרד השתתפות המשרד בגין ביטוח המטען היא עבור שווי תכולה הנשלחת עד לתקרת הסכומים כמפורט בטבלה שלהלן: מצב משפחתי שליח היוצא מהארץ שליח בלבד 34,900דולר ארה\"ב שליח נשוי 36,700דולר ארה\"ב תוספת עבור כל ילד 2,700דולר ארה\"ב • מודגש כי ,במקרה של חריגה ממסגרת הביטוח ,יחויב השליח בתשלום פרמיה של  1.5%מסכום החריגה."}, {"p": 53, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 54, "t": "ג .אופן קבלת ההשתתפות )1ביטוח המטענים מהארץ למקום השירות ייעשה על ידי חברת הביטוח שתיקבע במשרד ,באמצעות הגורם המוסמך. )2הביטוח בחברת הביטוח ייעשה בדולרים ואף הנזקים יוחזרו לשליחים בדולרים .הוצאות שהיו לשליח בגין נזיקין בשקלים יוחזרו בשקלים."}, {"p": 54, "t": ")3לצורך ביטוח המטען בחברת הביטוח ,השליח יעביר לגורם המוסמך במשרד ומבעוד מועד את רשימת החפצים ,לרבות ערך הביטוח של כל פריט ופריט בדולרים ,לשם הכנת פוליסת הביטוח. )4במקרה של נזק ,אי-הגעת המטען ו/או חוסר במטען ,השליח יפנה מידית לקצין המנהלה בנציגות .האחרון יעביר לחברת הביטוח ,בכתב ,באמצעות הגורם המוסמך במשרד ,את מהות הנזק והיקפו המוערך .חברת הביטוח תנחה את השליח באשר להמשך הטיפול בתביעה."}, {"p": 54, "t": ")5הגורם המוסמך במשרד יבקש מחברת השילוח הערכה כלכלית בכתב לפני הזמנתה לאריזת המטען .במקרה שבו חברת האריזה מודיעה ,שלהערכתה נפח/משקל המטען עולה על המותר לפי ההוראות ,הגורם המוסמך במשרד יודיע לה בכתב מהו הנפח ו/או המשקל וסכום הביטוח שהמשרד יכסה ויציין ,כי השליח יישא ישירות בהוצאות עודף המטען או הביטוח."}, {"p": 54, "t": ")6דמי ביטוח בעד חפצים ,הנשלחים כמטען אווירי מלווה או בלתי מלווה, ינוכו מסך כל דמי הביטוח ,שהשליח זכאי להם בהתאם להוראות הנ\"ל. רשימות הביטוח .1יש להכין רשימה מפורטת עם רשימת תכולה שתשלח לארץ ."}, {"p": 54, "t": ".2ערך התכולה יירשם במטבע דולר. .3יש לחשב את ערך התכולה לפי ערכם הנוכחי של הפריטים (כפריט יד )2 .4לקביעת ערך התכולה ניתן להיעזר בהערכת שמאי ו/או פוליסה לביטוח הדירה."}, {"p": 54, "t": ".5הרשימות יועברו על ידך לאכ\"ס  ,לר' מע' כספים נספחויות ונציגויות הגב' נחמה פיירוזמן ,לצורך אישורן -מסמכים אלה יועברו טרם החזרה לארץ . .6הרשימות ישלחו למייל האזרחי ,בצירוף פרטים אישיים מזהים :שם ,ת\"ז , משלחת/נספחות ,טלפון נייד  ,גובה זכאות ."}, {"p": 54, "t": "nechama_firousman@mod.gov.il טלפון נייד0506291409 : .7פריט שלא יירשם לא ייכלל בביטוח . חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 55, "t": ".8לתשומת לבך ,אי העברת רשימות הביטוח בזמן ,משמעותה כי הציוד לא מבוטח ,וכל נזק לא יפוצה. הכיסוי הביטוחי של המשרד ,אינו כולל: .1תכשיטים ,מעבר לסכום המצוין לעיל במסגרת ביטוח חפצי ערך (מומלץ לקחת תכשיטים במטען היד ולא לשלוח אותם במכולה) .2כסף מזומן ,לרבות שטרות ,מטבעות ,צ'קים והמחאות נוסעים."}, {"p": 55, "t": ".3מזון ומשקאות מכל סוג ,תרופות ,וויטמינים ותוספי מזון. .4טלפונים ניידים ( מכשיר ותוכן ,לרבות תמונות השמורות במכשיר .יש לדאוג לגיבוי מבעוד מועד). .5תוכנה וחומר השמור במחשב  ,יש לדאוג לגיבוי מוקדם."}, {"p": 55, "t": ".6מסמכים ומסמכים מסחריים ,כרטיסים ,בולים ,כתבי יד ,סרטים ,משקפיים. כיסוי לחפצי ערך: פוליסת הביטוח מכסה חפצי ערך עד לסכום של  $ 1,000לפריט ו $ 5,000 -בסה\"כ. לצורך ביטוח חפצי ערך ואמנות שערכם מעבר לסכום הנ\"ל לפריט ו/או במצטבר ,על השליח להמציא אשור הערכה ממעריך מוסמך .המשרד יפעל לביטוח השליח עפ\"י ההערכה שהמציא ,אולם כל תוספת פרמיה שתידרש בגין ביטוח חפצי ערך שערכם"}, {"p": 55, "t": "המצטבר מעל  , $ 5,000תחול על השליח .כמו כן ,כל עלויות הערכת החפצים או מילוי דרישות המבטח לגביהן ,יחולו על השליח. במקרה של פגיעה במטען ,תביעת הביטוח תתבסס על רשימות התכולה ,שאושרה לקראת החזרה לארץ על ידי ר' מע' כספים נספחויות ונציגויות."}, {"p": 55, "t": "התביעה חייבת להיעשות מיד עם התגלות הנזק ,באמצעות יחידת ביטוח ותביעות של המשרד ,ולא יאוחר מ 120 -יום מיום אריזת הציוד בארץ השליחות .התביעה תוגש בכתב ,בחתימת השליח ותכלול את פירוט הנזקים."}, {"p": 55, "t": "ערכי הפיצוי הינם ערכי שיפוי לא כינון (ערך כינון :הכוונה לעלות הדגם היום .ערך השיפוי :הכוונה לערך הפריט במצבו ביום המקרה). לבירורים במקרה של תביעת ביטוח ,ניתן לפנות לגב' נגה אטלס – מנמ\"ח תביעות וביטוח ,טל'  03-7380806או במייל. noga_a@mod.gov.il :"}, {"p": 55, "t": "היעדרות לצורך אריזת המכולה טרם היציאה לשליחות ככלל המערכת אינה מקצה ימי חופשה מיוחדים לצורך התארגנות לקראת היציאה לשליחות .היה והשליח נזקק לחופשה כאמור לעיל ,יחויבו ימי החופשה ע\"ח מכסת ימי חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 56, "t": "החופשה הצבורה שלו בארץ. יחד עם זאת, עובדי משהב\"ט: עובדי משהב\"ט בלבד ,זכאים ל 2 -ימי חופשה ,ע\"ח ימי עבודה ,לצורך אריזת מכולה. אופן דיווח הזכאות ל 2 -ימי חופשה בגין אריזת מכולה:"}, {"p": 56, "t": "בדוח נוכחות ידווח העובד קוד עבודה – \"עבודה יום מלא\" ובהערה יציין סיבת היעדרות אריזת מכולה. שליחי צה\"ל :אינם זכאים להיעדר ע\"ח המערכת ואין אישור לתוספת ימי שכר חו\"ל בגין האמור לעיל."}, {"p": 56, "t": "חופשה לצורך התארגנות לפריקת מכולה בבית השליח בחו\"ל שליח(למעט שליחים לומדים/עמיתי מחקר) יוכל להיעדר ממקום העבודה בחו\"ל במשך יומיים ,לצורך ארגון דירתו במקום השירות ,לאחר פריקת המכולה .ימים אלה ייחשבו כימי עבודה ולא ינוכו לשליח מימי חופשת חו\"ל שלו."}, {"p": 56, "t": "מובהר כי היה ויחול שינוי בכללי חיוב ימי התארגנות לפריקת המכולה כאמורלעיל יחולו הכללים החדשים על השליחים ולא תהא טענה על הרעת תנאים או כל טענה אחרת. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 57, "t": "שכר חו\"ל חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 58, "t": "פרק  - 6שכר חו\"ל הוראה .1.2.1.מבנה השכר הוראה  1.2.1.1משכורת שליחים בחוץ לארץ שכר שליחים שכר השליחים בחו\"ל נקבע ע\"י הועדה הבין-משרדית לשכר ותנאי שירות בחו\"ל. סימולציית שכר :במפגש עם יח' השכר במסגרת ההכנות לשליחות ,יקבל השליח סימולציית שכר אישית בהתאם לנתוניו."}, {"p": 58, "t": "מטרת הסימולציה הינה לתת לשליח מושג כללי לגובה השכר אותו יקבל במקום השירות. מובהר כי הסימולציה מהווה הערכה בלבד ולפיכך ,אין בה משום התחייבות לשכר הנקוב אלא לצורך קבלת מושג כללי לגובה השכר אותו יקבל השליח."}, {"p": 58, "t": "א .שליחי משהב\"ט ונספחי הגנה ,יקבלו סימולציית שכר והסברים במסגרת פגישה אישית אותה יתאמו עם יחידת השכר לאחר שיעברו את התדרוך האישי ביחידה למשאבי אנוש ומנהל בחו\"ל. ב .שליחי צה\"ל המשוגרים באמצעות הזרועות ,ימלאו \"סט קליטת שליח צה\"ל\", אותו יקבלו מקצין הנסיעות הזרועי ושיועבר לאחר מילויו ליחידה למשאבי אנוש ומנהל בחו\"ל עם כל המסמכים הנדרשים המפורטים בו."}, {"p": 58, "t": "רק לאחר קליטתו של שליח צה\"ל במערכת כוח-האדם של משרד הביטחון, ולאחר שיעבור את התדרוך האישי ביחידה למשאבי אנוש ומנהל בחו\"ל ,יוכל לפנות ליחידת השכר לקבלת סימולציית שכר."}, {"p": 58, "t": "מיסוי שכר חו\"ל משכר השליח מנוכים מיסי החובה עפ\"י החוקים והשיעורים בישראל :מס הכנסה, ביטוח לאומי ומס בריאות. יובהר כי עובד שיש לו הכנסה נוספת ,הכנסת המשרד משכר חו\"ל תיחשב תמיד כהכנסה ראשונה ובאחריות העובד לבצע תיאום מס מול רשויות המס ולהעבירו למעסיקו השני."}, {"p": 58, "t": "בנוסף ,מומלץ לכל שליח שנדרש לכך מכל סיבה שהיא ,להתייעץ עם יועץ מס או רואה חשבון פרטי ,המתמחה בנושאי מיסוי וביטוח לאומי ,בשל המעבר לחו\"ל. משכורת חוץ לארץ משכורת חוץ לארץ כוללת שני חלקים – שכר ישראלי ושכר חוץ לארץ."}, {"p": 58, "t": "(\"שכר ישראלי\" מתייחס לשכר שליחי משהב\"ט בלבד לצורך הפרשות פנסיוניות ,דהיינו זהו לא שכר לתשלום אלא רק בסיס להפרשות הפנסיוניות .לשליחי צה\"ל ינוהל החלק הישראלי של השכר באמצעות מופ\"ת)."}, {"p": 58, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 59, "t": "רכיבי השכר א. הסכום הבסיסי בסיס השכר לשליחים בכל מדינות השירות הינו על סך ( ₪ 19,643נכון לינואר .)2022 סכום זה יתעדכן אחת לשנה בחודש ינואר. ב. תוספת דרגה -דירוג חוץ לארץ ודרגות חו\"ל השליחים בחו\"ל מדורגים בדירוג מיוחד הנקרא \"דירוג לעובדי חוץ לארץ\" ובו  10דרגות מדרגה  9ועד דרגה  .18לכלל הדרגות מוצמדת דרגת שהייה (לדוגמא +16 , +15 :וכדו', המשמעות היא תוספת של חצי דרגה נוספת)."}, {"p": 59, "t": "דרגתו של השליח בדירוג חוץ לארץ נקבעת לפי תקן המשרה בחו\"ל .תנאי הקידום בדרגות חו\"ל ,תואמים את אלה שבארץ. לכל שליח ייקבעו מספר \"נקודות קידום\" לפי דרגתו ושנות הוותק שלו המוכרות לצרכי שכר .הנקודות באות לידי ביטוי בתלוש השכר כרכיב תוספת דרגה."}, {"p": 59, "t": "(לדוגמא :שליח בדרגה תחילית  9זכאי ל 100-נק' קידום שזה הבסיס ,דרגה  4 - +9נק' קידום נוספות סה\"כ  104נקודות קידום ,דרגה  108 -10נק' קידום וכו') כל נקודת קידום מהווה תוספת של אחוז על הסכום הבסיסי ,כך שבדרגה  10לדוגמא יתווספו לשליח  8%לסכום הבסיסי כאמור בסעיף א."}, {"p": 59, "t": "באחריות שליח צה\"ל לוודא מול מופ\"ת שדרגת חו\"ל אשר נקבעה לו הינה הדרגה המקבילה לדרגתו ולתפקיד במשלחת. ג. תוספת ותק. לכל שנת וותק המוכר לשכר ,תינתן תוספת של  0.32נקודות קידום ."}, {"p": 59, "t": "להלן דוגמא לאופן החישוב : • שליח בדרגת חו\"ל  14עם וותק של  10שנים יחושב שכרו באופן הבא: שכר בסיס (נכון לשנת )2022 תוספת דרגת חול  14מזכה ב 140-נקודות קידום כלומר 40% תוספת– ()0.4*19,643 תוספת וותק  10שנים מזכה ב 3.2-נקודות קידום (-)0.32*10 ()0.032*19,643 ₪ 19,643 ₪ 7,857 ₪ סכום נקודות הקידום בגין תוספת דרגה וותק יעודכן במועדים הבאים:"}, {"p": 59, "t": "אחת לשנה ,במועד עדכון השכר ,במועד קבלת הדרגה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 60, "t": "תוספת קושי שירות ד. לשליחים המשרתים במקומות שהוכרו ע\"י הוועדה הבין-משרדית כמקומות קשי שירות, תתווסף תוספת קושי שירות ,ששיעורה נקבע עפ\"י נתוני חברת .ECA הועדה הבינמשרדית מחלקת את המדינות קשות השירות לרמות מ A -עד  Fוקובעת לכל סוג מדינה אחוז קושי שירות החל מ 0% -ועד  30%בהתאמה (ראה הוראת שות\"ש 1.2.9.5 והודעה .)1.2.1.1.2 תוספת קושי שירות ייחודי (שות\"ש ה )1.2.1.1.3"}, {"p": 60, "t": "ה. לשליחים המשרתים במקומות שהוכרו ע\"י הוועדה הבין-משרדית כבעלי קושי שירות ייחודי ,בהתאם לסקרי בטמ\"ח (מרכיבי פח\"ע ופלילית בלבד) ,יתווסף מרכיב קושי שירות ייחודי בשיעור שייקבע לכל מקום שירות בהתאם לרמת הסיכון."}, {"p": 60, "t": "שיעורו של מרכיב קושי השירות יהיה בדר\"כ  .4%במדינות מסוימות יהיה שיעור זה 8% או .12% תוספת קושי שירות חוזר ו. שליח שסיים תקופת שירות של  3שנים לפחות במדינה קשת שירות (רמה  Bומעלה) ,ויוצא לשרת בשליחות הבאה במדינה קשת שירות מרמה  Cומעלה ,זכאי ל\"תוספת שירות חוזר במדינה קשת שירות\" בשיעור .4% תוספת ריפוי ז."}, {"p": 60, "t": "תוספת ריפוי בשיעור  3%מהסכום המצטבר של התוספות שפורטו לעיל ,רכיב זה כלול רק בשכר שליחי משהב\"ט. התאמת יוקר מחיה ח. התאמת יוקר המחיה נועדה לבצע התאמה של שכר השליח ליוקר המחיה במדינת השירות .התאמת היוקר מחושבת ע\"ב שני רכיבים:"}, {"p": 60, "t": "מקדם יוקר מחיה -מקדם הנקבע ע\"י הוועדה הבין-משרדית לכל מקום שירות בהתבסס על נתוני חב'  ECAוביחס למדד עלויות המחיה במקום השירות .מקדמי יוקר המחיה יעודכנו אחת לשנה במועד עדכון השכר או במידה וחל שינוי משמעותי ביוקר המחיה במהלך השנה (מעל .)10% מקדם צריכה – מקדם הנקבע ע\"י הוועדה הבין-משרדית לכל שליח ,בהתבסס על נתוני חב'  ECAבהתאם למצבו המשפחתי של השליח."}, {"p": 60, "t": "מקדם הצריכה מעודכן אחת לשנה במועד עדכון השכר. התאמת יוקר המחיה מוצגת בתלוש השכר כרכיב \"פיצוי יוקר \". ט. פנסיה ,קופות גמל וקרנות השתלמות שליח משהב\"ט – ההפרשות לקופות השונות ימשיכו בהתאם לשכרו בארץ ערב יציאתו לשליחות."}, {"p": 60, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 61, "t": "שליחי צה\"ל -הטיפול בהפרשות לקופות השונות ייעשה באופן פרטני ע\"י השליח מול מופ\"ת. מענק ביגוד י. שליח מקבל מענק ביגוד במשכורתו הראשונה בחו\"ל. מענק הביגוד תואם את תקופת השליחות ,כפי שמצוינת באסמכתא."}, {"p": 61, "t": "המענק חייב במסים כחוק. תשלום המענק מתבצע פר שנה קלנדרית בהתאם לתקופת השליחות. עם הארכת האסמכתא ,יקבל השליח השלמה למענק הביגוד לפי החלק היחסי של התקופה המוארכת. במקרה של קיצור האסמכתא ,ינוכה החלק היחסי של מענק הביגוד משכרו של השליח."}, {"p": 61, "t": "סכום המענק לשנת שליחות נקבע בהתאם להרכב המשפחתי באסמכתא ערב היציאה לשליחות: מצב משפחתי תוספת שנתית רווק 1800ש\"ח שליח עם בן/בת זוג* 3,330ש\"ח תוספת עבור כל ילד 137ש\"ח ניכויים אישיים יא."}, {"p": 61, "t": "לעובד משהב\"ט ,ימשיך רצף הניכויים האישיים מתלוש השכר. אנשי הצבא ,באחריותם לפנות למופ\"ת ,טרם יציאתם לשליחות ,להסדרת הוראת קבע לניכוי חובות אישיים בצה\"ל. זכויות בביטוח לאומי יב."}, {"p": 61, "t": "א .על השליח לבדוק במוסד לביטוח לאומי ,טרם היציאה לחו\"ל ,מהם הכללים לשמירת זכויות בתקופת השליחות. ב .המשרד מעדכן את המוסד לביטוח לאומי על המשך תשלום קצבת ילדים בלבד."}, {"p": 61, "t": "כל שאר הנושאים מול ביטוח לאומי ,על השליח להסדיר באופן עצמאי. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 62, "t": "תשלומים בארץ שאינם חלים בשכר שליחים בחו\"ל א .חברות באגודות מקצועיות בארץ (לדוגמא :אגודת ההנדסאים והטכנאים) ,הינה חלק מהסכמים קיבוציים הנחתמים עפ\"י דירוגים. עובד בחו\"ל מדורג בדירוג חו\"ל ולפיכך ,אינו זכאי להחזר בגין אגודות מקצועיות."}, {"p": 62, "t": "ב\" .מענק יובל\" – עובד המדורג בדרוג חו\"ל ,אינו זכאי למענק יובל (דרוג חו\"ל אינו חתום על ההסכם של הדרוגים הזכאים למענק יובל). לפיכך ,שליחים אינם זכאים בתקופת השליחות למענק יובל (גם אם קיבלו אותו בארץ לפני היציאה לשליחות)."}, {"p": 62, "t": "בהתאמה לכך ,שליחי צה\"ל בחו\"ל ,אינם זכאים ל\"משכורת שלוש עשרה\" בתקופת שליחותם. ג .הבראה – עובד המדורג בדירוג חו\"ל אינו זכאי. ד .ביטוח/רישיון רכב לשליחי משהב\"ט  -עובד בדירוג חו\"ל אינו זכאי להחזר."}, {"p": 62, "t": "שליח עובד משהב\"ט שרכבו הפרטי היה מבוטח בארץ וקיבל החזר מהמשרד ,ינוכה החלק היחסי של ההחזר ששולם לו עבור התקופה ממועד יציאתו לשליחות ועד תום השנה. איסור קבלת תגמול ממקור זר חל איסור מפורש על קבלת תגמול כספי או הטבה ממוסדות ממשלתיים מקומיים או ממקור זר אחר ,לבד מגורמי מדינת ישראל (משהב\"ט ,צה\"ל ,ביטוח לאומי וכד') .במקרה של התלבטות ,יש להתייעץ מראש ולפני מעשה ,עם היחידה למשאבי אנוש ומנהל בחו\"ל."}, {"p": 62, "t": "שמירת זכויות פנסיה לבן/בת זוג של שליח. קיימת אפשרות שהמשרד ישתתף בשמירת זכויות פנסיה לבן/בת זוג של שליח ,שעבד בארץ לפני שליחותו ,מפריש כספים לטובת שמירת זכויות באופן עצמאי ואינו עובד (מנוע מלעבוד) בזמן שהותו בחו\"ל."}, {"p": 62, "t": "השתתפות המשרד אינה כוללת בן/בת זוג ,שהינו עובד משרד ממשלתי בפנסיה תקציבית, המשלם בגין שמירת זכויות סך של  6.2%משכרו .הסיבה הינה כי שיעור ההפרשה הנ\"ל לשמירת זכויות ,הינו לאחר הנחה שניתנה ע\"י משרדי הממשלה."}, {"p": 62, "t": "לצורך השתתפות המשרד בשמירת זכויות לבן/בת זוג של שליח ,צריכים להתקיים התנאים הבאים: • בן/בת הזוג מנוע/ה מלעבוד בתקופת השליחות בהתאם להגדרות ההוראה שלהלן: המשרד אסר עליהם לעבוד בשכראו שלא התקבלו לעבודה בנציגות ולא מחוץ לנציגות.חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 63, "t": "• קיים רצף הפקדות של לפחות  6חודשים טרם היציאה לשליחות. במידה ובן/בת הזוג עומד בתנאים המצטברים הנ\"ל ,ניתן לבצע השתתפות בשמירת זכויות פנסיה ובכפוף להצגת מסמכים נדרשים שיפורטו ע\"י יחידת השכר בהתאם לפניית השליח בבקשת ההשתתפות הנ\"ל."}, {"p": 63, "t": "ההחזר מתבצע בתלוש השכר של השליח והוא חייב במס עפ\"י חוק. את בקשת ההחזר יש להגיש לכל המוקדם כל רבעון ועד חצי שנה. קצובת שכר דירה בחו\"ל קצובת שכר הדירה מאושרת ע\"י המטה  -ראש היח' למשא\"נ ומינהל בחו\"ל בלבד ומשולמת בכפוף לחתימה על חוזה שכירות עפ\"י התנאים שנקבעו בשות\"ש ואושרו ע\"י המטה כאמור."}, {"p": 63, "t": "הקצובה משולמת לשליח במסגרת השכר למעט שכירת דירת שרד לראש נציגות/נספחות המשולמת באמצעות הנספחות (ראה פירוט בפרק  -שכירת דירה בחו\"ל). דמי ייצוג והחזר הוצאות אירוח ראה פרק הנחיות החשב הכללי יישום לאופן השימוש בתקציב הוצאות ייצוג ,אירוח ואחזקת בית לשליחים עובדי מדינה המשרתים בחו\"ל."}, {"p": 63, "t": "בתקופת השירות בחו\"ל ,מקיימים השליחים קשרי עבודה מקצועיים עם עמיתים מקומיים. במסגרת זו ,קיימות הוצאות ייצוג ואירוח ,אותן נדרש השליח להוציא מכספו. לבעלי תפקידים בחו\"ל ,שהוגדרו ע\"י המשרד נקבעת מכסת זכאות שנתית בהתאם לתפקידם .ניתן לקבל החזרים בגין הוצאות ייצוג ואירוח בהתאם להגדרות בשות\"ש ,עד גובה המכסה המאושרת ובלבד שהוצאו כנגד חשבוניות או קבלות."}, {"p": 63, "t": "דמי הייצוג משולמים בשכר חו\"ל של השליח כנגד הצגת קבלות בלבד ובמסגרת מילוי תפקידו. מובהר כי דמי הייצוג לא נועדו לאירוח עובדי המשרד ,בני משפחה ,ישראלים המבקרים במקום או עמיתים ישראליים מנציגויות אחרות הפוקדים את הנציגות בתפקיד או באורח פרטי."}, {"p": 63, "t": "לשליח עומדת הזכאות לקבלת מקדמה חד פעמית לכל תקופת השליחות בגין דמי ייצוג בגובה  1/12מהמכסה השנתית המאושרת. השליח ימלא טופס בקשה למקדמת דמי ייצוג והמקדמה תועמד לקיזוז משכר השליח בחודש השכר שקודם לחודש סיום השליחות."}, {"p": 63, "t": "רכב בחו\"ל .1רכב פרטי משכורת חו\"ל מהווה שכר כולל ,ולפיכך לא ניתנת תוספת כספית מיוחדת לצורך אחזקת רכב פרטי של השליח. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 64, "t": "על השליח חלה חובה לבטח את רכבו הפרטי עפ\"י חוקי המקום. היה ומתוקף תפקידו ,נדרש השליח מעת לעת (ולא באופן קבוע) ,להשתמש ברכבו הפרטי לצרכי נסיעות בתפקיד ,יוכל לקבל על כך החזר כספי בהתאם להוראת \"נסיעות בתפקיד ברכב פרטי\" ,שבהוראות השות\"ש."}, {"p": 64, "t": ".2רכב צמוד לשליחים בחו\"ל קיימים בעלי תפקידים ,להם מוקצה רכב צמוד בחו\"ל ,בהתאם לתפקידם או דרגתם. במקרה זה ,משולמות כל הוצאות הרכב ע\"ח תקציב הנציגות או הזרוע המשגרת."}, {"p": 64, "t": "כל השליחים ,שלהם רכב צמוד בחו\"ל ,מחויבים במשכורתם בגין זקיפת הטבה לרכב – בהתאם לכללי המס בישראל. רכב צמוד לראשי משלחות ונספחי הגנה ,ראה הרחבה בפרק  -תנאי שירות ייחודיים לר' נציגויות."}, {"p": 64, "t": "לראש נציגות/נספחות /שליחי צה\"ל מדרגת אל\"מ בעלי רכב צמוד בחו\"ל, המשלמים בשכרם זקיפת הטבה בגין הרכב הצמוד ,זכאים לקבלת רכב במסגרת הגעה לארץ ,במהלך השליחות ,ללא חיוב נוסף מלבד זקיפת ההטבה בשכר חו\"ל – הזמנת הרכב עבור שליח משהב\"ט בלבד תתואם עם יח' משא\"נ ומינהל בחו\"ל ולנספחים ושליחי צה\"ל תתואם ע\"י קצין נסיעות זרועי ,מבעוד מועד לפחות  3שבועות טרם ההגעה .3חניה לרכבי שליחים"}, {"p": 64, "t": "המשרד מממן עלות חניה בסמוך למשרד בלבד לרכבו של שליח (רכב פרטי /צמוד) .אין המשרד מממן עלות חניה ליד בית השליח וכן לא מאושר לבצע המרות בין הזכאות לחניה ליד המשרד עבור מימון חניה ליד הבית."}, {"p": 64, "t": "טלפון נייד בחו\"ל השליחים מקבלים בתקופת השירות בחו\"ל טלפון נייד מהמשלחת  /נספחות ומשלמים השתתפות עצמית לפי הכללים שנקבעו במשרד ובהתאם למכרז חשכ\"ל. בגין השימוש בטלפון הנייד ,מחויב שכר השליח בזקיפת הטבה בגין הטלפון."}, {"p": 64, "t": "הלוואות על שליחים בחו\"ל חל איסור מוחלט לקבל הלוואות פרטיות בארץ השירות .המשרד מסייע לשליח החדש בהתארגנות במקום השליחות באמצעות מתן מקדמות והלוואות שונות. כללי • הזכאות לקבלת הלוואה/מקדמה ניתנת אך ורק לאחר היציאה לשליחות."}, {"p": 64, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 65, "t": "• ההלוואות והמקדמות כמצוין לעיל אינן נושאות ריבית. • בשל העובדה שאין ריבית על ההלוואות /מקדמות ,אזי ,קבלת ההלוואה נחשבת הטבה החייבת במס .המשרד יבצע זקיפת הטבה ויגלמה בתלוש השכר של השליח."}, {"p": 65, "t": "סוגי ההלוואות לשליחים בחו\"ל .1הלוואה לסידורים ראשוניים  -השליח יהא זכאי להלוואה בגובה בסיס השכר המעודכן. .2הלוואה לרכישת רכב – (ראשון). רכב לרכישת להלוואה זכאי יהא א .השליח הלוואה לרכישת רכב ראשון תהיה בגובה מחיר הרכב בפועל ועד לתקרה של .₪ 65,000 ב .רכישת רכב שני מאושרת במדינות מסוימות בהתאם למפורט בהוראת השות\"ש .הסכום המרבי להלוואה לרכב שני הינו .₪ 32,500"}, {"p": 65, "t": "ג .יודגש כי ההלוואה לרכב תאושר רק במקרה של רכישת רכב ולא ליסינג או שכירות. ד .השליח נדרש להציג למנהל כ\"א  /קצ\"מ הנציגות וחשב אזורי אסמכתת תשלום/קבלה על רכישת הרכב ,תוך חודשיים ממועד קבלת ההלוואה."}, {"p": 65, "t": ".3הלוואה לרכישת ריהוט  -שליח יהא זכאי להלוואה בגובה של עד  ₪ 18,000לצורך ריהוט דירתו בחו\"ל .השליח נדרש להציג למנהל כ\"א /קצ\"מ הנציגות ולחשב אזורי העתקי קבלות על רכישת הריהוט לא יאוחר מחודשיים ממועד קבלת ההלוואה."}, {"p": 65, "t": ".4הלוואת מקדמה בגין תשלום שכ\"ד מראש – שליח יהא זכאי להלוואה בגובה תשלום חודש שכירות. .5הלוואת מקדמה בגין פיקדון שכר דירה או ערבות  -במקרים בהם השליח נדרש לשלם פיקדון שכ\"ד  ,השליח יהא זכאי להלוואה בגובה תשלום חודש שכירות ועד לתקרה של שלושה חודשי שכירות בכפוף לחוזה ולאישור המשרד."}, {"p": 65, "t": "אופן קבלת ההלוואות: בתחילת השליחות ,מעבירה יחידת השכר במשהב\"ט לחשבות השכר האזורית את פירוט זכאויות השליח להלוואות. מובהר כי אין להגיש באופן עצמאי לחשבות האזורית את טופס הזכאות המועבר במסגרת סימולציית השכר."}, {"p": 65, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 66, "t": "שליח שמבקש לקבל הלוואה/מקדמה יפנה לחשב האזורי וימלא טופס בקשה להלוואה וכתב התחייבות בו מתחייב השליח בכתב להחזיר למשרד הביטחון את מלוא גובה ההלוואות שקיבל ,עד תום תקופת השליחות."}, {"p": 66, "t": "ההלוואות/המקדמות מועברות לחשבון הבנק של השליח בחו\"ל ולאחר מכן ,מתבצעת התחשבנות בתלוש השכר .ניכוי ההלוואות/מקדמות ייעשה במטבע הרשום בתלוש השכר, בתשלומים חודשיים שווים .מספר התשלומים ייקבע על ידי המשרד ויהיה לכל היותר מספר חודשי השירות הנותרים לשליח עד לסיום תפקידו או  36תשלומים ,הנמוך מבניהם כשבחודש האחרון לשליחות לא מתבצעת התחשבנות בגין הלוואות."}, {"p": 66, "t": "שליח אשר יסיים את תפקידו טרם ניכוי ההלוואה במלואה יחויב בניכוי היתרה ממשכורתו האחרונה בחוץ לארץ או מכל סכום אחר הנזקף לזכותו. הלוואות אישיות לשליחים עובדי משהב\"ט שליחים עובדי משהב\"ט ,מתוקף היותם עובדי המשרד ,זכאים לקבלת הלוואות באופן זהה לקריטריונים הניתנים לעובדים בארץ ,למעט הלוואה לרכב שניתנת בשנת השליחות האחרונה בלבד לקראת החזרה ארצה."}, {"p": 66, "t": "לצורך קבלת ההלוואות הנ\"ל ,יש למלא טופס מתאים (הטופס נמצא באתר \"רימון\" של המשרד או שניתן לקבלו מהיחידה למשאבי אנוש ומנהל בחו\"ל) ,לצרף המסמכים הרלוונטיים ולהגיש את כל החומר המקורי ליחידה למשאבי אנוש ומנהל בחו\"ל .ההלוואות ניתנות באמצעות בנק אוצר החייל."}, {"p": 66, "t": "מימוש ההלוואות לשליחים עובדי משהב\"ט השליח רשאי לממש את זכאותו ישירות מול בנק אוצר החייל בהתאם לכללים הנהוגים במשרד. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 67, "t": "חינוך שכ\"ל ילדי שליחים חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 68, "t": "פרק  – 7השתתפות בהוצאות חינוך ילדים הוראה .1.2.4.חינוך הוראה  1.2.4.1השתתפות בהוצאות חינוך בגין ילדים בגילאי 0-3 הוראה  1.2.4.2השתתפות בהוצאות חינוך בגין ילדים בגילאי 3-4 הוראה  1.2.4.3השתתפות בהוצאות חינוך בגין ילדים בגילאי  4-5ו6-18 - למען הסר ספק ,כל שינוי בהוראת השות\"ש יחול על המפורט בחוברת זו והוראת השות\"ש אשר תפורסם תגבר על האמור בחוברת."}, {"p": 68, "t": "השתתפות המשרד בהוצאות חינוך – כללי מדינת ישראל משתתפת בהוצאות חינוך של ילדי שליחים השוהים עימם בחו\"ל כפי שנהוג בארץ ,בהתאמות הנדרשות ובהתאם ליעדים השונים של הנציגויות."}, {"p": 68, "t": "ילדי שליחים המצטרפים להוריהם לשליחות בחו\"ל ,זכאים להמשך לימודים סדירים בארץ השירות ולהשלמת פערים לימודיים ,שנגרמו בגין השליחות. האחריות לרישום הילדים לגנים ולבית הספר חלה על השליח .השליחים זכאים למימון ,או השתתפות במימון (תלוי בגיל) ,עבור לימוד ילדיהם במוסדות חינוך במקום השליחות."}, {"p": 68, "t": "רשות המיסים קובעת תקרת פטור ממס על שכר לימוד של ילדי שליחים בחו\"ל. כל סכום שכר לימוד העולה על תקרת הפטור ,ימוסה כחוק. רישום ילדים לבית ספר האחריות לרישום הילדים לבית הספר חלה על השליח."}, {"p": 68, "t": "לצורך רישום ילדים לבתי הספר בחו\"ל וככל שהדבר נדרש במסגרת טפסי הרישום של ביה\"ס, יש להעביר ביחד עם טפסי הרישום :תעודות ,ציונים והערכות ממנהל בית-הספר והמורים בארץ ,מתורגמים לאנגלית  /שפת המקום."}, {"p": 68, "t": "קיימות מדינות בהן נדרש אישור נוטריון לתרגום המסמכים  /התעודות הנ\"ל. יש לוודא מראש הצורך בחתימת הנוטריון כאמור לעיל ולעדכן מבעוד מועד את היח' למשא\"נ ומינהל בחו\"ל/ק.נסיעות זרועי בעת הבקשה לתרגום המסמכים."}, {"p": 68, "t": "המשרד/צה\"ל מממן עלות תרגום תעודות בית הספר של הילדים והנוטריון אם נדרש. אבחונים לילדים בעת הרישום לבית הספר בחו\"ל ,מומלץ להציג אבחונים שיש לילד מתקופת לימודיו בישראל אבחון דידקטי ,אבחון פסיכו-דידקטי וכל אבחון אחר ,שרלוונטי להרשמה ולצרכיםמיוחדים של הילד בתקופת לימודיו בחו\"ל."}, {"p": 68, "t": "המשרד אינו מממן עלות אבחונים לפני השליחות. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 69, "t": "את דו\"ח האבחון ,יש לתרגם מעברית לשפה המקומית הרלוונטית אבחונים טרם היציאה לשליחות: לקראת היציאה לשליחות ,בעת הרישום לבית הספר בחו\"ל ,מומלץ להציג אבחונים שיש לילד מתקופת לימודיו בישראל  -אבחון דידקטי ,אבחון פסיכו-דידקטי וכל אבחון אחר, שרלוונטי להרשמה ולצרכים מיוחדים של הילד בתקופת לימודיו בחו\"ל."}, {"p": 69, "t": "מודגש שהמשרד אינו מממן עלות אבחונים לפני השליחות. את דו\"ח האבחון ,יש לתרגם מעברית לשפה המקומית הרלוונטית. אבחונים במהלך השליחות: אם במהלך תקופת השליחות מתקבלת המלצה מקצועית מגורם פדגוגי מוסמך ,לבצע לילד אבחון ,יעביר מנהל כ\"א  /קצ\"מ הנציגות את ההמלצה ליח' למשאבי אנוש ומנהל בחו\"ל .כל מקרה ייבחן לגופו ותינתן החלטה בנוגע למימון ביצוע האבחון."}, {"p": 69, "t": "בכל מקרה ,לא יאושר החזר כספי בדיעבד ,עבור אבחון שבוצע ללא קבלת האישור כאמור לעיל .היה ויתקבל אישור לכיסוי עלויות אבחון ,ישתתף המשרד ב 80%-מעלות האבחון. המשרד לא יממן עלות טיסה לארץ לצורך ביצוע אבחון."}, {"p": 69, "t": "תהליך התשלום למוסדות החינוך וההתחשבנות עם השליח א .השליח יעביר לקצין המנהלה  /מנהל כ\"א את הפרוספקט של הגן  /בית הספר ,שבו מצוינים בפירוש תאריכי הלימוד וכן מפורטים בו מרכיבי עלות שכר הלימוד ,לרבות :הסעות, ארוחות ,עזרי לימוד ,טיולים ,חוגים ,תלבושת אחידה ועוד."}, {"p": 69, "t": "ב .קצין המנהלה  /מנהל כ\"א יוודא שלאורך כל תקופת הלימוד ,לומדים הילדים באותה מסגרת ,עם אותן גננות  /מורות ובאותו מבנה ג .השתתפות המשרד תשולם ב 10-תשלומים שווים בתלוש השכר של השליח."}, {"p": 69, "t": "השתתפות במעונות יום עבור ילדים עד גיל ( 3טרום-טרום חובה) מעונות יום אשר יוכרו לצורך השתתפות המשרד יהיו בעלי האישורים הנדרשים להפעלת מעונות יום על פי הכללים המקומיים."}, {"p": 69, "t": ".1המשרד לא ישתתף בדמי הרישום למעונות היום. .2הזכאות להשתתפות בהוצאות מעונות יום הינה עבור ילד שטרם מלאו לו  3שנים ביום תחילת שהותו במעון יום. .3אין זכאות להשתתפות בעלות ארוחות ,שאינן כלולות בשכר הלימוד וכן בגין הסעות לגן."}, {"p": 69, "t": ".4תקרת ההוצאה המוכרת עבור מעונות יום היא  1,000דולר בחודש עבור כל ילד ,למעט הנציגויות המוחרגות המפורטות בנספח א' בהוראה  –1.2.4.1תקרת ההוצאה המוכרת. (ראה דוג' בטבלת תקרת ההוצאה המוכרת לפי נציגויות  -בסעיף  11להלן)."}, {"p": 69, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 70, "t": ".5המשרד לא ישתתף ב 500-הדולר הראשונים של העלות למעונות יום לחודש ,עבור כלל ילדי השליח (החישוב הוא עבור משפחה). .6המשרד ישתתף ב 50%-מעלות מעון היום שמעבר ל 500-הדולר הראשונים בחודש עד לתקרת ההוצאה המוכרת על פי המפורט בסעיף ( 1ראה דוגמאות בנספח ב' – דוגמאות לחישוב סכומי השתתפות)."}, {"p": 70, "t": ".7השתתפות המשרד בעלות מעון יום היא בגין שהות של עד  9שעות ביום ולמשך  10חודשי פעילות בשנה . .8בשהות מעל  9שעות ביום ו/או מעל  10חודשי פעילות בשנה ,השתתפות המשרד תחושב כלהלן:"}, {"p": 70, "t": "המשרד יפחית מסכום ההוצאה בפועל (טרם חישוב ההשתתפות) את החלק היחסי העולה על  9שעות ו/או על  10חודשי פעילות המעון .למען הסר ספק ,השתתפות המשרד לא תעלה על הקצובות החודשיות המופיעות בהוראה זו ,בהכפלה ב 10-חודשים .9אופן קבלת ההשתתפות:"}, {"p": 70, "t": "שליח זכאי יגיש לחשב האיזורי טופס שות\"ש \"בקשה להשתתפות במעונות יום עבור ילדים עד גיל  ,\"3מס' ט 1.2.4.1.1 .בתחילת כל שנה בצירוף המסמכים הבאים: א .אישור כי המעון הוא מעון מוסדר ורשמי ב .אישור מהמעון על שעות פעילות המעון ,עלות המעון ומרכיביו."}, {"p": 70, "t": "ג .קבלות על הוצאות החינוך במעון היום. .10השתתפות בגין מעון יום תועבר לשליח באופן הבא א .שליח המשלם מראש בתחילת השנה יקבל את סכום ההשתתפות בתשלום אחד. ב .שליח המשלם חודש בחודשו ,יקבל את סכום ההשתתפות באופן חודשי."}, {"p": 70, "t": "ג .במקרה שבו השליח שילם למעון מראש וילדו עזב את המעון באמצע שנת הלימודים ,יקבל השליח את היתרה המגיעה לו ויחזיר סכום זה למשרד. ד .ההשתתפות תשולם לשליח בתלוש המשכורת במטבע התשלום למעון ותחושב לפי שער חליפין שוטף, .11להלן תקרת ההוצאה המוכרת במעונות יום (בהתאם לנספח א' להוראת שות\"ש )1.2.4.1 וכן דוגמא לחישוב סכומי ההשתתפות (בהתאם להוראת שות\"ש  1.2.4.1נספח ב')."}, {"p": 70, "t": "מודגש כי במקרה של שינוי ההוראה מהמפורט בחוברת זו ,תיקבע הוראת השות\"ש בכל עת. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 71, "t": "נספח א' להוראת שות\"ש 1.2.4.1 תקרת ההוצאה המוכרת  -דוגמא תקרת ההוצאה המוכרת במעונות יום נציגות סמל הנציגות מטבע תקרת ההוצאה המוכרת וושינגטון 2,000 דולר ניו יורק 2,000 דולר לוס אנג'לס 1,800 דולר שיקאגו 1,200 דולר סן פרנסיסקו 1,600 דולר סאו פאולו 1,300 דולר הלסינקי 1,000 אירו שטוקהולם 2,000 דולר לונדון 1,600 ליש\"ט סינגפור 1,300 דולר שנחאי 1,200 דולר גוואנג'ו"}, {"p": 71, "t": "1,200 דולר קנברה 1,300 דולר לואנדה 1,500 דולר האג 1,730 יורו חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 72, "t": "נספח ב' להוראת שות\"ש 1.2.4.1 דוגמאות לחישוב סכומי השתתפות עלות עלות החינוך שליח מס. בפועל (לדוגמא) ילד (ללא דמי תקרת ההוצאה 500דולר ראשונים הפרש בין  500דולר עבור כל ילדי המשפחה ראשונים לבין תקרת יחד  100% -השתתפות ההוצאה המוכרת - השליח 50%השתתפות השליח המוכרת מעבר לתקרה המוכרת - סך סך 100% השתתפות השתתפות השתתפות המשרד השליח השליח רישום) השתתפות השתתפות"}, {"p": 72, "t": "השתתפות השתתפות השתתפות השליח המשרד השליח המשרד השליח א 1,000 ב 1,000 ג 1,200 1,000 ד 1,350 1,000 1,100 ה 1,200 2,000 1,000 1,000 1,200 1,000 1,200 1,000 1,000 1,000 ו ז השתתפות בהוצאות חינוך גיל ( 3-4טרום חובה) הוראת שות\"ש 1.2.4.2 גני ילדים אשר יוכרו לצורך השתתפות המשרד יהיו בעלי האישורים הנדרשים להפעלת גני ילדים על פי הכללים המקומיים."}, {"p": 72, "t": "דמי רישום: זכאות לדמי רישום: שליח שילדיו בגילאי טרום חובה (גילאי  ,)4-3בהתאם לתאריכי הלידה שמשרד החינוך מפרסם מידי שנה (ראה אתר משרד החינוך חוזרי מנכ\"ל( (להלן' :ילד' או 'ילדים') ,יהא זכאי להשתתפות בדמי רישום בעבור ילדו פעם אחת לכל תקופת הלימודים של הילד (מגן טרום חובה עד סיום הלימודים – פעם אחת במקום השירות)."}, {"p": 72, "t": "ילד אשר אינו עומד בתנאי הזכאות כפי שנקבעו בחוזר מנכ\"ל משרד החינוך והגיע לגיל 3 במהלך השנה יהא זכאי להחזר הוצאות על פי הוראה .1.2.4.1 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 73, "t": "השתתפות המשרד בדמי רישום המשרד ישתתף באופן חד-פעמי ב 75%-מדמי הרישום לגן טרום חובה עד לתקרה של 1,200 דולר ,עבור כל ילד (.)75% ∗ 1,200 השתתפות המשרד בשכר לימוד: .1עבור שני הילדים הראשונים ,המשרד ישתתף במלוא ההוצאה בפועל עד  1,000דולר בחודש ,עבור כל ילד."}, {"p": 73, "t": "בהוצאה בפועל שמעל  1,000דולר בחודש ,המשרד ישתתף ב 75%-מההפרש העולה על  1,000דולר ,ועד השתתפות חודשית כוללת של  1,600דולר עבור כל ילד ( ,)75% ∗ 600למעט הנציגויות המוחרגות (ראה נספח א' בהוראה )1.2.4.2 .2עבור הילד השלישי ומעלה המשרד ישתתף במלוא ההוצאה בפועל עד  1,600דולר בחודש אחוז השתתפות המשרד בהוצאות חינוך חודשיות סמל הנציגות נציגות כלל נציגויות טווח"}, {"p": 73, "t": "טווח טווח מספר להשתתפות להשתתפות להשתתפות מטבע ילד של 0% של 75% של 100% 1,2 0-1,000 ומעלה 0-1,600 1,0001,600 מעל 1,600 דולר חריגים 1,2 0-1,880 סן פרנציסקו ומעלה 0-2,600 1,2 0-1,595 ומעלה 0-2,315 ומעלה 0-2,315 בייג'ינג 1,8802,600 1,5952,315 מעל 2,600 מעל 2,600 מעל 2,315 דולר דולר .3השתתפות המשרד בשכר הלימוד עבור גן טרום חובה היא בגין שהות עד  9שעות ביום ו/או"}, {"p": 73, "t": "10חודשי פעילות בשנה .לעניין זה יובהר ,חודשי הפעילות הם החודשים המקבילים לתקופת הלימודים השנתית המקובלת במקום השליחות ,ובאם אינה מוגדרת כזו - המקבילה בישראל ,קרי חודשים ספטמבר עד יוני."}, {"p": 73, "t": ".4בשהות מעל  9שעות ביום ו/או  10חודשי פעילות בשנה ,השתתפות המשרד תחושב כלהלן: חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 74, "t": "המשרד יפחית את החלק היחסי מסכום ההוצאה בפועל העולה על  9שעות ו/או על  10חודשי פעילות הגן. למען הסר ספק ,השתתפות המשרד לא תעלה על הקצובות החודשיות המפורטות בהוראה זו, בהכפלה בעשרה חודשים."}, {"p": 74, "t": ".5ארוחות זכאות: שליח אינו זכאי להשתתפות בהוצאות בגין ארוחות ילדיו בגן טרום חובה. השתתפות המשרד: )1בגן טרום חובה ,המספק שירותי הזנה ,אך גובה סכום כולל בלי פירוט ההוצאה, ינוכה סך של  10%מעלות שכר הלימוד בעד ארוחות .למען הסר ספק ,ראשית יש לנכות עלות זו משכר הלימוד הכולל ולאחר מכן יש לבחון את החזר ההוצאה בגין השתתפות בשכ\"ל כמפורט בסעיף שלעיל."}, {"p": 74, "t": ")2המשרד לא יגבה משליח השתתפות של  10%בגין ארוחות המוגשות בגן אם ילדו של השליח אינו אוכל בגן מטעמי כשרות או מגבלה בריאותית. אופן קבלת ההשתתפות אופן השתתפות המשרד כמפורט בסעיף  7שלהלן .6הסעות זכאות :שליח זכאי להשתתפות המשרד בהוצאות עבור שירותי הסעות (לא כולל מוניות) לילדו הלומד בגן טרום חובה מביתו ואל מוסד הלימודים ובחזרה ,בהתקיים כלל התנאים הבאים:"}, {"p": 74, "t": ")1המרחק מביתו של השליח לגן בו לומד הילד עולה על  2ק\"מ (מרחק הליכה בדרך עבירה להולכי רגל). )2הממונה במשרד אישר כי בטווח של עד  2ק\"מ מביתו של השליח לא קיים גן מתאים אשר הסכים לקבל את הילד בגינו ניתנת ההשתתפות לשירותיו."}, {"p": 74, "t": ")3ההשתתפות תינתן עבור שירותי הסעה הניתנים על ידי מוסד הלימודים ,או המאורגנים על ידי גוף שלטוני (מרכזי/מקומי) המאושר על ידי המשרד במדינת השירות. )4השתתפות המשרד תעמוד על  50%מעלות ההסעה ,ולא יותר מ 1,000 -דולר בשנת לימודים ,עבור כל ילד."}, {"p": 74, "t": ".7אופן קבלת ההשתתפות בגין דמי הרישום ,שכר לימוד ,ארוחות והסעות: תאריכי הלידה של הילדים ,שהוראה זו מתייחסת אליהם ,יוגשו על ידי השליח לנציגויות מידי שנה לקראת פתיחת שנת הלימודים (ראה אתר משרד החינוך חוזרי מנכ\"ל(."}, {"p": 74, "t": "שליח הזכאי לקבלת ההשתתפות יגיש לקצ\"מ/חשב טופס שות\"ש\" ,בקשה להשתתפות בהוצאות חינוך עבור ילדים בגילאי  ,\" 3-4מס' ט 1.2.4.2.1 .בתחילת כל שנה בצירוף המסמכים הבאים: )1אישור כי הגן הוא גן רשמי ."}, {"p": 74, "t": ")2אישור מהגן על משך פעילות הגן ,עלות הגן ומרכיביו. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 75, "t": ")3 )4 )5 )6 )7 )8 קבלה על דמי הרישום לגן הילדים. קבלה על הוצאות החינוך בגן. קבלות על הוצאות בעבור שירותי הסעה (אם רלוונטי). טופס הצהרה על מניעת אכילת ארוחות במוסד החינוך מטעמי כשרות או מגבלה בריאותית (אם רלוונטי)."}, {"p": 75, "t": "מסמך מטעם מוסד הלימודים המאשר ,כי אינו מוכן לוותר על תשלום בעד הארוחות המוגשות בו על אף העובדה כי הילד של השליח נמנע מלאכול ארוחות אלה (אם רלוונטי). החשב יבדוק את זכאות השליח לקבלת ההחזר בהסתמך על המסמכים הנ\"ל."}, {"p": 75, "t": ".8השתתפות בגין גן טרום חובה תועבר לשליח באופן הבא: שליח המשלם מראש בתחילת השנה יקבל את סכום ההשתתפות בתשלום אחד. שליח המשלם עבור כל חודש יקבל את סכום ההשתתפות באופן חודשי .במקרה שבו הסכום החודשי קבוע ,על השליח להציג קבלה על עלות הגן של החודש הראשון בלבד ,ובסוף השנה להציג את כלל הקבלות."}, {"p": 75, "t": "במקרה שבו הסכום משתנה ,השליח יציג קבלות עבור כל חודשי השנה בעת התשלום. במקרה בו השליח משלם לגן טרום החובה מראש וילדו עוזב את הגן באמצע שנת לימודים, השליח יקבל את היתרה המגיעה לו ויעביר סכום זה לקופת הנספחות."}, {"p": 75, "t": "לשיקול החשב האיזורי ,ביצוע תשלום ישירות לספק. השתתפות המשרד תשולם ב 10-תשלומים שווים. ההשתתפות תשולם לשליח בתלוש המשכורת. ההשתתפות תשולם לשליח במטבע התשלום לגן בפועל ותחושב לפי שער החליפין השוטף."}, {"p": 75, "t": "ההשתתפות לא תשולם לשליחים שילדיהם לומדים בגן ילדים בביתו של שליח הנציגות. השתתפות בהוצאות חינוך בגילאי  5-18הוראת שות\"ש 1.2.4.3 .1דמי רישום: זכאות לדמי רישום שליח שילדיו בגילאי גן חובה ועד כיתה י\"ב ועד בכלל ,ושעליהם חל חוק לימוד חובה, תש\"ט ,1949-יהא זכאי להשתתפות המשרד בדמי רישום בעבור ילדו פעם אחת במהלך השליחות ,באותה מדינת שירות ולכל תקופת הלימודים של הילד (להלן' :ילד' או 'ילדים')."}, {"p": 75, "t": ".2השתתפות המשרד המשרד ישתתף באופן חד-פעמי ב 75%-מדמי הרישום למוסד הלימודים שבו לומד ילדו, עד לתקרה של  1,200דולר ,עבור כל ילד ( .)75% ∗ 1,200במקרה בו המשרד השתתף בתשלום דמי רישום לגן טרום חובה ,תשלום זה יקוזז מסכום ההשתתפות הנוכחי בגין חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 76, "t": "אותו ילד (ראה הוראת שות\"ש\" ,השתתפות בהוצאות חינוך עבור ילדים בגילאי  ,\"4-3מס' .)1.2.4.2 .3דמי ביטוח – זכאות שליח שילדיו בגילאי גן חובה ועד כיתה י\"ב כולל ,ושחל עליהם חוק לימוד חובה ,תש\"ט- ,1949יהא זכאי להשתתפות המשרד בגובה עלות דמי הביטוח עבור שהות במוסד הלימודים ,אם המוסד דורש זאת."}, {"p": 76, "t": ".4תשלום דמי מניה א .זכאות: שליח שילדיו בגילאי גן חובה ועד כיתה י\"ב כולל ,ושחל עליהם חוק לימוד חובה, תש\"ט ,1949-יהא זכאי להשתתפות חד-פעמית של המשרד בגין תשלום דמי מניה בעת ההרשמה למוסד לימודים ,אם המוסד דורש השתתפות זאת."}, {"p": 76, "t": "השתתפות המשרד: המשרד ישתתף בהוצאה חד-פעמית בגין תשלום דמי מניה במועד הרשמת הילד למוסד לימודים ובתנאי שיוחזרו על ידי השליח בתום השירות או בתום לימודיו של ילדו בבית הספר ,המוקדם ביניהם."}, {"p": 76, "t": ".5הסעות א .זכאות שליח יהא זכאי עבור ילדו להשתתפות בהוצאות נסיעה בתחבורה מאורגנת על ידי בית הספר או חברת הסעות או בתחבורה ציבורית ,למעט מוניות מיוחדות ,על פי ההוצאות בפועל שהיו לשליח."}, {"p": 76, "t": "ב .במקרים בהם אין הסדר נסיעה מאורגנת מטעם בית הספר או קיימת סכנה ממשית בנסיעה בתחבורה ציבורית ,השליח יהא זכאי להשתתפות בהוצאות נסיעה בהסעה מאורגנת (על ידי חברת הסעות) עבור ילדו עד גיל  .14עבור ילדים מעל גיל  14לא תינתן השתתפות בהסעות אלא מימון נסיעה בתחבורה ציבורית בלבד."}, {"p": 76, "t": ".9השתתפות המשרד במקרים כאמור ,בהם אין הסדר נסיעה מאורגנת מטעם בית הספר או קיימת סכנה ממשית בנסיעה בתחבורה ציבורית שיעור ההשתתפות יהיה עד  2,500דולר לשנה עבור משפחה."}, {"p": 76, "t": "במקרים בהם עלות שכר לימוד לילדיו של שליח נמוכה מתקרת סכום ההשתתפות כפי שנקבע בהודעת שות\"ש ה ,1.2.4.3.1.יהיה השליח זכאי ,באישור המשרד (קצ\"מ/חשב)  ,לחרוג מתקרת שיעור ההשתתפות המופיעה בסעיף א' לעיל ,כך שסכום עלויות שכר הלימוד והסעות לא יעלה על גובה תקרת ההשתתפות הרלוונטית."}, {"p": 76, "t": "במקרים בהם שליח חורג מתקרת שיעור ההשתתפות לפי סעיף  2.4.2.2לעיל ,יחול בכל מקרה סעיף  ,2.5.2.2.3בהוראת שות\"ש  1.2.4.3וינוכה האחוז הרלוונטי מעלות שכר הלימוד להלן הנוסח המפורט בשות\"ש סעיף : 2.5.2.2.3 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 77, "t": "\" בבתי ספר המספקים את השירותים הנ\"ל ,אך גובים סכום כולל בלי פירוט ההוצאות, ינוכה מעלות שכר הלימוד  10%בגין ארוחות ,ו 2%-בגין כלל השירותים האחרים הנ\"ל. למען הסר ספק ,ראשית יש לנכות עלויות אלו משכר הלימוד הכולל ולאחר מכן יש לבחון את החזר ההוצאה בהתאם .המשרד ישתתף בשכר לימוד עד לתקרת סכום ההשתתפות כמפורט בהודעת שות\"ש\" ,תקרת סכום השתתפות המשרד לשכר לימוד\" ,ה.1.2.4.3.1."}, {"p": 77, "t": "במקרים בהם הילד מתנייד בתחבורה ציבורית ,קצובת הנסיעה תשולם על פי התעריף הזול ביותר בתחבורה הציבורית ובמחיר הנמוך הקיים באותו מסלול נסיעה בלבד. ילד הנוסע בקווים שבהם לא חל הסדר \"חופשי חודשי\" ,יהא זכאי לקצובת נסיעה בשווי מחיר נסיעה בודדת ,הלוך ושוב ,ובהתאם לימי הלימודים במשך השנה."}, {"p": 77, "t": "ילד אשר לצורך נסיעותיו נזקק לכרטיס \"חופשי חודשי\" וגם לנסיעות בין-עירוניות ,זכאי הן לקצובת נסיעה כמחירו של כרטיס \"חופשי חודשי\" והן לנסיעות על בסיס יומי. .10אופן קבלת ההשתתפות החזר ההוצאה עבור הסדר נסיעה מאורגנת ע\"י בית הספר או חברת הסעות ,ישולם לשליח בגין הצגת קבלות."}, {"p": 77, "t": "לשיקול הנציגות ,ביצוע תשלום ישירות לספק. החזר ההוצאה עבור נסיעה בתחבורה ציבורית ישולם לשליח על פי התעריפים החודשיים הקבועים במדינת השירות. השתתפות בשכ\"ל גן חובה ושכ\"ל בית ספר עד כיתה י\"ב כל הפרטים מופיעים בהוראת שות\"ש:1.2.4.3 - הוצאות שכר לימוד בגן חובה .1זכאות שליח יהא זכאי להשתתפות המשרד בשכר לימוד של גן חובה החל מחודש ספטמבר של כל שנה ,בגין ילדים שמלאו להם  5שנים ,בין התאריכים שקבע משרד החינוך לאותה שנת"}, {"p": 77, "t": "לימודים ,בהתאם לחוק לימוד חובה ,תש\"ט .1949-התאריכים (ראה חוזר מנכ\"ל – משרד החינוך( שייקבעו יובאו לידיעת הנציגויות מידי שנה ,לקראת פתיחת שנת הלימודים. במקרה בו שנת הלימודים מתחילה מספר חודשים לאחר או לפני ספטמבר במדינת השירות, המשרד ישתתף בשכר לימוד של גן חובה ,החל מתחילת שנת הלימודים כנהוג במקום השירות, בהתקיים שבמועד תחילת שנת הלימודים הנהוגה במקום השירות ימלאו לילד לכל הפחות 4"}, {"p": 77, "t": "שנים ו 8-חודשים ולכל היותר  5שנים ו 8-חודשים. בהתקיים סעיף ב' לעיל ,גיל הכניסה לגן חובה יוקדם על פי התנאים הבאים: )1הקדמת גיל הכניסה לא תעלה על  4חודשים (תקף גם לגיל המינימום וגם לגיל המקסימום)."}, {"p": 77, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 78, "t": ")2בשום מקרה המשרד לא יכסה הוצאות בגן חובה לתקופה העולה על שנת לימודים אחת. .2השתתפות המשרד המשרד ישתתף בשכר לימוד של גן חובה עבור ילדי השליח עד לתקרת סכום ההשתתפות כמפורט בטבלה שלהלן (עפ\"י הודעת שות\"ש\" ,תקרת סכום השתתפות המשרד לשכר לימוד\" ,ה) .1.2.4.3.1."}, {"p": 78, "t": "מודגש כי ,ככל שיחולו שינויים בהוראת השות\"ש מהמפורט בחוברת זו ,תיגבר הוראת השות\"ש. תקרת סכום השתתפות המשרד לשכר לימוד הודעה  1.2.4.3.1בשות\"ש נציגות מדינה עיר תקרת השתתפות שנתית בשכ\"ל (בדולרים) ארה\"ב וושינגטון 40,500 ארה\"ב ניו יורק 44,100 ארה\"ב לוס אנג'לס 42,300 ארה\"ב שיקאגו 34,200 ארה\"ב אטלנטה 34,200 ארה\"ב יוסטון 29,700 ארה\"ב סן פרנציסקו 38,700 ארה\"ב"}, {"p": 78, "t": "בוסטון 42,300 ארה\"ב מיאמי 36,900 קנדה אוטווה 28,800 קנדה טורונטו 36,000 מקסיקו מקסיקו סיטי 32,400 קולומביה בוגוטה 20,700 ברזיל ברזיליה 30,600 צ'ילה סנטיאגו 33,300 פולין ורשה 29,700 רוסיה מוסקבה 45,900 גרמניה ברלין 26,100 פינלנד הלסינקי 26,100 אנגליה לונדון 51,300 בלגיה בריסל 46,800 צרפת פריז 59,400 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 79, "t": "תקרת סכום השתתפות המשרד לשכר לימוד הודעה  1.2.4.3.1בשות\"ש נציגות מדינה עיר תקרת השתתפות שנתית בשכ\"ל (בדולרים) איטליה רומא 40,500 יוון אתונה 19,800 הודו ניו דלהי 45,000 סינגפור סינגפור 46,800 פיליפינים מנילה 47,700 יפן טוקיו 41,400 סין בייג'ינג 47,700 ויטנאם הנוי 28,800 אוסטרליה קנברה 26,100 איחוד האמירויות אבו דאבי 19,600 איחוד האמירויות דובאי 20,200"}, {"p": 79, "t": "מרוקו רבאט 27,400 .3אופן קבלת ההשתתפות: שליח הזכאי לקבלת ההשתתפות יגיש לקצין המנהלה  /מנהל כ\"א  /חשב את הפרוספקט של הגן  /בית הספר ,שבו מצוינים בפירוש תאריכי הלימוד וכן מפורטים בו מרכיבי עלות שכר הלימוד ,לרבות :הסעות ,ארוחות ,עזרי לימוד ,טיולים ,חוגים ,תלבושת אחידה ועוד בצירוף טופס שות\"ש\" ,בקשה להשתתפות בהוצאות חינוך עבור ילדים בגילאי ,\" 5-18מס' ט 1.2.4.3.1 .בתחילת כל שנה וכן יצורפו המסמכים הבאים:"}, {"p": 79, "t": "אישור ממוסד הלימודים על גובה שכר הלימוד השנתי ומרכיביו. קבלות על תשלום דמי רישום ,דמי מניה ,דמי ביטוח ,שכר לימוד והוצאות נסיעה בתחבורה ציבורית. טופס הצהרה על מניעת אכילת ארוחות במוסד החינוך מטעמי כשרות או מגבלה בריאותית (אם רלוונטי)."}, {"p": 79, "t": "מסמך מטעם מוסד הלימודים המאשר ,כי אינו מוכן לוותר על תשלום בעד הארוחות המוגשות בו על אף העובדה כי הילד של השליח נמנע מלאכול ארוחות אלה (אם רלוונטי). )1ההשתתפות תשולם לשליח בתלוש המשכורת."}, {"p": 79, "t": ")2ההשתתפות תשולם לשליח במטבע תשלום שכר הלימוד בפועל ותחושב לפי שער החליפין השוטף. )3במקרים בהם אושרו מקדמות על חשבון שכר לימוד ,הנציגות תחייב את חשבונם האישי של השליחים בסכום המקדמה ולאחר קבלת תקרת ההשתתפות תשלם את מלוא ההשתתפות ,בניכוי המקדמה ,ותחייב בהוצאה את חשבון הוצאות החינוך בהתאם."}, {"p": 79, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 80, "t": "הוצאות שכר לימוד בבית ספר .1זכאות במקרה בו גיל הכניסה לבית ספר במדינת השירות הוא צעיר מהמקובל בארץ ,המשרד ישתתף בהוצאות שכר לימוד גם בגיל צעיר יותר ,בהתאם למקובל באותה מדינת שירות."}, {"p": 80, "t": ".2השתתפות המשרד השתתפות המשרד תהיה עפ\"י \"תקרת סכום השתתפות המשרד לשכר לימוד\", ה( .1.2.4.3.1.ראה טבלת תקרה לעיל) תקרת ההשתתפות כאמור הינה עבור שכר לימוד בלבד .השירותים להלן אינם כלולים בתקרה זו :דמי ביטוח ,דמי רישום ,הסעות ,דמי מניה ,ספרים ,מחברות ,ציוד ,מחשב אישי ,טאבלט, ביגוד ,חוגים ,ספר שנה ,ועד הורים ,ארוחות או כל הוצאה אחרת."}, {"p": 80, "t": ")1בבתי ספר המספקים את השירותים הנ\"ל ,אך גובים סכום כולל בלי פירוט ההוצאות ,ינוכה מעלות שכר הלימוד  10%בגין ארוחות ,ו 2%-בגין כלל השירותים האחרים הנ\"ל .למען הסר ספק ,ראשית יש לנכות עלויות אלו משכר הלימוד הכולל ולאחר מכן יש לבחון את החזר ההוצאה ."}, {"p": 80, "t": ")2המשרד לא יגבה משליח השתתפות של  10%בגין ארוחות המוגשות בבית הספר במקרה בו ילדו של השליח אינו אוכל בבית הספר מטעמי כשרות או מגבלה בריאותית. )3במקרה בו השליח אינו יכול לשלוח את ילדיו לבית ספר ציבורי בשל סיבות מיוחדות (למשל ,אין בית ספר מקומי ציבורי נאות) ,המשרד יהיה רשאי להשתתף בהוצאות חינוך בבית ספר בינלאומי או פרטי או יהודי או יהודי-דתי והשתתפות המשרד תהא עפ\"י \"תקרת סכום השתתפות המשרד לשכר לימוד\" ,ה.1.2.4.3.1."}, {"p": 80, "t": "(ראה טבלת תקרה לעיל) )4שליח שילדיו לומדים בבית ספר ציבורי ,שבו לא גובים שכר לימוד ,יהא זכאי להשתתפות שנתית לכיסוי הוצאות מיוחדות בסך  360דולר עבור כל ילד הלומד בבית ספר בשפה האנגלית ,ו 600-דולר עבור כל ילד הלומד בבית ספר בשפה אחרת."}, {"p": 80, "t": ")5החזר שכר הלימוד לא יכלול לימוד במוסדות אוניברסיטאיים ,קולג' או מוסד על- תיכוני אחר. .3אופן קבלת ההשתתפות שליח הזכאי לקבלת ההשתתפות יגיש לקצין המנהלה  /מנהל כ\"א  /חשב את הפרוספקט של הגן  /בית הספר ,שבו מצוינים בפירוש תאריכי הלימוד וכן מפורטים בו מרכיבי עלות שכר הלימוד ,לרבות :הסעות ,ארוחות ,עזרי לימוד ,טיולים ,חוגים ,תלבושת אחידה ועוד חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 81, "t": "בצירוף טופס שות\"ש\" ,בקשה להשתתפות בהוצאות חינוך עבור ילדים בגילאי ,\" 5-18מס' ט 1.2.4.3.1 .בתחילת כל שנה וכן יצורפו המסמכים הבאים: אישור ממוסד הלימודים על גובה שכר הלימוד השנתי ומרכיביו."}, {"p": 81, "t": "קבלות על תשלום דמי רישום ,דמי מניה ,דמי ביטוח ,שכר לימוד והוצאות נסיעה בתחבורה ציבורית. טופס הצהרה על מניעת אכילת ארוחות במוסד החינוך מטעמי כשרות או מגבלה בריאותית (אם רלוונטי)."}, {"p": 81, "t": "מסמך מטעם מוסד הלימודים המאשר ,כי אינו מוכן לוותר על תשלום בעד הארוחות המוגשות בו על אף העובדה כי הילד של השליח נמנע מלאכול ארוחות אלה (אם רלוונטי). )1ההשתתפות תשולם לשליח בתלוש המשכורת."}, {"p": 81, "t": ")2ההשתתפות תשולם לשליח במטבע תשלום שכר הלימוד בפועל ותחושב לפי שער החליפין השוטף. במקרים בהם אושרו מקדמות על חשבון שכר לימוד ,הנציגות תחייב את חשבונם האישי של השליחים בסכום המקדמה ולאחר קבלת תקרת ההשתתפות תשלם את מלוא ההשתתפות, בניכוי המקדמה ,ותחייב בהוצאה את חשבון הוצאות החינוך בהתאם."}, {"p": 81, "t": "תשלום שכר לימוד מרוכז .1זכאות במקומות שבהם ילדיהם של מספר שליחים לומדים באותו בית ספר ,הנציגות תהא רשאית לשלם מראש את שכר הלימוד ישירות לבית הספר לכל שנת הלימודים."}, {"p": 81, "t": ".2השתתפות המשרד הנציגות תשלם את שכר הלימוד וההוצאות הנלוות כנגד חשבון ופירוט מדויק שבית הספר ייתן ובתנאי שגובה שכר הלימוד וההוצאות המוכרות לתשלום (שכר דמי ביטוח ,דמי רישום, הוצאות נסיעה בתחבורה ציבורית ודמי מניה) לא יעלו על תקרת ההשתתפות שנקבעה עבור כל שירות בנפרד."}, {"p": 81, "t": "ככלל ,המשרד ישאף לשלם את שכר הלימוד ישירות לבית הספר ולא באמצעות השליחים. במקרה של תשלום מרוכז מראש ,הנציגות תבדוק אפשרות לקבלת הנחה מבית הספר ותגבה מהשליח את חלקו היחסי בעבור השירותים שבית הספר ייתן ובתנאי שגובה שכר הלימוד וההוצאות המוכרות לתשלום (שכר דמי ביטוח ,דמי רישום ,הוצאות נסיעה בתחבורה ציבורית ודמי מניה) לא יעלו על תקרת ההשתתפות שנקבעה עבור כל"}, {"p": 81, "t": "שירות בנפרד. .3אופן קבלת ההשתתפות חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 82, "t": "כמפורט בהוראת השות\"ש ולאחר קבלת פירוט מדויק של העלויות עבור שכר לימוד וההוצאות הנלוות אשר יתקבל מבית הספר לנציגות. הוצאות עבור שנת לימודים חלקית .1זכאות שליח שהגיע למקום השירות לאחר תחילת שנת הלימודים וכתוצאה מכך ילדיו לא ילמדו במשך שנת לימודים שלמה ,יהא זכאי להשתתפות יחסית בהוצאות החינוך ,בהתאם לתקופת הלימודים."}, {"p": 82, "t": "שליח המסיים את שירותו לפני תום שנת הלימודים ושילם שכר לימוד מראש ,ידרוש מבית הספר לקבל בחזרה את יתרת הסכומים המגיעים לו ,בגין הפסקת לימודי ילדיו .את סכומי ההחזר הנ\"ל ,שעבורם שולמה לו השתתפות ,יחזיר לקופת הנציגות."}, {"p": 82, "t": "שליח המסיים את שירותו לפני תום שנת הלימודים ומשלם את שכר הלימוד על בסיס חודשי, או בתשלומים ,יהא זכאי להשתתפות בהוצאות חינוך עד לתאריך שייקבע על ידי בית הספר בכפיפות לנוהלי בית הספר."}, {"p": 82, "t": ".2השתתפות המשרד כמפורט בהוראת השות\"ש. .3אופן קבלת ההשתתפות כמפורט בסעיף  .2.5.2.3בהוראת השות\"ש השלמת לימודי חינוך תיכון לילדי שליחים הוראת שות\"ש 1.2.4.6 מבוא מדינת ישראל משתתפת בהוצאות חינוך של ילדי שליחים השוהים עימם בחוץ-לארץ כפי שנהוג בארץ ,בהתאמות הנדרשות."}, {"p": 82, "t": "זכאות שליח יהיה זכאי עבור כל ילד שטרם מלאו לו  19שנה ,להשתתפות בהשלמת לימודי תיכון, אם ילדו לומד במקום השירות בבית ספר תיכון שבו תעודת הסיום (דיפלומה) אינה עומדת בדרישות המועצה להשכלה גבוהה בישראל."}, {"p": 82, "t": "שליח יהא זכאי להשלמת לימודים באופן פרטי עבור ילדו לצורך הכנה לבחינות בגרות ישראליות בלבד. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 83, "t": "שליח שמיצה את זכאותו להשתתפות המשרד בהוצאות עבור השלמת לימודים באופן פרטי, לא יהא זכאי למענק חד-פעמי עבור שיעורי עזר כמפורט בהוראת שות\"ש\" ,מענק חד פעמי לשיעורי עזר לילדי שליחים בכיתות א'-י\"ב החוזרים לארץ\" ,מס'  ,1.3.4.1ו/או להשתתפות בהוצאות בגין מכינה אוניברסיטאית ,כמפורט בהוראת שות\"ש 1.3.4.1 לימודים לבגרות ישראלית באופן פרטי הוראת שות\"ש 1.2.4.6 שליח יהא זכאי להשלמת לימודים באופן פרטי עבור ילדו לצורך הכנה לבחינות בגרות"}, {"p": 83, "t": "ישראליות בלבד .על השליח לטפל בכך בארץ עוד בטרם היציאה לשליחות. .4זכאות: שליח שמיצה את זכאותו להשתתפות המשרד בהוצאות עבור השלמת לימודים באופן פרטי ,כמפורט בהוראה  , 1.2.4.6לא יהא זכאי למענק חד-פעמי עבור שיעורי עזר כמפורט בהוראה  1.3.4.1ו/או להשתתפות בהוצאות בגין מכינה אוניברסיטאית, כמפורט בהוראה .1.3.4.2 .5השתתפות המשרד לימודים לבגרות ישראלית באופן פרטי"}, {"p": 83, "t": "השתתפות המשרד תהא עבור הכנה ל 3-בחינות בגרות לכל היותר ברמת  10יחידות במצטבר, כאשר מתוכן לפחות  3יחידות במתמטיקה ו 4-יחידות במקצוע אחד (בנוסף למתמטיקה). המשרד ישתתף בהוצאות של עד  6שיעורים פרטיים ליחידת לימוד בגרות ,בגובה 75% מההוצאה בפועל לשיעור עד לתקרת השתתפות של  24דולר לשיעור (כלומר ההשתתפות המרבית היא )24 ∗ 75% = 18 .6פתיחת תיק נבחן אקסטרני במשרד החינוך:"}, {"p": 83, "t": "א .על כל נבחן השוהה בחו\"ל ומעוניין להבחן במהלך שהותו שם ,לפתוח תיק נבחן אקסטרני בארץ ולהבחן בשאלונים אקסטרניים. ב .בדר\"כ מתקיים הרישום בחודשים ינואר עד מרץ בכל שנה .מומלץ לטפל בתהליכי הרישום מוקדם ככל האפשר .לא ניתן לבצע רישום לבחינות בחו\"ל באמצעות האינטרנט."}, {"p": 83, "t": "ג .יש להגיע לאחת משלוחות הבחינות האקסטרניות של משרד החינוך: בירושלים :רח' כנפי נשרים  ,24גבעת שאול .טל'02-6515913 : בבאר-שבע :שד' שזר  ,21בית נועם ,קומה  .6טל' 08-6283291 בחיפה :רח' ביאליק  ,3בית מנהל ההנדסה ,קומה  .9טל'04-8645584 :"}, {"p": 83, "t": "באזור תל אביב והמרכז :רח' עמל  ,48קרית אריה ,פתח תקווה .טל'.03-6164022 : ד .במידה ונציג מטעם השליח מטפל ברישום ,יש לצייד אותו בייפוי כוח (אין צורך בייפוי כוח נוטריוני) ,צילום דרכון בתוקף ותמונת פספורט אחת של התלמיד הנבחן."}, {"p": 83, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 84, "t": "ה .המבחנים נערכים בחו\"ל ,בנציגות ישראל הקרובה למקום מגורי השליח .בעת ההרשמה ,יש לעדכן את הפקיד המטפל בשלוחה ,לאיזו נציגות לשלוח את הבחינות. ו .הבחינות בחו\"ל מתקיימות אך ורק במועד קיץ ,בחודשים מאי-יולי .מועדי הבחינות מפורסמים באתר האינטרנט של משרד החינוך ,אך אין הם סופיים .יש לעקוב אחר שינויים אפשריים."}, {"p": 84, "t": "ז .חומר הלימוד לבחינה מופיע באתר האינטרנט של משרד החינוך. ח .נבחן שאושרו לו בארץ התאמות ודרכי היבחנות יוכל להיבחן עם ההתאמות שלהן בשגרירות בעת הבחינה :תוספת זמן של  ,25%התעלמות משגיאות כתיב ,הקראת שאלון ,שיעתוק בחינה ,דף נוסחאות מורחב במתמטיקה ושאלון מותאם."}, {"p": 84, "t": "ט .נבחן שהוכר בישראל במעמד של תלמיד תושב חוזר (לאחר שליחות קודמת) ,ויצא לשליחות נוספת בחו\"ל ,זכאי להיבחן בשאלון עולה חדש או לחילופין בשאלון רגיל ולקבל תוספת ניקוד ,בהתאם לחוזר מנכ\"ל."}, {"p": 84, "t": "י .בחו\"ל לא מתקיימות בחינות במועד ב'. מבחני  I.Bאו ( A.Pאו דומיהם המוכרים ע\"י המל\"ג) הוראת שות\"ש 1.2.4.6 .7שליח שזכאי עבור ילדו להשלמת לימודי בגרות באופן פרטי כמפורט לעיל אך לא מיצה את זכאותו ,יהא זכאי להשתתפות בהוצאות בגין מבחני  I.Bאו  A.Pבמקצוע ספרות עברית."}, {"p": 84, "t": ".8למען הסר ספק ,שליח שלילדו יש תעודת בגרות מקומית המוכרת בארץ ,לא יהא זכאי להשתתפות בהוצאה בגין מבחני .A.P / I.B .9שליח שניצל זכאותו להשתתפות בשנת לימודים בקולג' לא יהא זכאי להשתתפות במבחני .A.P /I.B .10שליח שניצל זכאותו להשתתפותו במבחני  A.P/I.Bלא יהא זכאי למענק חד פעמי עבור שיעורי עזר לילדיו בשובם לארץ או להשתתפות במכינה אוני' לימודי קולג' במקום כיתה י\"ב הוראת שות\"ש 1.2.4.6"}, {"p": 84, "t": "זכאות: .1ילדי השליח זכאים להמיר את שנת הלימודים האחרונה בתיכון (כיתה יב') לשנת לימודים ראשונה בקולג' .שליח שילדו ניצל את הזכאות להשתתפות במבחני  A.P/I.Bלא יהא זכאי להשתתפות בשנת לימודים בקולג'."}, {"p": 84, "t": ".2המשרד ישתתף בשכר לימוד עבור שנת לימודים אחת בקולג' במקום כיתה יב' ועד לגובה שכר הלימוד של לימודי תיכון במקום השירות. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 85, "t": ".3ההשתתפות תשולם בתלוש השכר של השליח בכפוף להצגת קבלות ואישור המשרד. .4שליח שזכאי עבור ילדו להשלמת לימודים באופן פרטי ,כמפורט בסעיף שלעיל ,אך לא מיצה את זכאותו ,וילדו אינו לומד בבית הספר במקום השירות ,אין בידו תעודת בגרות מקומית ואינו עובד בשכר ,יהא זכאי להשתתפות בהוצאות בגין לימודי שנה אחת בקולג' (במקום כיתה י\"ב) עבור ילדו."}, {"p": 85, "t": ".5שליח שניצל את זכאותו להשתתפות במבחני  I.Bאו  ,A.P.לא יהא זכאי להשתתפות בשנת לימודים בקולג'. .6שליח שניצל את זכאותו להשתתפות בשנת לימודים בקולג' לא יהא זכאי למענק חד-פעמי עבור שיעורי עזר בגין ילדיו בגילאי תיכון בהתאם להוראה  1.3.4.1ו/או להשתתפות בהוצאות בגין מכינה אוניברסיטאית בהתאם להוראה .1.3.4.2 אופן קבלת ההשתתפות .1שליח הזכאי לקבלת ההשתתפות יגיש לממונה טופס .1.2.4.6.1.בקשה להשתתפות"}, {"p": 85, "t": "בהוצאות לימודי תיכון בצירוף המסמכים המפורטים בטופס. .2ההשתתפות תשולם בתלוש השכר בכפוף להצגת קבלות ולאישור המשרד. מענק חד פעמי לשיעורי עזר לילדי שליחים בכיתות א' – י\"ב החוזרים לארץ הוראת שות\"ש 1.3.4.1 .1שליח יהא זכאי למענק חד פעמי לשיעורי עזר לכל אחד מילדיו העולים לכיתות א'-יב', שנלוו אליו לשליחות ,וחוזרים ללמוד בארץ .שליח המשרת בחו\"ל פחות משנתיים לא יהא"}, {"p": 85, "t": "זכאי למענק זה. .2שליח או ילדו שחזר לארץ לפני תום תקופת השירות המינימלית תקופת השירות של שליחים תימשך (לפחות שנתיים כמפורט בהוראה  ) 1.1.11.1לא יהא זכאי למענק החד- פעמי .3המענק יקוזז משיעור ההשתתפות בגין לימודים במכינה אוניברסיטאית אם ילדו של השליח יהא זכאי לכך בעתיד."}, {"p": 85, "t": ".4המענק משולם במשכורת חו\"ל האחרונה וחייב במס. .5אופן התשלום :המענק נבחן מאושר ומשולם ע\"י יחידת השכר באכ\"ס בתום השליחות. השתתפות חד פעמית בהוצאות מכינה אוניברסיטאית זכאות .1שליח החוזר משליחות בחו\"ל יהא זכאי להשתתפות חד-פעמית במימון לימודים במכינה אוניברסיטאית בארץ ,לילדיו שנלוו אליו לשליחות בהתקיים כל התנאים הבאים שלהלן במצטבר:"}, {"p": 85, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 86, "t": "א .הילד סיים בית ספר תיכון בחו\"ל. ב .לילד אין תעודת בגרות ישראלית. ג .הילד לומד במכינה במסגרת מוסד להשכלה גבוהה. ד .הילד אינו זכאי למלגה ממשהב\"ט. .2שליח ששירת בחו\"ל פחות משנתיים (תקופה מינימלית הוראה  )1.1.11.1אינו זכאי להשתתפות במכינה עברו ילדו."}, {"p": 86, "t": ".3שליח שניצל זכאותו להשתתפות בגין הוצאות מבחני  A.P/I.Bאו דומיהם או שילדו למד בקולג' בחו\"ל במקום כיתה יב' ,אינו זכאי להשתתפות המשרד בהוצאות בגין מכינה אוניברסיטאית."}, {"p": 86, "t": ".4שליח שניצל זכאותו למענק חד פעמי עבור שיעורי עזר לילדו בסיום השליחות תקוזז השתתפות המשרד בגין מכינה אוניברסיטאית מהסכום אותו קיבל עבור שיעורי עזר. .5השתתפות המשרד בעלות המכינה כאמור לעיל ,היא בשיעור של  75%מעלות שכר הלימוד האוניברסיטאי לתואר שני ,לפי קביעת המועצה להשכלה גבוהה ולא יותר מ 75% -מעלות המכינה בפועל ,עפ\"י קבלות מקוריות שימציא השליח .ההשתתפות חייבת בניכוי מס"}, {"p": 86, "t": "הכנסה. .6לצורך קבלת ההשתתפות בעלות מכינה בארץ ,יש לפנות ליחידה למשאבי אנוש ומנהל בחו\"ל. .7ההשתתפות במכינה אוניברסיטאית לילדי שליחים המתגייסים לצה\"ל או שירות לאומי תאושר לא יאוחר מהמועד המוקדם מבין השניים:"}, {"p": 86, "t": "שנת הלימודים הסמוכה אחרי השירות הצבאי /לאומי. במלאת לילד  22שנים. מקרים חריגים ,לרבות קצינים בצה\"ל ,יובאו לדיון בפני הועדה הבין משרדית. השתתפות המשרד .1השתתפות המשרד בהוצאות בגין מכינה אוניברסיטאית תהיה  75%משכר הלימוד בפועל במכינה ועד לתקרת הסכום המפורט בהודעת שות\"ש\" ,סכום השתתפות בגין מכינה אוניברסיטאית\" ,ה( 1.3.4.2.1.ההשתתפות = התקרה ∗ .)75% ההשתתפות תינתן בגין לימודים במכינה בשנת הלימודים הסמוכה למועד החזרה ארצה."}, {"p": 86, "t": "ההשתתפות במכינה אוניברסיטאית לילדי השליחים המתגייסים לצה\"ל או לשירות לאומי תאושר לא יאוחר מהמועד המוקדם מבין השניים: )1שנת הלימודים הסמוכה אחרי סיום השירות הצבאי או לאומי."}, {"p": 86, "t": ")2במלאת לילד  22שנים. מקרים חריגים ,לרבות קצינים בצה\"ל ,יובאו לדיון בפני הוועדה. )3ההשתתפות תשולם לשליח בתלוש המשכורת באמצעות סמל שכר. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 87, "t": "אופן קבלת ההשתתפות .1שליח הזכאי לקבלת ההשתתפות יגיש לחשב המשרד טופס\".1.3.4.2.1.בקשה להשתתפות עבור מכינה אוניברסיטאית\" ,,בצירוף הקבלות על הוצאות לימודים במכינה אוניברסיטאית."}, {"p": 87, "t": ".2חשב המשרד יבדוק את זכאות השליח בדבר קבלת ההשתתפות בהתאם לסעיף הזכאות שלעיל. המלצות המשרד עבור ילדי שליחים לקראת סיום לימודי תיכון במהלך השליחות .1טרם ההרשמה לבית הספר בחו\"ל ,כדאי לברר מול הנהלת בית הספר בו ילמד הילד ,האם התעודה שהמוסד מעניק אכן מקנה זכאות ללימודים על תיכוניים  /אקדמאיים .במקרה של ספקות ,ניתן לפנות למשרד החינוך  /היחידה להערכות השכלה תיכונית."}, {"p": 87, "t": ".2בחזרה ארצה ,תלמיד אשר מעוניין ללמוד במוסד להשכלה גבוהה ,יכול להשתמש בתעודה מחו\"ל .יש לקחת בחשבון כי רוב המוסדות להשכלה גבוהה מכירות בתעודות בגרות בינלאומיות כשקילות לתעודת הבגרות הישראלית ,אך נכון להיום לא משקללות את הציונים ,כך שניתן להגיש מועמדות למוסד על סמך התעודות מחו\"ל ,אבל הקבלה תהיה רק על בסיס הציון הפסיכומטרי."}, {"p": 87, "t": "במידה והמוסד מבקש אישור של משרד החינוך להכרה בתעודה מחו\"ל כמקבילה לתעודת בגרות או נדרש לתעודת בגרות לצורך מקום עבודה ,יש לפנות למשרד החינוך  /היחידה להערכת השכלה תיכונית."}, {"p": 87, "t": "\"אולפנון\" לילדי שליחים בתום שליחות (מיועד לילדים שיעלו בארץ לכיתות ב' עד י') על מנת לאפשר לילדי שליחים הסתגלות קלה ככל האפשר ללימודים בארץ לאחר החזרה מהשליחות ,מאפשר המשרד הצטרפות למסגרת \"אולפנון\" ,שמקיימים משרד החוץ או משרד ראה\"מ בחופשת הקיץ בארץ."}, {"p": 87, "t": "מטרות האולפנון הנן הפגת חששות ,חיבור והסתגלות למסגרת בית הספר הישראלי ,מפגש עם מורים המלמדים בעברית ,העברת תכנים דידקטיים והשתלבות חברתית. האולפנון ההשתתפות אינה כרוכה בתשלום מצד ההורים ,אך מחייבת השתתפות מלאה למי שנרשם."}, {"p": 87, "t": "המעוניינים בפרטים יפנו באמצעות קציני המנהלה  /מנהלי כ\"א ,ליחידה למשאבי אנוש ומנהל בחו\"ל בחודש מאי בכל שנה .מובהר כי האחריות על קיום האולפנון הינה של משרד החוץ/משרד רוה\"מ והיה והאולפנון ולפיכך ,השתתפות ילדי המשרד בכפוף לקיום הפרוייקט ע\"י המשרדים כאמור."}, {"p": 87, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 88, "t": "חינוך עברי משלים הוראת שות\"ש ( 1.2.4.5לילדים בגילאי )5-18 .1חינוך עברי משלים ,הינו מסגרת לימודית לילדי שליחים (מאורגנת או פרטית) ,שבה לומדים הילדים את המקצועות העבריים ,שאינם נלמדים בבתי הספר המקומיים."}, {"p": 88, "t": "מקצועות הלימוד הנכללים במסגרת \"חינוך עברי משלים\" :עברית ,היסטוריה של עם ישראל ,ידיעת הארץ ,אזרחות ,מולדת ,תנ\"ך ,חגי ישראל ומקצועות אחרים ,הקשורים ללימודים עבריים."}, {"p": 88, "t": ".2לא יכללו במסגרת זו ,לימודים כלליים כגון חשבון ,מתמטיקה ,היסטוריה כללית ,כימיה, פיזיקה וכיוצא באלה. .3זכאות השתתפות בחינוך עברי משלים לילדיו בגילאי .18-5 ההשתתפות בחינוך עברי משלים חלה גם עבור ילדים הלומדים בגן חובה ,אך רק כאשר מדובר במסגרת מאורגנת ,שמשרד החינוך אישר."}, {"p": 88, "t": "במקרים חריגים ,השליח יהא זכאי להשתתפות בלימודי חינוך עברי משלים בשנה כלשהי במהלך שליחותו במקום בשנת שירותו האחרונה ,וזאת בכפוף לאישור הוועדה הביינמשרדית. שליח אשר בן זוגו מלמד במסגרת חינוך עברי משלים ,וילדיו משתתפים בשיעורים אלה ,לא יהא זכאי להשתתפות נוספת בהוצאות."}, {"p": 88, "t": "הלימוד בבית הספר הווירטואלי אינו פוגע בזכות התלמיד ללמוד במסגרת חינוך עברי משלים, באותם מקומות שמסגרת כזו קיימת. .4השתתפות המשרד קצין המנהלה בנציגות יפנה בתחילת שנת הלימודים ישירות למחלקה לארגון מוסדות חינוך במשרד החינוך ויפעל לקבלת תקציב למסגרת לימודי חינוך עברי משלים עבור כל התלמידים, שיועבר לנציגות על ידי משרד החוץ."}, {"p": 88, "t": "בכל מקום שבו תאושר הקמת מסגרת לחינוך עברי משלים ,תוקם ועדה שבראשה יעמוד ראש הנציגות ,או מי שימונה על ידו .הוועדה תהא אחראית לניהולה ולתפעולה התקין של המסגרת וכל הקשור בכך."}, {"p": 88, "t": "השתתפות המשרד לשיעור בכיתה תהיה בגובה  75%מההוצאה בפועל לשיעור עד לתקרת השתתפות של  32דולר לשיעור (כלומר ההשתתפות המרבית היא  )32 ∗ 75% = 24עבור כל ילד. מכסת ההשתתפות היא עד  75שיעורים בשנה עבור כל ילד ,כאשר כל שיעור בן  60דקות."}, {"p": 88, "t": "במקומות שבהם השיעורים לא מתבצעים במסגרת כיתתית ,עקב מספר מצומצם של ילדים, ו/או פער הגילאים שביניהם ,המשרד ישתתף בהוצאות חינוך זה גם אם הוא ניתן במסגרת שיעורים פרטיים ,למעט עבור ילדים הלומדים בגן חובה."}, {"p": 88, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 89, "t": ".5אופן קבלת ההשתתפות שליח הזכאי להשתתפות המשרד ימלא טופס שות\"ש\" ,בקשה להשתתפות בהוצאות חינוך עברי משלים\" ,מס' ט 1.2.4.5.1.ויגישו לחשב המשרד ,בצירוף הקבלות בגין הוצאות החינוך."}, {"p": 89, "t": "השתתפות המשרד תאושר עם סיום שנת הלימודים ,ולאחר שחשב המשרד או מי מטעמו, אישר את פירוט הוצאות החינוך על סמך קבלות ,וכמפורט בטופס הנ\"ל. החזר ההוצאות ישולם לשליח בתלוש המשכורת."}, {"p": 89, "t": ".1השתתפות המשרד שליח אשר ילדו לומד בבית הספר הווירטואלי יחויב בתשלום לפי המדרגות הבאות: ₪ 660עבור הילד הראשון. ₪ 500עבור הילד השני ( ₪ 1160לשני ילדים). ₪ 330עבור כל ילד החל מהילד השלישי כולל ( ₪ 1490לשלושה ילדים)."}, {"p": 89, "t": ".2אופן קבלת ההשתתפות התשלום ינוכה מתלוש השכר של השליח. \"חינוך עברי משלים\" במסגרת מאורגנת מדובר במסגרת כגון \"בית ספר של יום ראשון\" ( ,)SUNDAY SCHOOLהמאורגן ע\"י השגרירות ושתוכנית הלימודים והמורים אושרה ע\"י משרד החינוך."}, {"p": 89, "t": "שליח ,שילדיו לומדים \"חינוך עברי משלים\" במסגרת מאורגנת ,זכאי להשתתפות בגובה של 75%מההוצאה הממשית לשיעור או עד לתקרה של  32$לשיעור .קרי 24$ ,עבור כל ילד. מכסת השיעורים הפרטיים המאושרת בשנה היא  75שיעורים בלבד ,כל שיעור באורך 60 דקות."}, {"p": 89, "t": "\"חינוך עברי משלים\" במסגרת פרטית במקומות ,בהם לא ניתן לקיים מסגרת מאורגנת ל\"חינוך עברי משלים\" עקב מספר ילדים קטן או פערי גילאים ,יהיה השליח זכאי להשתתפות בהוצאות \"חינוך עברי משלים\", במתכונת של שיעורים פרטיים ובתנאי ,שנושאי הלימוד יהיו במקצועות עבריים כפי שפורטו לעיל."}, {"p": 89, "t": "לשיעורי \"חינוך עברי משלים\" במסגרת פרטית ,זכאים ילדים בגילאי  5-18למעט ילדים בגן חובה. שליח ,שילדיו לומדים \"חינוך עברי משלים\" בשיעורים פרטיים ,זכאי להשתתפות בגובה של 75%מההוצאה הממשית לשיעור."}, {"p": 89, "t": "תקרת ההשתתפות בעלות שיעור המאושרת ל\"חינוך עברי משלים\" זהה לתקרת ההשתתפות במסגרת מאורגנת. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 90, "t": "שליח ,המבקש השתתפות בשיעורי \"חינוך עברי משלים\" במסגרת פרטית ,יגיש בקשה ליחידה למשאבי אנוש ומנהל בחו\"ל ,באמצעות מנהל כ\"א /קצ\"מ הנציגות .הבקשה תכלול: שם הילד ,גילו ,עלות השיעור ,שם המורה."}, {"p": 90, "t": "לימודי ילדי שליחים ב\"בית הספר הווירטואלי\" הוראת ות\"ש 1.2.4.5 .1במסגרת החינוך העברי המשלים משרד החוץ וחברת  , E-TEACHERהמתמחה בהוראה מרחוק באמצעות האינטרנט ,מפעילות יחדיו את \"בית הספר הווירטואלי\" באינטרנט לילדי שליחים בחו\"ל .בית הספר הווירטואלי מאפשר לכל ילדי השליחים בחוץ-לארץ ללמוד ולהשתלם במקצועות העבריים."}, {"p": 90, "t": ".2בית הספר מעניק ללומדים סביבת לימודים ממוחשבת ,התואמת את תוכנית הלימודים של משרד החינוך בארץ החל משלב ההכנה לכתה א' ועד כתה יב' – כולל הכנה לבחינות הבגרות. .3נושאי הלימוד מתמקדים בהבנת הנקרא בעברית ,מיומנויות בשפה העברית ,שיפור הכתיבה והקריאה בעברית ,תנ\"ך ,הבעה ,לשון ואזרחות הלימוד בבית הספר הווירטואלי אינו פוגע בזכות התלמיד ללמוד במסגרת חינוך עברי משלים ,באותם מקומות שמסגרת"}, {"p": 90, "t": "כזו קיימת. .4שנת הלימודים בבית הספר הווירטואלי תואמת את שנה\"ל בארץ. .5ההרשמה למסגרת לימודים זו נעשית בכל שנה בחודשי הקיץ בהמשך לחוזר שמופץ ע\"י היחידה למשאבי אנוש ומנהל בחו\"ל לכל הנציגויות ברחבי העולם."}, {"p": 90, "t": ".6הלימודים בבית הספר הווירטואלי ,כרוכים בהשתתפות כספית של השליח בסך של 380 ש\"ח לכל ילד ,סכום זה ינוכה מתלוש השכר של השליח. .7ביטול השתתפות ילד במסגרת בית הספר הווירטואלי והחזר כספי של  380ש\"ח ,תיעשה לאחר שהילד למד  4-5שיעורים בלבד .מעבר לכך ,לא ניתן יהיה להחזיר את ההשתתפות העצמית הנ\"ל."}, {"p": 90, "t": ".8ילדים שלומדים בבית ספר וירטואלי יוכלו ללמוד במקביל גם במסגרת \"חינוך עברי משלים\". הכרה בילדי שליחים חוזרים כ\"תושב חוזר\" משרד החינוך בישראל מכיר בילדי שליחים חוזרים כ\"תושב חוזר\" ומעניק להם הטבות מסוימות המאפשרות קליטה קלה במערכת החינוך בארץ."}, {"p": 90, "t": "תלמיד מוכר כ\"תושב חוזר\" אם שהה בחו\"ל לפחות  4שנות לימוד רצופות (הספירה מתחילה מכיתה א') .על מגוון ההטבות המוענקות לתלמידים שהם תושבים חוזרים ניתן ללמוד בעמוד האגף לקליטת עולים חדשים באתר משרד החינוך באינטרנט."}, {"p": 90, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 91, "t": "יחד עם זאת ,ילדי שליחים שחזרו לאחר  3שנות לימוד רצופות (ולא פחות מכך) יוכלו להגיש באמצעות המשרד בקשה לוועדת חריגים של משרד החינוך. השתתפות בעלות קייטנות לילדי שליחים .1השתתפות בעלות קייטנות לילדים בוגרי כיתות א' -ג' - משרד החינוך בארץ מפעיל תכנית \"בית ספר של החופש הגדול\" לתלמידים שסיימו כיתות א' -ג' בעלות מסובסדת להורים לאור כך ,מאושרת גם לשליחים בחו\"ל השתתפות"}, {"p": 91, "t": "בקייטנות בחו\"ל לפי התנאים שלהלן: א .ההשתתפות מאושרת רק עבור ילדי שליח הנלווים אליו לשליחות ,ושסיימו כיתות א' – ג'. ב .הקייטנה תתקיים במקום השירות. ג .ההשתתפות המאושרת הינה עבור  5שעות פעילות ביום ,למשך  15ימי פעילות בלבד (סה\"כ  75שעות פעילות) ,המתקיימת בתחילת החופשה הנהוגה במערכת החינוך המקומית עם תום שנת הלימודים .אם הפעילות בקייטנה מתקיימת באופן רחב יותר"}, {"p": 91, "t": "מ 75-שעות ,העלות המוכרת תחושב כחלק היחסי של עלות הקייטנה לפי היחס שבין 75שעות פעילות לבין סך שעות הפעילות בקייטנה בפועל. ד .השתתפות המשרד בעלות הקייטנה תהיה באופן הבא:"}, {"p": 91, "t": "ההוצאה אחוז ההשתתפות דוגמא להוצאה מוכרת טווח בשווי של  - 1200$סך בטווח המוכרת בדולרים השתתפות המשרד יעמוד על 825$ ()=100+325+400 0% 100X0%=0 100% 400X100%=400 65% 500X65%=325 50% 200X50%=100 מעל 1500 0% 0X0%=0 ה .השתתפות המשרד תשולם כנגד אישור רישום הילד לקייטנה וכנגד קבלות."}, {"p": 91, "t": "ו .לצורך קבלת ההשתתפות הכספית עבור הקייטנה כאמור לעיל ,יעביר השליח את הקבלות לחשב האזורי. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 92, "t": "ז. ההשתתפות תשולם לשליח בתלוש המשכורת ,במטבע תשלום הקייטנה בפועל ותחושב לפי שער החליפין השוטף. .2קייטנות לילדי שליחים ביתר הגילאים לשליחים ,עובדי משרד הביטחון ,מעביר וועד העובדים בשכר חו\"ל של חודש אוגוסט בכל שנה סכום הטבה בסך ( ₪ 300או בהתאם לסכום המעודכן שיהיה בתוקף באותו סכום) לילד בגילאי  ,2-12וזאת ללא צורך בהגשת קבלות."}, {"p": 92, "t": ".3שליחי צה\"ל יקבלו השתתפות בקייטנות כפי שמקבלים כל המשרתים בצה\"ל בארץ, באמצעות אכ\"א .לבירורים ניתן לפנות לרמ\"ד מעבר חו\"ל באג\"ת. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 93, "t": "זכויות ילדים חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 94, "t": "פרק  – 8זכויות ילדים זכויות ילדים מצטרפים לשליחות/נשארים בארץ ,פרוייקט גדנ\"ע/הכנה לצה\"ל /גיוס ,הגעת ילד למבדקים/הגעת הורה לגיוס וכיוצ\"ב זכויות ילדים שנשארו בארץ ביקור ילדים שנשארו בארץ ,אצל ההורים במקום השירות בחו\"ל ל\"ביקור הורים\" ,זכאים ילדי שליחים ,שנשארו בארץ ,או ילדים מנישואים קודמים של השליח ו/או של בן/בת זוגו."}, {"p": 94, "t": "יג. הזכאות לביקור הורים ניתנת בתנאים שלהלן: .1מינימום תקופת השליחות בחו\"ל – שנתיים. .2במקרה של ילדים מנישואים קודמים ,עד גיל  ,15המגיעים לבקר את השליח בחו\"ל במסגרת הזכאות ל\"ביקור הורים\" ,מאשר המשרד מימון דיילת מלווה לילד .עלות שירות זה תשולם ע\"י השליח .ההחזר הכספי יינתן תמורת קבלות באמצעות קצין המנהלה /מנהל כ\"א של הנציגות .במקרה שגיל הילד הינו מעל גיל  15ועד  .18היה והשליח מעוניין במלווה"}, {"p": 94, "t": "לילדו ,ייעשה הדבר על חשבונו. .3ילד המשרת בשירות חובה בצה\"ל ועד לאחר חצי שנה מסיום שירות החובה. .4ילד המשרת בשירות לאומי ועד לאחר חצי שנה מסיום השירות ,בתנאי שהשירות הלאומי נמשך שנתיים."}, {"p": 94, "t": ".5ילד הלומד במסגרת \"עתודה אקדמאית\" (רק במסגרת  3השנים הראשונות ללימודים). .6בהקשר לסעיפים  ,1-5כל האמור לא יחול לגבי ילדים בגיל  22שנה ומעלה. .7באותה שנה בה ההורים או אחד מהם יבקרו בארץ בחופשת מולדת או בחופשת הבראה, הילדים לא יהיו זכאים לביקור הורים."}, {"p": 94, "t": ".8פרק הזמן בין ביקור אחד למשנהו לא יהיה קצר משמונה חודשים. .9הביקור לא יאושר בשמונת החודשים הראשונים או שמונת החודשים האחרונים לשירות השליח בחו\"ל. .10מועד קיום ביקור ההורים יהיה לפי בחירת ההורים והילד .במקרה של חייל בשירות חובה בצה\"ל ,יהיה בתיאום ובאישור היחידה הצבאית בה הוא משרת."}, {"p": 94, "t": ".11לבני שליחים ,ששהו עם הוריהם בחו\"ל ושבו לארץ מכל סיבה שהיא (לימודים ,גיוס לצה\"ל) ,לא יאושר ביקור הורים בתקופה של חצי השנה הראשונה לעזיבתם את מקום השליחות. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 95, "t": ".12ילד המגיע לביקור הורים מבוטח בביטוח רפואי ע\"ח המשרד עד שישה שבועות בלבד. מעבר לכך ,על השליח לדאוג להמשך הביטוח הרפואי באופן פרטי. .13על השליח לוודא כי לילדו דרכון לאומי בתוקף לתקופה של  6חודשים לאחר המועד הצפוי ליציאה לביקור ההורים."}, {"p": 95, "t": ".14לילד של שליח שנמצא בארץ בשירות בצה\"ל /שירות לאומי /עתודה אקדמית ,יונפק דרכון דיפלומטי לפני יציאת ההורים לשליחות .הדרכון נשמר ביחידת נסיעות חו\"ל באכ\"ס ונמסר לילד בסמוך למועד נסיעתו לביקור הורים."}, {"p": 95, "t": ".15המשרד  /הזרוע הצבאית המשגרת את השליח ינפיק לילד אסמכתא לנסיעה ל\"ביקור הורים\" יטפל בוויזה ע\"פ הצורך) וירכוש לילד כרטיסי טיסה בדרך הקצרה והזולה ביותר. .16בנוסף ,יממן המשרד הוצאות נסיעה בתחבורה ציבורית מבית הילד בארץ לשדה התעופה ובשובו ,משדה התעופה בארץ לביתו."}, {"p": 95, "t": ".17עפ\"י הצורך ,יכסה המשרד עלות חיסונים לילד המבקר את הוריו במסגרת \"ביקור הורים\". .18ההוראות הנ\"ל חלות גם על ילדים מנישואים קודמים של השליח או של בן/בת זוגו. יד. תשלום מזונות לילדים מנישואין קודמים ,שנשארו בארץ שליח המשלם מזונות לגרושתו ולילדיו שבחזקתה ,על פי פסק דין מוסמך יציג ליחידת השכר בארץ טופס  101עדכני ויצרף צילום של הסכם הגירושין .בגין הילד עליו משלם השליח מזונות,"}, {"p": 95, "t": "יקבל השליח בשכרו נקודת זיכוי ממס. ילדים מצטרפים לשליחות לקראת גיל גיוס הגדרה \" -בן שליחים\" בן שליחים הוא מי שלפחות אחד מהוריו שעימו הוא שוהה בחו\"ל מייצג בחו\"ל גוף ישראלי כלשהוא ,ממשלתי ,ציבורי ,פרטי או אחר."}, {"p": 95, "t": "פטור/דחיית שירות צבאי בן שליחים פטור/דחיית שירות צבאי לילדי שליחים השוהים בחו\"ל איננו עניין אוטומטי .חובת השירות בצבא חלה על כל אזרח ישראלי ,בין אם הוא מתגורר בישראל ובין אם לא .הכלל הוא – עד שצה\"ל לא מעניק לך פטור/דחיית שירות ,אתה חייב בשירות בצבא בהיותך ישראלי .וכך, מגיל  16מוגדרים כל נער ונערה בישראל מלש\"בים – מועמדים לשירות בטחון ,מתחילים לקבל צווי התייצבות וצווי גיוס .גם צעירים ישראלים השוהים בחו\"ל מקבלים לא אחת זימונים"}, {"p": 95, "t": "למיונים ומבחנים לצה\"ל ,לפעמים כשהם כלל לא נמצאים בארץ .ככלל על כל מלש\"ב בגיל 16 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 96, "t": "חלה חובת גיוס והתייצבות לצווים ומיונים ,והוא ייקרא לגיוס בין הגילאים  18-20על פי החוק .יחד עם זאת ,לגבי מלש\"בים אשר הוריהם שוהים בשליחות ,קיימות אפשרויות של קבלת דחיית שירות וקבלת פטור משירות צבאי בקטגוריית \"בן שליחים\" .חובת הסדרת הפטור/דחיית השירות מול רשויות הצבא לפני עזיבה ולא בדיעבד על מנת לא להיחשב עריקים חלה על השליח .ניתן להסדיר את המעמד באמצעות פניה מתאימה אל רשויות הצבא עוד"}, {"p": 96, "t": "בהיות המשפחה בישראל ,וניתן לבצע זאת גם בחו\"ל באמצעות פניה לקונסוליה תוך הצגת מסמכים רלוונטיים. אם לשליח בן/בת המצטרפים אליו לשליחות והם מעל גיל  17ומיועדים לשירות ביטחון (מלשבי\"ם) ניתן לבקש עבור המלש\"ב מעמד מיוחד ,אמנם הוא אינו זכאי למעמד המיוחד של בן מהגרים או יליד חו\"ל ,אך ,הוא יוכל לבקש את דחיית ההתייצבות לשירות בטחון."}, {"p": 96, "t": "יש לשלוח ללשכת הגיוס אישור רשמי מהיחידה למשאבי אנוש ומנהל בחו\"ל על יציאת המשפחה לשליחות (\"אישור שליחות\") .הנ\"ל נדרש לצורך הסדרת מעמדם הצבאי כ\"בני שליחים\" על מנת שהמערכת הצבאית תדע לטפל בהם במסלול ייחודי לילדים לפני גיוס ו/או לצורך קבלת אישור דחיית גיוס .לנוחיותכם להלן קישור לאתר רישום והסדרת מעמד צבאי מול נציג דיפלומטי או קונסולרי."}, {"p": 96, "t": "https://www.gov.il/he/service/registration_and_regulation_of_idf_status זכאות לילדים המצטרפים לשליחות לפני גיל גיוס בני שליחים ,שקיבלו אישור על פטור משירות ביטחון או דחיית שירות ,יכללו באסמכתת השליח ,עד לפני שמלאו להם גיל  19בלבד על כל המשתמע מכך (לדוג'  :לא יהיו זכאים להיכלל באסמכתא ולפיכך לא יהיו זכאים לחופשות ,השתתפות בעלות כרטיסי טיסה וכד')."}, {"p": 96, "t": "לגבי ילדי שליחים ,שבמועד היציאה לשליחות יהיו מעל גיל  ,18חובה על השליח להציג ליחידה למשאבי אנוש ומנהל בחו\"ל את אישור צה\"ל על דחיית הגיוס או פטור משירות ביטחון ,במידה וניתן כזה .ללא אישורים אלה ,לא ניתן יהיה לכלול את הבן/בת באסמכתא."}, {"p": 96, "t": "הגעת הורה לארץ לגיוס/סיום קורס/מבדק ליח' מובחרת הוראת שות\"ש  1.2.5.1נסיעות שליח או ילדיו במהלך השירות המשרד מממן הגעת הורה אחד (לפי בחירת המשפחה) ,לצורך ליווי הילד/ה בתהליך הגיוס לצה\"ל .מימון המשרד הינו לכרטיס טיסה בלבד .לא כולל הוצאות מוניות ,שהייה ולינה בארץ."}, {"p": 96, "t": "ילדי שליחים המשרתים בצה\"ל  -הגעת הורה לארץ לסיום קורס /מבדק ליח מובחרת חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 97, "t": "במקרים בהם לשליח שני ילדים ויותר המשרתים באותה העת בצה\"ל ,יממן המשרד כרטיס טיסה לארץ פעם אחת לכל ילד לסיום מסלול /קורס. טו. הטסה לישראל במסגרת גיוס לצה\"ל .1זכאות שליח או בן זוגו אשר מלווה את ילדו המתגייס לצה\"ל יהא זכאי לכרטיס טיסה אחד מיעד השליחות לישראל ובחזרה .זאת ,עבור טיסה שמועדה עד שבועיים לפני מועד הגיוס של המתגייס."}, {"p": 97, "t": ".2השתתפות המשרד א .המשרד ישתתף בהוצאות כרטיס הטיסה בלבד. ב .למען הסר ספק ,מובהר ,כי אין באמור בהוראה זו כדי להוות אישור לתשלום קצובת לינה ושהייה בארץ. ימי הטיסה הלוך ושוב וימי השהייה בארץ ינוכו מחשבון ימי חופשת חוץ-לארץ של השליח."}, {"p": 97, "t": "ג .למימוש זכאות זו תונפק להורה אסמכתא להגעה לארץ ,תמורת הצגת צו גיוס בתוקף של המתגייס. .3אופן קבלת ההשתתפות א .כרטיס הטיסה יירכש על ידי המשרד. ב .אישור מימון כרטיס הטיסה יבוצע כנגד הצגת צו גיוס בתוקף של המתגייס."}, {"p": 97, "t": "טז. הטסה לישראל במסגרת מבדקי צה\"ל ליחידות מובחרות .1זכאות ילדו של שליח ,המועמד לשירות ביטחון ואשר קיבל זימון מצה\"ל להשתתף במבדקים ליחידות מובחרות ,יהא זכאי פעם אחת במהלך תקופת השליחות לכרטיס טיסה לצורך נסיעתו ממקום השליחות של הוריו למקום מגוריו בישראל ובחזרה."}, {"p": 97, "t": ".2השתתפות המשרד א .המשרד ישתתף בהוצאות כרטיס הטיסה בלבד. ב .למען הסר ספק ,מובהר ,כי אין באמור בהוראה זו כדי להוות אישור לתשלום קצובת לינה ושהייה בארץ. ג .ימי הטיסה הלוך ושוב וימי השהייה בארץ ינוכו מחשבון ימי חופשת חוץ-לארץ של השליח."}, {"p": 97, "t": ".3אופן קבלת ההשתתפות כרטיס הטיסה יירכש על ידי המשרד. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 98, "t": "אישור מימון כרטיס הטיסה יבוצע כנגד הצגת זימון למבדקים על ידי צה\"ל. הגעת ילד/ה לארץ לצו ראשון  /מיונים ומבדקים ליחידות שונות המשרד מממן לילדי שליחים עלות הגעה אחת לארץ לצורך ביצוע \"צו ראשון\" (אם הנ\"ל לא בוצע במסגרת שבוע הגדנ\"ע וההכנה לצה\"ל) ,או למבדקים ליחידות שונות  /מסלולים ייחודיים .מימון ההגעה לארץ למטרות הנ\"ל ,הינו בנוסף על מימון ההגעה לגדנ\"ע."}, {"p": 98, "t": "היות והמשרד מממן עלות טיסה בלבד לארץ למבדקים ומיונים לצה\"ל ולצורך צמצום עלויות הנסיעות הנוספות ,שיחולו על ההורים ,מומלץ לשליח לפנות למיט\"ב בניסיון לרכז מבדקים (במידת האפשר) ,כך שניתן יהיה בהגעה אחת להספיק כמה שיותר."}, {"p": 98, "t": "מימון ההגעה ע\"ח המשרד  /צה\"ל מותנה בהמצאת אישור זימון רשמי מצה\"ל ע\"ש הילד המלש\"ב. לילדי שליחי משהב\"ט ונספחי הגנה ,תמומן הנסיעה ע\"ח אסמכתא ,שתונפק ע\"י היח' למשאבי אנוש ומנהל בחו\"ל .לילדי שליחי צה\"ל ,תונפק האסמכתא ע\"י קצין הנסיעות הזרועי."}, {"p": 98, "t": "לצורך אישור ההגעה והנפקת האסמכתא לילד ,יפנה השליח ליח' למשאבי אנוש ומנהל בחו\"ל, באמצעות מנהל כ\"א של המשלחת  /נספחות ,לפחות חודש לפני מועד ההגעה הרצוי .שליחים הכפופים מנהלתית למשלחת ניו יורק יקבלו את האישור מממש\"ן .11 ילדי שליחים המשרתים בצה\"ל – זכויות \"חייל בודד\" חייל המשרת בשירות חובה בצה\"ל ,יוכר כ\"בן-שליחים\" ,כאשר שני הוריו אינם נמצאים בארץ ,מאחר שהם נמצאים בחו\"ל בשליחות לתקופה של חצי שנה ומעלה ומועד חזרתם"}, {"p": 98, "t": "ידוע. לאחר שיוכר בצה\"ל כ\"בן-שליחים\" ,יקבל החייל \"תעודת בודד\" ,המעניקה לו את ההטבות הבאות: .1מענק בודדים חודשי בגובה שכר טוראי ,בנוסף על המשכורת הצבאית. .2יהיה זכאי לחופשה מיוחדת של עד  21יום לביקור הוריו בחו\"ל (מימון כרטיס טיסה פעם אחת) ,פעם בכל שנת שירות שלו בצה\"ל (מימוש החופשה ייעשה במסגרת הזכאות ל\"ביקור הורים\")."}, {"p": 98, "t": ".3זכאות כספית חודשית לרכישה ברשת שיווק. .4תווי חג מצה\"ל בראש השנה ובפסח. .5זכאות ליום סידורים אחד בחודש בתקופת הכשרה או אחת לחודשיים במהלך השירות. .6דמי שהייה בעת חופשת מחלה."}, {"p": 98, "t": ".7לינה בבית החייל בסופי שבוע. .8הוצאות אחזקת דירה ,במקרה בו מאושר שכר דירה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 99, "t": "האמור לעיל בכפוף להוראות הצבא המתעדכנות מעת לעת  -למימוש זכויות חייל בודד, על החייל לפנות לקצינת הת\"ש ביחידתו. חזרת ילדי שליחים ארצה לפני תום השליחות שליח ,שאחד מילדיו חזר לארץ לפני תום תקופת השליחות ,לרבות בגין גיוס לצה\"ל ,חייב לדווח על כך באופן מיידי ליחידה למשאבי אנוש ומנהל בחו\"ל באמצעות מנהל כ\"א /קצין מנהלה בנציגות."}, {"p": 99, "t": ".1המשרד יממן לילד כרטיס טיסה ארצה (כמו כרטיס טיסה של תום שליחות). .2ילד החוזר ארצה רשאי לקחת עימו ע\"ח המשרד ,מטען אווירי בלבד של  100ק\"ג ומזוודה אחת נוספת בטיסה ארצה (פרטים ראה בפרק  – 2מטענים אישיים)."}, {"p": 99, "t": ".3כל עוד השליח נישאר בדירה בה גר לפני עזיבת ילדו ,לא יחול שינוי בקצובת שכר הדירה המשולמת לו .במידה והשליח עבר לדירה אחרת לאחר עזיבת הילד ועל פי בחירתו ,קצובת הדיור תתעדכן בהתאם למצבו המשפחתי החדש בחו\"ל ולקצובת שכר הדירה המאושרת ע\"י הוועדה הבין-משרדית באותה העת במקום המגורים החדש של השליח."}, {"p": 99, "t": ".4ילד החוזר ארצה במהלך תקופת שליחות הוריו בחו\"ל ,יהיה זכאי ל\"ביקור הורים\" ובלבד ששהה בארץ בנפרד ממשפחתו לפחות חצי שנה. .5במקרה של ילד החוזר לארץ לגיוס ,קיימת זכאות אחד ההורים להגיע עימו לארץ ."}, {"p": 99, "t": "פרוייקט גדנ\"ע בכל שנה בחודש יולי ,מתקיים בארץ שבוע גדנ\"ע והכנה לצה\"ל לילדי שליחים. מדובר בפרוייקט ייחודי ,אותו מובילים במשותף משהב\"ט ,משרד החוץ ומשרד ראה\"מ. יודגש כי קיום הפרוייקט מותנה בפתיחת בסיסי הגדנ\"ע לפעילות בהתאם להנחיות צה\"ל."}, {"p": 99, "t": "מטרות התכנית: חיזוק הזהות הישראלית היהודית בקרב בני השליחים ,חיזוק תחושת המחויבות של בני השליחים כלפי מדינת ישראל והשירות בצה\"ל. העצמת תחושת המסוגלות האישית שלהם כפרטים בתוך המסגרת הצבאית והעברת מידע חיוני על מסלולי השירות והיחידות השונות בצה\"ל."}, {"p": 99, "t": "קהל היעד: התוכנית מיועדת לבני  /בנות שליחים בגילאי  , 17-18ששוהים בשליחות עם הוריהם וסיימו כיתה יא' בחו\"ל. מקום ביצוע הפרוייקט: שבוע הגדנ\"ע וההכנה לצה\"ל יתקיים בארץ באחד מבסיסי הגדנ\"ע ."}, {"p": 99, "t": "יודגש כי קיום הפרוייקט מותנה בפתיחת בסיסי הגדנ\"ע לפעילות בהתאם להנחיות צה\"ל. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 100, "t": "מועד הפרוייקט: חודש יולי ,ימים א' עד -ו'. בנוסף ,בשיתוף עם מיט\"ב ,ניתנת אפשרות לבצע התייצבות לצו ראשון מותאם לילדי שליחים ,באופן קבוצתי ,מיד בסיום שבוע הפעילות בגדנ\"ע."}, {"p": 100, "t": "לבנות ,תתאפשר השתתפות ב\"יום המאה\". יש לקחת בחשבון השארות הילדים בארץ לפחות שבוע ימים לאחר תקופת הגדנ\"ע, לצורך צו ראשון ויום המא\"ה. השתתפות המשרד השתתפות המשרד במימון רכישת הכרטיסים– לילד בלבד ."}, {"p": 100, "t": "מודגש כי המשרד איננו מממן כל שהיה או הסעות הכרוכות בהגעת הילד במסגרת הפרוייקט (כגון :הסעות לשדה התעופה ומשדה התעופה ,שהייה/לינה/אש\"ל עד למועד שבוע הגדנ\"ע ולאחריו)."}, {"p": 100, "t": "על השליח לוודא כי לילד המגיע לפרוייקט יש את כל הנדרש לשהות כאמור; לרבות מקום להתארח וכד'. כמו-כן ,ביום החמישי לפרוייקט נערך טקס בבסיס הגדנ\"ע (החל מהשעה . )16:30 לטקס מוזמנים קרובי המשפחה הנמצאים בארץ ,יש לוודא ולעדכן פרטי קרוב המשפחה אשר יגיע/ו (לצורך הגעה לטקס המשרד מסדיר הסעות מאורגנות לטקס)."}, {"p": 100, "t": "אסמכתא – פרוייקט גדנ\"ע . מימון הטיסה לארץ ייעשה במסגרת אסמכתא שתוזרם ע\"י המשרד/צה\"ל או במסגרת הגעת הבן/בת לארץ לחופשת מולדת/חופשת הבראה ,או סיום שליחות (במקרה שתקופת השליחות תסתיים בשנת הפעילות תוזרם אסמכתא סיום שליחות לילד השליח אשר זכאי להגיע לפרוייקט הגדנ\"ע .הילד יסיים את תקופת השליחות בחודש יולי מייד לאחר פרוייקט הגדנ\"ע ולא יהיה זכאי למימון כרטיסי טיסה או כל מימון אחר לחזרה"}, {"p": 100, "t": "למקום השירות של אביו/אימו. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 101, "t": "זכויות מצטרפים ידוע בציבור/ הורה סמוך חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 102, "t": "פרק  – 9זכויות מצטרפים ידוע בציבור /הורה סמוך ידוע  /ידועה בציבור .1שליח ,שהמשרד אישר צירוף בן/בת הזוג במעמד \"ידוע/ה בציבור\" ,יקבל בגינו בתקופת השליחות ,זכויות כשל \"נשוי\"."}, {"p": 102, "t": ".2לצורך התנעת תהליך ההכרה בבן /בת הזוג כידוע/ה בציבור ,יש לפנות ליחידה למשאבי אנוש ומנהל בחו\"ל מוקדם ככל הניתן. .3ההכרה בידוע/ה בציבור לצורך שליחות תהיה לבני זוג ,שהוכיחו קשר זוגי כמפורט להלן, בתקופה של  3-4שנים לפחות לפני היציאה לשליחות ולאחר גיל .21 אם לבני הזוג ילד משותף או שיש ביניהם הסכם ממון ,יש צורך בהוכחת קשר זוגי של שנה אחת בלבד."}, {"p": 102, "t": ".4על השליח להגיש מכתב בקשה להכיר בבן/בת זוגו כידוע/ה בציבור לצורך יציאה לשליחות ולצרף אישור מביטוח לאומי המכיר בבני הזוג כידועים בציבור .לחילופין ניתן להמציא לפחות שתי ראיות ,המוכיחות שהציבור הכיר וקיבל את בני הזוג ,כאילו היו בעל ואישה וכך התייחס אליהם ,ושבני הזוג מקיימים קשר קבוע ,שיש בו סימני היכר של קיום יחידה משפחתית ,לדוגמא :מגורים משותפים ,ניהול משק בית משותף ,מען משותף לחשבונות,"}, {"p": 102, "t": "חשבון בנק משותף ועוד. אין די בחברות או בחיים משותפים לצורך הוכחת ההכרה כאמור. בנוסף לראיות כמצוין לעיל ,יש להגיש תצהיר נוטריוני. לתשומת לב השליחים היוצאים לארה\"ב השלטונות האמריקאים אינם מכירים בדרך כלל במעמד של ידוע/ה בציבור לצורך הענקת אשרת כניסה דיפלומטית."}, {"p": 102, "t": "על בן/בת הזוג ,לדאוג בעצמו לדרכון לאומי בר תוקף ולהנפקת אשרת תייר (מותנית בעמידה בקריטריונים של מחלקת המדינה האמריקאית) .במקרה כזה ,תוגבל שהותו בארה\"ב עפ\"י שיקולי פקיד ההגירה בכניסה לארה\"ב ,לתקופה שבין חודש לשנה .לאחר מכן יהיה עליו לעזוב את גבולות המדינה .היה ובן/ת הזוג יועסק כאית\"ן ,ניתן להסדיר לו אשרת עבודה (וויזה  A2בדרכון הלאומי)."}, {"p": 102, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 103, "t": "\"הורה סמוך\" מצטרף לשליחות (הוראת שות\"ש )1.2.5.1 .1צירוף הורה סמוך צירוף הורה סמוך הינה בהתאם להחלטת הנהלת המשרד ובכפוף לתנאים לאחר שהשליח המציא את כל המסמכים הנדרשים המעדים על שההורה מתגורר בבית השליח וסמוך על שולחנו כלכלית ,כשירות רפואית מרופא המשפחה וחוו\"ד רופא האמון ומסמכים נוספים עפ\"י דרישת המשרד."}, {"p": 103, "t": ".2זכאות א .שליח יהיה זכאי לצרף הורה סמוך למקום שירותו אם הוא עונה על הגדרת הורה סמוך ובכפוף לתנאים הרשומים בהוראת השות\"ש כדלהלן. ב .שליח שבקשתו לצירוף הורה סמוך אושרה יחתום על התחייבות להודיע לאגף הכספים ולאגף אמ\"ש על כל שינוי בתנאים שעל פיהם אושרה ההצטרפות."}, {"p": 103, "t": "ג .אם הוברר במהלך השרות ,כי צירוף ההורה נעשה בניגוד לתנאים האמורים יחויב השליח להחזיר את כל הסכומים ששולמו לו עבור ההורה. ד .אם במהלך השירות חדלו להתקיים התנאים ששימשו בסיס להחלטת צירוף ההורה, לא יהיה המשרד חייב לשלם את הוצאות החזרה לארץ או הוצאות הנסיעה למקום שירות אחר של ההורה."}, {"p": 103, "t": ".3השתתפות המשרד א .ביטוח רפואי  -ההורה יצורף לביטוח הרפואי הקיים במקום השירות תהא בהתאם להחלטת חשב במסגרת ביטוח שיעשה ע\"י השליח באופן פרטי ו/או במסגרת הביטוח הרפואי הקיים בנציגות ו/או במסגרת דמי ניהול הכל בכפוף להחלטת חשב המשרד."}, {"p": 103, "t": "ב .במקרה של ביטוח פרטי ,על השליח לפעול לאיתור ולקבלת הצעות לפוליסת ביטוח פרטית להורה הסמוך ,התואמת את מסגרת סל הבריאות הישראלי ולהעביר אותה לפני ביצוע התשלום לחשב לצורך קבלת אישור עקרוני להחזר כספי עתידי בגובה של עד 50% -מעלות הפרמיה .רק ובכפוף לאישור חשב ,השליח ישלם עלות הביטוח במלואו ויגיש קבלה למנהל כ\"א  /קצ\"מ הנציגות."}, {"p": 103, "t": "ג .המשרד יממן כרטיס טיסה להורה למקום השירות ובחזרה בעת סיום השליחות. ד .השתתפות בגין מטען – בהתאם לזכאויות השליח עבור ילדו לפי הוראה \"שינוע מטענים מישראל ליעד השליחות לפני השירות\" ,מס' .1.1.5.2 ה .המשרד ישתתף בהוצאות שהייה במלון בתחילת תקופת השירות ובסיומה בשיעור של 25%מקצובת הלינה (ר' הוראה \"קצובות שהייה והסדר לינה בנסיעה בתפקיד במהלך השירות\" ,מס' .)1.2.8.4"}, {"p": 103, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 104, "t": "ו .לשליח תינתן תוספת בשיעור  10%לקצובת הדיור במקרה שהקצובה המגיעה אינה מספיקה. ז .יובהר כי השליח לא יהיה זכאי לקצובת ביגוד נוספת ,החזרי טיסות נוספים ,או כל תוספת והחזר שאינם רשומים במפורש בהוראת השות\"ש."}, {"p": 104, "t": "ח .המשרד איננו משתתף בעלויות והוצאות מעבר לאמור לעיל לרבות חופשות מזכות של השליח וכל עלות בגין חופשה או הוצאות תהא על חשבון השליח. ט .אופן קבלת ההשתתפות שליח יהיה זכאי לצרף הורה סמוך למקום שירותו על סמך הגשת תצהיר באמצעות עורך דין המאשר כי ההורה עונה על הגדרת הורה סמוך ואין פתרון אחר אלא בצירופו למקום השירות .בנוסף ,התצהיר יכלול:"}, {"p": 104, "t": ")1הצהרה כי ההורה מסתמך אך ורק על הכנסה מקצבת זקנה ואין לו כל הכנסה אחרת. )2הצהרה שההורה אינו סיעודי .יובהר שלא תאושר הצטרפותו של הורה סיעודי. )3הצהרה כי לשליח אין אחים שמתגוררים בישראל ,אלא אם הינם במצב סיעודי ו/או נתמכי סעד והוצג על כך אישור מהגורמים המוסמכים בישראל."}, {"p": 104, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 105, "t": "לינה בבית מלון בישראל לפני /במהלך ובסוף השירות חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 106, "t": "פרק  - 10לינה בבית מלון בישראל לפני השירות במהלך השירות ובתום השירות הוראה .1.1.2.1.לינה בבית מלון בישראל לפני השירות הוראה .1.2.2.2.לינה בבית מלון בחול ובארץ במהלך השירות במטרה להקל על המשפחה בתקופה שבין שיגור המטען ובין היציאה לחו\"ל בפועל ,זכאים השליח ובני המשפחה שבאסמכתא ,ללינה במלון בארץ לפני היציאה לשליחות."}, {"p": 106, "t": "לרשות השליח ובני המשפחה שבאסמכתא ,עומדת מכסה של עד  22ימי לינה במלון בישראל או בדירת  AIRBNBאו בצימר או בשכירות דירה ,למשך כל תקופת השליחות .מתוך הניסיון המצטבר ,מומלץ להשאיר לילות רבים יותר במלון ,לסוף השליחות."}, {"p": 106, "t": "להלן נוהל לינה מעודכן דצמבר :2021 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 107, "t": "אגף הכספים מדינת ישראל  -משרד הביטחון דצמבר 2021 נוהל הזמנת לינות בישראל במסגרת הזכאות ל 22-לילות .1כללי – א .לרשות שליח ובני משפחתו שבאסמכתא ,עומדת מכסה של עד  22לילות במלון בישראל למשך כל תקופת השליחות ,אותם יכול לנצל במקרים שיפורטו להלן:"}, {"p": 107, "t": "• לפני היציאה לשליחות ,לאחר שמכולת החפצים האישיים נלקחה מביתו. • במהלך השליחות בעת הגעה לארץ לחופשות. • לאחר החזרה מהשליחות וכל עוד מכולת החפצים האישיים טרם הגיעה לביתו בארץ."}, {"p": 107, "t": "ב .באחריות מנהל כ\"א /קצ\"מ הנציגות לנהל רישום ומעקב אחר יתרת הזכאות של כל שליח אל מול ה 22-לילות שעומדים לרשותו (לרבות תחילת שליחות, במהלכה ובסוף השליחות). ג .בכל במקום במסמך זה שבו מצוין המונח\" :מנהל כ\"א  /קצ\"מ הנציגות\" ,הכוונה היא לגורם המטפל במנהלות השליחים (בנספחויות הקטנות ,יהא זה הנספח עצמו או עובד האית\"ן האחראי על הניהול הכספי של הנספחות)."}, {"p": 107, "t": ".2אפשרויות הלינה – א .לינה בבית מלון. ב .לינה בדירת ( AirBnbאו אפליקציה דומה) או בצימר ג .שכירות בלתי מוגנת -נדרש להציג חוזה שכירות. לעניין סעיפים ב-ג ובלבד שניתן להמציא קבלה או הוכחת תשלום כנגד ההוצאה."}, {"p": 107, "t": "מודגש כי במקרה זה ,יהיה על השליח להעביר למשרד הצהרה בכתב לפיה אין לו הכרות אישית מוקדמת או קרבה כלשהי למשכיר או לבעל הדירה  /צימר. ג .בסוף שליחות בלבד ,קיימת אפשרות לשכירת ציוד לצורך מגורים בדירת השליח בארץ."}, {"p": 107, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 108, "t": ".3קצובות הלינה – א .קצובה ללינה בבית מלון  -לרשות השליח עומדת קצובת לינה בסך של ₪ 462 ללילה לעובד ,לא כולל מע\"מ ,כמצוין בהוראת תכ\"ם מס' \" 13.4.0.3החזר הוצאות בגין לינה אקראית לעובד בתפקיד\" (קצובה זו מתעדכנת מעת לעת בהתאם להחלטת החשב הכללי במשרד האוצר)."}, {"p": 108, "t": "הזכאות הינה בהתאם להוראת השות\"ש ,כמפורט להלן: מצב משפחה שיעור מקצובת הלינה בהוראת התכ\"ם שליח רווק שליח המגיע למקום כהונתו בגפו בהתאם לקצובה שליח נשוי (קצובה לשליח עצמו)בעד בן/בת זוג תוספת של 40% בעד כל ילד תוספת 25% להלן דוגמת הסכומים המאושרים ללינה בבית מלון בהתאם לאמור לעיל:"}, {"p": 108, "t": "מצב משפחה קצובת הלינה לא כולל מע\"מ * רווק ₪ 462 נשוי ₪ 647 נשוי 1 + ₪ 762 נשוי 2 + ₪ 878 נשוי 3 + ₪ 993 נשוי 4 + ₪ 1,109 * חריגה מהקצובה ללינה בבית מלון ,בחודשי יולי אוגוסט בלבד:"}, {"p": 108, "t": "בנסיבות מיוחדות ,במקרים בהם הוכיח השליח ,שהקצובה אינה מספיקה (בדגש על משפחות עם ילדים) ,יפנה במכתב מנומק ,המגובה בהצעות מחיר שקיבל, למנהל כ\"א  /קצ\"מ הנציגות .הנ\"ל יבחן את הבקשה והיה והשתכנע ,יפנה לחשב האזורי להמשך טיפול למול הנהלת אכ\"ס בארץ."}, {"p": 108, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 109, "t": "ב .קצובה ללינה בדירת  AirBnbאו לינה בצימר או בשכירות בלתי מוגנת: 75%מהקצובה המפורטת בסעיף א' לעיל. הקצובה תעמוד על להלן דוגמת הסכומים המאושרים בדירת  AirBnbאו לינה בצימר או בשכירות בלתי מוגנת בהתאם לאמור לעיל:"}, {"p": 109, "t": "מצב משפחה קצובת הלינה לא כולל מע\"מ* רווק ₪ 347 נשוי ₪ 486 נשוי 1 + ₪ 573 נשוי 2 + ₪ 660 נשוי 3 + ₪ 746 נשוי 4 + ₪ 833 למען הסר ספק ,מע\"מ יתווסף לסכום הקצובה רק במקרים בהם מחויב מע\"מ על פי חוק וכנגד המצאת קבלה הכוללת מע\"מ .כך לדוגמא במצב של שכירות בלתי מוגנת מול ישות פרטית ,הקצובה לא תכלול מע\"מ * הגדלת הקצובה במקרים חריגים ללינה בדירת  AirBnbאו לינה בצימר או"}, {"p": 109, "t": "בשכירות בלתי מוגנת: בנסיבות מיוחדות ,במקרים חריגים ,בהם מיצה השליח את כל האפשרויות ולא מצא מקום לינה בהתאם לצרכיו במסגרת הקצובה ,יפנה השליח למנהל כ\"א / קצ\"מ הנציגות ויעביר את תוצאות חיפושיו בצירוף נימוקים."}, {"p": 109, "t": "מנהל כ\"א  /קצ\"מ הנציגות ,יפנה לחשב האזורי בצירוף המלצתו ,ויבקש לאשר הגדלת הקצובה עפ\"י סמכותו של החשב האיזורי ,עד ל 100%-הקצובה המפורטת בסעיף  3א' לעיל. בחודשי יולי אוגוסט בלבד לדירת  AirBnbאו צימר או שכירות – תהיה הקצובה בשיעור של עד  ,100%בהתאם למפורט בסעיף  3א' לעיל .מודגש כי לא תאושר במקרים אלה כל חריגה מהקצובה המלאה."}, {"p": 109, "t": "ג .שכירת ציוד לצורך מגורים בדירת השליח בארץ – בחזרה משליחות ,במקרה שבו דירת השליח פנויה ומכולת החפצים האישיים טרם הגיעה לארץ ,יוכל השליח להתקשר באופן עצמאי עם חברת השכרת ציוד חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 110, "t": "וריהוט .במקרה זה המסגרת התקציבית שעומדת לרשות השליח תהיה עד גובה תקרת קצובת הלינה כאמור בסעיף  3א' לעיל  Xמספר ימי הזכאות שעומדים לרשותו במסגרת ה 22-לילות .לא תתאפשר חריגה מהקצובה."}, {"p": 110, "t": "אישור שכירת הציוד ייעשה מראש ,בטרם התקשרות עם החברה ,בכפוף להגשת שתי הצעות מחיר לבחינת החשב האזורי. ד .תשלום עבור חניות בבית מלון  /דירת  Airbnbבמסגרת ה 22-לילות - ככלל ,הזמנת המלון תכלול גם חניה במסגרת הקצובה .היה ואין למלון/דירת Airbnbחניון או שחניון המלון מתופעל ע\"י זכיין ולא ניתן לכלול את מחיר החניה בעלות החדר ,ישלם השליח מכספו עבור חניה בחניון סמוך ויקבל החזר תמורת"}, {"p": 110, "t": "קבלות עד לתקרה של  ₪ 70ליום .את הקבלות יגיש השליח במסגרת ההתחשבנות. סכום החניות יומר למטבע מקומי בהתאם לשער החליפין במועד החניה. נספח הגנה בעת הגעה לארץ בתקופת השליחות ,יוכל לשלם את החניה באמצעות כרטיס האשראי של הנספחות .במקרה שלא ניתן לבצע ההזמנה/תשלום באמצעות כרטיס האשראי של הנספחות (רגולציה ,בעיה טכנית ,כרטיס תקול ,המלון עובד רק עם כרטיסי אשראי מקומיים /בנקים מסוימים ,)....אזי הנספח ישלם עלות"}, {"p": 110, "t": "החניה מכספו ויקבל החזר ,כמקובל. .4אופן ביצוע ההזמנה – א .לפני היציאה לשליחות - השליח יזמין את הלינה באופן עצמאי וישלם באמצעי התשלום הפרטיים שלו, בהתאם לכללים לעיל."}, {"p": 110, "t": "את הקבלה המקורית/הוכחת תשלום יגיש לאחר תחילת השליחות למנהל כ\"א / קצ\"מ הנציגות ויקבל החזר כספי בהתאם להוצאה בפועל ולא יותר מהתקרה. מקדמה – לשליח שירצה בכך ,תאושר מקדמה עד  100%לצורך מימון הלינה ועד לקבלת ההחזר הכספי מהמשרד .המקדמה תאושר רק לאחר היציאה לשליחות."}, {"p": 110, "t": "לצורך קבלת המקדמה ,יהיה על השליח למלא \"טופס בקשה למקדמה לצורך הזמנת לינה במלון בישראל\" ,המצורף כנספח לנוהל זה. הטופס יוגש למנהל כ\"א  /קצ\"מ הנציגות ,שיעבירו לחשב האזורי לצורך אישור המקדמה."}, {"p": 110, "t": "למען הסר ספק ,המקדמה תשולם במדינת השרות. ב .במהלך השליחות ובחזרה משליחות – הזמנת השינה בארץ או שכירת הציוד ,תבוצע ע\"י השליח באופן עצמאי באמצעי התשלום הפרטיים שלו ,בהתאם לכללים לעיל."}, {"p": 110, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 111, "t": "מקדמה  -שליח שימציא אישור על ביצוע הזמנה למלון  / AirBnb /צימר  /שכירות בלתי מוגנת/שכירת ציוד ,יוכל לקבל מקדמה עד  85%מגובה ההזמנה בפועל או מתקרת הקצובה המאושרת ,הנמוך מבניהם."}, {"p": 111, "t": "ניתן לקבל את המקדמה בשקלים לחשבון הבנק בישראל או במטבע תשלום השכר במדינת השירות ,בהתאם לבחירת השליח. לצורך קבלת המקדמה ,יהיה על השליח למלא \"טופס בקשה למקדמה לצורך הזמנת לינה במלון בישראל\" ,המצורף כנספח לנוהל זה."}, {"p": 111, "t": "הטופס יוגש למנהל כ\"א  /קצ\"מ הנציגות ,שיעבירו לחשב האזורי לצורך אישור המקדמה. למען הסר ספק ,המקדמה תשולם בארץ. .5אופן קבלת ההחזר לאחר סיום השהות במלון  /דירה  /צימר - א .בתחילת שליחות ובמהלך שליחות  -לאחר גמר השהות במלון  /דירה  /צימר ,על השליח לדרוש קבלה או להציג חוזה שכירות לשהייתו בתאריכים המצוינים וזאת כהוכחה לניצול הלינות בהתאם להזמנה .את הקבלה/חוזה  +הוכחת תשלום יעביר"}, {"p": 111, "t": "השליח תוך  7ימים למנהל כ\"א  /קצ\"מ הנציגות לצורך טיפול למול החשב האזורי ולהתחשבנות למול המקדמה. ב .בסיום שליחות – לאחר גמר השהות במלון  /דירה  /צימר  /שכירת הציוד ,על השליח לדרוש קבלה/להציג חוזה חתום+הוכחת תשלום ,לשהייתו בתאריכים המצוינים וזאת כהוכחה לניצול הלינות בהתאם להזמנה .את הקבלה/חוזה + הוכחת תשלום יעביר השליח תוך  7ימים מסיום השהות ,לגורמים המטפלים"}, {"p": 111, "t": "כמפורט להלן: • שליח עובד משהב\"ט יגיש את הקבלה ליחידה למשאבי אנוש ומנהל בחו\"ל. • שליח צה\"ל יגיש את הקבלה לקצין הנסיעות הזרועי הגורמים המטפלים כאמור לעיל יבדקו את הקבלה/חוזה+הוכחת תשלום והתאמתה להזמנה ויעבירו ליחידת השכר ,לצורך גמר התחשבנות למול המקדמה."}, {"p": 111, "t": "נספח לנוהל לינה טופס בקשה למקדמה לצורך הזמנת לינה בישראל  /שכירת ציוד חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 112, "t": "אל: מנהל כ\"א  /קצ\"מ הנציגות חשב אזורי אבקש לקבל מקדמה לצורך הזמנת לינה בישראל  /שכירת ציוד בתום שליחות עבור: תתחילת שליחות במהלך שליחות סיום שליחות המקדמה מיועדת לצורך הזמנת לינה במלון  /בדירת  / AirBnbבצימר / שכירות/שכירת ציוד בתום שליחות (נא להקיף) לתקופה מתאריך ___________ עד תאריך ___________ סה\"כ ____ לילות, בסך ____________ במטבע מקומי  /בש\"ח (נא להקיף)"}, {"p": 112, "t": "הריני מצרף לטופס זה את העתק ההזמנה/חוזה שכירות שבוצעה על ידי. אני מתחייב להגיש למשרד קבלה ,תוך  7ימים מגמר השהות במלון  /בדירת AirBnb /בצימר  /סיום שכירת הציוד בתום שליחות."}, {"p": 112, "t": "ידוע לי שככל שלא תוגש הקבלה כנדרש ,שמורה למשרד הזכות לקזז הכספים שקיבלתי בגין המקדמה מכל סכום שמגיע לי מהמשרד. ___________ שם השליח _____________ מס' ת.ז _____________ תאריך ____________ חתימה חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 113, "t": "לינה בבית מלון בחו\"ל בתחילת השליחות חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 114, "t": "פרק  - 11לינה בבית מלון בחו\"ל בתחילת השליחות הוראה .1.1.2.2.לינה בבית מלון בחו\"ל ובארץ במהלך השירות הוראת תכ\"ם מס' \" 13.4.0.3החזר הוצאות בגין לינה אקראית לעובד בתפקיד\"."}, {"p": 114, "t": "הודעת תכ\"ם ,מס' ה\" 13.10.0.2.2 .תעריפי קצובות שהייה ולינה בחוץ-לארץ\" שהייה במלון בחו\"ל .1לינה בבית מלון בחוץ-לארץ בתחילת השליחות זכאות א .שליח המגיע למקום השליחות לפני תחילת חוזה השכירות של דירתו יהא זכאי להשתתפות בהוצאות לינה במלון עבורו ועבור בני משפחתו הנלווים אליו."}, {"p": 114, "t": "ב .שליח המועבר למקום שירות אחר בחוץ-לארץ במהלך תקופת שירותו יהא זכאי להשתתפות בהוצאות לינה במלון עבורו ועבור בני משפחתו הנלווים אליו. השתתפות המשרד א .המשרד ישתתף בהוצאות הלינה בבית מלון בחוץ-לארץ עד למועד תחילת חוזה השכירות או עד  21יום ראשונים לשהייתו של השליח בחוץ-לארץ ו/או במקום השירות שאליו הועבר ,המוקדם מבניהם."}, {"p": 114, "t": "ב .אם במהלך תקופת הזמן של  21יום משהגיע למקום השירות ,לא מצא השליח דירה ,יפנה לקצין המנהלה בבקשה מנומקת בכתב להארכת שהותו במלון .במקרה שהנימוקים מצדיקים זאת ,קצין המנהלה יעביר את הבקשה לחשב המשרד."}, {"p": 114, "t": "ג .בהינתן אישור חשב המשרד ,השליח יהא זכאי להשתתפות החל מהיום ה22- ועד ליום ה 51-לשהייתו בחוץ-לארץ וזאת בתנאים הבאים: א .סכום ההשתתפות לא יעלה על הסכום שהשליח שילם במשך  21הימים הראשונים ,באופן יחסי."}, {"p": 114, "t": "ב .סכום ההשתתפות לא יעלה על השיעורים הנקובים בהוראת התכ\"ם. .2המשרד ישתתף בסכום ההוצאה בפועל בהתאם לתעריפים המפורסמים בהודעת תכ\"ם, \"תעריפי קצובות שהייה ולינה בחוץ-לארץ\" ,מס' ה ,13.10.0.2.2 .בשיעורים הבאים:"}, {"p": 114, "t": "מצב משפחתי שיעור מקצובת הלינה בהוראת התכ\"ם שליח נשוי בהתאם לקצובה בעד בן  /בת זוג תוספת של 40% בעד כל ילד  /הורה נלווה  /הורה סמוך תוספת של 25% שליח רווק או שליח המגיע למקום כהונתו בגפו בהתאם לקצובה חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 115, "t": ".3במקרה שאין אפשרות למצוא מקום בבתי מלון בתעריפים המפורטים בהודעת תכ\"ם, \"תעריפי קצובות שהייה ולינה בחוץ-לארץ\" ,מס' ה ,13.10.0.2.2 .חשב המשרד יהא רשאי לאשר חריגה מקצובת הלינה בהתאם להוראת התכ\"ם."}, {"p": 115, "t": ".4עבור התקופה שהשליח זכאי להשתתפות בהוצאת לינה במלון ,הוא לא יהא זכאי לקצובת דיור ,כמפורט בהוראת שות\"ש \"תשלום קצובת הדיור\" ,מס' .1.2.2.1 .5על אף האמור ,במקרה שבו חוזה השכירות נכנס לתוקפו ומדובר בדירה בלתי מרוהטת ומטען השליח טרם הגיע למקום שירותו ,ואם העיכוב בהגעת המטען אינו תלוי בהתנהלות בלתי תקינה של השליח ,בסמכות חשב המשרד לאשר המשך שהיית השליח במלון עד"}, {"p": 115, "t": "שבוע ימים ,או לחלופין שכירת ציוד בסיסי למגורים בדירה עד למועד הגעת המטען ,הזול מבניהם וזאת בנוסף לתשלום קצובת הדיור. .6יובהר כי שליח השוהה בבית מלון כאמור בהוראת זו ,לא יהא זכאי לכל השתתפות אחרת למעט הוצאות הלינה בבית מלון."}, {"p": 115, "t": "אופן קבלת ההשתתפות .1החזר הוצאות לינה בבית מלון ישולם בהתאם למפורט בהוראת תכ\"ם\" ,נסיעות לחוץ- לארץ – קצובות שהייה ולינה והחזרי הוצאות\" ,מס' .13.10.0.2 .2החזר הוצאות לינה בבית מלון שהשליח שילם בעצמו ,יבוצע בתלוש המשכורת בכפוף להצגת קבלות."}, {"p": 115, "t": "לינה במלון בעת ביקור בישראל במהלך השליחות – בהתאם לנוהל לינה המפורט בפרק 9 שליח המוחזר לישראל לפני תום תקופת שליחותו זכאות שליח המוחזר לארץ על-ידי המשרד לפני תום תקופת שליחותו ,ללא הודעה מוקדמת ,ולכן איננו יכול לחזור לדירתו בארץ מפאת השכרתה ,יהא זכאי להשתתפות בהוצאות לינה במלון בישראל או להשתתפות בהוצאות שכר דירה עבורו ועבור בני משפחתו הנלווים אליו."}, {"p": 115, "t": "השתתפות המשרד .1שליח המוחזר לישראל יקבל החזר הוצאות לינה במלון בישראל ,בהתאם לנוהל לינה פרק ,9ולמשך תקופה של עד  30יום מחזרתו לארץ .ימים אלו כוללים את ימי הלינה במלון בישראל הנותרים לו מהמכסה להם היה זכאי בתקופת שירותו."}, {"p": 115, "t": ".2המשרד ישתתף בהוצאות לינה במלון בארץ או בהוצאות שכירת דירה אחרת בארץ ,הזול מבניהם. .3במקרה שבו לשליח קיימת התחייבות לתשלום שכר דירה בחוץ-לארץ ,המשרד ישתתף בנוסף בתשלום כאמור וזאת לתקופה של עד  60יום או עד לסיום חוזה השכירות, המוקדם מבניהם."}, {"p": 115, "t": "לינה במלון בחוץ-לארץ טרם חזרה מהשליחות לישראל חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 116, "t": "זכאות השליח יהא זכאי ,בהתאם לשיקול דעת המשרד ,להחזר הוצאות לינה במלון בחוץ-לארץ במקרה של סיום חוזה השכירות טרם מועד סיום תפקידו. השתתפות המשרד .1השתתפות המשרד כמפורט בהודעת תכ\"ם."}, {"p": 116, "t": ".2השתתפות המשרד תהיה לתקופה של עד  30יום לינה במלון .ימים אלו חייבים להסתיים לפני מועד סיום השירות. .3בעד התקופה שהשליח זכאי להשתתפות בהוצאת לינה במלון ,כאמור לעיל ,השליח לא יהא זכאי לקצובת דיור ,כמפורט בהוראת שות\"ש\" ,תשלום קצובת הדיור\" ,מס' .1.2.2.1 .4על אף האמור ,במקרה שבו השליח כבר אינו יכול להתגורר בדירה ,אך טרם הסתיים החוזה ,בסמכות חשב המשרד לאשר השתתפות לינה במלון כאמור לעיל ,וזאת בנוסף"}, {"p": 116, "t": "לתשלום קצובת דיור ,לתקופה של עד שבוע ימים. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 117, "t": "פרק – 12 חופשות/ היעדרויות חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 118, "t": "פרק  - 12חופשות וימי מחלה הוראה .1.2.9.1.זמני עבודה חגים ומועדים הוראה .1.2.9.2.ימי חופשת מנוחה בחוץ לארץ הוראה .1.2.9.3.חופשת מחלה הוראה .1.2.9.4.מימון כרטיס טיסה לחופשת מולדת הוראה .1.2.9.5.מימון כרטיס טיסה לחופשת הבראה הוראה הוראה .1.2.9.6.מימון כרטיס טיסה לחופשה מיוחדת בישראל למשרתים במקומות רחוקים הוראה .1.2.9.7.מימון כרטיס לחופשה עבור שליח המשרת בגפו"}, {"p": 118, "t": "הוראה .1.2.9.9.היריון ותקופת לידה והורות הוראה .1.2.9.10.ימי אבל • המפורט בפרק זה הוכן ונערך על מנת לסייע בהבנת הזכאויות לחופשות/היעדרויות/לינה בארץ ובמקום השירות לפני ובמהלך השליחות."}, {"p": 118, "t": "• ריכוז הנתונים בפרק זה מתבסס על הוראות השות\"ש. • היחידה למשאבי אנוש ומינהל בחו\"ל ,קובעת ומאשרת את הזכאויות ותנאי השירות לשליחים בחו\"ל ,על בסיס הוראות השות\"ש. למען הסר ספק ,מובהר כי ,בכל מקרה של סתירה בין נתוני המצגת לבין הוראות השות\"ש, הוראות השות\"ש ,התקש\"יר ונהלי/הנחיות נש\"מ הם שגוברים."}, {"p": 118, "t": "כללי: \" .1חופשה פרטית\" היא חופשה ,לה זכאי שליח במסגרת ימי החופשה העומדים לזכותו במהלך תקופת השליחות למעט שליחי צה\"ל לומדים/קורסים/עמיתי מחקר אשר ימי החופשה נקבעים להם בהתאם לתקופת הלימודים ."}, {"p": 118, "t": ".2שליח יהא זכאי ל 22 -ימי חופשה שנתית ,כאשר מתוכם הוא חייב לנצל  14ימי חופשה לפחות בכל שנת שליחות קלנדרית (ינואר-דצמ). .3מדינת ישראל קובעת את תנאי הזכאות לחופשת מנוחה עבור שליח בחוץ-לארץ על בסיס הוראות התקשי\"ר\" ,חופשת מנוחה לעובדים המועסקים בחוץ-לארץ\" ,פרק 33.140 א .חשבון חופשת המנוחה של עובד ,המועסק בחוץ-לארץ ערב צאתו לחוץ-לארץ ,ייחסם (להלן \" -חופשה חסומה\");"}, {"p": 118, "t": "ב .עם צאתו של העובד לחוץ-לארץ ,יתנהל חשבון מיוחד ונפרד של חופשת המנוחה שלה הוא זכאי בתקופת שירותו בחוץ-לארץ (להלן \" -חופשת חוץ-לארץ\"). ג .עובד המועסק בחוץ-לארץ ,זכאי למשכורת חוץ-לארץ בעד ימי חופשת חוץ-לארץ שקיבל בזמן שהותו בחוץ-לארץ."}, {"p": 118, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 119, "t": "ד .חדל עובד להיות מועסק בחוץ-לארץ ,הוא זכאי למשכורת חוץ-לארץ בעד יתרת ימי חופשת חוץ-לארץ ,עד לתקופה של  32ימים (לרבות ימי מנוחה דהיינו; עד  22ימי עבודה) ,אם הוא מקבל אותה חופשה ברצף מיד עם סיום העסקתו בחוץ-לארץ ,בין אם הוא מבלה אותה בארץ ובין אם הוא מבלה אותה בחוץ-לארץ .כל עוד ובתנאי שלא התחיל לעבוד ושובץ במשרה אחרת בארץ (במשרד/בצה\"ל).."}, {"p": 119, "t": "ה .שליח משהב\"ט אשר סיים את תפקידיו בחוץ-לארץ ,יצורפו ימי החופשה שלא ניצל מתוך ימי הזכאות לחופשת חוץ-לארץ לחשבון החופשה החסומה ,עד למספר המרבי של ימי צבירה מותרת (הסעיף שלעיל) ."}, {"p": 119, "t": "ו. למרות האמור לעיל ,רשאי האחראי להורות לעובד לחזור לעבודה לפני שניצל את ימי החופשה העודפים ,כולם או מקצתם; ז .ניצול ימי חופשה לשליח צה\"ל – חשבון חופשת המנוחה בארץ מתנהל במסגרות הצבאיות עפ\"י הכללים הנהוגים בצה\"ל ובתום השליחות והתנהלות השליח בתום השליחות בכל הקשור לניצול ימי החופשה יהיו בהתאם לכללי צה\"ל וכל עוד לא התחיל תפקיד בארץ יוכל לנצל את היתרה (עפ\"י כללי מכסת יתרה צבורה לתקופת"}, {"p": 119, "t": "השליחות) יוכל לנצל את ימי החופשה בארץ. היה ולא ניצל את יתרת ימי החופשה הצבורה בגין שירותו בחו\"ל (הימים העודפים) ו/או התחיל תפקיד חדש ,עפ\"י הכללים בצה\"ל לא יוכל להזדכות בגין יתרת הימים ימים אלו ולא ניתן יהיה להעבירם למכסה הצהלית ערב יציאתם וכן לא ניתן יהיה לפדותם (לאחרונה מתקיימים דיונים בנושא זה מול מופ\"ת ואת\"ק ועם תתקבלנה החלטות שונות יחולו החלטות אלו על כלל השליחים)."}, {"p": 119, "t": "ח .חופשה פרטית משמעה בין היתר גם חופשת מולדת/מסובסדת/הבראה ,ההבדל הינו שחופשות מולדת/מסובסדת/הבראה מזכות בהשתתפות המשרד בעלות כרטיסי טיסה בלבד בהתאם לחלקיות ולתנאים המפורטים בהוראת השות\"ש."}, {"p": 119, "t": "בכל יתר התנאים בחופשות המזכות יחולו כללי החופשה הפרטית. הליך בקשה לחופשה א .שליח יבקש אישור ליציאה לחופשה מהממונים עליו ,בהתאם לנהלים. ב .ימי החופשה ,שינצל השליח במסגרת החופשה הפרטית/מולדת/מסובסדת/הבראה, ינוכו לו ממכסת ימי החופשה להם זכאי במהלך השליחות."}, {"p": 119, "t": "ג .ביציאה לחופשה פרטית שאיננה במסגרת החופשות המזכות (מולדת/הבראה/ מסובסדת) ,השליח לא יהא זכאי לכל החזר (חלקי או מלא) עבור כרטיסי טיסה/מוניות/שכירת רכב וכיוצ\"ב. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 120, "t": "ד .באחריות הקצ\"מ/נספח והשליח לוודא שלא לחרוג מימי החופשה השנתית (22 ימים) ,יחד עם זאת ,שליח אשר חרג ממכסת ימי החופשה המגיעים לו ,יבוצע ניכוי בשכר – על השליח חובת נימוק והסבר על החריגה – יש להעביר מכתב הסבר באמצעות מנהל המשא\"נ/קצ\"מ/נספח לראש יחידת משא\"נ ומינהל בחו\"ל."}, {"p": 120, "t": "ה .בקשה ליציאה לחופשה מזכה (מולדת/הבראה/מסובסדת) תועבר באמצעות השליח לקצ\"מ/נספח ע\"ג הטופס הרלוונטי לכל אחד מבני המשפחה המתוכננים לצאת לחופשה ובהתאם לכללים המזכים."}, {"p": 120, "t": "ו .אישור החופשה בזכאות כאמור הינו בסמכות יח' משא\"נ ומינהל בחו\"ל ע\"ג הטופס אשר הועבר.. שילוב ימי עבודה במסגרת חופשה פרטית /מולדת/הבראה/מסובסדת – הזרמת אסמכתא: א .שליח השוהה בארץ בחופשה פרטית/מולדת/הבראה/מסובסדת ובשל צורך חריג הטילה עליו הנהלת המשרד תפקידים שונים במהלך החופשה – ימי החופשה שבהם עבד בארץ ייחשבו כימי עבודה ,אך לא יותר משני ימי עבודה למעט במקרים חריגים"}, {"p": 120, "t": "באישור מנכ\"ל המשרד .תמורת ימים אלה השליח יהיה זכאי לתשלום בעד כלכלה בלבד בארץ ,בהתאם להוראות התקשי\"ר\" ,קצובת אש\"ל בארץ\" ,פרק ( .26.2הוראת שות\"ש )1.2.9.4 ב .שליח אשר כאמור לעיל מגיע לארץ לחופשה פרטית ,מולדת/הבראה/מסובסדת ונדרש ע\"י הגוף האחראי/ממונה עליו (באגפי המשרד או בצה\"ל) להגעה לימי עבודה  -תעודכן האסמכתא להגעתו או תוזרם אסמכתא נפרדת ללא טיסה על ידי הגוף המזמין תוך"}, {"p": 120, "t": "פירוט ימי העבודה הנדרשים לביצוע התפקיד ובהתאם לכללים למכסת ימי עבודה מותרת במסגרת חופשה פרטית (אך לא יותר מ 2 -ימי עבודה באישור מנכ\"ל). חופשה בארץ לאריזת– תחילת שליחות האמור להלן אינו חל על שליחי צה\"ל בלימודים  /קורסים בחו\"ל ,לאור שאינם זכאים למכסת ימי חופשת חו\"ל."}, {"p": 120, "t": "שליח יוכל להיעדר ממקום העבודה בארץ במשך יומיים ,לצורך אריזת המטען האישי בביתו לפני שיגורו למקום השליחות בחו\"ל .ימים אלה ייחשבו כימי עבודה ולא ינוכו לו מימי חופשת הארץ (בימים אלה יש לדווח בדו\"ח הנוכחות סיבת היעדרות \" :יום אריזה/פריקה\" ולרשום במלל חופשי\" :אריזת מכולה בארץ\" – תשלום בשכר הארץ."}, {"p": 120, "t": "חופשה בחו\"ל לפריקת מכולה– בתום שליחות האמור להלן אינו חל על שליחי צה\"ל בלימודים  /קורסים בחו\"ל ,לאור שאינם זכאים למכסת ימי חופשת חו\"ל. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 121, "t": "שליח יוכל להיעדר ממקום העבודה בחו\"ל במשך יומיים ,לצורך ארגון הבית במקום השירות ,לאחר פריקת המכולה .ימים אלה ייחשבו כימי עבודה ולא ינוכו לשליח מימי חופשת חו\"ל . שליח יוכל להיעדר ממקום העבודה בחו\"ל במשך יומיים ,לצורך ארגון הבית בחו\"ל לקראת אריזת המכולה בטרם שיגורה ארצה."}, {"p": 121, "t": "ימים אלה ייחשבו כימי עבודה ולא ינוכו לשליח מימי חופשת חו\"ל. היה ובן/ת זוגו של השליח העובד/ת כאית\"ן ירצה לממש זכאות זו במקום השליח ,יוכל לעשות זאת כנגד הצהרה על כך שבן זוגו (השליח) ,לא מממש הזכאות."}, {"p": 121, "t": "חופשה בארץ לצורך פריקת המכולה בבית השליח לאחר סיום השליחות ,רשאי השליח להיעדר במשך יומיים ,לצורך פריקת המכולה בביתו בארץ .בגין ימים אלה ,יקבל בתום שליחות תוספת של יומיים בשכר חו\"ל."}, {"p": 121, "t": "תקופת חל\"ת פרק  33.2בתקש\"יר תקופת חופשת מחלה ללא משכורת אינה נחשבת כתקופת שירות לצורך קביעת מספר ימי חופשת המנוחה וחופשת המחלה בתשלום הניתנים לעובד באותה שנה ולצורך קביעת שיעור פיצויי הפיטורים וגמלאות; על תקופת חופשת מחלה ללא משכורת יודיע מנהל היחידה בטופס הודעה על שינויים אישיים תקופת חופשה ללא משכורת אינה נחשבת כתקופת שירות לצורך צבירת מספר ימי חופשת"}, {"p": 121, "t": "המנוחה וחופשת מחלה ,גם אם העובד רכש זאת לגמלאות ולפיצוי פיטורין ושולמו .18.5% חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 122, "t": "ימי חופשת מנוחה בחוץ לארץ הוראת שות\"ש 1.2.9.2 מי זכאי \"חופשה פרטית\" היא חופשה ,לה זכאי שליח במסגרת ימי החופשה העומדים לזכותו במהלך תקופת השליחות למעט שליחי צה\"ל לומדים/קורסים/עמיתי מחקר אשר ימי החופשה הינם בהתאם לתקופת הלימודים תנאי לזכאות • בתקופת שירותו של השליח בחוץ-לארץ ,הוא יהא זכאי לחופשת חוץ-לארץ."}, {"p": 122, "t": "לצורך כך יתנהל עבורו חשבון מיוחד ונפרד של חופשת המנוחה. • חשבון חופשת המנוחה בארץ של השליח ייחסם (להלן\" :חופשה חסומה\") ערב צאתו לשליחות בחוץ-לארץ ותישמר בחשבון חופשת ארץ .יתרת חשבון חופשת המנוחה בחוץ-לארץ (לאחר ניצול חופשה תועבר לחשבון חופשת ארץ עפ\"י כללי ניצול חופשת חו\"ל כמפורט בשות\"ש ולהלן."}, {"p": 122, "t": "ניצול ימי חופשה סייגים שליח יהא זכאי ל 22 -ימי חופשה שנתית ,כאשר מתוכם הוא חייב לנצל  14ימי חופשה לפחות בכל שנת שליחות קלנדרית (ינואר-דצמ). השליח יהא זכאי לצבור בכל שנה עד  8ימי חופשה ולהעביר  8ימים בלתי מנוצלים משנה לשנה .יובהר שלא ניתן לצבור יותר מ 8 -ימי חופשה כפול מספר שנות השירות או  32ימי חופשה (לשליח המשרת  4שנים) – הנמוך מבניהם."}, {"p": 122, "t": "בתקופת העסקתו בחוץ-לארץ השליח יהא זכאי למשכורת חוץ-לארץ בעד ימי חופשת חוץ-לארץ. שליח שחדל להיות מועסק בחוץ-לארץ יהא זכאי למשכורת חוץ-לארץ בעד יתרת ימי חופשת חוץ-לארץ ,עד לתקופה של חודש ימים (לרבות ימי מנוחה דהיינו; עד 22ימים בפועל) ,אם הוא מקבל את החופשה מיד עם סיום העסקתו בחוץ-לארץ וזאת בין אם הוא מבלה אותה בארץ או בחוץ-לארץ."}, {"p": 122, "t": "בעד יתר ימי חופשת חוץ-לארץ (אך עד  10ימי חופשה בלבד) יהא השליח זכאי למשכורתו הרגילה בארץ. במקרה שבו השליח לא ניצל את ימי החופשה העודפים ,בהתאם לאמור בסעיפים לעיל ,יבוטלו אותם ימים והשליח לא יהא זכאי לכל תמורה בעדם."}, {"p": 122, "t": "• • • • • • זכאות בחלק מחופשות המנוחה המשרד יממן כרטיס טיסה לשליח ולבני משפחתו הנלווים אליו ,והכול לפי המפורט ביתר ההוראות בפרק זה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 123, "t": "זמני עבודה וחגים הוראת שות\"ש 1.2.9.1 - מי זכאי מדינת ישראל קובעת כללים בדבר שעות עבודה ,חופשות וימי מועד עבור שליח הנמצא בשליחות בחוץ-לארץ. הנחיות לביצוע. זכאות • השליח יעבוד בהתאם לדרישת הממונה עליו ובהתאם לצורכי העבודה ,גם אם הדבר מחייבו לעבוד מעבר לשעות העבודה הנהוגות בנציגות ביום מסוים ,בשבוע מסוים או בחודש מסוים."}, {"p": 123, "t": "• מספר שעות העבודה השבועיות של שליח יעמוד על  42שעות לכל הפחות ,כנהוג בארץ ביחידות משרדיות ,הנקבעות כמפורט להלן: • שליח יעבוד בימים שני עד שישי ובשעות כפי שהאחראי יקבע לו ,אלא אם כן הנציגות פועלת בימים אחרים או שנקבע אחרת על-ידי האחראי."}, {"p": 123, "t": "• יום עבודה רגיל של שליח במשרה מלאה הוא לפחות  8.5שעות ,אלא אם כן האחראי יקבע אחרת. • במקרה שחלו החגים הישראלים ו/או יום טוב שני של גלויות ביום השבת ,השליח לא יהא זכאי ליום חופשי אחר תמורתם."}, {"p": 123, "t": "• אם תנאי המקום או תנאים מיוחדים יחייבו זאת ,רשאי ראש הנציגות לקבוע ,כי ביום טוב שני של גלויות תיפתח הנציגות ,אך השליח לא יהא זכאי ליום חופשי אחר תמורתם .למען הסר ספק ,יום טוב שני של גלויות וחגים מקומיים אינם נחשבים לימי חג/מועד .אולם ,אין להעסיק בימים אלו עובדים מקומיים יהודים שאינם ישראלים ,כי עבורם ימים אלו הם ימי חג לכל דבר."}, {"p": 123, "t": "• מספרם הכולל של ימי החגים המקומיים ,שבהם הנציגות תהיה סגורה ,לא יעלה על  9ימים בשנה. • מידי שנה ,קצין המנהלה בנציגות ישלח למשרד בארץ את התאריכים שבהם מתקיימים החגים המקומיים."}, {"p": 123, "t": "• מתוך סך ימי החגים המקומיים ייבחרו על ידי ראש הנציגות  9הימים שבהם הנציגות תהיה סגורה . • הוראות התקשי\"ר\" ,ימי בחירה\" ,פרק  .32.4לא יחולו על שליחים המשרתים בחוץ-לארץ חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 124, "t": "מועדי חגי ישראל ויום טוב שני של גלויות שבהם תהיינה הנציגויות סגורות מועדי חגי ישראל ויום טוב שני של גלויות שבהם תהיינה הנציגויות סגורות ,הם לפי הטבלה שלהלן: יום חג יום טוב שני של גלויות א' ו-ב' בראש השנה יום הכיפורים יום ראשון של סוכות יום שני של סוכות שמיני עצרת שמחת תורה יום ראשון של פסח יום שני של פסח שביעי של פסח יום אחרון של פסח יום העצמאות שבועות"}, {"p": 124, "t": "יום שני של שבועות חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 125, "t": "חופשת מולדת  -הוראת שות\"ש  1.2.9.4ריכוז תנאים וסייגים מי זכאי תנאי לזכאות תקופת הזכאות בשליחות סייגים זכאות ימי עבודה השליח ובני משפחתו הנלווים אליו לשליחות והרשומים באסמכתא לשליחות למעט שליחי צה\"ל לומדים/עמיתי מחקר/בקורסים אשר אינם זכאים לחופשה • בתנאי שהשליח ישרת תקופת שירות מלאה -תקופה של  3שנים לשליח צה\"ל ( שות\"ש  1.2.9.4ס' – )2.1.1ותקופה של  4שנים לשליח עובד משרד עפ\"י מדיניות המשרד"}, {"p": 125, "t": "• אם הוארכה תקופת השירות בשנת שליחות נוספת (מעבר ל 4 -שנים) ,השליח יהא זכאי לחופשת מולדת שנייה ממועד ההארכה אך ,לא יהא זכאי לנצלה ב 4 -החודשים האחרונים לשירותו בח\"ל) • קבלת החופשה מצריכה אישור מוקדם מיח' משא\"נ ומינהל בחו\"ל .הבקשה לחופשה תוגש לקצ\"מ / מנהל כ\"א בנציגות ע\"ג טופס בקשה לחופשה  3חודשים לפני מועד החופשה אישור הטופס זה יהווה אסמכתא ליציאה לחופשה ולהחזר ההוצאות( ,אין צורך להזרים אסמכתא)"}, {"p": 125, "t": "• לזכות השליח קיימת מכסת ימי חופשת חוץ-לארץ ,שהצטברה בשירותו בחוץ-לארץ (אין חובה על בני המשפחה לצאת לחופשה בתאריכים חופפים) • לאחר שנת שירות אחת לפחות. • התקופות שבהן השליח לא יהא זכאי להשתתפות בהוצאות כרטיס הטיסה הן במהלך  4החודשים שלפני סיום שירותו ו/או במהלך  4החודשים שלפני ו /או אחרי חופשת הבראה/חופשה מיוחדת וב 4-החודשים האחרונים לשירותו בחוץ-לארץ."}, {"p": 125, "t": "• בני משפחה שהצטרפו לאחר צאת השליח יהיו זכאים רק בתום  4חודשים מיום הגעתם למקום שירות השליח זאת בנוסף לתנאים שלעיל אין חובה על בני המשפחה לצאת לחופשה בתאריכים חופפים."}, {"p": 125, "t": "• החופשה תימשך עד  3שבועות ,כאשר לפחות  75%מתקופת החופשה תהיה בארץ. ימי החופשה ,ייזקפו על חשבון חופשת חוץ-לארץ של השליח • נתיב הטיסה ולוח הזמנים יהיו בדרך הקצרה והזולה ביותר ,בהתאם להוראות • במקרה של סיום שירות בטרם סיים תקופת שירות מלאה ולאחר שניצל חופשת מולדת ,המשרד יקזז 2%מההשתתפות בהוצאות הנסיעה כפול מספר החודשים שהשליח לא שירת."}, {"p": 125, "t": "• מימון כרטיס טיסה לשליח/בן משפחה והחזרי נסיעות – מוניות/תחבורה ציבורית מ -ואל שדה התעופה (החזר הוצאות ייעשה תמורת קבלות בלבד). • בנציגויות רחוקות בטיסה עם קונקשיין ,שהייה במלון במסלול הנסיעה בדרך לישראל ובחזרה (עד יום) במידת הצורך ובמידה שהשליח לא קיבל החזר בגין הוצאות לינה מחברת התעופה."}, {"p": 125, "t": "• תהליך רכישת כרטיסי הטיסה והשתתפות המשרד בהוצאות נסיעה מ/אל שדה התעופה עבור השליח ובני משפחתו הנלווים אליו ,יהא בהתאם למפורט בהוראות תכ\"ם\" ,טיסות ושירותים נלווים לנסיעות בתפקיד לחוץ-לארץ\" ,מס' .13.10.0.1 • ימי עבודה בגין טיסה  -עד יום אחד לכל כיוון."}, {"p": 125, "t": "אם ימי הטיסה הם בימים בהם הנציגות סגורה ,לא ייחשבו ימים אלו כימי עבודה . • שילוב עבודה במסגרת החופשה  -כפוף לאישור הגוף המזמין ולהזרמת אסמכתא ע\"י הגוף המזמין מראש לתקופה הנדרשת לימי עבודה בתפקיד ,ימי החופשה שבהם עבד בארץ ייחשבו כימי עבודה ,אך לא יותר משני ימי עבודה למעט במקרים חריגים באישור מנכ\"ל המשרד( .שות\"ש  1.2.9.4ס'  )2.2.7תמורת ימים אלה השליח יהיה זכאי לתשלום בעד כלכלה בלבד בארץ ,עפ\"י התקשי\"ר\" ,קצובת אש\"ל בארץ\" ,פרק"}, {"p": 125, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 126, "t": "חופשת הבראה (אוורור)  -הוראת שות\"ש  1.2.9.5ריכוז תנאים וסייגים מי זכאי שליח ובני משפחתו (הנלווים אליו לשליחות והרשומים באסמכתא לשליחות) המשרת במדינות אשר הוגדרו ע\"י הועדה הבין- משרדית כ\"קשות שירות\" (ראה רשימת מדינות קשות שירות בנספחים לפרק חופשות) .למעט שליחי צה\"ל לומדים/עמיתי מחקר/בקורסים אשר אינם זכאים לחופשה תנאי לזכאות • בתנאי שהשליח ישרת תקופת שירות מלאה -תקופה של  3שנים לשליח צה\"ל ( שות\"ש  1.2.9.4ס'  )2.1.1ותקופה של 4"}, {"p": 126, "t": "שנים לשליח עובד משרד עפ\"י מדיניות המשרד • קבלת החופשה מצריכה אישור מוקדם מיח' משא\"נ ומינהל בחו\"ל .הבקשה לחופשה תוגש לקצ\"מ  /מנהל כ\"א בנציגות ע\"ג טופס בקשה לחופשה  3חודשים לפני מועד החופשה אישור הטופס זה יהווה אסמכתא ליציאה לחופשה ולהחזר ההוצאות( ,אין צורך להזרים אסמכתא) • ניצול ימי החופשה יחולו ע\"ח מכסת חופשתו של השליח (אין חובה על בני המשפחה לצאת לחופשה בתאריכים חופפים)"}, {"p": 126, "t": "• התקופות שבהן השליח לא יהא זכאי להשתתפות במימון כרטיס הטיסה הינה במהלך  4החודשים הראשונים לשירות השליח בחוץ-לארץ ובמהלך  4החודשים שלפני סיום שירותו. • לא יהא זכאי במהלך  4החודשים שלפני ו /או אחרי חופשת מולדת /חופשת הבראה קודמת /חופשה מיוחדת • שליח שעבר בין נצי גויות במהלך תקופת שליחותו יהא זכאי עבור יתרת תקופת השליחות למכסת חופשות הבראה בהתאם למקום השליחות החדש ובאופן יחסי לתקופה שנותרה לו."}, {"p": 126, "t": "• במקרה שבו השליח האריך את שליחותו במדינה המוגדרת כקשת שירות ,כמפורט בשות\"ש ,הוא לא יהא זכאי לחופשת הבראה נוספת • שליח שיצא לשליחות ורמת קושי השירות ו\\ או רמת קושי השירות הייחודי עודכנו במהלך שליחותו ,תעודכן עבורו מכסת החופשות כפי שנקבעה במועד העדכון האחרון ע\"י הוועדה הבינמשרדית."}, {"p": 126, "t": "• שליח המגיע לארץ על חשבון המשרד לצורך קבלת טיפול רפואי ,ו/או מסיבה אחרת כלשהי ,הביקור ייחשב כחופשת הבראה לכל דבר (הוראה  1.2.9.5ס'  2.2.5והוראה  1.2.3.1ס'  -2.2.5פירוט בנספחים) • המשרד ישתתף בהוצאות כרטיס טיסה אחד בשנה לשליח או לאחד מבני משפחתו לחופשות הבראה בישראל או במדינה אחרת ,שתימשך עד שלושה שבועות בלבד."}, {"p": 126, "t": "• עלות כרטיס טיסה למדינה אחרת תהיה בשווי עלות כרטיס טיסה ממקום השירות לישראל ,בדרך הקצרה והזולה ביותר ,או שווי כרטיס טיסה למקום שאליו בחר השליח לנסוע ,לפי הסכום הנמוך ביניהם."}, {"p": 126, "t": "• רכישת כרטיסי הטיסה לחופשת הבראה המתקיימת בישראל ,תתבצע על ידי קצין המנהלה  /מנהל כ\"א של המשלחת / נספחות. • במקרה שהנסיעה לחופשת ההבראה אינה לישראל ,ירכוש השליח את כרטיסי הטיסה בעצמו ועל חשבונו ויפנה לנציגות לקבלת ההחזר הכספי .במקרה זה ,האחריות על שינויים בטיסה או במועדה ,עלות וויזות למדינות יעד החופשה או למדינות בחניות הביניים בדרך לחופשה ,הינן באחריות השליח ועל חשבונו."}, {"p": 126, "t": "• החזר הוצאות כנגד קבלות בגין נסיעה במונית/תחבורה ציבורית מ/אל שדה התעופה. • המשרד לא ישתתף בכל הוצאה אחרת במסגרת הנסיעה ,כגון :הוצאה נלווית כמו מיסי נמל ,לינה וכיוצ\"ב."}, {"p": 126, "t": "• המשרד (קצ\"מ/מנהל כ\"א במשלחת/נספחות) ירכוש כרטיסי טיסה לשליח בדרך הקצרה והזולה ביותר לישראל ובהתאם לתהליך המפורט בהוראות תכ\"ם\" ,טיסות ושירותים נלווים לנסיעות בתפקיד לחוץ לארץ\" ,מס' .13.10.0.1 • ימי הטיסה וחזרה ממנה למדינת השירות לא ייחשבו כימי חופשה ויוכרו כימי עבודה ,ועד יום אחד בלבד לכל כיוון .אם ימי הטיסה הם בימים בהם הנציגות סגורה ,לא ייחשבו ימים אלו כימי עבודה"}, {"p": 126, "t": "תקופת הזכאות בשליחות סייגים זכאות ימי עבודה חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 127, "t": "חופשת מיוחדת (מסובסדת/חופשת לונדון) - מי זכאי תנאי לזכאות תקופת הזכאות בשליחות סייגים זכאות ימי עבודה הוראת שות\"ש  1.2.9.6ריכוז תנאים וסייגים שליח המשרת במדינה מרוחקת ,כלומר שטיסה ישירה אליה מישראל אורכת מעל  10שעות (וזאת ללא קשר למשך הנסיעה בפועל) ,יהא זכאי במהלך שליחותו להשתתפות חד-פעמית בהוצאות הנסיעה לחופשה לישראל ,שלו ושל בני משפחתו הנלווים אליו למעט שליחי צה\"ל"}, {"p": 127, "t": "לומדים/עמיתי מחקר/בקורסים אשר אינם זכאים לחופשה מדינות השירות המזכות הינן :אוסטרליה  ,ארה\"ב סינגפור ,יפן וקנדה (ייתכנו שינויים בהתאם להוראות השות\"ש והןראות אלו הן שקובעות) • בתנאי שהשליח ישרת תקופת שירות מלאה -תקופה של  3שנים לשליח צה\"ל ( שות\"ש  1.2.9.4ס' )2.1.1ותקופה של  4שנים לשליח עובד משרד עפ\"י מדיניות המשרד • קבלת החופשה מצריכה אישור מוקדם מיח' משא\"נ ומינהל בחו\"ל .הבקשה לחופשה תוגש לקצ\"מ"}, {"p": 127, "t": "/מנהל כ\"א בנציגות ע\"ג טופס בקשה לחופשה  3חודשים לפני מועד החופשה אישור הטופס זה יהווה אסמכתא ליציאה לחופשה ולהחזר ההוצאות( ,אין צורך להזרים אסמכתא) • ניצול ימי החופשה יחולו ע\"ח מכסת חופשתו של השליח (אין חובה על בני המשפחה לצאת לחופשה בתאריכים חופפים) לאחר ובכפוף לכך שהשליח ניצל את זכאותו לחופשת מולדת • הזכאות לאחר שנת שליחות אחת לפחות."}, {"p": 127, "t": "• התקופות שבהן השליח לא יהא זכאי להשתתפות בהוצאות כרטיס הטיסה הן במהלך  4החודשים שלפני סיום שירותו ו/או במהלך  4החודשים שלפני ו /או אחרי חופשת מולדת. • מעבר בין מקום שירות אחד למשנהו כאשר השליח עובר בישראל  -במקרה שבו שליח עבר ממדינה שאינה מרוחקת למדינה מרוחקת ,הוא יהא זכאי להשתתפות במימון כרטיס טיסה לחופשה מיוחדת רק בתנאי שנותרו לו עוד שנתיים לסיום השירות."}, {"p": 127, "t": "• השליח יהא זכאי להשתתפות במימון חופשה מיוחדת בתנאי שאינו זכאי לחופשות הבראה. • השליח יהא זכאי לחופשת מיוחדת רק אם לזכותו חופשת חוץ-לארץ ,שהצטברה בשירות בחוץ- לארץ."}, {"p": 127, "t": "• המשרד ישתתף ב 50%-מעלות כרטיס הטיסה בלבד עבור השליח ו/או בני משפחתו הנלווים אליו ,או עד  1200דולר לכרטיס ,הנמוך מביניהם. • המשרד ירכוש כרטיסי טיסה לשליח ולבני משפחתו הנלווים אליו בדרך הקצרה והזולה ביותר לישראל ובהתאם לתהליך המפורט בהוראות תכ\"ם\" ,טיסות ושירותים נלווים לנסיעות בתפקיד לחוץ לארץ \" ,מס' .13.10.0.1 • המשרד ישתתף בהוצאות כרטיס טיסה כאמור עבור חופשה לישראל שתימשך עד שלושה שבועת"}, {"p": 127, "t": "בלבד, • המשרד לא ישתתף בכל הוצאה אחרת במסגרת הנסיעה ,כגון :הוצאות לינה ,מוניות וכדומה. • במקרה של סיום שירות בטרם סיים תקופת שירות מלאה ולאחר שניצל חופשה מיוחדת ,המשרד יקזז  2%מההשתתפות בהוצאות הנסיעה כפול מספר החודשים שהשליח לא שירת."}, {"p": 127, "t": "• אין זכאות  -ימי הטיסה לחופשה ובחזרה ממנה ,ייזקפו על חשבון חופשת חוץ-לארץ של השליח. • שליח שאושרה לו נסיעה בתפקיד לישראל תשולב נסיעתו לחופשה במסגרת נסיעת העבודה ,כאשר הוצאות הנסיעה עבורו בלבד ישולמו במלואן על ידי המשרד .עבור בני המשפחה השליח יקבל השתתפות כמפורט בהוראת שות\"ש  1.2.9.6סעיף . 2.2.2 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 128, "t": "מימון כרטיס טיסה שליח בגפו  -הוראת שות\"ש 1.2.9.7 מי זכאי שליח המשרת בגפו בחוץ לארץ יהא זכאי להחזר בגין הוצאות כרטיס טיסה אחד לארץ עבורו בכל שנת שירות. תנאי לזכאות בתנאי שישרת תקופת שירות מלאה -תקופה של  3שנים ( שות\"ש  1.2.9.4ס' )2.1.1 זכאות ימי עבודה • ההחזר הוא עבור הוצאות כרטיס טיסה לביקור ילד אחד או יותר ,שנשארו בארץ ועומדים באחד התנאים הבאים:"}, {"p": 128, "t": "• ילד עד גיל  ,18ילד בגיל שירות חובה/שירות לאומי  -במהלך השירות ועד לחצי שנה לאחר סיום השירות ,למעט מקרה של שירות חובה לאחר סיום הלימודים בעתודה, ילד בעתודה אקדמית  -במהלך  3השנים הראשונות ללימודים."}, {"p": 128, "t": "• הזכאות תחול במקרים המפורטים לעיל או עד גיל  ,22המוקדם ביניהם. • שליח יהא זכאי להשתתפות בגין ילדיו מנישואיו הקודמים ,או בגין ילדים של בן/בת זוגו על פי האמור בשות\"ש הוראה  1.2.9.7בסעיפים  .2.1.1ו.2.1.2- • השליח יהא זכאי להמיר את כרטיס הטיסה עבורו ,כמפורט בשות\"ש הוראה  1.2.9.7בסעיף 2.1.1לעיל ,לכרטיס טיסה עבור אחד מילדיו שנשארו בארץ או עבור בן/בת זוגו."}, {"p": 128, "t": "• שליח שאחד מילדיו ו/או בן/בת זוגו הצטרף אליו בעת יציאתו למקום שירותו והילד חזר לארץ במהלך תקופת השליחות ,לא יהא זכאי להשתתפות המשרד במימון כרטיס הטיסה כמפורט בהוראה זו ,בשנה הראשונה ממועד חזרתו של ילדו ו/או של בן/בת זוגו לארץ."}, {"p": 128, "t": "• השליח יהא זכאי להחזר כאמור ,לאחר  4החודשים הראשונים לשירותו בחוץ-לארץ ועד 4 החודשים שלפני סיום שירותו. • המשרד ישתתף בהוצאות כרטיס טיסה אחד לשליח או לאחד מבני משפחתו לישראל או למדינת השירות."}, {"p": 128, "t": "• החופשה תימשך עד  3שבועות. • במקרה שהשליח לא השלים תקופת שירות מלאה ,מסיבות שאינן מצורכי המשרד ,המשרד יגבה ממנו את כל ההוצאות בגין נסיעת השליח באותה שנה כמפורט בהוראה זו."}, {"p": 128, "t": "• המשרד לא ישתתף בכל הוצאה אחרת במסגרת הנסיעה ,כגון :הוצאות לינה ,מוניות וכדומה. • למימוש הזכאות יפנה בקשתו בכתב מבעוד מועד למשרד ויפרט את הפרטים הבאים :מועד הביקור ,גיל הילד ,תאריך גיוס (אם רלוונטי) ,האם הילד נמצא בשירות חובה/שירות לאומי/עתודה אקדמית וכתובת הילד בארץ .אישור המשרד יהווה אסמכתא ליציאה לחופשה ולהחזר ההוצאות ,כאמור לעיל."}, {"p": 128, "t": "• תהליך רכישת כרטיס הטיסה יהיה בהתאם למפורט בהוראות תכ\"ם\" ,טיסות ושירותים נלווים לנסיעות בתפקיד לחוץ-לארץ \" ,מס' .13.10.0.1 • אין זכאות  -ימי הטיסה לחופשה ובחזרה ממנה ,ייזקפו על חשבון חופשת חוץ-לארץ של השליח."}, {"p": 128, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 129, "t": "טבלה מרכזת של מימון כרטיס טיסה עבור שליח בחופשות מנוחה /חופשה פרטית/מולדת/הבראה/מיוחדת הודעת שות\"ש 1.2.9.8.1 -למעט שליחי צה\"ל לומדים/עמיתי מחקר/בקורסים אשר אינם זכאים לחופשה מימון כרטיס טיסה לחופשת מולדת שות\"ש 1.2.9.4 מימון כרטיס טיסה לחופשת הבראה שות\"ש 1.2.9.5 מימון כרטיס טיסה לחופשה מיוחדת שות\"ש מימון כרטיס טיסה לשליח/ה בגפו שות\"ש 1.2.9.7 מי זכאי השליח ובני משפחתו"}, {"p": 129, "t": "הנלווים אליו לשליחות. שליח ובני משפחתו הנלווים אליו לשליחות. שליח המשרת תקופת שירות מלאה במדינה רחוקה מישראל השליח או אחד מילדיו הנותרים בארץ או בן/בת זוג תנאי לזכאות בתנאי שישרת תקופת שירות מלאה בתנאי שמשרת במדינת קשת שירות תקופת שירות מלאה בתנאי שישרת תקופת שירות מלאה ומימש חופשת מולדת בתנאי שישרת תקופת שירות מלאה זמן בשליחות לזכאות • לאחר שנת שירות"}, {"p": 129, "t": "לפחות. • לא במהלך  4חודשים בין חופשת הבראה, חופשה מיוחדת, מעבר בין נציגויות כאשר השליח עובר בישראל • לא ב 4-חודשים האחרונים לשירות. • לא במהלך  4חודשים בין חופשת מולדת, חופשת הבראה, חופשה מיוחדת, מעבר בין נציגויות כאשר השליח עובר בישראל."}, {"p": 129, "t": "• לא ב 4-חודשים ראשונים ואחרונים בשירות. • לאחר שנת שירות לפחות ו 4 -חודשים לאחר ניצול חופשת המולדת. • בתנאי שנותרו לו עוד שנתיים לתום השירות. • לא במהלך  4חודשים בין חופשת מולדת ,חופשת הבראה, לא ב 4-חודשים האחרונים לשירות."}, {"p": 129, "t": "לא ב 4-החודשים הראשונים והאחרונים לשירות סייגים במעבר בין נציגויות, כאשר השליח עובר בישראל ,הדבר יחשב כחופשת מולדת במקרה של שהייה מעל 3שבועות בישראל. במקרה שהשליח האריך את שליחותו, לא יהא זכאי לחופשה נוספת."}, {"p": 129, "t": "במעבר בין מדינה שאינה מרוחקת למדינה מרוחקת כהגדרתה בהוראה  ,.1.2.9.6זכאי רק במקרה שנותרו לו עוד שנתיים לתום השירות. שליח שאחד מילדיו ו/או בן זוגו הצטרף אליו לשליחות וחזר לארץ במהלכה ,לא יהא זכאי בגין אותו בן משפחה שחזר ,במהלך השנה הראשונה ממועד חזרתו לארץ."}, {"p": 129, "t": "זכאות כרטיס טיסה והוצאות נסיעות מ ואל שדה התעופה. שהייה במלון במסלול הנסיעה בדרך לישראל ובחזרה (עד יום) במידת הצורך. כרטיסי טיסה לפי מכסת החופשות במדינות קשות שירות והוצאות נסיעות מ ואל שדה התעופה."}, {"p": 129, "t": "50%מעלות כרטיס טיסה בפועל בלבד ועד לתקרת השתתפות של  1200דולר לכרטיס. המשרד לא ישתתף בכל הוצאה אחרת במסגרת הנסיעה ,כגון :הוצאות לינה ,מוניות וכדומה כרטיס טיסה אחד לארץ לשליח בכל שנת שירות/ הטסה של ילדו או בן זוגו למקום השירות."}, {"p": 129, "t": "ימי טיסה ע\"ח ימי עבודה ,עד יום לכל כיוון. ע\"ח ימי עבודה ,עד יום לכל כיוון. ע\"ח ימי חופשת מנוחה. ע\"ח ימי חופשת מנוחה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 130, "t": "הריון ותקופת לידה והורות  -הוראת שות\"ש 1.2.9.9 מי זכאי • בהתאם למפורט בחוק הביטוח הלאומי (נוסח משולב) ,התשנ\"ה1995- ובהוראות התקשי\"ר\" ,היעדרות לרגל היריון ולידה \" ,פרק  - .33.3הוראה זו חלה בתקופת טיפולי פוריות ,ושליחה בהיריון ובתקופת הלידה וההורות על • הוראה זו חלה על כל סוגי השליחים בשירות ,לרבות הורה מאמץ ,הורה מיועד והורה במשפחת אומנה ."}, {"p": 130, "t": "זכאות • במהלך ההיעדרות בתקופת הלידה וההורות אין השליחה זכאית למשכורת .עם זאת, יונפק עבורה תלוש משכורת ובו מחד ,יפורטו כל התשלומים הנלווים לשכר ,כגון :קצובת דיור ,תשלומים בגין חינוך ילדים וכו' .ומאידך ,יפורטו בתלוש השכר כל הניכויים של השליחה בחוץ-לארץ ,כגון :הלוואות ,ניכויים והפרשות לקרן השתלמות ,פנסיה וכיו\"ב."}, {"p": 130, "t": "• שליחה אשר קיבלה אישור מהמשרד על סמך חוות דעת של רופא האמון ,לביצוע הלידה בארץ ,תהיה זכאית ל: • • כרטיס טיסה על חשבון קרן הריפוי לה ולבני המשפחה הנלווים בתנאי שהם חוזרים תוך חודש ימים למדינת השירות ממועד הלידה .למעט במקרים בהם יש מניעה רפואית לחזור למקום השירות ,ע\"פ החלטת רופא האמון."}, {"p": 130, "t": "• משכורת מיום צאתה את מקום השירות עד ליום הלידה ולא יותר מאשר משכורת חודשית אחת ,כאשר המשכורת תהיה לפי מקום השירות. שליחה התובעת דמי לידה ,תגיש למוסד לביטוח לאומי ,באמצעות קצין המנהלה ,בקשה לתשלום דמי לידה בצירוף המסמכים הבאים:"}, {"p": 130, "t": "• אישור רפואי בדבר יום הלידה המשוער ,אם השליחה יוצאת לתקופת לידה והורות לפני הלידה. • אישור קצין המנהלה בדבר תאריך הפסקת עבודתה לרגל ההיריון או הלידה. • פירוט שכר העבודה לשליחה ב 3-החודשים שקדמו להפסקת העבודה לרגל ההיריון."}, {"p": 130, "t": "• שליחה הזכאית למענק לידה מהמוסד לביטוח לאומי ,בגין הוצאות אשפוז ועבור רכישת ציוד בשביל הרך הנולד ,תקבל מהמוסד לביטוח לאומי את מענק הלידה במטבע ישראלי, ישירות לחשבונה של היולדת בארץ."}, {"p": 130, "t": "• בהתאם לאמור לעיל ,קצין המנהלה ישלח טופס תביעה לתשלום מענק לידה למשרד בארץ. • במקרה שהשליחה תגיש תביעה לביטוח לאומי לקבלת קצבת ילדים ,יש להקפיד כי התביעה תוגש בהתאם למפורט להלן:"}, {"p": 130, "t": "• בתביעה יש לרשום כתובת המגורים בישראל ,או כתובת קשר בישראל. • התביעה תוגש לסניף המוסד לביטוח לאומי שבתחום מגורי המבוטח בישראל. • המוסד לביטוח לאומי יעביר את קצבה הילדים במטבע ישראלי לחשבונה של האם ,או לחשבון משותף לאם ולאב ,מידי חודש."}, {"p": 130, "t": "• במטרה לאפשר טיפול מהיר בתביעות ,על השליחה להקפיד לשלוח את כל הטפסים ביחד :מענק לידה ,דמי לידה וקצבת ילדים. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 131, "t": "ימי אבל הוראת שות\"ש 1.2.9.10 מי זכאי שליח המשרת בחוץ-לארץ ונאלץ להיעדר מהעבודה לרגל פטירת קרוב משפחה, כקביעתם בהוראות התקש\"יר\" ,חופשת אבל\" ,פרק .33.5 זכאות • שליח אשר לפי הלכות המסורת נעדר מהעבודה עקב פטירת קרוב משפחה ,או בעקבות שינוי מקום קבורתו של קרוב משפחה ,יהא זכאי לימי אבל ,וזאת מבלי שימים אלו ינוכו מימי חופשת חוץ-לארץ שלו או משכרו."}, {"p": 131, "t": "• השליח יהא זכאי להשתתפות במימון כרטיס טיסה לישראל או למקום הפטירה וחזרה למדינת השירות. • במקרה של פטירת קרוב משפחה של אחד מבני משפחת השליח הנלווים אליו לשליחות ,אותו בן משפחה יהא זכאי להשתתפות בהוצאות הנסיעה (מימון כרטיס טיסה לישראל או למקום הפטירה וחזרה למדינת השירות) ,כמפורט בסעיף  2.1.2בהוראה."}, {"p": 131, "t": "• בתקופת ימי האבל השליח יהא זכאי למשכורת חוץ-לארץ. • המשרד יישא בעלות נסיעה לשדה התעופה בחוץ-לארץ ובחזרה ממנו ,אך לא ישתתף בכל הוצאה אחרת. • במקרה של פטירת קרוב משפחה של שליח יהודי:"}, {"p": 131, "t": "• ימי עבודה • השליח יהא זכאי ,לפי הדין ,לימי אבל מיום פטירת קרוב המשפחה ועד יום קבורתו ועוד  7ימים קלנדאריים החל מיום הקבורה. • במקרה שבו חל היום השביעי של שבעת ימי האבל בשבת ,ולמחרת ,ביום ראשון, עולים לבית הקברות ,יש לראות גם את יום ראשון כיום אבל."}, {"p": 131, "t": "• במקרה שבו חל אחד מחמשת הימים הבאים :יום א' של פסח ,חג השבועות ,יום א' של סוכות ,יום א' של ראש השנה או יום הכיפורים ,תוך שבעת הימים הבאים אחרי הקבורה ,יהא שליח יהודי זכאי ,לפי הדין ,ל 7-ימי אבל מיום הקבורה."}, {"p": 131, "t": "• במקרה שבו אירע מות קרוב המשפחה באחד מימי חג הפסח או חג הסוכות ,יהא שליח יהודי זכאי ,לפי הדין ,לימי אבל עד ליום הקבורה וכן ל 7-ימים לאחר סיום המועד. • ביום שינוי מקום קבורתו של קרוב משפחתו ,השליח יהא זכאי לימי אבל בתשלום מלא ,כיוון שלפי המסורת חל עליו באותו יום דין \"שבעה\"."}, {"p": 131, "t": "במקרה של פטירת קרוב משפחה של שליח מוסלמי או נוצרי: • מקרבה ראשונה ,השליח יהא זכאי לימי אבל מיום פטירת קרוב המשפחה עד יום קבורתו ועוד  7ימים החל מיום הקבורה. • מקרבה שנייה ,השליח יהא זכאי לימי אבל מיום פטירת קרוב המשפחה עד יום קבורתו ועוד  3ימים החל מיום הקבורה."}, {"p": 131, "t": "• במקרה של פטירת קרוב משפחתו של שליח דרוזי השליח יהיה זכאי ל 7-ימי אבל מיום פטירת קרוב המשפחה. • המשרד ירכוש כרטיסי טיסה לשליח בדרך הקצרה והזולה ביותר לישראל ובהתאם לתהליך המפורט בהוראות תכ\"ם\" ,טיסות ושירותים נלווים לנסיעות בתפקיד לחוץ לארץ\" ,מס' ימי הטיסה לישראל יוכרו כימי עבודה (מתייחס לשליח העובד במשרד)."}, {"p": 131, "t": "ימי שהותו של השליח בישראל או במדינת הפטירה של קרוב המשפחה בתום ימי האבל ,כמפורט בהוראה זו ,יהיו על חשבון חופשת חוץ-לארץ. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 132, "t": "חופשת מחלה  -הוראת שות\"ש 1.2.9.3 מכסת ימי מחלה לשליח (למעט לומדים) -הזכאות הינה ל 30 -ימי מחלה בשנת שליחות (  2.5ימים בעד כל חודש שירות ,עם זכות צבירה בלתי מוגבלת) תקופת המחלה מחושבת על בסיס לוח קלנדארי .ימי מנוחה ,ימי מועד וכיו\"ב ,החלים במהלך תקופת המחלה ,ייחשבו אף הם כימי חופשת מחלה שליח הנעדר ממקום עבודתו עקב מחלה יודיע על כך לממונה עליו ולקצין המנהלה בנציגות מוקדם ,ככל הניתן ,ביום הראשון להיעדרו"}, {"p": 132, "t": "שליח יהא זכאי למשכורת חוץ-לארץ מלאה בתקופת המחלה ,בכפוף לזכאותו לימי מחלה למימוש ימי המחלה חובה להמציא אישור רופא שליח שחלה למשך תקופה העולה על  30יום יודיע על כך למשרד בארץ וישלח את המסמכים הרפואיים הנוגעים למחלה ימי חופשת המחלה שלא נוצלו בחו\"ל ,יירשמו במאזן ימי המחלה כ\"ימי מחלה משנה קודמת\" ויצטרפו ליתרת ימי המחלה טרם השליחות .ימי מחלה אלה יהיו ניתנים לניצול עפ\"י הצורך ובכפוף לכללים"}, {"p": 132, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 133, "t": "הנחיות וכללים בעת מימוש חופשות הגעת ראש משלחת/נספח הגנה לארץ (חופשה/ביקור/תפקיד) בעת הגעת ראש משלחת/נספח הגנה לארץ מכל סיבה שהיא ,באחריותו ליידע בדבר הגעתו לארץ את הגורמים הבאים במשהב\"ט לא יאוחר משבוע לפני מועד ההגעה:"}, {"p": 133, "t": "• סמנכ\"ל וראש אמ\"ש • ראש מלמ\"ב • ראש האגף הביטחוני מדיני. • ראש מפא\"ת/ראש אגף סיב\"ט – בהתאם לעניין. • רח\"ט קש\"ח (נציג צה\"ל). • ראש היחידה למינהל ומשא\"נ בחו\"ל (משהב\"ט) חופשה לצורך התארגנות לקראת היציאה לחו\"ל המערכת אינה מקצה ימי חופשה מיוחדים לצורך התארגנות לקראת היציאה לשליחות .היה והשליח נזקק לחופשה כאמור לעיל ,יחויבו ימי החופשה ע\"ח מכסת ימי החופשה הצבורה"}, {"p": 133, "t": "שלו בארץ. האמור לעיל הינו למעט הזכאות לעובדי משהב\"ט ,ליומיים חופשה לאריזת מכולה . שימוש בטלפון נייד בעת חופשה בארץ שליחים עובדי משהב\"ט בהגעת השליח לארץ ,ישתמש במכשירו הישראלי לפי \"מסלול שליח\" ,שאושר במכרז החשב הכללי .במקרה של שהות ממושכת בארץ ,יפנה השליח במידת הצורך למוקדי חברת פלאפון לשינוי מסלול בהתאם למסלולים הקיימים במכרז חשכ\"ל אשר יהיה בתוקף בעת הבקשה."}, {"p": 133, "t": "מודגש כי עם סיום השהות בארץ ,שליח ששינה מסלול ,חייב לחזור וליצור קשר עם מוקד חב' פלאפון לצורך החזרת המסלול לקדמותו. הזמנת רכב בהגעה לחופשה בארץ לשליחים עובדי משהב\"ט מתייחס לשליחים עובדי משהב\"ט בלבד במסגרת היותם בחופשה פרטית /חופשת מולדת/ חופשת הבראה/חופשה מסובסדת."}, {"p": 133, "t": "שליחי צה\"ל  -יפנו לקצין הנסיעות הזרועי לבדיקת הזכאות לרכב בארץ בעת הגעה לחופשה והזמנת הרכב תתבצע באמצעות קצין הנסיעות הזרועי. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 134, "t": ".1השליח זכאי לקבלת רכב מהמשרד בעת הגעתו לארץ לחופשה ב\"תנאי שליח\" ,עד 14 יום בכל אחת משנות השליחות .ימים שלא נוצלו באותה שנת שליחות ,לא ייצברו ולא ניתן יהיה להעבירם משנת שליחות אחת לשנת השליחות הבאה."}, {"p": 134, "t": "\" .2תנאי הזכאות לרכב\" עד  14יום בשנת שליחות  -השליח יקבל את הרכב ב\"תנאי שליח\" ,קרי תשלום עבור ביצוע קילומטרז' בלבד לפי  ₪ 0.65לכל קילומטר (התעריף יתעדכן מעת לעת עפ\"י החלטת המשרד)."}, {"p": 134, "t": ".3תנאי הזכאות לרכב מהמשרד לאחר  14יום בשנת שליחות אם יזדקק השליח בבואו לחופשה בארץ לרכב לתקופה העולה על  14ימים בשנת שליחות ,ישלם על הרכב לפי חיוב אישי מלא ,כלומר תשלום יומי קבוע של + ₪ 98 ₪ 0.65לכל ק\"מ .מומלץ לערוך בדיקה ולהחליט אם לקבל את הרכב באמצעות המשרד או לשכור אותו על חשבונו באופן פרטי מחברת השכרה."}, {"p": 134, "t": ".4למען הסר ספק ,מובהר כי ,הסכומים המפורטים לעיל עשויים להשתנות והסכומים הקובעים לשכירת הרכב יהיו הסכומים שייקבעו במשרד במעמד קבלת הרכב. .5הזמנת רכב לבעלי רכב צמוד בחו\"ל המשלמים זקיפת הטבה בגין הרכב ראש נציגות/אש נספחות/שליח עובד משרד המשלם זקיפת הטבה בגין הרכב הצמוד בחו\"ל יהא זכאי לרכב בכל הגעה לארץ רכב ללא חיוב גם בעת חופשה פרטית."}, {"p": 134, "t": ".6תנאי הזכאות לרכב מהמשרד בתום שליחות מפורטים בחוברת לשליח חוזר. סייגים ותנאים להזמנת רכב שליחים עובדי משהב\"ט .1המשרד מעמיד לשליח רכב משפחתי בעל  5מקומות .רכב  7מקומות יאושר כחריג בלבד ע\"י ר' חטיבת התחבורה."}, {"p": 134, "t": ".2בן/בת הזוג של שליח עובד המשרד ,אינם רשאים לנהוג ברכב המשרד. .3את הרכב יקבל השליח מחטיבת התחבורה של המשרד והוא ימתין לו בחניון שבקריה .4שליח המגיע במסגרת תפקיד ,יח' המשא\"נ באגף ממנו יצא או האחראי על השליח ידאג להזרמת אישור כניסה ואסמכתא לצורך קבלת הרכב מהתחבורה ובכל יום הנדרש לצורך הגעת השליח לתפקיד."}, {"p": 134, "t": ".5ר' משלחות ,סגני ר' משלחות (לרבות חשב מש\"ן) ונספחי הגנה (עובדי משהב\"ט) ,יוכלו לקבל את הרכב בשדה התעופה בתיאום מראש על ידם עם חטיבת התחבורה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 135, "t": "טפסים ונספחים לפרק חופשות והיעדרויות חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 136, "t": "תאריך________/________/_____ : טופס בקשה לניצול חופשה של שליח ובני משפחתו (הטופס איננו רלוונטי לשליחים לומדים או היוצאים לתקופה של פחות משנת שליחות ) לידי יח' משא\"נ ומינהל בחו\"ל הנני מבקש/ת לאשר לי חופשה."}, {"p": 136, "t": "פרטים אישיים שם משפחה מס' זהות שם פרטי תפקיד נציגות מספר טלפון לזכותי נצברו ____________ ימי חופשה בעת שירותי בחוץ-לארץ.  אבקש לנצל מתוכם ______ חופשת ימי מנוחה ע\"ח חופשת חוץ-לארץ."}, {"p": 136, "t": "מתאריך _____ ________/________/ועד תאריך _____________/________/ימי החופשה הינה לטובת בעיגול): (הקף במסגרת הזכאות לשליח היוצא לתקופת שליחות בת של  3שנים  :חופשת מולדת בארץ (עד  3שבועות ומינימום  14ימים)  /חופשה בגפי  /חופשת הבראה  /חופשה מיוחדת בישראל ."}, {"p": 136, "t": "להלן פירוט החופשות בזכאות אותן ניצלתי עד כה: o חופשת __________ בין התאריכים ________ :עד_____________ - o חופשת __________ בין התאריכים ________ :עד_____________ - ידוע לי כי מכסת ימי החופשה הניתנים לצבירה לא תעלה על  8ימים לשנת העסקה בחו\"ל ולא יותר מ 32 -ימים במצטבר ,בכפוף לחלקיות משרה."}, {"p": 136, "t": "שם פרטי ומשפחה ________________ חתימה ______________________ אישור מנהל כ\"א/קצ\"מ הנציגות/קצין נסיעות זרועי (נציגות ללא קצ\"מ -הטופס יאושר וייחתם ע\"י הנספח לעובדי הנציגות במקרה של נספח ייחתם ע\"י חשב איזורי):"}, {"p": 136, "t": "מספר ימי חופשת מנוחה נותרים לאחר ניצול החופשה המבוקשת לעיל ____________ שם פרטי ומשפחה ____________________ חתימה ___________________________ אישור יח' משא\"נ ומינהל בחו\"ל החופשה מאושרת/לא מאושרת ______________________________________________ שם פרטי ומשפחה __________________________ :חתימה______________________ :"}, {"p": 136, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 137, "t": "רמות קושי שירות בנציגויות ומכסות חופשת הבראה הוראת שות\"ש 1.2.1.1 הוראת שות\"ש - 1.2.9.5מימון כרטיסי טיסה לחופשת הבראה הודעת שות\"ש ה \" 1.2.1.1.2רמות קושי שירות בנציגויות\" ,ה,1.2.1.1.2."}, {"p": 137, "t": "הודעת שות\"ש ה \" 1.2.1.1.2שיעורי תוספת קושי ייחודי בנציגויות\" ,ה,1.2.1.1.3. הודעת שות\"ש \" 1.2.9.8.1טבלה מרכזת של זכאויות למימון כרטיס טיסה עבור שליח בחופשת מנוחה\" הוראות תכ\"ם ,מס' \" 13.10.0.1טיסות ושירותים נלווים לנסיעות בתפקיד לחוץ לארץ\" .1רמות קושי שירות הינן זהות עבור חישוב משכורות שליחים ,עובדי אית\"ן ,אית\"ן בני זוג ועובדי אית\"ן אבטחה."}, {"p": 137, "t": ".2מובהר כי מדינות ברמת קושי שירות  ,Aאינן מזכות את השליח בתוספת זו. .3רמות הקושי תעודכנה במועד עדכון השכר ,ביום ה 1-בינואר של כל שנה. .4להלן רמות קושי השירות לפי עיר השירות בהתאם לנתוני חברת השירותים ECA :International .5שליח המשרת במדינה קשת שירות תקופת שירות מלאה יהא זכאי למימון כרטיס טיסה לחופשות הבראה בישראל או במדינה אחרת עבורו ועבור בני משפחתו הנלווים אליו"}, {"p": 137, "t": "לשליחות ,וזאת בהתאם לטבלה שלהלן: קושי שירות (ה )1.2.1.1.2 קושי שירות ייחודי ( ה )1.2.1.1.3.1 סה\"כ חופשות הבראה בכל תקופת השליחות רמה מספר חופשות הבראה רמה מספר חופשות הבראה A 0%ומעלה B 0%ומעלה C 8%-0% 12%ומעלה D 4%-0% 8%ומעלה E 0% 4%ומעלה F 0% 4%ומעלה טבלת עזר מפורטת ,הבנויה על בסיס נוסחה זו מופיעה בהודעת שות\"ש \"רמות קושי בנציגויות\" ,ה.1.2.1.1.2."}, {"p": 137, "t": "ובהודעת שות\"ש \"שיעורי תוספת קושי ייחודי בנציגויות\" ,ה .1.2.1.1.3.למען הסר ספק ,הטבלה המוצגת בהוראה זו, היא הקובעת חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 138, "t": "להלן דוגמא למכסת \"חופשות ההבראה\" (הנתונים בטבלה שלהלן מעודכנים לפי ינואר  )2022בהתבסס על טבלת רמות קושי שירות ובהתאם להודעת שות\"ש \"מכסת חופשות הבראה במדינות קשות שירות\" ,ה.1.2.1.1.2."}, {"p": 138, "t": "רמות הקושי תעודכנה במועד עדכון השכר ,ביום ה 1-בינואר של כל שנה ולפיכך ,יש לוודא הזכאויות מידי שנה קוד נציגות שם נציגות רמת קושי מקדם קושי מכסת חופשות שירות הבראה בשליחות מקסיקו D 20% בוגוטה D 20% ברזיליה D 20% מוסקבה D 20% ניו דלהי D 20% בנגקוק C 15% מנילה E 25% בייגינג D 20% הנוי D 20% רבאט C 15% הערות לטבלת מכסות חופשת הבראה שלעיל:"}, {"p": 138, "t": ".1הוועדה הבינמשרדית תעדכן ,במועד עדכון השכר ,את המקומות המוכרים ואת רמות קושי השירות ו/או קושי שירות ייחודי במקומות השירות השונים .בהתאם לכך תעודכן מכסת החופשות עבור השליח .שליח שיצא לשליחות ורמת קושי השירות ו\\או רמת קושי השירות הייחודי עודכנו במהלך שליחותו ,תעודכן עבורו מכסת החופשות כפי שנקבעה במועד העדכון האחרון ע\"י הוועדה .יובהר כי אם המכסה תתעדכן כלפי מטה ועד יום"}, {"p": 138, "t": "עדכון מכסת חופשות ההבראה השליח ניצל מספר חופשות אשר גבוה מהמכסה המעודכנת ,השליח לא יחזיר את עלות החופשה שכבר נוצלה .היה והשליח לא ניצל את החופשה יעודכנו מס' החופשות כלפי מטה ככל שיעודכן ע\"י הועדה ולשליח לא תהא עילה לדרוש את הזכאות למס' החופשות בהתאם למס' החופשות אשר הגדירו לו בשות\"ש או בחוברת בעת יציאתו לשליחות."}, {"p": 138, "t": ".2למען הסר ספק ,בזכאות לחופשות הבראה הוראות השות\"ש הן שקובעות (כאמור בסעיף 1לעיל) ולא המפורט בחוברת זו. .3במקרה שבו השליח האריך את שליחותו במדינה המוגדרת כקשת שירות ,כמפורט בהודעת שות\"ש 1.2.9.5 ,סעיף\" 2.1.6 ,רמות קושי שירות בנציגויות\" ,הוא לא יהא זכאי חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 139, "t": "לחופשת הבראה נוספת מעבר למפורט בהודעת שות\"ש\" ,מכסת חופשות הבראה במדינות קשות שירות\" ,ה.1.2.1.1.2 . .4המשרד ישתתף בהוצאות כרטיס טיסה אחד בשנה לשליח או לאחד מבני משפחתו עבור חופשה לישראל או למדינת השירות ,שתימשך עד שלושה שבועות בלבד ,כאשר ימי החופשה ,ובכלל זה ימי הטיסה לחופשה ובחזרה ממנה ,ייזקפו על חשבון חופשת חוץ- לארץ של השליח."}, {"p": 139, "t": ".5ימי הטיסה וחזרה ממנה למדינת השירות לא ייחשבו כימי חופשה ויוכרו כימי עבודה ,ועד יום לכל כיוון. .6שליח הזכאי למימון כרטיס טיסה לחופשת הבראה ,בהתאם לכללים שבהוראה זו ,יפנה בקשתו למשרד בצירוף המלצת ראש הנציגות."}, {"p": 139, "t": ".7המשרד ירכוש כרטיסי טיסה לשליח ולבני משפחתו הנלווים אליו בדרך הקצרה והזולה ביותר לישראל ,בהתאם לתהליך המפורט בהוראות תכ\"ם\" ,טיסות ושירותים נלווים לנסיעות בתפקיד לחוץ לארץ \" ,מס' .13.10.0.1 טיפול רפואי מחוץ לארץ השירות:"}, {"p": 139, "t": "שליח המגיע לארץ על חשבון המשרד לצורך קבלת טיפול רפואי ו/או מסיבה אחרת כלשהי, הביקור ייחשב כחופשת הבראה לכל דבר .משך השהייה בארץ יקבע על ידי הנהלת קרן הריפוי/רופא אמון .במקרה בו הנהלת קרן הריפוי/רופא אמון אישר/ה נסיעת ריפוי מחוץ- לארץ השירות (כולל ישראל) ,המטופל והמלווה (אם אושר על ידי רופא האמון) יקבלו קצובת לינה לתקופה שאינה עולה על  45יום ,כדלקמן:"}, {"p": 139, "t": "בתקופה שהמטופל מאושפז בבית החולים: המטופל לא יהא זכאי לקצובת לינה. המלווה יהא זכאי לקצובת לינה כאמור בהוראה\" ,קצובות שהייה והסדר לינה בנסיעה בתפקיד במהלך השירות\" ,מס' .1.2.8.4 בתקופה שהמטופל אינו מאושפז בבית החולים:"}, {"p": 139, "t": "המטופל יהא זכאי לקצובת לינה כאמור בהוראה\" ,קצובות שהייה והסדר לינה בנסיעה בתפקיד במהלך השירות\" ,מס' .1.2.8.4 המלווה יהא זכאי ל 50%-מקצובת לינה כאמור בהוראה\" ,קצובות שהייה והסדר לינה בנסיעה בתפקיד במהלך השירות\" ,מס' .1.2.8.4 בסמכות חשב המשרד להאריך את השתתפות המשרד בהוצאות לינה לתקופה של  45ימים נוספים ,בהתחשב בהמלצת רופא האמון."}, {"p": 139, "t": "המשרד לא יישא בהוצאות בגין טיפולים רפואיים או רכישת תרופות במסגרת פרטית במהלך שהותו של השליח בארץ. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 140, "t": "פרק מס'  – 13מעמד שליח בגפו \"שליח בגפו\" המדיניות המוצהרת של המשרד היא ,שיש לצאת לשליחות ביחד עם המשפחה .במקרים מיוחדים ,כשמסיבות שונות ,משפחת השליח אינה יכולה להצטרף אליו לשליחות ,או כשמשפחת השליח נאלצת לשוב לארץ והשליח ממשיך את השליחות בגפו ,יוכל השליח לפנות ליחידה למשאבי אנוש ומנהל בחו\"ל ,בבקשה להכיר בו כ\"שליח בגפו\"."}, {"p": 140, "t": "זכאויות ותנאי השירות הנלווים למעמד שליח בגפו אישור מעמד שליח בגפו מבטל את זכאויותיהם של בני משפחת השליח למעט האמור להלן: .1בני משפחת השליח לא יהיו זכאים להחזיק בדרכונים דיפלומטיים .היה והונפקו דרכונים דיפלומטיים לבני המשפחה ,יהיה עליהם להחזירם לאלתר לאכ\"ס /מע' הסדרי נסיעות חו\"ל."}, {"p": 140, "t": ".2שכר חו\"ל – השליח יקבל שכר חו\"ל לפי מצבו המשפחתי כאילו היו בני משפחתו עימו בשליחות. .3קצובת שכ\"ד – הקצובה של שליח בגפו תיקבע כקצובת \"נשוי\" ,בהתאם לקצובות שכ\"ד שנקבעו ע\"י הועדה הבין -משרדית במקום שירותו."}, {"p": 140, "t": ".4זכאות למימון כרטיס טיסה שליח בגפו הוראת שות\"ש  – 1.2.9.7ראה בפרק חופשות. שליח שהפך לשליח בגפו במהלך השליחות: .1בני המשפחה יקבלו מהמשרד כרטיסי טיסה לארץ במועד חזרתם ('תום שליחות')."}, {"p": 140, "t": ".2בני המשפחה יידרשו להחזיר למשרד את הדרכונים הדיפלומטיים. .3מיום חזרת בני המשפחה לארץ ,יפסיק המשרד את הכיסוי הרפואי עבורם במקום השירות. .4השליח לא יהא זכאי להשתתפות המשרד במימון כרטיס טיסה לביקור המשפחה בארץ בשנה הראשונה ממועד קביעת מעמדו כשליח בגפו."}, {"p": 140, "t": ".5השליח יהא זכאי לשלוח מטען אישי לארץ לצורך התאקלמות ומגורי בני משפחתו. האמור ייעשה בהתאם לאופן שייקבע בהחלטת וועדת חריגים ייעודית שתתכנס לצורך כך .בהקשר לכך ,תתקבל גם החלטה בוועדת החריגים לגבי המשך מגורי השליח בדירתו הנוכחית או מעבר לדירה אחרת שתואמת את מצבו החדש."}, {"p": 140, "t": "ביקור פרטי של המשפחה את השליח במקום השירות בביקורים פרטיים של המשפחה אצל השליח במקום שירותו ,לא יהיו בני המשפחה מכוסים בביטוח רפואי מטעם המשרד .אחריות בנושא זה חלה על השליח בלבד חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 141, "t": "ביקור השליח את משפחתו בארץ מובהר כי במקרה של סתירה בין האמור להלן להוראות השות\"ש ההוראות הן שייגברו. .1שליח המשרת בגפו יהיה זכאי למימון כרטיס טיסה אחד לארץ עבורו בכל שנת שירות ובתנאי שישרת בחו\"ל בכל תקופת השליחות ,מעל לשנתיים .הזכאות כאמור לעיל לא מאושרת בארבע החודשים הראשונים /האחרונים לשליחות."}, {"p": 141, "t": ".2שהות השליח בארץ תהיה על חשבון ימי חופשת חו\"ל שלו ,לרבות ימי הטיסה לחופשה ובחזרה ממנה. .3המשרד יממן עלות כרטיס הטיסה בלבד .לא ימומנו הוצאות לינה ,מוניות וכו'. .4שליח יהא זכאי להמיר את כרטיס הטיסה עבורו ,לכרטיס טיסה עבור אחד מילדיו שנשארו בארץ או עבור בן/בת זוגו .לבני המשפחה שיגיעו לביקור השליח במקום מושבו, תונפק אסמכתא מטעם המשרד שבמסגרתה יכוסו ההוצאות הרפואיות במהלך הביקור"}, {"p": 141, "t": "ולא יותר מ 6-שבועות ,כפי שמתקיים לכלל הנסיעות הקצרות. .5לכל נסיעה במסגרת זכאויות שליח בגפו ,לשליח /לבני משפחתו ,יהא על השליח לקבל מראש אישור מהיחידה למשאבי אנוש ומנהל בחו\"ל שתפעל להוצאת אסמכתא לנסיעה."}, {"p": 141, "t": ".6במקרה שהשליח לא השלים תקופת שירות מלאה ,מסיבות שאינן מצורכי המשרד ,ייגבה ממנו המשרד את כל ההוצאות בגין נסיעתו/הגעת בני המשפחה באותה שנה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 142, "t": "פרק מס'  – 14שכירת דירה בחו\"ל הוראת שות\"ש - 1.2.2.1.תשלום קצובת דיור במהלך השליחות הודעה  - 1.2.2.1.1קצובת דיור לפי מדינת שרות טופס  - 1.2.2.1.1טופס הצהרת שליח במקרה של חתימה על חוזה שכירות טופס - 1.2.2.1.2טופס סיכום חוזה שכירות הצהרת השליח קצובת שכר דירה בחו\"ל .1זכאות א .שליח זכאי לקצובת דיור עבורו ועבור בני משפחתו הנלווים אליו."}, {"p": 142, "t": "ב .המשרד יידע את השליח על גובה הקצובה שנקבעה לו במסגרת פגישת התדרוך שמתקיימת ביחידה למשאבי אנוש ומנהל בחו\"ל ,באחריות הקצ\"מ והשליח לוודא הקצובה המאושרת ולקבל את טופס אישור קצובת שכר הדירה המאושרת על ידי יח' משא\"נ ומינהל בחו\"ל."}, {"p": 142, "t": "ג .חוזה שכירות ייחתם בין בעל הבית לבין השליח – הדייר (למעט בחוזה שכירות של ראש נציגות או במקרים חריגים ובאישור מוקדם בכתב מחשב המשרד ,בהם הנציגות תחתום על החוזה במקום השליח) ולפיכך ,קיום תנאי החוזה הוא באחריות השליח."}, {"p": 142, "t": "ד .השליח יעשה את מירב המאמצים שהחוזה יכלול סעיף שיאפשר לו ,אך לא למשכיר, לסיים את החוזה בהודעה מוקדמת קצרה ככל הניתן .בכל מקרה ,על השליח ,בתיאום עם קצין המנהלה ,להקפיד ולוודא שחוזה השכירות של דירתו יכלול \"סעיף דיפלומטי\" לפיו ניתן לבטל את החוזה בהודעה מוקדמת של  30יום ולא יותר מ 60-יום במקרים הבאים:"}, {"p": 142, "t": ")1סיום ו/או הקפאה ו/או השעיית היחסים הדיפלומטיים ו/או הקונסולריים; )2העברת הנציגות אל מחוץ לעיר שבה היא שוכנת; )3סגירת הנציגות; )4העברת השליח מתפקידו ,בין לארץ ובין לנציגות אחרת ,שאינה בשליטת השליח; )5פטירת השליח."}, {"p": 142, "t": "ה .במקרה ולא מתאפשר להכניס סעיף דיפלומטי ,השליח יעשה את מירב המאמצים לכלול בחוזה \"סעיף חלופי\" במקום \"סעיף דיפלומטי\" ,המאפשר לו עזיבת דירה בהתראה מוקדמת של  30יום ולא יותר מ 60-יום."}, {"p": 142, "t": "ו .במקרה בו השליח עוזב את הדירה מיוזמתו וחוזה הדירה לא כולל סעיף דיפלומטי או סעיף חלופי ,כאמור בסעיף לעיל ההוצאות בגין ביטול חוזה השכירות יחולו על השליח. ז .השליח ,בתיאום עם קצין המנהלה ,ישתדל שבחוזה שכירות הדירה ייכלל סעיף ,שיפרט את שיטת עדכון שכר הדירה בתקופת החוזה."}, {"p": 142, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 143, "t": "ח .המשרד לא יכסה ולא ישתתף בכל הוצאה אחרת ,הקשורה בחוזה השכירות. ט .שליח יהא זכאי לתשלום קצובת דיור מיום כניסתו לדירה ו/או מיום שהגורם המוסמך במשרד יאשר ובכפוף להוראות השות\"ש .הקצובה תשולם עד ליום סיום תשלום שכר חו\"ל."}, {"p": 143, "t": "י .שליחי משהב\"ט הזכאים לדירת שרד הם: )1ראש נציגות משרד החוץ או משרד הביטחון. )2נספח הגנה. יא .שליח שלרשותו הועמדה דירת שרד מטעם משרדו או מטעם גוף אחר לא יהא זכאי לקצובת דיור."}, {"p": 143, "t": "יב .תוספת עבור ילדים  /הורה סמוך קצובת הדיור המרבית נקבעת על בסיס הקצובה המפורטת בהודעת שות\"ש\" ,קצובת הדיור\" ,ה ,1.2.2.1.1.כאשר עבור כל ילד המתלווה לשליחות מתווספים  10%מקצובת הדיור."}, {"p": 143, "t": "יג .תוספת עבור הורה סמוך אם המשרד אישר לשליח לצרף למקום שירותו בחוץ-לארץ את אחד ההורים או את שניהם ,כהורים סמוכים ,ייחשב כל הורה כילד המתלווה לשליחות ולקצובת שכ\"ד מתווספים  . 10%מובהר שהתוספת כאמור והשוואה לילד המתלווה הינה רק במסגרת תנאי שכ\"ד בלבד ואין מדובר בהשוואה לזכאויות נוספות המוקנות לילדים בנושאים שונים.0 יד .קצובת שכר דירה במקרים מיוחדים )1במקרים בהם חל שינוי במצבו המשפחתי של השליח או במספר בני המשפחה"}, {"p": 143, "t": "הנלווים אליו ,תיקבע לשליח קצובה בהתאם למצבו המשפחתי החדש ,ולא יותר משכר הדירה בפועל .אם בעקבות השינוי הקצובה המרבית תרד מההשתתפות קודם לכן ,השליח ימשיך לקבל השתתפות לפי מצבו המשפחתי ערב השינוי ,כל עוד לא שינה את מקום מגוריו."}, {"p": 143, "t": ")2שליח גרוש או אלמן ,שילדיו נלווים אליו ,יהא זכאי לקצובת דיור כנשוי עם תוספת עבור ילדיו בהתאם. )3שליח גרוש או אלמן ללא ילדים ,או שילדיו אינם עמו במקום השירות ,יהא זכאי לקצובת דיור כרווק."}, {"p": 143, "t": ")4שליח נשוי ,שרעייתו וילדיו אינם עמו במקום השירות ,זכאי לקצובת דיור כנשוי בלבד. )5שליח רווק ,הממלא תפקיד ייצוגי כמפורט בהוראת שות\"ש\" ,החזר הוצאות\", מס'  ,1.2.1.2המחייב לארח בביתו אורחים ולשם כך זקוק לדירה מתאימה ,יהא חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 144, "t": "זכאי לקצובה של שליח נשוי ללא ילדים באותה דרגה או כאמור בסעיף ,2.1.2.4.2 בהוראת השות\"ש הגבוה מבניהם. )6שליח השוכר דירה בשכירות משותפת יהא זכאי לקצובה בשיעור של 70% מקצובת הדיור המפורטת בסעיף .2יא )3.בהוראת השות\"ש."}, {"p": 144, "t": "ה .תוספת ייצוגית לשכ\"ד )1שליח בתפקיד ייצוגי ,אשר הוכיח כי למרות מאמצים ממשיים שעשה ,לא הצליח למצוא דירה במסגרת הקצובה שנקבעה לו( ,הוכחה באמצעות מכתבי תימוכין של מתווכים ואתרי שכירויות) ,יהא רשאי לקבל תוספת בשיעור של עד 10% מהקצובה ,כאמור בשות\"ש ."}, {"p": 144, "t": ")2האמור לעיל יהיה כפוף להמלצת קצין מנהלה או ראש הנציגות ואישור מהמשרד בארץ יוכל לפנות בכתב ליחידה למשאבי אנוש ומנהל בחו\"ל באמצעות מנהלי כ\"א /קציני מנהלה במשלחות  /נספחויות בבקשה לקבלת \"תוספת ייצוגית לשכ\"ד\", של עד  10%מעל לקצובה."}, {"p": 144, "t": ")3מובהר במפורש כי ,התוספת הנ\"ל תאושר לצורך עלות שכר דירה בסיסית בלבד ללא עלויות נוספות מלבד שכ\"ד (לדוגמא :אחזקה ,ניקיון ,גינון ,חניה ,חשמל, כבלים ,וכל הוצאה אחרת ,שלא נכללה ב UTILITES -כאמור לעיל)."}, {"p": 144, "t": "לשליח שקיבל אישור לתוספת הנ\"ל ,תעודכן קצובת שכ\"ד בהתאם ,אך במקרה זה ,הוא לא יהיה זכאי למענק במקרה שבו שכר הדירה נמוך מקצובת הדיור שאושרה. ו .תוספת בגין משפחה ברוכת ילדים בסמכות האחראי לאשר תוספת של  10%לקצובת הדיור עבור שליח שלו  4ילדים ויותר, ומפאת גודל משפחתו לא הצליח למצוא דירה מתאימה במסגרת קצובת הדיור שנקבעה."}, {"p": 144, "t": "ז .תוספת מנהטן לבעלי תפקידים ייחודיים במש\"נ: בעלי התפקידים הבאים ,המוצבים בעיר מנהטן ,זכאים לקצובת דיור ייחודית הנקראת 'ניו יורק  -מנהטן': ראש משלחת משרד הביטחון בארה\"ב ()1 סגני ראש משלחת משרד הביטחון בארה\"ב ()3 קב\"ט משהב\"ט (.)1 .2אופן תשלום שכר דירה א .על שליח ,העומד לשכור דירה בהתאם להוראות אלו ,לקבל המלצות לגבי שכירת דירה (שווי ,מיקום ,ועוד) מהגורמים המוסמכים בנציגות ,לרבות אישור קב\"ט יועמ\"ש"}, {"p": 144, "t": "השגרירות ואישור יח' משא\"נ ומינהל בחו\"ל. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 145, "t": "ב .לאחר קבלת האישורים הנ\"ל מהמשרד ולאחר חתימה על חוזה השכירות ,על השליח להעביר ,באמצעות קצין המנהלה/הנספח ,טופס שות\"ש\" ,אישור לקצובת דיור במהלך השירות\" ,ט 1.2.2.1.2.בצירוף העתק מחוזה השכירות."}, {"p": 145, "t": "ג .השתתפות המשרד בהוצאות שכר דירה תשולם לשליח בכפוף להצגת חוזה שכירות על שמו ,המציין את גובה השכירות בפועל. ד .השתתפות המשרד תשולם במטבע תשלום שכר הדירה  /החשבונות בפועל ,באמצעות תלוש השכר."}, {"p": 145, "t": "ה .קצובת שכר הדירה משולמת לשליח באמצעות תלוש השכר .ככל ששכ\"ד המשולם גבוה מתקרת המס ,ההפרש יגולם בשכר. .3חריגה מהקצובה א .במקרה שבו שכר הדירה גבוה מקצובת הדיור המרבית שליח ששכר דירה בסכום הגבוה מהקצובה שאושרה לו ,ישלם בכל חודש מכספו את הפער שבין עלות החוזה בפועל לבין הקצובה שאושרה לו ,כולל התייקרויות .כל בקשה לתוספת לקצובת שכ\"ד מעבר לאמור בס\"ק  3,4לעיל ,מחייבת אישור מראש של הועדה הבין-"}, {"p": 145, "t": "משרדית (יש לפנות לר' היחידה למשאבי אנוש ומנהל בחו\"ל באמצעות מנהלי כ\"א /קציני מנהלה במשלחות  /נספחויות). ב .חידוש חוזה  -בעת חידוש החוזה ,ימשיך השליח לשלם מכספו את סכום ההשתתפות העצמית ,אלא אם עודכן בסיס שכ\"ד ע\"י הוועדה הבין-משרדית."}, {"p": 145, "t": "במקרה זה ,תצטמצם  /תתבטל ההשתתפות העצמית שלו בהתאם לגובה הקצובה המעודכנת שקבעה הוועדה. ג .במקרה שבו שכר הדירה נמוך מקצובת הדיור המרבית (ללא התוספת הייצוגים אם אושרה לשליח) השליח יהא זכאי לתוספת ,שמהווה השתתפות חלקית בהוצאות הנלוות לשכר הדירה ,כגון :חשמל ,מים ,גז ,הסקה ,מיזוג אוויר ,הוצאות בית משותף אחזקה וניקיון ,ביטוח ,מיסוי מקומי ,ביול חוזה ,התקנת טלפון,"}, {"p": 145, "t": "שכירת מוסך או מקום חניה ,בגובה של עד  ₪ 720לחודש ובתנאי שלא יעלה על קצובת הדיור המרבית .השתתפות המשרד בהוצאות הנלוות לשכר הדירה, כמפורט בסעיף זה תשולם בכפוף להצגת קבלות."}, {"p": 145, "t": "ד .בעת חידוש החוזה בשנת השליחות השנייה ואילך ,ימשיך השליח לקבל את ההשתתפות בגין הוצאות נלוות או חלק ממנה (כמפורט בסעיף ג' לעיל) ,כל עוד שעלות שכ\"ד בפועל (בסיס והתייקרויות)  +ההוצאות הנלוות ,לא יעלו על גובה קצובת שכ\"ד הבסיסית שקבעה הוועדה הבין-משרדית ושהייתה בתוקף ביום חתימת החוזה המקורי  .במקרה שבמהלך תקופת השכירות יעלה גובה שכר הדירה של השליח בהתאם למנגנון עדכון החוזה (\"התייקרויות\") ,תישחק התוספת או"}, {"p": 145, "t": "תתבטל לגמרי. .4עדכון קצובת שכ\"ד עקב שינוי מצב משפחתי של השליח חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 146, "t": "במקרה של שינוי מצב משפחתי של השליח במהלך השליחות (לידת ילד /עזיבת בני משפחה) ,תקבע לשליח קצובת שכ\"ד עדכנית היה וקיבל תוספת ייצוגית הזכאות לתוספת בגין לידת ילד תקוזז למול התוספת הייצוגית שניתנה והיה ולמרות התוספת בגין לידת ילד קצובת שכ\"ד במקום השירות גבוהה ובמקרה שבו השליח מוסיף מכספו ,ניתן להשלים לו עד גובה הקצובה החדשה ולא יותר מעד 10% -תוספת ייצוגית על קצובת הבסיס המפורטת בהוראת השות\"ש – מובהר כי הסמכות לאישור"}, {"p": 146, "t": "קצובת שכ\"ד הינה של היח' למשא\"נ ומינהל בחו\"לבלבד. תשלום מס על שכירת דירה בחו\"ל .1חובת מס על שכ\"ד מעבר לתקרת הפטור של רשות המיסים -רשות המיסים בישראל קובעת למדינות או ערים שונות בעולם ,תקרת פטור ממס על שכר דירה לשליח בחו\"ל."}, {"p": 146, "t": ".2תקרת הפטור ממס נקבעת לפי מקום המגורים בפועל של השליח ולא לפי מקום השירות שלו (מקום עבודתו). .3שליח שיקבל בפועל בשכרו ,סכום הגבוה מתקרת הפטור המרבית בדולרים ,לפי מקום מגוריו בחו\"ל ,יחויב במס על הפער בין הסכום שקיבל בפועל לבין הסכום הפטור ממס."}, {"p": 146, "t": ".4ניתן לברר את גובה תקרת הפטור ביחידת השכר. .5המשרד מגלם את המס על שכר דירה לשליחים שחוזה שכר הדירה שלהם חרג מעבר לתקרת הפטור. .6לתשומת לב :התייקרויות על חוזה שכר דירה ,אינן מאושרות לצורך גילום מס."}, {"p": 146, "t": "דמי תיווך ותשלומים ייחודיים נוספים .1זכאות שליח יהא זכאי להשתתפות בדמי תיווך ,פעם אחת במהלך השליחות ,במקרה שלא קיימת אפשרות למציאת דירה באופן עצמאי ,בכפוף לאישור קצין המנהלה והמשרד."}, {"p": 146, "t": ".2השתתפות המשרד השתתפות המשרד תהא עד גובה קצובת הדיור החודשית שאושרה לשליח .במקרה בו דמי התיווך בפועל גבוהים מהקצובה החודשית שאושרה לשליח ,סכום ההשתתפות המרבי של דמי התיווך יהא קצובת הדיור החודשית שאושרה לו בתוספת .20% תשלום ההחזר יחושב לפי התנאים המקובלים במקום השירות ,למשל :אחוז משכר הדירה השנתי ,או ביחידות של שכר דירה חודשי."}, {"p": 146, "t": ".3אופן קבלת ההשתתפות דמי התיווך ישולמו לאחר קבלת אישור מהמשרד ,על סמך חוזה השכירות והצגת קבלה על תשלום דמי התיווך. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 147, "t": ".4תשלום שכר דירה מראש ופיקדון עבור שכר דירה א .זכאות במקרים חריגים ,בהם השליח נדרש לשלם שכר דירה מראש בגובה של יותר מחודש אחד ,יהיה רשאי המשרד להעמיד מקדמה בהתאם לסכום הנדרש .בנוסף ,שליח הנדרש לשלם פיקדון שכר דירה או ערבות יהיה זכאי להלוואה בגובה הפיקדון או הערבות ועד לתקרה של שלושה חודשי שכירות בהתאם למטבע התשלום."}, {"p": 147, "t": "ב .השתתפות המשרד כמפורט בהוראת שות\"ש\" ,בקשה להלוואה לפני השירות\" ,מס' .1.1.6.1 ג .אופן קבלת ההשתתפות כמפורט בהוראת שות\"ש\" ,בקשה להלוואה לפני השירות\" ,מס .1.1.6.1 .5מיסים מקומיים ודמי ביול חוזה במקומות בהם מוטלים מיסים נוספים או דמי ביול חוזה על שוכרי הדירות ,תכוסה ההוצאה הנ\"ל על פי קביעת הוועדה הבין-משרדית."}, {"p": 147, "t": ".6תשלומים ייחודיים נוספים (ארה\"ב) במסגרת מחויבות המשרד להובלת מטען השליח בשיטת \" ,\"DOOR TO DOOR מאשר המשרד לשליחים הבוחרים לשכור דירה במנהטן ,לרבות המתגוררים בדירות המשרד ,החזר כספי בגין עלות המשולמת להנהלת הבניין בגין עצירת מעלית או תשלומים אחרים הנובעים מהעברת המטען בתחילת שליחות ובסופה .הנ\"ל יוחזר לשליח כנגד קבלות."}, {"p": 147, "t": ".7לשליחים בארה\"ב ,הנדרשים לשלם להנהלת הבניין עלות \"\"APPLICATION FEE בעת חיפוש דירה ,יחזיר המשרד סך של עד  ,600$פעם אחת ,עבור הדירה עליה חתם השליח חוזה ההחזר ייעשה כנגד קבלה."}, {"p": 147, "t": "שכירת הדירה מציאת הדירה היא באחריות השליח בלבד ,אך הנציגות במקום מסייעת באיתור דירה מתאימה באמצעות מתווכים מקומיים. .1איתור דירה בנסיעת אוריינטציה או ביציאה לשליחות:"}, {"p": 147, "t": "א .מומלץ להתחיל ולאתר דירה בתקופת נסיעת האוריינטציה. ב .איתור הדירה יתבצע בהתאמה למצב המשפחתי ובהתאם לקצובת שכר הדירה שאושרה לו ע\"י יח' משא\"נ ומינהל בחו\"ל .כל חריגה מקצובת שכר הדירה תשולם על ידי השליח."}, {"p": 147, "t": ".2איתור דירה ושכירת דירה במקום השירות : חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 148, "t": "א .שליח לא יהא זכאי לתשלום קצובת דיור במקביל לתשלום לינה בבית מלון בחוץ- לארץ .זאת למעט מקרים מיוחדים ,כמפורט בהוראת שות\"ש\" ,שהייה בבית מלון בחוץ-לארץ ובישראל במהלך השירות\" ,מס' .1.2.2.2 ב .שליח המגיע למקום השליחות לפני תחילת חוזה השכירות של דירתו יהא זכאי להשתתפות בהוצאות לינה במלון עבורו ועבור בני משפחתו הנלווים אליו."}, {"p": 148, "t": "ג .שליח המועבר למקום שירות אחר בחוץ-לארץ במהלך תקופת שירותו יהא זכאי להשתתפות בהוצאות לינה במלון עבורו ועבור בני משפחתו הנלווים אליו. ד .המשרד ישתתף בהוצאות הלינה בבית מלון בחוץ-לארץ עד למועד תחילת חוזה השכירות או עד  21יום ראשונים לשהייתו של השליח בחוץ-לארץ ו/או במקום השירות שאליו הועבר ,המוקדם מבניהם."}, {"p": 148, "t": "ה .אם במהלך תקופת הזמן של  21יום משהגיע למקום השירות ,לא מצא השליח דירה, יפנה לקצין המנהלה בבקשה מנומקת בכתב להארכת שהותו במלון .במקרה שהנימוקים מצדיקים זאת ,קצין המנהלה יעביר את הבקשה לחשב המשרד."}, {"p": 148, "t": "ו .בהינתן אישור חשב המשרד ,השליח יהא זכאי להשתתפות החל מהיום ה 22-ועד ליום ה 51-לשהייתו בחוץ-לארץ וזאת בתנאים הבאים: ז .סכום ההשתתפות לא יעלה על הסכום שהשליח שילם במשך  21הימים הראשונים, באופן יחסי."}, {"p": 148, "t": "ח .סכום ההשתתפות לא יעלה על השיעורים הנקובים בהוראת שות\"ש .1.2.2.2 ט .המשרד ישתתף בסכום ההוצאה בפועל בהתאם לתעריפים המפורסמים בהודעת תכ\"ם\" ,תעריפי קצובות שהייה ולינה בחוץ-לארץ\" ,מס' ה 13.10.0.2.2 .בשיעורים הבאים:"}, {"p": 148, "t": "מצב משפחתי שיעור מקצובת הלינה בהוראת התכ\"ם שליח נשוי בהתאם לקצובה בעד בן  /בת זוג תוספת של 40% בעד כל ילד  /הורה נלווה  /הורה סמוך תוספת של 25% שליח שווק או שליח המגיע למקום בהתאם לקצובה כהונתו בגפו י."}, {"p": 148, "t": "במקרה שאין אפשרות למצוא מקום בבתי מלון בתעריפים המפורטים בהודעת תכ\"ם\" ,תעריפי קצובות שהייה ולינה בחוץ-לארץ\" ,מס' ה ,13.10.0.2.2 .חשב המשרד יהא רשאי לאשר חריגה מקצובת הלינה בהתאם להוראת התכ\"ם יא .השתתפות המשרד בקצובת שכר דירה."}, {"p": 148, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 149, "t": ")1עבור התקופה שהשליח זכאי להשתתפות בהוצאת לינה במלון ,הוא לא יהא זכאי לקצובת דיור ,כמפורט בהוראת שות\"ש \"תשלום קצובת הדיור\" ,מס' 1.2.2.1 )2קצובת הדיור נקבעת לפי המשתנים הבאים :מדינת השירות והעיר ,המצב המשפחתי של השליח ,דרגתו וסוג המטבע בו משולם שכר הדירה."}, {"p": 149, "t": ")3הקצובה מתעדכנת מעת לעת בהתאם לקביעת הוועדה ומתפרסמת בהודעת שות\"ש\" ,קצובות דיור\" ,ה.1.2.2.1.1. )4על אף האמור ,במקרה שבו חוזה השכירות נכנס לתוקפו ומדובר בדירה בלתי מרוהטת ומטען השליח טרם הגיע למקום שירותו ,ואם העיכוב בהגעת המטען אינו תלוי בהתנהלות בלתי תקינה של השליח ,בסמכות חשב המשרד לאשר המשך שהיית השליח במלון עד שבוע ימים ,או לחלופין שכירת ציוד בסיסי למגורים"}, {"p": 149, "t": "בדירה עד למועד הגעת המטען ,הזול מבניהם וזאת בנוסף לתשלום קצובת הדיור. )5יובהר כי שליח השוהה בבית מלון כאמור בהוראת זו ,לא יהא זכאי לכל השתתפות אחרת למעט הוצאות הלינה בבית מלון ."}, {"p": 149, "t": ")6שליח המגיע למקום השליחות וטרם איתר דירה או לפני תחילת חוזה השכירות של דירתו יהא זכאי להשתתפות בהוצאות לינה במלון עבורו ועבור בני משפחתו הנלווים אליו כדלהלן: א."}, {"p": 149, "t": "ב. ג. ד. ה. המשרד ישתתף בהוצאות הלינה בבית מלון בחוץ-לארץ עד למועד תחילת חוזה השכירות או עד  21יום ראשונים לשהייתו של השליח בחוץ-לארץ ו/או במקום השירות שאליו הועבר ,המוקדם מבניהם."}, {"p": 149, "t": "אם במהלך תקופת הזמן של  21יום משהגיע למקום השירות ,לא מצא השליח דירה ,יפנה לקצין המנהלה בבקשה מנומקת בכתב להארכת שהותו במלון .במקרה שהנימוקים מצדיקים זאת ,קצין המנהלה יעביר את הבקשה לאישור ולהחלטת חשב המשרד."}, {"p": 149, "t": "שליח שיתמהמה עם שכירת הדירה מעבר ל 21-הימים כאמור לעיל, מסיבות שאינן מוצדקות או שלא קיבל אישור חשב מבעוד מועד ,ישלם מכיסו  50%מעלות ההוצאות הכרוכות בשהיית משפחתו במלון ,השהיית המכולה בנמל או אחסונה ,ביטוח המכולה וכד'."}, {"p": 149, "t": "היה ולא נמצאה דירה בעת נסיעת אוריינטציה ,ימשיך השליח בניסיונות לאיתור דירה באמצעות קשר טלפוני ותכתובות עם מתווכים מקומיים. היה ולא נמצאה דירה בנסיעת האוריינטציה או בתחילת השליחות יפנה הקצ\"מ/הנספח ליח' משא\"נ ומינהל בחו\"ח עם המסמכים התומכים באי מציאת דירה לבחון את בסיס קצובת שכר הדירה מול יח' השכר ."}, {"p": 149, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 150, "t": "הליך אישור שכירת דירה -ראה תרשים זרימה לאחר שאיתר השליח דירה ,המתאימה לצרכיו והעומדת בקצובת שכ\"ד שאושרה לו ,עליו לפעול כדלהלן: .1לקבל אישור קב\"ט השגרירות בכתב. .2להעביר את טיוטת החוזה לאישור עו\"ד מקומי העובד עם המשלחת/השגרירות ולקבל אישורו בכתב לנוסח החוזה ותנאיו."}, {"p": 150, "t": ".3באחריות השליח לוודא שקצובת שכר הדירה ומועד תחילת חוזה השכירות תואם את הקצובה שאושרה לו וכן את תקופת השליחות (ללא תקופת האופציה) כל חריגה אשר תגרור עלויות נוספות אשר אינן במסגרת השכירות הבסיסית (כגון; מים ,חשמל ,גז ,חניה גינון וכיוצ\"ב) תושת על השליח."}, {"p": 150, "t": ".4לאחר קבלת אישור קב\"ט ,אישור עו\"ד יעביר את טיוטת החוזה לקצ\"מ/נספח אשר יבדוק שהנתונים בטיוטה הינם בהתאם לכללים הנדרשים והחוזה מכיל את הסעיף הדיפלומטי וכן כל התנאים המפורטים בטיוטה הינם בהתאם לתנאים הנדרשים לרבות תקופת החוזה ,סכום שכ\"ד וכי החוזה מכיל סעיף התייקרויות ואיננו מכיל עלויות בגין הוצאות נלוות כגון; מים ,חשמל ,גז ,גינון וכד' .ויאשר לשליח לחתום על החוזה."}, {"p": 150, "t": ".5החוזה החתום יועבר ע\"י השליח מייד עם חתימתו ליח' משא\"נ ומינהל בחו\"ל באמצעות הקצ\"מ/הנספח בצירוף טופס (שות\"ש ט , )1.2.2.1.2.אישור קב\"ט ואישור עו\"ד. .6מובהר שכל סטיה מתנאי החוזה או אי קיום התנאים שפורטו לעיל שמשמעותם יכולה לגרור עלויות וקנסות כל האמור יושת על השליח."}, {"p": 150, "t": ".7באחריות השליח לוודא שסכום שכ\"ד תואם לקצובה שאושרה לו ע\"י יח' משא\"נ ומינהל בחו\"ל – מודגש כי אף גורם אחר (לא קצ\"מ ולא נספח) יכול לאשר את קצובת שכ\"ד ולפיכך השליח יוודא שבידיו אישור תקף מיח' משא\"נ ומינהל בחו\"ל .מובהר כי כל סכום שיהיה מעבר לסכום הקצובה יחול על השליח."}, {"p": 150, "t": ".8לאחר חתימה על החוזה ,השליח יעביר למנהל כ\"א /קצ\"מ הנציגות את המסמכים הבאים מייד עם חתימת חוזה השכירות: א .חוזה חתום בצירוף אישור עורך הדין ואישור קב\"ט. ב .טופס \"אישור קצובת דיור במהלך השירות מנהל כ\"א/קצ\"מ/נספח הנציגות יבדוק את המסמכים ותקינותם ויעבירם ליחידה למשאבי אנוש ומנהל בחו\"ל לקבלת אישור לתשלום שכר דירה ע\"י יח' השכר – באחריות השליח לוודא שהמסמכים הועברו."}, {"p": 150, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 151, "t": "תרשים זרימה  -אישור שכ\"ד וחתימה על חוזה שכירות על ידי שליח: (בחוזה של דירת שרד לראש נציגות/נספחות שכ\"ד איננו נכלל במסגרת השכר) שלב 3 * איתור דירה ע\"י השליח בסיוע קצ\"מ /נספח."}, {"p": 151, "t": "* קבלת אישור קב\"ט בכתב * קבלת אישור עו\"ד לטיוטת החוזה לרבות קיום סעיף דיפלומטי או סעיף חליפי. שלב 2 שלב 1 טרם היציאה לשליחות יקבל השליח מסמך מהמטה המפרט את קצובת שכר הדירה המאושרת עפ\"י מקום השירות ונתוניו האישיים העתק יועבר לק.זרועי לקצ\"מ /נספח ולחשב האיזורי ק.זרועי יעביר ליח' משא\"נ ומינהל בחו\"ל בקשה לקביעת קצובת שכר דירה לשליח (טופס ייעודי בסט הקליטה)"}, {"p": 151, "t": "שלב 6 שלב 5 שלב 4 יח' משא\"נ ומינהל בחו\"ל תבדוק את המסמכים שהועברו ע\"י הקצ\"מ /נספח ותעביר אישור להמשך ההליך לחתימה על החוזה. קצ\"מ  /נספח יעביר טיוטת החוזה בצירוף טופס בקשה לאישור טיוטת חוזה (טופס ייעודי) באחריות השליח לוודא שכל ההנחיות בשלבים עד כה מולאו ככתבן וכלשונן קצ\"מ/נספח יוודא שהחוזה תואם את תקופת האסמכתא, קצובת שכ\"ד שאושרה ,קיום סעיף התייקרויות בשיעור עד"}, {"p": 151, "t": "5%וכל הכללים בהתאם להנחיות המופיעות במסמך המטה של קצובת שכ\"ד שלב 9 יח' משא\"נ ומינהל בחו\"ל תבדוק את המסמכים תאשרם ותעבירם ליח' השכר להמשך תשלום שכ\"ד לשליח בשכר. שלב 8 שלב 7 בקשה לאישור הארכת חוזה בשנה נוספת השליח יעביר את הבקשה להארכת תוקף החוזה לקצ\"מ/ נספח אשר יוודאו התאמת הנתונים לתקופה ולקצובה ויעבירו לאישור המטה בטופס ייעודי השליח יחתום על החוזה ועל"}, {"p": 151, "t": "טופס הצהרת שליח על אישור חתימה על חוזה שכ\"ד ויעביר לקצ\"מ/נספח אשר יוודא תקינות החוזה ויעביר המסמכים ליח' משא\"נ ומינהל בחו\"ל אשר תאשר ותעביר ליח' השכר. להלן מצ\"ב דוגמאות לטפסים הנדרשים עפ\"י שלבי תרשים זרימה לקביעת שכר דירה וחתימה על חוזה שכריות חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 152, "t": "טופס בקשה לקביעת קצובת שכ\"ד לשליח חדש – שלב 1 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 153, "t": "טופס – דוגמא לאישור קצובת שכ\"ד – שלב 2 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 154, "t": "טופס – בקשה לאישור טיוטת חוזה לשכירת דירה – שלב 5 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 155, "t": "טופס הצהרת שליח על חתימת חוזה שכ\"ד – שלב 7 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 156, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 157, "t": "טופס – בקשה לאישור טיוטת חוזה לשכירת דירה – שלב 8 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 158, "t": "תחילת תשלום קצובת שכר הדירה .1תשלום קצובת שכר הדירה בשכר ,לרבות קבלת הלוואות  /מקדמות בגין הוצאות דירה יבוצעו בכפוף לאישור המטה לעמידה בתנאים ובכללים לשכירת דירה ,מיום תחילת החוזה אך לא לפני מועד תחילת השליחות .ועד סוף השליחות ,מקרים חריגים יובאו מראש להחלטת ואישור ראש היחידה למשאבי אנוש ומנהל בחו\"ל ור' יחידת השכר באכ\"ס."}, {"p": 158, "t": ".2על השליח להודיע בכתב ליחידה למשאבי אנוש ומנהל בחו\"ל על כל שינוי בתאריכי החוזה (הארכה וכיוצ\"ב) ולהמציא את החוזה המעודכן. .3במקרה של קיצור השליחות ,מחובתו של השליח לטפל מול בעל הדירה בקיצור תקופת חוזה שכירת הדירה ולהמציא את החוזה המעודכן."}, {"p": 158, "t": "המלצות המשרד לאיתור ושכירת דירה בבואך לשכור דירה בחו\"ל ,עליך לקחת בחשבון מספר נושאים .1גודל הדירה  :יש לקחת בחשבון דירה שתתאים לגודל המשפחה (הזכאים להצטרף לשליח)."}, {"p": 158, "t": ".2קצובת שכ\"ד  :יש לאתר דירה העומדת במסגרת הקצובה .במקרים חריגים ,בהם לא ניתן למצוא דירה מתאימה ,העומדת בקצובה שנקבעה ,יש לפנות לר' היחידה למשאבי אנוש ומנהל בחו\"ל ,מראש וטרם חתימת החוזה ,לקבלת אישור לתוספת ייצוגית לשכ\"ד (עד- , 10%ראה סעיף לעיל תוספת ייצוגית)."}, {"p": 158, "t": ".3תיקונים בדירה : א .מומלץ לבצע בדיקה מקיפה של הדירה ולבקש לצרף לחוזה רשימת פגמים  /נזקים המצויים בדירה ,על-מנת שבתום תקופת השכירות ,בעל הבית לא ינצל זכאותו ויממש את הפיקדון עבור כיסוי עלות הנזקים (מומלץ לצלם את הפגמים בדירה)."}, {"p": 158, "t": "ב .תיקונים בדירה ,הנובעים מבלאי עקב שימוש סביר ,יהיו ע\"ח בעל הדירה (צנרת, חשמל ,מיבנה). ג .יש להגדיר בחוזה פרק זמן מינימאלי ,שבו מתחייב בעל הדירה לבצע התיקונים ולפרט נוהל במקרה של תיקון דחוף ,כגון פיצוץ צנרת ,שבו יהיה רשאי השוכר לבצע התיקון ולהגיש לבעל הדירה קבלה."}, {"p": 158, "t": "ד .יש לשאוף כי בעל הדירה יבטח את הדירה (ביטוח מבנה). ה .בתום תקופת השכירות ,תיקונים שאינם נובעים מבלאי שמקורו בשימוש סביר ,יחולו על-חשבון השליח עצמו. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 159, "t": ".4היבטים ביטחוניים בשכירת דירה : א .הדירה תהייה בבית מגורים לא קומת קרקע או קומת גג. ב .לא תהיה אפשרויות הגעה לפתחי הדירה מדירות סמוכות ,גגות סמוכים או בעזרת מתקנים חיצוניים כגון :סולם ,צנרת ,עצים גבוהים וכו'."}, {"p": 159, "t": "ג .עדיפות לדירה הנמצאת בבניין בו קיים פיקוח של שוער המסנן את הנכנסים. ד .עדיפות לדירה בבניין בו מתגוררים אנשים קבועים ואין בו משרדים ציבוריים המאפשרים לכל אדם להסתובב במקום באופן חופשי."}, {"p": 159, "t": "ה .תועדף חניית רכב בחניה סגורה של הבניין .למען הסר ספק לא יהיה תשלום נוסף. ו .עדיפות לדירה בה דלת כניסה מאסיבית. ז .הקב\"ט יוודא כי אזור המגורים איננו בעייתי מבחינה פלילית ואופי האוכלוסייה במקום (קרבה למסגד ,מרכז תרבות של בני מיעוטים ,שגרירות של אחת ממדינות ערב וכו')."}, {"p": 159, "t": "ח .יש לבדוק מיהם השכנים .האם מתגוררים בבניין בני מיעוטים ,במקומות בהן ניתן (דרך שמות בתיבת דואר דלתות וכו). ט .ככלל לא יאושר בית קרקעי ,אלא במקומות בהם אין ברירה אחרת .במקרים חריגים תועבר בקשה לאישור בית קרקעי לגורמי מטה בארץ."}, {"p": 159, "t": "י .אין לחתום על חוזה דירה ללא קבלת אישור ביטחוני מתאים. יא .דרישות נוספות מבעל הדירה. יב .מומלץ לדרוש מבעל הדירה חיבור לכבלים ,קו טלפון נוסף לאינטרנט. יג .בבית צמוד קרקע ,מומלץ לנסות להטיל על בעל הדירה עלות אחזקה שוטפת לגינה, על-חשבונו."}, {"p": 159, "t": ".5החוזה ותנאיו: א .חוזה השכירות ייחתם בין בעל הדירה לבין השליח .קיום תנאי החוזה ,באחריות השליח .למעט בחוזה שכירות של ראש נציגות או במקרים חריגים ובאישור מוקדם בכתב מחשב המשרד ,בהם הנציגות תחתום על החוזה במקום השליח)."}, {"p": 159, "t": "ב .על החוזה להיות בשפת המקום ובאנגלית ,במידת הצורך יש לתרגם את החוזה כדי שהשליח יבין את התנאים. ג .השליח יעשה את מירב המאמצים שהחוזה יכלול סעיף שיאפשר לו ,אך לא למשכיר, לסיים את החוזה בהודעה מוקדמת קצרה ככל הניתן .בכל מקרה ,על השליח להקפיד ולוודא שחוזה השכירות של דירתו יכלול \"סעיף דיפלומטי\" ,או סעיף חליפי לפיו ניתן לבטל את החוזה בהודעה מוקדמת של  30יום ולא יותר מ 60-יום."}, {"p": 159, "t": ")1במקרה שבו השליח עוזב את הדירה מיוזמתו וחוזה הדירה לא כולל סעיף דיפלומטי או סעיף חלופי כאמור לעיל ,ההוצאות בגין ביטול חוזה שכירות יחולו על השליח. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 160, "t": ")2 )3 )4 )5 )6 )7 )8 )9 במקרים שבהם המשרד הורה לשליח לעבור דירה ,או אם המשכיר חייב את השליח לעזוב אותה ,וניתנה חוות דעת תומכת של היועץ המשפטי בנציגות, השליח יהא זכאי להשתתפות בהוצאות העברת הדירה ועד לתקרה של ,₪ 9,000 וזאת בכפוף לאישור האחראי במשרד .במקרה שבו טיפל השליח באופן עצמאי בהתקשרות עם חברת אריזה והעברת החפצים לביתו החדש ,ימציא למשרד קבלות כהוכחה להוצאה."}, {"p": 160, "t": "סעיף  UTILITESבחוזה שכר הדירה ,מתייחס להחזר הוצאות עבור מים ,חשמל, גז ,מיזוג/הסקה וכד' .המשרד יאשר ההוצאה הנ\"ל כל עוד סכומים אלה כלולים בסך הכולל של תשלום שכר הדירה החודשי בהתאם לקצובה שאושרה (ללא התוספת הייצוגית) בחוזה ולא מפורטים בנפרד ממנו."}, {"p": 160, "t": "תשלומים אחרים שיפורטו בחוזה מלבד שכ\"ד ,לא ישולמו ע\"י המשרד (לדוגמא :אחזקה ,ניקיון ,גינון ,חניה ,חשמל ,כבלים ,וכל הוצאה אחרת ,שלא נכללה ב UTILITES -כאמור לעיל) .יש לשים לב לכך לפני החתימה על החוזה שכן חוזה שיוגש שלא כמצוין לעיל ,לא ישולם במלואו."}, {"p": 160, "t": "יש לשאוף להכנסת סעיף בחוזה ,לפיו לא יחויב השליח בפינוי הדירה לפני תום תקופת החוזה במקרה שהיא נמכרת. יש להוסיף לחוזה סעיף אופציה להארכת השכירות בשנה או בשנתיים ,בכפוף להארכת השליחות."}, {"p": 160, "t": "יש לקחת בחשבון שאת הנכס יש להחזיר לבעליו במצב בו התקבל ,לרבות צביעת הדירה ,ניקוי שטיחים ותיקוני נזקים אחרים .המשרד אינו משתתף במימון הוצאות אלה. חובה להעביר את טיוטת החוזה לפני חתימתו לבדיקת עו\"ד מקומי ,העובד עם השגרירות/משלחת וזאת לצורך בדיקה אם בחוזה לא נכללו סעיפים בלתי חוקיים או כאלה שהשליח לא יוכל לעמוד בהם."}, {"p": 160, "t": "חוזי שכר דירה בגרמניה – בשונה ממקומות אחרים בעולם ,בגרמניה נכללים בחוזה סעיפים א. המכונים \"חם/קר\" ,המביאים לביטוי בין השאר הערכה כללית של בעל הדירה לגבי עלויות שונות כגון :חימום ,מים ,חשמל ,גז וכד'."}, {"p": 160, "t": "לאחר שנה של שכירות ,בודק בעל הדירה את ההוצאות בפועל ומחייב את הדייר בפער .בנוסף ,קיים בחוזים מסויימים סעיף \"שונות\". השליח יעביר ליחידה למשאבי אנוש ומנהל בחו\"ל באמצעות ב."}, {"p": 160, "t": "הקצ\"מ/הנספח את \"טופס אישור חוזה שכ\"ד חדש\" .בסעיף המפרט את מרכיבי שכר הדירה ,יוסיף השליח תרגום לעברית בכתב ידו לגבי כל סעיף וסעיף. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 161, "t": "לגבי סעיף ה\"שונות\" יפרט השליח את מרכיבי ה\"שונות\" .אם תיכלל ג. בהם החניה ,יתמחר השליח את עלותה מתוך הסה\"כ של ה\"שונות\". המשרד יקזז סכום זה מהסכום הכולל של קצובת שכ\"ד שתאושר להעברה לשכרו של השליח."}, {"p": 161, "t": "בבוא העת ,כשתתקבל דרישה בכתב מבעל הבית לעדכון סכומי ד. ה\"חם/קר\" בחוזה ,יאשר זאת המשרד עד גובה קצובת שכ\"ד שאושרה לשליח בתחילת תקופת השכירות. .6התייקרויות שכר הדירה:"}, {"p": 161, "t": "א .השליח יקפיד כי בחוזה השכירות ייכלל סעיף שיפרט את שיטת עדכון שכר הדירה בתקופת החוזה. ב .מקובל ,שבשנת השכירות הראשונה ,לא יהיה כל עדכון לגובה שכ\"ד בחוזה. ג .החל מחידוש החוזה לשנה השנייה וכן לשנים נוספות מעבר לכך ,מקובל כי גובה סכום השכירות בפועל מתייקר."}, {"p": 161, "t": "ד .המשרד יכסה לשליח את אחוז ההתייקרויות בפועל אך לא יותר מ 5%-מסכום שכ\"ד שאושר לו ,ובלבד שסעיף ההתייקרויות ,לרבות שיעור או סכום ההתייקרות יופיע בחוזה המקורי שייחתם בין בעל הדירה לשליח."}, {"p": 161, "t": "אם מסיבה כלשהי ,ידרוש בעל הדירה התייקרויות מעל  5%לשנה ,יש לקבל אישור מראש מהיחידה למשאבי אנוש ומנהל בחו\"ל ור' יחידת השכר ,לפני חתימת החוזה. עדכון חריג שלא אושר מראש ,לא ישולם ע\"י המשרד."}, {"p": 161, "t": "ביטוח תכולת הדירה המשרד ממליץ לשליח לבטח במקום השירות את רכושו הפרטי מכל נזק אפשרי (גניבה ,אש, שוד ,רעידת אדמה ,שיטפון או כל סיבה אחרת) .במקומות מגורים אשר הביטוח הבסיסי איננו כולל נזקים בגין שיטפון או כל נזק אחר ,באחריות השליח להרחיב את פוליסת הביטוח לצורך ביטוח מלא בגין נזקים רכושו הפרטי."}, {"p": 161, "t": "האמור הינו בגדר המלצה ,אך מודגש כי המשרד אינו מממן או משתתף בעלות ביטוח לרכושם הפרטי של השליחים בחו\"ל. עוד יודגש כי המשרד אינו נושא באחריות לנזק העלול להיגרם לרכושו הפרטי של שליח (למעט בתהליך האריזה ושיגור המטען לארץ השירות וממנה לישראל)."}, {"p": 161, "t": "האחריות לרכש ותשלום עבור פוליסת הביטוח ותנאיה חלה על השליח ,שחובתו לברר את תנאי הפוליסה והכיסוי הנרכש על ידו ,העלויות ,ההשתתפויות העצמיות וכל פרט רלוונטי אחר. מומלץ כי ביטוח התכולה יהיה בערך כינון (ערך הרכוש כחדש) וככל שניתן ,יכלול גם כיסוי בגין אחריות כלפי צד ג'."}, {"p": 161, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 162, "t": "פרק מס'  – 15שירותי בריאות ורפואה הוראת שות\"ש .1.2.3.1.הוצאות רפואיות כיסוי הוצאות רפואיות מבוא .1הסדרת כיסוי רפואי הינה תנאי ליציאה לשליחות. .2באחריות המשרד לספק מענה רפואי לשליחיו ולבני משפחתו הנלווים אליו."}, {"p": 162, "t": ".3לפני היציאה לשליחות ,שליח ובני משפחתו הנלווים אליו מחויבים לעבור בדיקה רפואית ולהמציא למשרד מסמך רפואי המעיד על מצב בריאות עדכני לפני צאתם לשליחות. השליח ובן/בת הזוג משפחתו הנלווים אליו יחתמו על טופס \"וויתור על סודיות רפואית\" על שמם ועבור ילדיהם ,וימלאו שאלונים רפואיים ,אותם יקבלו במהלך התדרוך ביחידה למשאבי אנוש ומנהל בחו\"ל או אצל קצין הנסיעות הזרועי .יש הכרח במידע זה לשם סיוע"}, {"p": 162, "t": "בבעיות רפואיות ,שעלולות להתעורר במהלך השליחות או לצורך טיפול בבעיות רפואיות שניתן לטפל בהן כבר בארץ המידע הרפואי הנמסר במסגרת השאלונים ,יועבר לרופא האמון של המשרד (שליחי משהב\"ט ע\"י יח' משא\"נ ומינהל בחו\"ל ,נספחי הגנה ושליחי צה\"ל ע\"י קצין הנסיעות הזרועי) ."}, {"p": 162, "t": ".4במקרה והתגלתה בעיה רפואית העשויה להשית על המדינה הוצאות משמעותיות ,יש להעלות לוועדה פנים משרדית שתשקול את יציאת המשפחה לשליחות .הוועדה תורכב מנציגי חשב המשרד ,משאבי אנוש ויועץ משפטי."}, {"p": 162, "t": ".5זכאויות השליח ובני משפחתו נקבעות בהתאם לחוק ביטוח בריאות ממלכתי ,התשנ\"ד- ,1994על פי סל שירותי הבריאות שנקבע בו. .6ביטוחים משלימים לא חלים במסגרת הכיסוי הרפואי."}, {"p": 162, "t": "א .הריפוי ייעשה בארץ השירות .עם זאת ,בסמכות המשרד לקבוע טיפול בישראל ובמקרים חריגים גם בארץ אחרת. ב .המשרד משתתף בהוצאות הכיסוי הרפואי לשליח ובני משפחתו הנלווים אליו במקרים המפורטים בהוראת השות\"ש ."}, {"p": 162, "t": "ג .שיטת ההתקשרות הנהוגה במשרד הינה בהסדר של חברת ניהול ד .השתתפות השליח ובני משפחתו הנלווים אליו בהוצאות הרפואיות בהסדר ניהול הינה כדלהלן: )1עבור תרופות ,ביקורי רופא והוצאות אחרות (לרבות ביקור חד פעמי בחדר מיון שאינו מוארך מאוחר יותר לאשפוז) –  3%מההוצאה ולא יותר מאשר 100דולר בחודש לכלל המשפחה."}, {"p": 162, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 163, "t": ")2עבור הוצאות אשפוז בית חולים – אין השתתפות לשליח ולבני משפחתו הנלווים אליו. )3שליח המבצע עבודה של משקף דואר פטור מהשתתפות עצמית עבור בדיקות דם תקופתיות. )4השתתפות המשרד בכיסוי הוצאות רפואיות עבור הורה סמוך לפי הוראת שות\"ש והחלטת חשב – ראה פרק הורה סמוך."}, {"p": 163, "t": ")5שליחה או בת זוג של שליח בהריון המכוסה על ידי המשרד וקיבלה אישור מהמשרד על סמך חוות דעת של רופא האמון ללדת בארץ ,תהא זכאית לכרטיס טיסה על חשבון המשרד לה ולבני משפחתה הנלווים אליה."}, {"p": 163, "t": ")6במקרה של חזרה לארץ עבור לידה ,הטיסה תבוא על חשבון מכסת חופשות ההבראה (ככל שיש) ליולדת ולבני המשפחה הנלווים אליה. )7יולדת זכאית למענק לידה ולמענק אשפוז על פי הקריטריונים של המוסד לביטוח לאומי .על יולדת שילדה בחוץ לארץ להגיש תביעה למענק אשפוז ולהעביר את הסכום שהתקבל למשרד לצורך כיסוי עלויות הלידה."}, {"p": 163, "t": "ה .ילדי שליח הנמצאים עמו בשליחות בחוץ-לארץ ,זכאים לטיפולי ריפוי בעיסוק, ריפוי בדיבור ופיזיותרפיה ,בהתאם לסל הבריאות שניתן בארץ על ידי קופות החולים ובאישור מראש בכתב של העובדת הסוציאלית של המשרד בארץ ,לפי הפירוט הבא:"}, {"p": 163, "t": ")1ילדים עד גיל  – 3יהיו זכאים ל 27-טיפולים בשנה בסמכות חשב המשרד לאשר טיפולים נוספים בכפוף לחוות דעת מקצועית. )2ילדים מגיל  3ועד גיל  – 6יהיו זכאים ל 27-טיפולים בשנה ."}, {"p": 163, "t": ")3ילדים מגיל  6ועד גיל  – 9יהיו זכאים ל 9-טיפולים בשנה . )4ילדים עד גיל  18זכאים לטיפולי שיניים משמרים בהתאם לסל הבריאות הממלכתי בארץ. ו .כיסוי רפואי לילדי השליחים המבקרים במדינת שירות הוריהם ,יינתן עבור ילדים הזכאים לביקור הורים ,כמפורט בהוראת שות\"ש \" 1.2.9.7מימון כרטיס טיסה לחופשה עבור שליח בגפו\" ועבור ביקורים אלו בלבד."}, {"p": 163, "t": "ז .במקרה בו שליח מעורב בתאונת דרכים ,עליו לתבוע את חברות הביטוח של כלי הרכב המעורבים בתאונה .כל סכום שהשליח יקבל מחברות הביטוח ייחשב בראש ובראשונה כסכום שהתקבל לכיסוי ההוצאות הרפואיות ,גם אם הוסכם בין השליח וחברות הביטוח המשלמות שהסכום נועד לכיסוי הוצאה אחרת ,או תשלום עבור נזקים אחרים."}, {"p": 163, "t": "שירותי רפואה במקום השירות .1הטיפול הרפואי בחו\"ל ,הממומן ע\"י המשרד ,מבוצע באמצעות חברת \"דיויד שילד\" בשיטת דמי ניהול .שירותי הרפואה הניתנים במקום השירות תואמים את \"סל הבריאות\" חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 164, "t": "המאושר בארץ על ידי משרד הבריאות/קופות החולים במסגרת \"חוק ביטוח בריאות ממלכתי\" .בהסדר הכיסוי להוצאות הרפואיות בחו\"ל ,נכללים השליח ,בן/בת זוגו וילדיו הרשומים באסמכתא."}, {"p": 164, "t": ".2הכיסוי הרפואי של השליח יחול מיום צאתו של השליח לחוץ-לארץ ועד ליום הפסקת תשלום שכר חו\"ל או יום שובו ארצה ,המוקדם מביניהם .מובהר כי גם בזמן חופשה בחו\"ל השליח מכוסה על ידי המשרד .הכיסוי של בני משפחתו של השליח יחול כל עוד הם מתלווים אליו לשליחות ורשומים כזכאים באסמכתא."}, {"p": 164, "t": ".3במסגרת ההסדר עם חב' דיויד שילד מקבל כל שליח חדש כרטיס מגנטי באמצעותו יפנה לספקים הרפואיים השונים וחוברת הסברים על מסגרת התוכנית ,שתשלח ישירות לכתובת המייל הפרטית שלו."}, {"p": 164, "t": ".4באחריות קצ\"מ/נספח לוודא הוספת השליח ובני משפחתו לשירותי הרפואה באמצעות חב' דיויד שילד וקבלת כרטיס מגנטי מייד עם הגעתו לשליחות. .5במקרה בו השליח ובני משפחתו הנלווים אליו מגיעים לארץ חל עליהם חוק ביטוח בריאות ממלכתי ,התשנ\"ד .1994-במהלך שהותם בארץ הם אינם מכוסים על ידי המשרד."}, {"p": 164, "t": "מובהר כי ,הכיסוי הרפואי ,אינו חל בישראל וכי על השליח לוודא כי ,בעת שהותו בישראל בחופשה פרטית/בתפקיד או בכל סיבת שהות אחרת הוא ובני משפחתו מכוסים במסגרת קופ\"ח בארץ ,אליה משתייך השליח ובני משפחתו ולא ביטל את התשלום או חברותו בקופה ,למען הסר ספק ,שליח צה\"ל מקבל את שירותי הרפואה במסגרת מקרפ\"ר ובני המשפחה הזכאים במסגרת קופ\"ח .6הוספה לזכאות לכיסוי רפואי של בן משפחה שאינו באסמכתא"}, {"p": 164, "t": "ילדים במהלך \"ביקור הורים\"  -ילדים שמסיבות שונות לא הצטרפו לשליחות וקיבלו אישור להגיע ל\"ביקור הורים\" בחו\"ל ,יקבלו כיסוי עלות הוצאות רפואיות רק במשך תקופת הביקור אך לא מעבר ל 6 -שבועות ."}, {"p": 164, "t": "השתתפות השליח בהוצאות ריפוי. .1השתתפות עצמית – א .עבור ביקור רופא וטיפול ע\"י רפואה ראשונית ,קרי רופא משפחה ,רופא ילדים ורופא נשים ,אין השליח מחויב בהשתתפות עצמית והוא יקבל החזר כספי מלא בכפוף להמצאת קבלה מקורית."}, {"p": 164, "t": "ב .רופאים מומחים: עבור ביקורים וטיפולים אצל רופא מומחה (אורטופד ,כירורג ,עיניים וכל רופא מקצועי אחר) ,חייב השליח בהשתתפות עצמית בשיעור של  3%מהחשבון הכללי של הוצאות הריפוי שיוגשו על-ידו בגין תרופות ,בדיקות ,ביקורי רופא ,מעבדות חדר מיון וכיו\"ב."}, {"p": 164, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 165, "t": "אם לאחר הביקור בחדר המיון ,מועבר המטופל מידית לאשפוז ,יהיה השליח פטור מתשלום ההשתתפות העצמית של .3% ג .שיעור ההשתתפות החודשית למשפחה ,לא יעלה על  100$ארה\"ב. ד .מסגרת ההשתתפות העצמית בכל אחד ממקומות השירות בהם מופעל ההסכם עם חב' \"דיוויד שילד\" ,משתנה בהתאם להסכם ומפורט בחוברת ההטבות המופצת לשליחים ע\"י החברה."}, {"p": 165, "t": "ה .בתחום רפואת הנשים ,לא יחויב השליח בהשתתפות עצמית בגין ביקור שוטף אצל רופא נשים ומעקב היריון שיגרתי כגון בדיקות דם ,אחות נשים ואולטרה-סאונד .לעומת זאת ,בדיקות במהלך היריון כגון חלבון עוברי ,שקיפות עורפית ,סקירת מערכות מוקדמת ומורחבת ,יהיה השליח חייב בהשתתפות עצמית בשיעור של 3%מעלות כל בדיקה."}, {"p": 165, "t": "ו .עבור אשפוז בבית חולים וכל ההוצאות הכרוכות בכך ,לא יחויב השליח בהשתתפות עצמית. רופא אמון ו\"רופא השליחים\" רופא האמון הינו רופא שנבחר על ידי אגף משאבי אנוש ,לשמש יועץ רפואי לשליחים בחו\"ל."}, {"p": 165, "t": "לרופא האמון ניתן לפנות באופן ישיר ,לצורך התייעצות רפואית או קבלת חוות דעת נוספת לגבי טיפול או המלצה רפואית שקיבל השליח או אחד מבני משפחתו מרופא בחו\"ל. חובה לפנות לרופא האמון במקרים בהם נדרשים טיפולים רפואיים יקרים במיוחד (מעל )1,000$או במקרים בהם נדרשת סדרת טיפולים מתמשכת."}, {"p": 165, "t": "במקרה זה ,הפניה לרופא האמון תעשה באופן ישיר באמצעות המייל. שליח יכול לבקש להגיע לארץ לביצוע טיפול רפואי ,בכפוף לאישור מראש מרופא האמון. במקרה זה ,תיבחן הבקשה לגופו של עניין למול איכות המענה הרפואי במקום השירות ,עלויות ושיקולים נוספים .פרטי ההתקשרות עם הרופא ,מפורטים ב\"טלפונים חיוניים\" בסוף החוברת."}, {"p": 165, "t": "בארה\"ב ,ישתמשו השליחים בשירותיו של \"רופא השליחים\" בניו -יורק (במש\"נ)  ,כגורם מייעץ ומכוון. טיפולי שיניים לילדים ככלל ,טיפולי שיניים לא מכוסים בחו\"ל .למרות זאת ,בהתאם לחוק ביטוח בריאות ממלכתי, מאושרים טיפולי שיניים משמרים לילדים בהתאם לסל הבריאות בארץ מובהר כי כל שינוי במסגרת סל הבריאות בארץ יחול על השליחים בכל עת."}, {"p": 165, "t": "להלן הזכאות לטיפולי שיניים: חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 166, "t": ".1גילאי הזכאות לכיסוי עלות טיפולי שיניים כל הילדים אשר טרם מלאו להם  18שנים זכאים להחזר כספי עבור טיפולי שיניים כמפורט בהמשך. .2טיפולים הכלולים בסל הבריאות הישראלי ,ללא השתתפות עצמית • בדיקה תקופתית על ידי רופא -פעם בשנה  -פעם שניה באותה שנה ע\"פ שיקול דעת רפואי • בדיקות שגרה ומעקב כחלק מטיפול רפואי • ייעוץ והכנת תכניות טיפול -פעם בשנה • צילומי רנטגן במהלך הטיפול"}, {"p": 166, "t": "• זוג צילומי נשך -במסגרת בדיקה תקופתית • הדרכה בהיגיינה אורלית -עד פעמיים בשנה. • הסרת אבנית-פעם בשנה • טיפול מניעה באפליקציה מקומית • איטום חריצים וחרירים .3טיפולים עם השתתפות עצמית נמוכה בסך  US6$לטיפול • עזרה ראשונה • שחזורים (\"סתימות\") מאמלגם ומחומרים מורכבים • טיפול מוך השן (כולל טיפול שורש) • מבנים (יצוקים ומידיים) • כתרים טרומיים בשיניים אחוריות וקדמיות"}, {"p": 166, "t": "• עקירות • שומר מקום לאחר עקירה • שימוש בסדציה /גז צחוק • טיפולי שיניים בהרדמה כללית לילדים עד גיל  5הסובלים מעששת ילדים מוקדמת .4טיפולים שאינם כלולים בסל הבריאות הישראלי • יישור שיניים (טיפול אורתודנטי) .גם אם הטיפול החל בארץ לפני היציאה לשליחות."}, {"p": 166, "t": "• טיפולים נוספים שאינם כלולים ברשימה. .5כיסוי עבור זריקות הרדמה מקומית חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 167, "t": "זריקות להרדמה מקומית הן חלק בלתי נפרד מהטיפולים עצמם ולכן לא נדרשת עבורן השתתפות עצמית בנפרד. .6ההשתתפות העצמית במקרים בהם מבוצע במהלך הביקור יותר מטיפול אחד שדורש השתתפות עצמית במקרים אלו ההשתתפות המקסימלית תעמוד על  US12$לאותו ביקור."}, {"p": 167, "t": "חשוב לציין כי במידה ובאותו הביקור מתבצע הטיפול הדורש תשלום השתתפות עצמית ובנוסף טיפולים ללא השתתפות ,סך ההשתתפות תעמוד על  US6$בלבד. .7קבלת אישור מראש • כל הליך בעלות  US1,000$או יותר ,מחייב אישור רופא האמון טרם קבלת השירות."}, {"p": 167, "t": "• אנו ממליצים לבדוק מראש האם הטיפול המתוכנן לילד/ה מכוסה ע\"י הסל כדי למנוע אי נעימות. • במקרה של טיפול מורכב ,יש לפנות לגורם המטפל ולבקש ממנו תכנית טיפולים כתובה טרם קבלת השירות ,אותה יש להעביר לאישור רופא האמון."}, {"p": 167, "t": "הוצאות רפואיות שאינן ממומנות על ידי המשרד .1המשרד לא יכסה את ההוצאות הבאות (פרט לילדים עד גיל  18שזכאותם הינה לטיפולים משמרים ועפ\"י סל הבריאות בארץ בלבד): א .ריפוי שיניים לרבות טיפולי חירום ,שיניים תותבות ,גשרים ,יישור שיניים ועבודות טכניות בשיניים .משקפיים ,פרוטזות למיניהן ,חגורות אורטופדיות ומדרסים."}, {"p": 167, "t": "לתשומת לב עובדי משהב\"ט ,המבוטחים בחב' \"דקלה/הראל\" ,ניתן לקבל החזר כספי מהחברה ,עפ\"י התעריפים והקריטריונים בארץ .הגשת הבקשות תיעשה ישירות ע\"י השליח למול החברה. ב .כמו כן ,המשרד לא יחזיר הוצאות הבראה והחלמה ,או כל הוצאה רפואית אחרת שקופת חולים בארץ אינה מחזירה."}, {"p": 167, "t": ".2עלות משקפיים ועדשות משקפיים ,אינה מכוסה ילד עד גיל  ,18הסובל מקוצר ראיה ,שאושר בחוות דעת של רופא עיניים ,זכאי למימון עדשות משקפיים בלבד ,אחת לשנה ,עד לסך של סכום שווה ערך ל .₪ 600-מימון מסגרת המשקפים –ע\"ח השליח."}, {"p": 167, "t": ".3כיסוי רפואי בארץ המשרד אינו מממן הוצאות רפואיות ,שהיו לשליח ולבני משפחתו בעת שהייתם בביקור בארץ (בתפקיד או פרטי) .במקרים אלה על השליח או בן המשפחה לפנות לקופת החולים שלו או למרפאות צבאיות במקרה של אנשי צבא."}, {"p": 167, "t": ".4כיסוי רפואי – ספורט אתגרי: הכיסוי הרפואי בתקופת השליחות ,אינו כולל ספורט אתגרי מחוץ למקום השירות. האמור מתייחס לעיסוק בספורט אתגרי באופן קבוע או באופן חד-פעמי (בחופשה או חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 168, "t": "סופ\"ש) .כיסוי לספורט אתגרי במקום השירות יינתן בכפוף לביצוע הפעילות במקום השירות באתרים מורשים בלבד בעלי רשיון להפעלת האתר בהתאם לחוקי המקום ולאחר שננקטו כל הפעילויות ע\"י השליח לביצוע הספורט בציוד הרלוונטי ובשעות ההפעלה של האתר בלבד."}, {"p": 168, "t": "ביצוע ספורט אתגרי מחוץ למקום השירות הינו באחריות השליח בלבד ולפיכך ,חובה על השליח לדאוג לעצמו ו/או לבני משפחתו לביטוח פרטי לפעילות ספורט אתגרי (סקי ,בנג'י, סירה מהירה ,אופנוע ים ,סנפלינג וכד') .מוצע לברר עם חב' \"דיוויד שילד\" ,אפשרות לרכישת כיסוי ביטוחי פרטי לספורט אתגרי בסכום סביר במימון ובאחריות השליח."}, {"p": 168, "t": "הוצאות אשפוז ,טיפולים ,דמי שהייה בכל מקרה של אשפוז ,יש להודיע למשהב\"ט  /היחידה למשאבי אנוש ומנהל בחו\"ל באמצעות קצ\"מ המשלחת  /הנספחות ,בציון סיבת האשפוז ולהעביר את המסמכים הרפואיים לרופא האמון."}, {"p": 168, "t": "במקרים בהם יודע השליח כי הוא ,או אחד מבני משפחתו עומדים להתאשפז ,עליו לבקש מראש אישור מרופא האמון ולהעביר ארצה את כל המסמכים הנדרשים. אישור לטיפולים מיוחדים במקרים חריגים ,בהם נדרש טיפול מיוחד ,החורג מסל הבריאות ,יש להעביר בקשה מנומקת מראש לרופא האמון בארץ ,הכוללת מכתב מהגורם המטפל ,ובה פירוט לתכנית הטיפול ולצרף מסמכים רפואיים רלוונטיים."}, {"p": 168, "t": "הריון ולידה בחלק מהמדינות ,שהוגדרו ע\"י הועדה הבין-משרדית כ\"קשות שירות\" ,מאפשר המשרד הגעת שליחה או אשת שליח לבדיקות היריון סטנדרטיות וללידה בישראל ראה הרחבה בשות\"ש."}, {"p": 168, "t": "טיפולים רפואיים בארץ הגעה לארץ למטרת טיפול רפואי ככלל ,יטופלו השליחים ובני משפחותיהם במקום השירות .במקרים מסוימים ,יאשר המשרד הגעת שליח או בן משפחתו לארץ לביצוע הטיפול הרפואי:"}, {"p": 168, "t": ".1במקרים בהם יעדיף השליח  /בן המשפחה להיות מטופל בארץ ועלות הטיסה לארץ +השהייה ,לא יהיו גבוהים יותר מעלות המוערכת לביצוע הטיפול במקום השירות. .2כאשר מדובר בטיפול רפואי המוכר במסגרת סל הבריאות הישראלי ,אך אינו קיים במקום השירות."}, {"p": 168, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 169, "t": "כאשר מדובר בטיפול מתמשך או יקר במיוחד במקום השירות .במקרה זה ,בסמכות המשרד להביא את המטופל ארצה לביצוע הטיפול במסגרת קופת החולים. לשליחים המשרתים במדינות קשות שירות ,הטיפול רפואי בארץ יתבצע במסגרת ההגעה לחופשת ההבראה (אוורור)."}, {"p": 169, "t": "רופא האמון  /רופא השליחים יהיה זה שיאשר את הצורך הרפואי וימליץ אם להביא את המטופל ארצה. במקרה של מטופל שהוא ילד ,תובא להחלטת רופא האמון הסוגיה בדבר צירוף הורה מלווה לנסיעה לארץ."}, {"p": 169, "t": "לצורך הגעה רפואית לארץ תונפק למטופל ו/או למלווה שאושר אסמכתא. במקומות שירות שבהם מנוהל הכיסוי הרפואי באמצעות ההתקשרות עם חב' \"דיוויד שילד\" ,תממן החברה למטופל ו/או למלווה מטעמו את כרטיס הטיסה ואילו המשרד /הזרוע בארץ יזרימו \"אסמכתא ללא טיסה\" .המלון בארץ יוזמן ע\"י מנהל כ\"א / קצ\"מ הנציגות המשרד יממן עלות ההגעה והשהיה בארץ אך הטיפול עצמו ייעשה במסגרת קופת החולים או בכל מסגרת פרטית אחרת ,ע\"ח השליח .באסמכתא יכללו"}, {"p": 169, "t": "ימים \"בתפקיד\" באופן שפורט לעיל. בהגעה לארץ לטיפול רפואי ,שאושרה ע\"י המשרד ,הימים שיוכרו למטופל עצמו ו/או למלווה כימים ע\"ח המשרד יהיו: • יום טיסה לארץ. • יום הכנה לטיפול ,במידה ונדרש ואושר ע\"י רופא האמון."}, {"p": 169, "t": "• יום הטיפול ו/או ימי האשפוז. • ימי ההחלמה עד ביקורת רפואית אם נדרש ,עפ\"י קביעת הרופא המטפל. • יום טיסה בחזרה למקום השירות. כל יתר הימים בהם יבקש המטופל  /המלווה לשהות בארץ במסגרת ההגעה לטיפול הרפואי ,יהיו ע\"ח ימי חופשת חו\"ל שלו (אם מדובר בשליח ,או במקרה ומדובר בבן/בת הזוג המועסקים כאית\"ן ,יהיו ימים אלה ע\"ח ימי החופשה השנתית)."}, {"p": 169, "t": "במקרה של בן/בת זוג המועסק כאית\"ן ונדרש להגיע לארץ לטיפול רפואי או כמלווה לילד ,יחויבו כל יתר הימים בהם יבקש לשהות בארץ מעבר לימים ב\"תפקיד\" ,ע\"ח ימי החופשה השנתית שלו."}, {"p": 169, "t": "דמי שהייה ולינה במסגרת הגעה לטיפול רפואי בארץ • בגין ימי האשפוז לא יקבל המטופל החזר דמי שהייה ולינה. • בימים שהמטופל אינו מאושפז ,הוא יהיה זכאי להחזר דמי שהייה ולמימון לינה במלון חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 170, "t": "• וזאת עד לתקרה של  45יום וכל עוד נכללו ימים אלה במסגרת הימים המאושרים באסמכתא כמצוין לעיל. • המלווה – אם אושרה הצטרפותו ,יהיה זכאי ל 50%מקצובת הלינה ע\"ח המשרד ולדמי שהייה ,בכל ימי האסמכתא עד  45יום."}, {"p": 170, "t": "המשך חברות בקופת חולים בארץ בתקופת השליחות ,בעת הגעת שליח או בן משפחתו לארץ ,יקבלו שירות רפואי מקופת החולים בה היו מבוטחים בארץ לפני היציאה לשליחות. טיפולים שיבוצעו בארץ או תרופות שירכשו בארץ ,לא ימומנו ע\"י המשרד."}, {"p": 170, "t": "התשלום לקופת החולים מוסדר במסגרת חוק ביטוח בריאות ממלכתי והסכום החודשי מנוכה משכרו של השליח. אנשי צבא ,יקבלו בארץ טיפולים במסגרת מרפאות צבאיות ובני משפחתם ,באמצעות קופת החולים."}, {"p": 170, "t": "אין לבטל או להקפיא ביטוחים משלימים בקופת החולים .יש להמשיך לשלמם בתקופת השליחות. טיפולים אלקטיביים לקראת תום השליחות במהלך שלושת החודשים האחרונים לשליחות ,אין אישור לבצע טיפולים רפואיים אלקטיביים."}, {"p": 170, "t": "מקרים חריגים יובאו לאישור רופא האמון או רופא השליחים. סיום הזכאות לכיסוי רפואי ע\"ח המשרד יום סיום התפקיד לפי האסמכתא ,הינו היום האחרון לזכאות לכיסוי רפואי בחו\"ל לשליח ומשפחתו."}, {"p": 170, "t": "למרות זאת ,לשליח שקיבל מראש אישור להמשיך ולנצל לאחר סיום התפקיד חופשת חו\"ל בשכר חו\"ל בחו\"ל ושב ארצה במועד מאוחר יותר ,ימשיך הכיסוי הרפואי להיות בתוקף בתקופת החופשה וכל עוד השליח ממשיך לקבל שכר חו\"ל .ממועד הטיסה ארצה או מיום סיום שכר חו\"ל (המוקדם מבניהם) ,תתבטל הזכאות לכיסוי רפואי בחו\"ל ע\"ח המשרד והשליח ייאלץ לדאוג לו ולמשפחתו לכיסוי רפואי פרטי בחו\"ל."}, {"p": 170, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 171, "t": "פרק  - 16רכב שכור  /מוניות בתחילת שליחות הוראה  1.1.8.1השכרת רכב לפני השירות הוראה  1.2.8.1החזר הוצאות השכרת רכב במקום השירות שליח זכאי בתחילת שליחות להחזר עבור שכירת רכב או נסיעה במוניות .ההחזר ניתן תמורת קבלות מקוריות בלבד."}, {"p": 171, "t": ".1המשרד ישתתף בהוצאות השליח בגין שכירת רכב ,נסיעות בתחבורה ציבורית או מוניות עד לתקרת השתתפות של  ₪ 1800בתחילת השליחות ו ₪ 1800-בסיום תפקידו. .2המשרד לא ישתתף בהוצאות בגין דלק ,חניות וכבישי אגרה."}, {"p": 171, "t": "האמור לעיל מהווה השתתפות של המשרד בעלויות שכירת רכב  /מוניות בתחילת שליחות ואין בכך התחייבות המשרד לכיסוי מלא להוצאות השליח בהקשר זה. האמור לעיל אינו חל על שליח ,שמתוקף תפקידו זכאי לרכב צמוד בתקופת השליחות .במקרה זה ,עד לקבלת הרכב הקבוע ,יקבל השליח רכב שכור במימון מלא."}, {"p": 171, "t": "מובהר בזאת כי עם ההגעה למקום השירות ,זכאי השליח למימון מונית משדה התעופה לבית המלון (תמורת קבלות) .זכאות זו אינה קשורה להחזר עבור שכירת רכב או נסיעה במוניות בתקופת ההתארגנות הראשונית כמצוין בתחילת סעיף זה."}, {"p": 171, "t": "ראשי משלחות ,נספחי הגנה ובעלי תפקידים נוספים המקבלים \"רכב ר' נציגות\" /רכב צמוד מהמשרד ,זכאים למימון רכב שכור עד לעזיבת השליח אותו יחליפו. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 172, "t": "פרק  – 17נסיעה בתפקיד והגעה לארץ הוראה תכ\"מ מס' מס' \" ,.13.10.0.2נסיעות לחו\"ל קצובת שהייה ולינה והחזרי הוצאות\" הוראת תכ\"ם מס' \" 13.4.0.3החזר הוצאות בגין לינה אקראית לעובד בתפקיד\"."}, {"p": 172, "t": "א .תשלום קצובת שהייה בנסיעות בתפקיד במהלך השליחות ,כששליח נשלח בתפקיד למקום המרוחק מעבר ל 20 -ק\"מ מגבול שטח השיפוט של מקום שירותו הקבוע (לרבות נסיעה בתפקיד לישראל או למדינות אחרות) ,הוא זכאי לתשלום קצובת שהייה."}, {"p": 172, "t": "שליח היוצא לנסיעות בתפקיד למרחק של מעל  200ק\"מ מתחום השיפוט העירוני של יעד השירות ,יהא זכאי גם ללינה במלון .שליח יוכל לקבל מקדמה על חשבון הוצאות הנסיעה. קצובות השהייה העדכניות עפ\"י חלוקה למדינות (לרבות ישראל) ,מפורטות בהוראות תכ\"מ, \"נסיעות לחו\"ל קצובת שהייה ולינה והחזרי הוצאות\" מס' .13.10.0.2 לצורך קבלת דמי השהייה ,על השליח למלא טופס בקשה לדמי שהייה ולהגישו באמצעות"}, {"p": 172, "t": "מנהל כ\"א /קצ\"מ הנציגות ,לחשב האזורי. ב .הטבות ה\"נוסע המתמיד\" .1יש לשאוף להנפקת כרטיס \"הנוסע המתמיד\" ,נפרד מהכרטיס הפרטי של השליח וזאת על מנת למנוע מצב שבו כרטיס \"הנוסע המתמיד\" האישי  /פרטי של השליח ,יזוכה בנקודות, שמקורן בכרטיסי טיסה שנרכשו  /מומנו ע\"ח המשרד."}, {"p": 172, "t": ".2במקרים בהם לא ניתן להפריד את הסדר \"הנוסע המתמיד\" מהכרטיס הפרטי ,יש לעשות אבחנה ברורה בין הפרטי לציבורי ,קרי ,לנהל רישום לנקודות/הטבות בצורה ברורה ,כך שניתן יהיה לזהות את הנקודות שמקורן בכרטיסים פרטיים שנרכשו לעומת הנקודות שנצברו בגין כרטיסי טיסה שמומנו ע\"י המשרד."}, {"p": 172, "t": ".3יצוין כי השימוש בנקודות הנוסע המתמיד בגין טיסות שמומנו ע\"ח המשרד ,יעשה לרכישת כרטיסי טיסה בתפקיד (ללא שדרוגים ,טרקלין עסקים וכיו\"ב) ,בתיאום ובאישור החשב האזורי."}, {"p": 172, "t": "ג .הגעה לארץ במהלך שליחות .1הגעה לארץ של שליח במסגרת תפקיד ,תגובה תמיד באסמכתא .במקומות בהם קיימת מערכת נסיעות חו\"ל ממוחשבת ,מונפקת האסמכתא ע\"י המשלחת  /נספחות .במקומות אחרים ,מונפקת האסמכתא ע\"י הגורם בארץ ,היוזם את הנסיעה."}, {"p": 172, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 173, "t": "עבור ימי העבודה בתפקיד בארץ ,זכאי השליח לדמי שהייה לפי קצובת השהייה בארץ וכן מימון מוניות לשדה התעופה. בתום השהיה בארץ ,ימלא השליח טופס בקשה להחזר הוצאות שהייה ,אותו יעביר לחשב האזורי באמצעות מנהל כ\"א של המשלחת או קצ\"מ הנספחות .ההחזר הכספי יינתן בשכר השליח."}, {"p": 173, "t": "בהגעה לארץ לחופשה ,לא מונפקת בדרך כלל אסמכתא ,אולם במקרה ושליח נדרש לעבוד בארץ במהלך חופשתו ,ידאג הגוף שביקש את השליח לעבוד בארץ ,להזרים אסמכתא (ללא טיסה). ללא גיבוי באסמכתא חתומה ,לא ניתן יהיה להכיר בימים אלה כימי עבודה והשליח לא יוכל לקבל הוצאות שהייה."}, {"p": 173, "t": "המשרד לא יכיר בדיעבד בימי עבודה במהלך חופשה ,שלא גובו באסמכתא. .2מנהלות בהגעה בתפקיד לארץ .1הזמנת מלון הזמנת המלון בארץ תבוצע ע\"י המשלחת /נספחות .במקרה שלא ניתן לבצע הזמנה/תשלום באמצעו כרטיס האשראי של הנציגות (רגולוציה ,בעיה טכנית ,כרטיס תקול ,המלון עובד רק עם כרטיסי אשראי מקומיים /בנקים מסויימים )...אזי השליח יבצע הזמנה באופן עצמאי ,ישלם באמצעות כרטיסו האישי ויקבל החזר כמקובל בהתאם לכללים."}, {"p": 173, "t": "תאריכי הלינה יהיו תואמים את תאריכי ה\"תפקיד\" באסמכתא. הכללים להזמנת הלינה יהיו תואמים את כללי הלינה בתפקיד בחו\"ל ,לרבות כניסה מוקדמת ויציאה מאוחרת כמפורט בהמשך. קצובת הלינה הינה בהתאם לנוהל לינה המפורט בחוברת זו ולהוראת תכ\"ם מס' 13.4.0.3 \"החזר הוצאות בגין לינה אקראית לעובד בתפקיד\"."}, {"p": 173, "t": "חריגה מהקצובה • בסמכות ר' הנציגות לאשר חריגה של עד  25%מהקצובה. • בסמכות חשב אזורי לאשר חריגה של עד  50%מהקצובה (למעט חשב מש\"ן וחשב אזורי בארץ ,שבסמכותם לאשר עד  100%חריגה)."}, {"p": 173, "t": "• בסמכות ר' חטיבת כספים נספחויות ונציגויות בחו\"ל לאשר חריגה של בין .100%-50% • בסמכות חשב המשרד לאשר חריגה מעל ל 100%-מהקצובה. • חריגה שלא אושרה מראש ,לא תאושר. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 174, "t": "בסיום השהות במלון ,על השליח לדרוש חשבונית/קבלה לשהייתו במלון בתאריכים המצויינים וזאת כהוכחה לניצול הלינות בהתאם להזמנה .את החשבונית /קבלה יעביר השליח למנהל כ\"א /קצ\"מ הנציגות ,תשלום למלון יטופל ע\"י הנציגות."}, {"p": 174, "t": "ככלל ,הזמנת המלון תכלול גם חנייה במסגרת הקצובה .היה ואין למלון חניון או שחניון מתופעל ע\"י זכיין ולא ניתן לכלול את מחיר החניה בעלות החדר ,ישלם השליח מכספו עבור חניה בחניון סמוך ויקבל החזר תמורת קבלות עד לתקרה של  ₪ 70ליום .את הקבלות יגיש השליח למנהל כ\"א /קצ\"מ הנציגות ויקבל החזר בשכרו."}, {"p": 174, "t": "נספח הגנה בעת הגעה לארץ בתפקיד ,יוכל לשלם את החניה באמצעות כרטיס האשראי של הנספחות .במקרה שלא ניתן לבצע הזמנה /תשלום באמצעות כרטיס האשראי של הנספחות (רגולוציה ,בעיה טכנית ,כרטיס תקול ,המלון עובד רק עם כרטיסי אשראי מקומיים /בנקים מסוימים ,)...אזי הנספח ישלם את עלות החניה מכספו ,בהתאם לכללים ויקבל החזר כמקובל."}, {"p": 174, "t": "כניסה מוקדמת למלון כניסה מוקדמת לבית מלון תאושר במקרים בהן השליח מתחיל לעבוד בארץ ביום הנחיתה וזאת לאחר שלו\"ז הפגישות בארץ הועבר לגורם המזמין את המלון. שליח המגיע לארץ בטיסות ארוכות (מעל  6שעות) ,במידה והשליח הגיע לארץ יום קודם לפגישות העבודה וזאת נוכח חלופת טיסה יחידה ,תאושר לו כניסה מוקדמת."}, {"p": 174, "t": "בטיסות ארוכות (מעל  6שעות) ,במידה והשליח בחר בטיסה מוקדמת ,מבין חלופות אחרות שהיו קיימות ,לא תאושר כניסה מוקדמת למלון. יציאה מאוחרת מהמלון יציאה מאוחרת תאושר בתנאים הבאים:"}, {"p": 174, "t": "• השליח שהה בתפקיד בארץ עד למועד הטיסה חזרה למקום השירות. • במקרים בהם הטיסה חזרה למקום השירות אורכת מעל  6שעות. • במקרים בהם הטיסה חזרה למקום השירות אורכת פחות מ 6-שעות ,תאושר יציאה מאוחרת במידה והשליח נאלץ להמתין  3שעות ומעלה מרגע סיום העבודה ועד ליציאה לשדה התעופה."}, {"p": 174, "t": ".2הזמנת רכב בתפקיד בארץ לשליחים עובדי משהב\"ט ,המשרתים בכפיפות למשלחת ניו יורק -תוזרם הזמנת הרכב ב\"תפקיד\" ע\"י המשלחת. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 175, "t": "לשליחים עובדי משהב\"ט ,המשרתים בשאר העולם -תוזרם הזמנת הרכב ב\"תפקיד\" ע\"י הגורם המזמין על בסיס כתובת תקציבית או על ידי היחידה למשאבי אנוש ומינהל בחו\"ל. את הבקשה להזמנת רכב ,יש להעביר כ 10-ימי עבודה לפני מועד ההגעה לארץ באמצעות קצין המנהלה/הנספח /מנהל כוח-האדם של המשלחת."}, {"p": 175, "t": "את הרכב יקבל השליח מחטיבת התחבורה של המשרד והוא ימתין לו בחניון שבקריה – על השליח לוודא מול הגורם המזמין ומול חטיבת הרכב כי קיימת הזמנה ושוריין רכב בהתאם למועדים שסוכמו."}, {"p": 175, "t": "• ר' משלחות ,סגני ר' משלחות ונספחי הגנה (עובדי משהב\"ט) ,יוכלו לקבל את הרכב בשדה התעופה בתיאום מראש עם חטיבת התחבורה. לשליחי צה\"ל – תטופל הבקשה לרכב בארץ ע\"י קצין הנסיעות הזרועי."}, {"p": 175, "t": ".3שימוש בטלפון נייד בארץ לשליחים עובדי משהב\"ט בהגעת השליח לארץ ,ישתמש במכשירו הישראלי לפי \"מסלול שליח\" ,שאושר במכרז הנוכחי של החשב הכללי ושמרכיביו הם: •  500דקות שיחה בישראל."}, {"p": 175, "t": "•  500דקות שיחה ברשת הארגונית בישראל. •  500הודעות  SMSבישראל. • חצי ג'יגה גלישה בישראל. במקרה של שהות ממושכת בארץ ,ניתן לפנות במידת הצורך למוקדי חברת פלאפון ולשנות מסלול בהתאם למסלולים הקיימים במכרז חשכ\"ל."}, {"p": 175, "t": "מספרי הטלפון של מוקדי פלאפון: • מוקד חשכ\"ל * 177 :מהמכשיר הנייד. המוקד פועל בימים א'-ה' בין השעות .08:00-17:00 • מוקד שירות כללי *166 :מהמכשיר הנייד. המוקד פועל בימים א'-ה' בין השעות  08:00-19:00וביום ו' עד השעה . 13:00 מודגש כי, • הנתונים שלעיל הינם לפי מכרז קיים אך ,ייתכנו שינויים בהתאם לתנאים שייקבעו מעת לעת במכרז חדש."}, {"p": 175, "t": "• עם סיום השהות בארץ ,שליח ששינה מסלול ,חייב לחזור וליצור קשר עם מוקד חב' פלאפון לצורך החזרת המסלול לקדמותו. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 176, "t": "פרק  – 18זכאויות בעקבות שינוי מצב משפחתי דיווח שינוי מצב משפחתי על כל שינוי במצב המשפחתי חייב השליח לדווח באופן מידי למשרד. לפני היציאה לשליחות שליח משהב\"ט יעביר את הדיווח ליחידה למשאבי אנוש ומנהל בחו\"ל ושליח צה\"ל יעביר באמצעות קצין הנסיעות הזרועי."}, {"p": 176, "t": "במהלך השליחות במהלך השליחות יועבר דיווח למשרד באמצעות מנהל כ\"א/קצ\"מ הנציגות. שינויי זכאויות בעקבות שינוי סטטוס משפחתי נישואי השליח: שליח שיצא לחו\"ל כרווק ונישא במהלך השליחות ,יעודכנו זכאויותיו בהתאם."}, {"p": 176, "t": "על השליח לדווח בכתב על הנישואין למנהל כ\"א  /קצין המנהלה של הנציגות ולצרף להודעתו העתק מתעודת הנישואין .הנ\"ל יעביר דיווח כמקובל ליחידה למשאבי אנוש ומנהל בחו\"ל ,לצורך עדכון הרישומים במערכות הממוחשבות והתאמת הזכאויות."}, {"p": 176, "t": "שליח גרוש  /גירושין במהלך שליחות שליח גרוש ,המשלם מזונות בגין ילד/ים ,שנשארו בארץ בחזקת בן הזוג הקודם ,ימציא למשרד עותק מהסכם הגירושים לפיו הוא משלם מזונות וידווח על כך ב\"טופס  \"101אותו יתבקש למלא אחת לשנה ע\"י יחידת השכר .יחידת השכר תעדכן הרישומים במערכת השכר והשליח יקבל נקודת זיכוי במס עבור כל ילד."}, {"p": 176, "t": "שליח המתגרש במהלך השליחות ,יעביר למנהל כ\"א /קצין המנהלה של הנציגות העתק תעודת הגירושין או הסכם הגירושין ,מאושר על ידי בית הדין. הנ\"ל יעביר דיווח כמקובל ליחידה למשאבי אנוש ומנהל בחו\"ל לצורך עדכון הרישומים במערכות הממוחשבות והתאמת הזכאויות."}, {"p": 176, "t": "בנוסף ,יהיה עליו לדווח על כך בכל שנה ב\"טופס  .\"101יחידת השכר תעדכן הרישומים במערכת השכר והשליח יקבל נקודת זיכוי במס עבור כל ילד. לידה .1מסמכים ותעודות כשנולד לשליח/ה ילד/ה במהלך השליחות ,עליו להעביר למנהל כ\"א /קצין המנהלה של הנציגות ,אישור \"לידת אזרח ישראלי בחו\"ל\" מהקונסוליה הקרובה ביותר למקום מגוריו."}, {"p": 176, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 177, "t": ".2רק עם קבלת מסמך זה ,יעביר הנ\"ל דיווח ליחידה למשאבי אנוש ומנהל בחו\"ל לצורך עדכון הרישומים במערכות הממוחשבות והתאמת הזכאויות. .3שליחה  /אשת שליח היולדת בחו\"ל שליחה /אשת שליח היולדת בחו\"ל במהלך תקופת השליחות ,זכאית לקבל מענק לידה וקצבת ילדים מביטוח לאומי."}, {"p": 177, "t": "יש להעביר דיווח על הלידה ליחידה למשאבי אנוש ומנהל בחו\"ל באמצעות מנהל כ\"א /קצ\"מ הנציגות ולצרף אישור על הלידה הכולל תאריך לידה ושם התינוק ואישור מהקונסוליה על רישום אזרח ישראלי שנולד בחו\"ל .רק ובכפוף להעברת ההודעה יעודכנו מערכות כוח האדם והשכר של המשרד בלידה וביציאה לחופשת לידה."}, {"p": 177, "t": ".4שליחה (עובדת משהב\"ט או שליחת צה\"ל) או אשת שליח המועסקת כאית\"ן, שיולדת במהלך תקופת השליחות בחו\"ל תצא לחופשת לידה (חל\"ד) ,בהתאם ל\"חוק עבודת נשים\". בתקופת חופשת הלידה מופסק תשלום השכר באמצעות המשרד."}, {"p": 177, "t": "עם תום חופשת הלידה ,יש לדווח בכתב ליחידה למשאבי אנוש ומנהל בחו\"ל באמצעות מנהל כ\"א /קצ\"מ הנציגות על החזרה לעבודה. שליחה /אשת שליח היולדת בארץ במהלך תקופת השליחות הגעה לארץ של שליחה או אשת שליח בהיריון .1בחלק מהמדינות ,שהוגדרו ע\"י הועדה הבין-משרדית כ\"קשות שירות\" ,מאפשר המשרד הגעת שליחה או אשת שליח לבדיקות היריון סטנדרטיות וללידה בישראל."}, {"p": 177, "t": ".2לצורך הגעה ארצה במסגרת זו ,יש לפנות ולקבל אישור מרופא האמון .לכל נסיעה כזו, מונפקת אסמכתא. .3שליחה /אשת שליח שקיבלה אישור מהמשרד על סמך חוות דעת של רופא האמון, לביצוע הלידה בארץ ,תהיה זכאית ל:"}, {"p": 177, "t": "א .שליחה או בת-זוג של שליח המגיעה ארצה כאמור לעיל ,זכאית לעד  45ימי שהייה ולינה בארץ (לפי הקצובות המאושרות בישראל) ,האמור לעיל חל גם על בני משפחה נלווים ,שאושרה הגעתם לארץ במסגרת זו ובתנאי שישובו למדינת השירות תוך חודש ימים מיום הלידה."}, {"p": 177, "t": "ב .כרטיס טיסה על חשבון המשרד ,לה ולבני המשפחה הנלווים בתנאי שהם חוזרים תוך חודש ימים למדינת השירות ממועד הלידה .למעט במקרים בהם יש מניעה רפואית לחזור למקום השירות ,ע\"פ החלטת רופא האמון."}, {"p": 177, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 178, "t": "ג .שליחה /אשת שליח המועסקת כאית\"ן זכאית למשכורת מיום צאתה את מקום השירות עד ליום הלידה ולא יותר מאשר משכורת חודשית אחת ,כאשר המשכורת תהיה לפי מקום השירות. ד .שליחה /אשת שליח היולדת בארץ במהלך תקופת השליחות ,זכאית לקבל מענק לידה וקצבת ילדים מביטוח לאומי .אשת שליח שעבדה בחו\"ל ,זכאית גם לדמי לידה (בהתאם לתקופת חופשת הלידה כמצוין בחוק עבודת נשים)."}, {"p": 178, "t": "ה .כדי לממש זכויות אלה ,על שליחה/אשת שליח להפיק מאתר הביטוח הלאומי באינטרנט טופס \"תביעה לדמי לידה\" ולשלוח אותו למוסד לביטוח לאומי בצירוף אישור רשמי על הלידה. הגעה לארץ לבדיקות היריון וללידה הגעה לארץ למטרת טיפול רפואי ככלל ,יטופלו השליחים ובני משפחותיהם במקום השירות .במקרים מסוימים ,יאשר המשרד הגעת שליח או בן משפחתו לארץ לביצוע הטיפול הרפואי .ראה הרחבה בפרק–"}, {"p": 178, "t": "\"שירותי בריאות ורפואה\". שינוי זכאויות עקב לידה במהלך שליחות. .1תקבע לשליח קצובת שכ\"ד חדשה ולא יותר משכר הדירה בפועל. .2בתום השליחות ,יותאמו זכאויות השליח השונות בהתאם להרכב המשפחתי החדש."}, {"p": 178, "t": "ברית מילה במקרה שאין בארץ השירות מוהל ויש להביאו מחוץ לגבולות מדינת השירות או מישראל, יפנה השליח (ניתן אפילו טרם הלידה) ליחידה למשאבי אנוש ומנהל בחו\"ל ,באמצעות מנהל כ\"א  /קצין המנהלה של הנציגות לקבלת אישור למימון המשרד את הוצאות הנסיעה / טיסה ,הוצאות הלינה והוצאות השהייה של המוהל .באחריות השליח להתקשר עם מוהל לביצוע ברית המילה .שכר המוהל ישולם ע\"י השליח."}, {"p": 178, "t": "הזכאות בגין הגעת המוהל תהא בהתאם לכללים המפורטים בשות\"ש ואינם כוללים סייגים או עלויות בגין שהייה בבידוד במקרה של ההנחיות במקום השירות או שהייה ואש\"ל בגין תחלואה של המוהל או מתן שירותי רפואה במקום השירות ,כל העלויות מעבר למפורט בשות\"ש יחולו על השליח לרבות כיסוי רפואי של המוהל."}, {"p": 178, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 179, "t": "חזרת ילדים ארצה )1שליח ,שאחד מילדיו חזר לארץ לפני תום תקופת השליחות ,לרבות בגין גיוס לצה\"ל ,חייב לדווח על כך באופן מיידי ליחידה למשאבי אנוש ומנהל בחו\"ל באמצעות מנהל כ\"א /קצין מנהלה בנציגות .המשרד יממן לילד כרטיס טיסה ארצה (כמו כרטיס טיסה של תום שליחות."}, {"p": 179, "t": ")2ילד החוזר ארצה רשאי לקחת עימו ע\"ח המשרד ,מטען אווירי בלבד של  100ק\"ג ומזוודה אחת נוספת בטיסה ארצה ראה הרחבה בפרק שינוע ובשות\"ש. )3כל עוד השליח נישאר בדירה בה גר לפני עזיבת ילדו ,לא יחול שינוי בקצובת שכר הדירה המשולמת לו .במידה והשליח עבר לדירה אחרת לאחר עזיבת הילד ועל פי בחירתו ,קצובת הדיור תתעדכן בהתאם למצבו המשפחתי החדש בחו\"ל ולקצובת שכר הדירה המאושרת"}, {"p": 179, "t": "ע\"י הוועדה הבין-משרדית באותה העת במקום המגורים החדש של השליח. ידוע  /ידועה בציבור ראה פרטים בפרק  9זכויות מצטרפים )1שליח ,שהמשרד אישר צירוף בן/בת הזוג במעמד \"ידוע/ה בציבור\" ,יקבל בגינו בתקופת השליחות ,זכויות כשל \"נשוי\"."}, {"p": 179, "t": ")2לצורך התנעת תהליך ההכרה בבן /בת הזוג כידוע/ה בציבור ,יש לפנות ליחידה למשאבי אנוש ומנהל בחו\"ל מוקדם ככל הניתן. )3ראה פרטים בפרק  9זכויות מצטרפים מעמד \"שליח בגפו\" ראה פרטים בפרק  9זכויות מצטרפים המדיניות המוצהרת של המשרד היא ,שיש לצאת לשליחות ביחד עם המשפחה .במקרים מיוחדים ,כשמסיבות שונות ,משפחת השליח אינה יכולה להצטרף אליו לשליחות ,או כשמשפחת השליח נאלצת לשוב לארץ והשליח ממשיך את השליחות בגפו ,יוכל השליח לפנות"}, {"p": 179, "t": "ליחידה למשאבי אנוש ומנהל בחו\"ל ,בבקשה להכיר בו כ\"שליח בגפו\". חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 180, "t": "פרק מס'  – 19דמי ייצוג דמי ייצוג והחזר הוצאות אירוח (ראה נוהל דמי ייצוג פרק ) 20 שליחי המדינה בחו\"ל נדרשים לקדם את האינטרסים של מדינת ישראל בתחומי יחסי החוץ, הביטחון ,הכלכלה ,תרבות ועוד .הם נדרשים לייצגה בצורה ראויה ונאותה ,תוך יצירת מארג קשרים בני-שיח מקהלים שונים ומגוונים .כדי לעשות כן ,נדרשים השליחים למגוון פעולות והוצאות ייצוג ואירוח."}, {"p": 180, "t": "משרד האוצר קבע נוהל ובו הגדיר את ההוצאות המותרות לשימוש במסגרת תקרת דמי הייצוג לשליח. בהתאם לנוהל משרד האוצר ,מעמיד המשרד לכל שליח מסגרת תקציבית שנתית לביצוע פעולות הייצוג והאירוח במסגרת תפקידו ומחזיר לו את ההוצאות בהתאם לכללים .בשנת היציאה לשליחות יקבל השליח את החלק היחסי מתוך המסגרת השנתית שלו."}, {"p": 180, "t": "מובהר כי תקציב הייצוג אינו מיועד לאירוח עובדי המשרד ,בני משפחה ,ישראלים המבקרים במקום או עמיתים ישראליים מנציגויות אחרות ,הפוקדים את השליח במקום שירותו – אם בתפקיד ואם באופן פרטי."}, {"p": 180, "t": "השימוש בתקציב הייצוג ייעשה אך ורק במסגרת מילוי תפקידו של השליח. הוצאות הייצוג מוחזרות לשליח בשכר חו\"ל ,תמורת קבלות .הקבלות בגין דמי הייצוג ,יהיו בגין הוצאות ייצוג ואירוח של השליח מיום תחילת השליחות ועד ליום האחרון של תפקידו בחו\"ל בהתאם לתאריך המצוין באסמכתא."}, {"p": 180, "t": "סוגי הוצאות הייצוג והאירוח המאושרות .1הוצאות אירוח בבית השליח ,המהוות הוצאות ישירות הקשורות לאירוח עצמו כגון מוצרי מזון ,משקאות ,מבשלת ,קייטרינג ,מנקה ,מלצר .לעניין סעיף זה ,לא תוכר כל הוצאה מעורבת כגון הוצאות חשמל ,כלים שנרכשו וכיו\"ב."}, {"p": 180, "t": ".2הוצאות אירוח מחוץ לבית השליח (במשרד ,במקומות הארחה ,בבתי מלון או במסעדות) לרבות תשלומים לעובדים ומלצרים ,שכירת אולמות ,תשלום בגין חניית האורחים וכיו\"ב. יובהר כי אירועים ממלכתיים כגון יום העצמאות ,יום הזכירון וכנס נספחים זרים ,ימומנו מתקציב המשרד ובכפוף לאישור חשב המשרד."}, {"p": 180, "t": ".3מוצרים ותשורות צנועות ,בעלות אופי ישראלי ,אשר נרכשו בישראל לטובת אירוח והתארחות במשימות העבודה .ערך התשורה לא יעלה על .₪ 200 .4הוצאות משלוח פרחים ,שליחויות ,מתנות ,בקבוקי יין וכו' לנציגים זרים במקום השירות כגון אנשי ממשל ואנשי ציבור שהקשר איתם רצוי."}, {"p": 180, "t": ".5דמי חברות במועדונים ,לדוגמא הסגל הדיפלומטי ,למעט חברות במועדון ספורט .יובהר כי לא יוכרו דמי חברות בגינם השליח מקבל תמורה או שירות כלשהו. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 181, "t": ".6הוצאות נסיעה בתחבורה ציבורית לרבות מוניות וכן הוצאות בגין חניה לצורך קבלות פנים ,אירועים רשמיים ,פגישות עם גורמים זרים וכיו\"ב ,עד לסכום של  .₪ 600החזרי הוצאות אלו יהיו אך ורק כנגד קבלות."}, {"p": 181, "t": ".7דמי שירות בסכומים סבירים בהתאם למנהגי המקום. אופן השימוש בתקציב הייצוג: .1מסגרת התקציב נקבעת בשקלים ,אך ההחזר הכספי משולם במטבע מקומי. .2שליח יכול לקבל מהמשרד מקדמה עומדת בסך  1/12מהמסגרת השנתית העומדת לרשותו .המקדמה תקוזז חודש לפני סיום השליחות."}, {"p": 181, "t": ".3החזרים עבור הוצאות ייצוג ואירוח ,כמפורט ברשימה לעיל ,יינתנו למול הגשת חשבוניות/קבלות ולא יהיו חייבים במס. .4במקרים בהם נהוג לשלם סכומים מסוימים במזומן ללא תיעוד ,כגון טיפים למלצרים, יוכרו ההוצאות כאמור בסכום סביר ומידתי ביחס לנהוג בנסיבות העניין ,אשר לא יעלה על 15%מסכום הקבלה בגין השירות שניתן .וזאת בכפוף להצהרה בכתב של השליח."}, {"p": 181, "t": ".5בסוף כל חודש ,ימלא השליח טופס דיווח על הוצאות הייצוג ,יגיש אותו למנהל כ\"א/ קצ\"מ הנציגות ,לאחר בדיקה ואישור ,יועברו הקבלות לחשב האזורי לצורך טיפול בהחזר הכספי לשליח באמצעות השכר."}, {"p": 181, "t": ".6הוצאות ייצוג במדינות אמנה – ראה פרק תנאי שירות ייחודים לר' נציגויות. החזר הוצאות אירוח ללומדים ומשתלמים: לומדים ומשתלמים ,אינם מקבלים דמי ייצוג בשכרם. יחד עם זאת ,מכיוון שיש לשליחים אלה מפעם לפעם הוצאות אירוח וייצוג ,החליט המשרד שיקבלו \"החזר הוצאות אירוח\" בסך של עד  2,000$בשנת שליחות ,תמורת הגשת קבלות, לצורך כיסוי הוצאות אירוח המתבקשות עקב היותם לומדים מטעם מדינת ישראל בחו\"ל."}, {"p": 181, "t": "הקצובה מיועדת לאירוח זרים בלבד ואינה מיועדת לאירוח עובדי המשרד/צה\"ל ,ישראלים או עמיתים ישראלים עימם מקיים המשתלם קשרים מסגרת לימודיו. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 182, "t": "פרק  - 20הנחיות חשב – אופן השימוש בדמי ייצוג מדינת ישראל משרד האוצר הנחיות יישום לאופן השימוש בתקציב הוצאות ייצוג ,אירוח ואחזקת בית לשליחים עובדי מדינה המשרתים בחו\"ל רקע ומטרות .1שליחי המדינה בחו\"ל נדרשים לקדם את האינטרסים של מדינת ישראל בתחומי יחסי החוץ ,הביטחון ,הכלכלה ,דיפלומטיה ציבורית ,תרבות ועוד .הם נדרשים לייצגה בצורה ראויה ונאותה ,תוך יצירת מארג קשרים עם בני-שיח מקהלים שונים ומגוונים .כדי"}, {"p": 182, "t": "לעשות כן נדרשים השליחים למגוון של פעולות והוצאות ייצוג ואירוח .נוהל זה בא להסדיר ולקבוע את ההוצאות המותרות לשימוש במסגרת תקרת דמי הייצוג ואחזקת הבית לשליח כמפורט במסמך זה."}, {"p": 182, "t": ".2בשלהי שנת  2018יושם הסכם שכר חדש לשליחים בחו\"ל .בד בבד עם יישום הסכם השכר ,הותקנו תקנות מס חדשות המסדירות את כללי המס לשליחים בחו\"ל. .3לאור זאת ,בסביבת חוקת השכר וכללי המס החדשים ,נוצר הצורך להבהיר למשרדי הממשלה כיצד לנהוג בכל הנוגע לאופן השימוש בתקציב ייצוג ,אירוח ואחזקת בית לעובדי מדינה אשר מוקצה להם תקציב כאמור מתוקף תפקידם )להלן\" :תקציב ייצוג\"(."}, {"p": 182, "t": ".4הנחיות היישום )להלן\" :הנחיות יישום\" או \"נוהל (\"המפורטות במסמך זה הינן בתוקף מיום .1.1.2019 כללי .5הנהלת המשרד תעמיד לרשות עובדי המדינה השליחים המשרתים בחו\"ל ,תקציב לביצוע פעולות ייצוג מדינת ישראל במסגרת תפקידם כמפורט להלן:"}, {"p": 182, "t": "א .תקציב החזר הוצאות בגין \"דמי ייצוג\" לבעלי תפקידים שבמסגרת מילוי תפקידם עליהם לארח גורמים רשמיים זרים ו/או להתארח על ידם )להלן\" :החזר הוצאות בגין ייצוג(\". ב .תקציב החזר הוצאות בגין \"אחזקת בית\" לבעלי תפקידים שבמסגרת מילוי תפקידם נדרשים לארח גורמים רשמיים זרים בביתם הפרטי )להלן\" :החזר הוצאות בגין אחזקת בית\")."}, {"p": 182, "t": ".6מובהר כי תקציב הייצוג אינו מיועד לאירוח עובדי המשרד ,בני משפחה ,ישראלים המבקרים במקום או עמיתים ישראלים מנציגויות אחרות הפוקדים את הנציגות בתפקיד או באורח פר טי .7השימוש בתקציב יעשה אך ורק במסגרת מילוי תפקידו של השליח ועל פי הנחיות היישום המפורטות בהמשך מסמך זה."}, {"p": 182, "t": "סוגי הוצאות המותרות לשימוש במסגרת תקציב הייצוג 1במקרים מיוחדים ,כאשר הדבר תורם לפעילות ייצוג מדינת ישראל ,רשאי חשב המשרד לאשר החזר הוצאות בגין אירוח קהילה יהודית מקומית."}, {"p": 182, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 183, "t": ".8החזר הוצאות בגין דמי ייצוג ,כנגד קבלות בלבד ,שישמש אך ורק למטרות הבאות: א .הוצאות אירוח בבתי העובדים המהוות הוצאות ישירות הקשורות לאירוח עצמו כגון מוצרי מזון ,משקאות ,מבשלת ,קייטרינג ,מנקה ומלצר .לעניין סעיף זה ,לא תוכר כל הוצאה מעורבת כגון הוצאות חשמל ,כלים שנרכשו וכיו\"ב."}, {"p": 183, "t": "ב .הוצאות אירוח מחוץ לבתי העובדים) במשרד ,במקומות הארחה ,בבתי מלון או במסעדות( לרבות תשלומים לעובדים ולמלצרים ,שכירת אולמות ,תשלום בגין חניית האורחים וכיו\"ב .יובהר כי אירועים ממלכתיים כגון יום העצמאות ,יום הזיכרון וכנס נספחים זרים ,ימומנו מתקציב המשרדים ובכפוף לאישור חשב המשרד."}, {"p": 183, "t": "ג .מוצרים ותשורות צנועות בעלות אופי ישראלי אשר נרכשו בישראל לטובת אירוח והתארחות במשימות עבודה.2 ד .הוצאות משלוח פרחים ,שליחויות ,מתנות ,בקבוקי יין ,כרטיסי תיאטרון וכד' לנציגים זרים במקום ,כגון :אנשי ממשל ואנשי ציבור שהקשר אתם רצוי ה .דמי חברות במועדונים ,לדוגמה הסגל הדיפלומטי או הקונסולרי ,במועדון יהודי מקומי ,בבית כנסת ,במועדון עיתונאים וכיו\"ב ,למעט חברות במועדון ספורט .יובהר כי"}, {"p": 183, "t": "לא יוכרו דמי חברות בגינם השליח מקבל תמורה או שירות כלשהו. ו .הוצאות נסיעה בתחבורה ציבורית לרבות מוניות וכן הוצאות בגין חניה לצורך קבלות פנים ,אירועים רשמיים ,פגישות עם גורמים זרים וכיו\"ב ,עד לסכום של  .₪ 600החזרי הוצאות אלו יהיו אך ורק כנגד קבלות."}, {"p": 183, "t": "ז .דמי שירות בסכומים סבירים בהתאם למנהגי המקום. ח .הוצאות נוספות בגין ייצוג לבעלי תפקידים שבמסגרת מילוי תפקידם עליהם לארח גורמים רשמיים זרים 3ו/או להתארח על ידם ,באישור מראש ובכתב על ידי חשב המשרד."}, {"p": 183, "t": ".9החזר הוצאות בגין אחזקת בית ,חייב במס ,4שישמש אך ורק למטרות הבאות: א .הוצאות כלכלה ,שכר וביטוח של עובדי משק הבית. ב .שעות עבודה ושעות נוספות לעובדי הבית המועסקים על ידי הנציגות כאמור ,מעבר למכסה שאושרה לשליח ,בגין עבודות הקשורות בניקיון ואחזקה שוטפת של הבית ג .תשלום לחברת ניהול בבתי דירות שאינן דירות שרד."}, {"p": 183, "t": "ד .החזרים בגין הוצאות חשמל ,מים ,סולר ,גז ,ועד בית שאינו נכלל בשכ\"ד. ה .הוצאות מבשל/ת (באמצעות חברה או בהעסקה ישירה). ו .מים מינרליים וכל סוגי מים המיועדים לבישול ולשתייה ,וכן מסננים מכל סוג."}, {"p": 183, "t": "ז .הוצאות ניקיון כמפורט להלן: .1הוצאות שירותי ניקיון לרבות פוליש רצפה (באמצעות חברה או בהעסקה ישירה). .2הוצאות ביגוד למנקה. .3אביזרי ניקיון ,התקנים לשירותים ולאמבטיות ,נייר טואלט."}, {"p": 183, "t": "2לעניין סעיף זה ,לא יותרו בניכוי מתנות ששווין עולה על .₪ 200 3במקרים מיוחדים ,כאשר הדבר תורם לפעילות ייצוג מדינת ישראל ,רשאי חשב המשרד לאשר החזר הוצאות בגין אירוח קהילה יהודית מקומית."}, {"p": 183, "t": "4בהתאם לעמדת רשות המסים ,החזר בגין הוצאות אלו יהיה בכל מקרה חייב במס ללא קשר להצגת קבלות בגינן . חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 184, "t": ".4כלי ניקוי ,כגון מברשת ,מטאטא ,יעה ,סחבה ,שקיות לשואב אבק ,מטלית וכיו\"ב. .5חומרי ניקוי מכל הסוגים ,כולל אבקת כביסה ,מרכך כביסה ,מפיות לריכוך כביסה ,מלח וסבון למדיח כלים ,מתקנים לייבוש כביסה .6הוצאות ניקוי לביגוד ,לווילונות ולמפות שולחן ."}, {"p": 184, "t": ".7הוצאות ניקוי ותיקון לשטיחים ,וילונות וריהוט. .8הדברה שנתית לרבות חומרי הדברה. .9פינוי אשפה. ח .אביזרים שונים לבית כמפורט להלן: .1מזוזות. .2ספרי אורחים בקבלות פנים ואירועים."}, {"p": 184, "t": ".3מחצלות בכניסה לבית ,לחצר ולמרפסות. .4תמונות ,פוסטרים ,מסגרות לתמונות ,תיקונים של תמונות ומסגרות לתמונות . .5כלי מטבח ,סכו\"ם ,כוסות ,גביעי משקה לאירוח ,צלחות ,תבניות אפיה ,סירי בישול ,מחבתות ,כלי עבודה למטבח ,כלים חד פעמיים ,שקיות קרח וכיו\"ב."}, {"p": 184, "t": ".6רכישה/השכרה של מכונת מים ועלות החלפה של מסננים. .7רכישה/השכרה של מכונת קפה  +קפסולות. .8מכשירים סופגי לחות  +החלפה תקופתית של פילטרים. .9מכשיר  UPSביתי ,שנאים מ 220 -ל 110 -וולט."}, {"p": 184, "t": ".10נורות ,מנורות ,תאורת חירום ,פנסים ,סוללות למכשור ,כבלי חשמל וכיו\"ב. .11מגבות ,מגבות נייר ,מפות שולחן ,מפיות קישוט וכיו\"ב. ט .הוצאות תחזוקת הבית כמפורט להלן: .1תיקוני בית שוטפים כולל צביעה וחומרי צביעה וכיו\"ב."}, {"p": 184, "t": ".2שירות למזגנים ,מסנני אוויר והחלפת חלקים . .3גינון צמחים ועציצים. י .הוצאות נוספות בגין אחזקת בית לבעלי תפקידים שבמסגרת מילוי תפקידם עליהם לארח גורמים רשמיים זרים 5בביתם הפרטי ,באישור מראש ובכתב על ידי חשב המשרד."}, {"p": 184, "t": "גובה התקציב אגף תקציבים במשרד האוצר יקבע לכל משרד ממשלתי תקרת תקציב שנתית המיועדת להחזר הוצאות בגין ייצוג ואחזקת בית. הנהלת המשרד תקבע הקצאה עבור דמי הייצוג ואחזקת הבית לכל אחד מבעלי התפקידים הרלוונטיים במשרד )ברמת הפרט( ,כך שסך ההקצאה המאושרת בגין כלל בעלי התפקידים במשרד לא תחרוג מהתקרה שנקבעה על ידי אגף התקציבים במשרד האוצר ,כאמור בסעיף  10לעיל."}, {"p": 184, "t": "תקרות ההקצאה המותרות בגין דמי הייצוג ואחזקת בית ברמת הפרט ,מפורטות בנספח א' לנוהל .הנהלת המשרד אינה רשאית לאשר הקצאה ,ברמת הפרט ,מעבר לתקרות אלו. 5במקרים מיוחדים ,כאשר הדבר תורם לפעילות ייצוג מדינת ישראל ,רשאי חשב המשרד לאשר החזר הוצאות בגין אירוח קהילה יהודית מקומית."}, {"p": 184, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 185, "t": "מטה השכר באגף החשב הכללי יעדכן את סכומי תקרות דמי הייצוג ואחזקת הבית ברמת הפרט בהתאם לצורך מעת לעת . ככלל ,ההקצאה בגין דמי הייצוג ואחזקת בית ,כאמור לעיל ,תיקבע בשקלים ותשולם במטבעהמקומי בהתאם לנציגות הרלוונטית למעט נציגויות מסוימות שיאושרו בכתב ומראש על ידימטה השכר באגף החשב הכללי."}, {"p": 185, "t": "ניתן לאשר החזר הוצאות בגין אירועי ייצוג נוספים בכפוף לעמידה בתקרת תקציב המשרד השנתית לייצוג כאמור בסעיף  10לעיל .החזרי הוצאות אלו יהיו בהתאם למפורט בנספח ג' . אופן השימוש בתקציב .15החזר הוצאות בגין ייצוג א .החזרים בגין הוצאות שהוצאו ניתן יהיה לדרוש עד לגובה המכסה שאושרה לבעל התפקיד ובלבד שהוצאו כנגד חשבוניות או קבלות."}, {"p": 185, "t": "ב .החזרים כאמור ,בגין הוצאות שבוצעו במסגרת מילוי תפקידו של העובד ,ושהומצאו בגינם קבלות ,אינם חייבים במס.6 ג .במדינות שיאושרו בכתב ומראש על ידי מטה השכר באגף החשב הכללי ,בהן נקבע כי קיים קושי ייחודי בהמצאת קבלות ,רשאי המשרד להסדיר נוהל פנימי ,שיאושר על ידי חשב המשרד ,אשר יסדיר את היחס בין הוצאות כנגד קבלות להוצאות כנגד הצהרה."}, {"p": 185, "t": ".16החזר הוצאות בגין אחזקת בית א .החזרים בגין הוצאות שהוצאו כנגד חשבוניות או קבלות ,ניתן יהיה לדרוש עד לגובה המכסה שאושרה לבעל התפקיד. ב .היה ולא נוצלה מכסת התקציב במלואה כנגד חשבוניות או קבלות ,רשאי בעל תפקיד לדרוש ,בגין יתרת התקציב שלא נוצל ,החזר על בסיס דיווח אישי )ללא חשבוניות או קבלות( ובלבד שהחזר ההוצאה כנגד חשבוניות או קבלות נוצל במלואו בהתאם לשיעור"}, {"p": 185, "t": "המכסה על בסיס דיווח אישי כמפורט בטבלה שלהלן: תקופה שיעור מכסת החזר הוצאה כנגד קבלות שיעור מכסת החזר הוצאה על בסיס דיווח אישי עד ליום 2019.12.31 מיום 2022.10.1 50% 50% 54% 58% 67% 50% 50% 46% 42% 33% החזרים כאמור ,בגין הוצאות שבוצעו במסגרת מילוי תפקידו של העובד ,יחויבו במס במלואם וזאת בין אם הומצאו כנגד חשבוניות או קבלות ובין אם לאו."}, {"p": 185, "t": "6במקרים בהם נהוג לשלם סכומים מסוימים במזומן ללא תיעוד ,כגון טיפים למלצרים ,יוכרו הוצאות כאמור בסכום סביר ומידתי ביחס לנהוג בנסיבות העניין אשר לא יעלה על  15%מסכום הקבלה בגין השירות שניתן ,זאת בכפוף להצהרה מתאימה של מורשה החתימה והמארח על גבי הקבלה /חשבונית בגין ההוצאה העיקרית עבורה ניתן הטיפ."}, {"p": 185, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 186, "t": ".17מובהר כי הדיווח בדבר ניצול תקציב החזר ההוצאות יהיה ברמה חודשית אולם ההתחשבנותלגביו תהיה על בסיס שנה קלנדרית )לא ניתן להעביר יתרות שלא נוצלו משנת התקציב לשנהעוקבת(."}, {"p": 186, "t": ".18לעובד יוקצה תקציב ייצוג ואחזקת בית מיום תחילת עבודתו בפועל בנציגות ועד ליום האחרון שעבד בפועל בנציגות. א .לא יוקצה תקציב בגין ימי חופשה שמנצל העובד בסיום שירותו ,אשר עבורם הוא מקבל משכורת חו\"ל."}, {"p": 186, "t": "ב .לעובד העובר מנציגות לנציגות יוקצה תקציב ייצוג עד ליום עבודתו האחרון בנציגות הקודמת ומיום תחילת עבודתו בנציגות החדשה .בתקופת המעבר שבין נציגות לנציגות אין העובד זכאי לתקציב ייצוג."}, {"p": 186, "t": ".19מובהר כי שליח יהיה זכאי לדרוש החזר הוצאות בגין ייצוג ,אירוח ואחזקת בית כמפורט לעיל ,עד לגובה התקציב שאושר לו ,במסגרת הכללים המפורטים במסמך זה בלבד .לא יאושרו החזרי הוצאות מתקציב המדינה בגין העילות המפורטות במסמך זה במסגרת התחשבנות כספית אחרת למעט הוצאות תפעוליות מהותיות הממומנות בדרך קבע מתקציב הנציגות כגון :דירות שרד והוצאותיהן ,אירועי תרבות ,העסקת עובדי משק בית לבעלי תפקידים בכירים"}, {"p": 186, "t": "וכיו\"ב ,בהתאם לנוהל משרדי שיאושר על ידי חשב המשרד וככל שלא ייכללו במסגרת החזר ההוצאות בגין ייצוג ואחזקת בית. אופן ההתחשבנות והבקרה השוטפת .20עובד המבקש להוציא הוצאה מהתקציב העומד לרשותו )בהתאם לאחת ההוצאות המותרות כמפורט בפרק \"סוגי הוצאות המותרות לשימוש במסגרת תקציב הייצוג\"( שעלותה  18,000ש\"ח או יותר ,יגיש בקשה לקצין המנהלה /ראש הנציגות בטופס ייעודי .7קצין המנהלה יבחן את הבקשה ויוודא כי ההוצאה המבוקשת הינה בהתאם"}, {"p": 186, "t": "להוצאות המותרות כמפורט בסעיפים האמורים .במידה וההוצאה מותרת ,קצין המנהלה יחתום על הטופס במקום המיועד לכך ,ויבצע הזמנה ישירות לספק המספק את השירות. קצין המנהלה יבצע את התשלום לספק וידווח על ההוצאה שבוצעה מתקציב בגין הייצוג לגורם הרלוונטי בחשבות המשרד ,באמצעות הטופס הייעודי ,לצורך התחשבנות מול יתרת תקציב החזר הוצאות בגין ייצוג ואחזקת הבית של השליח."}, {"p": 186, "t": ".21עובד המבקש להוציא הוצאה מהתקציב העומד לרשותו )בהתאם לאחת ההוצאות המותרות כמפורט בפרק\" סוגי הוצאות המותרות לשימוש במסגרת תקציב הייצוג\"( שעלותה מתחת ל ₪ 18,000 -ו/או שלא בוצעה באמצעות קצין המנהלה ,רשאי לעשות כן באופן עצמאי .העובד ימלא מדי חודש את הטפסים המצורפים בנספח ב' לפי העניין )להלן\" :הטופס(\" ,יצרף אליו את הקבלות בגין ההוצאות שבוצעו בהתאם להוצאות"}, {"p": 186, "t": "המותרות כמפורט בפרק האמור ויעבירו בצירוף הקבלות לגורם הרלוונטי בחשבות המשרד. .22בהתאם להוראות רשות המסים ,שימוש בתקציב לצרכי אירוח זרים מחייב תיעוד מסודר בגין כל אירוח לרבות מהות האירוח ,מקום ,תאריך שבו התקיים ורשימת בעלי 7הטופס יוגדר על ידי המשרד ויאושר על ידי חשב המשרד."}, {"p": 186, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 187, "t": "התפקידים המוזמנים .במקרים אלו ,העובד יפרט בטופס מידע רלוונטי כאמור לעיל לצורך תיע ודוביקורת .בסמכות חשב המשרד ,במקרים מסוימים ,לדרוש מהעובד דיווח מלא על פרטיהאורחים לרבות שם מלא ותפקיד וכן כל פרט נוסף הנדרש לצרכי ביקורת, כתנאי לקבלת החזר הוצאות.8 .23חשב המשרד יקיים פיקוח ובקרה על מנת לוודא כי ההוצאות המאושרות לתשלום הינן בהתאם לנוהל ואינן חורגות ממכסת התקציב שאושרה לעובד .החשב יאשר החזר"}, {"p": 187, "t": "הוצאות לעובד באמצעות תלוש השכר תוך הבחנה בין הוצאות חייבות במס ולבין הוצאות פטורות . .24חשב המשרד יאשר לכל שליח טרם יציאתו לשליחות את סכום התקציב בשקלים העומד לרשותו בכפוף לאמור בפרק \"גובה התקציב\"."}, {"p": 187, "t": ".25חשב המשרד יאשר לשליח מקדמה עומדת בגובה תקציבו החודשי ,בכפוף לאישור השליח בחתימתו לביצוע קיזוז המקדמה משכרו ,בכל עת ,בהתאם לשיקול דעתו הבלעדי של חשב המשרד .בתום תקופת השליחות תקוזז המקדמה העומדת משכר השליח."}, {"p": 187, "t": ".26חשב המשרד יקיים מערך פנימי לפיקוח ובקרה אפקטיביים על אופן השימוש בתקציב החזר הוצאות בגין ייצוג ואחזקת בית. .27חשב המשרד יקבע את תהליך הדיווח האישי שעל השליחים להעביר לגורמים הרלוונטיים במשרד ,שעל בסיסה יאושרו לתשלום החזרי ההוצאות בגין ייצוג ואחזקת בית בכפוף להוראות נוהל זה."}, {"p": 187, "t": ".28חשב המשרד יוודא כי החזרי הוצאות לשליח ימוסו כדין כמפורט להלן: א .החזר הוצאות בגין דמי ייצוג פטור ממס ככל שהומצאה חשבונית או קבלה בגינו בהתאם לעילות המפורטות במסמך זה."}, {"p": 187, "t": "ב .החזר הוצאות בגין אחזקת בית יהיו חייבות במס במלואן ,בהתאם להנחיית רשות המסים .למען הסר ספק מובהר כי חשב המשרד אינו מוסמך לאשר גילום הוצאות אלו. 8בשל צורכי אבטחת מידע ורגישויות פוליטיות במדינות שיר ות מסוימות ,על חשב המשרד להבטיח חיסיון מלא של פרטים אלו ואי- חשיפתם לגורמים נוספים."}, {"p": 187, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 188, "t": "נספח א' – מכסה שנתית ברמת הפרט להחזר הוצאות בגין ייצוג ואחזקת בית )אלפי (₪ מכסה שנתית בגין בעל תפקיד מכסה שנתית בגין ייצוג ראש נציגות או דרג שגריר כל יתר השליחים אחזקת בית חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 189, "t": "נספח ב' - 1טופס הצהרה על הוצאות בגין דמי ייצוג נציגות_______________________ שם השליח_________________________ מטבע מקומי_______ _________ חודש_____________________ מס ' קבלה תאריך הקבלה עילת ההוצאה שם האורח /מקבל המתנה תפקיד האורח /מקבל המתנה סכום במטבע מקומי סה\"כ הוצאות ייצוג כנגד קבלות אני מצהיר שכל ההוצאות המדווחות לעיל הן הוצאות שנדרשו לייצוג המדינה ,ידוע לי כי ככל"}, {"p": 189, "t": "שיתברר אחרת – אני כפוף לדין משמעתי וייתכן שבנוסף אדרש להחזיר את הסכומים האמורים. חתימת השליח חתימת נציג חשב המשרד תאריך תאריך חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 190, "t": "נספח ב' - 2טופס הצהרה על הוצאות בגין אחזקת בית נציגות_______________________ שם השליח_________________________ מטבע מקומי_______ _________ חודש_____________________ תאריך הקבלה סכום במטבע מקומי עילת ההוצאה מס ' קבלה סה\"כ הוצאות אחזקת בית כנגד קבלות הריני להצהיר כי בנוסף להוצאות המפורטות לעיל היו לי הוצאות אחזקת בית נוספות ללא קבלות ,במסגרת מילוי תפקידי ,בסך של___________. :"}, {"p": 190, "t": "הריני להצהיר כי ידוע לי שבגין הוצאות אחזקת בית ינוכה מס כחוק . סה\"כ הוצאות אחזקת בית חתימת השליח תאריך חתימת נציג חשב המשרד תאריך חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 191, "t": "נספח ג' – החזר הוצאות בגין אירועי ייצוג אחרים להלן הוצאות ייצוג בגין אירועים נוספים המותנים באישור בכתב מחשב המשרד: .1ראש נציגות ומספר  2במדינות אמנה א .ראש נציגות המאומן לנציגויות נוספות זכאי להחזר הוצאות ייצוג ואירוח לכל נסיעה בתפקיד למדינות האמנה ,בכפוף לאמור בנוהל זה."}, {"p": 191, "t": "ב .הוצאות אלה הן בנוסף לקצובת הייצוג הקבועה שלו ,והן מיועדות להוצאות ייצוג במדינות האמנה. ג .הוצאות אלה תוחזרנה כנגד קבלות בלבד ,על פי ההוצאה הממשית ,לא יותר מאשר 150דולר או שווה ערך במטבע מקומי לכל נסיעה ולא יותר מאשר  12פעמים בשנה."}, {"p": 191, "t": "אם האירוח כולל הזמנה לארוחה יש לקזז מהעובד את דמי הכלכלה בגין ארוחה זו. .2ממונה זמני א .ממונה זמני אשר קצובת הייצוג שלו נמוכה ממחצית קצובת הייצוג של ראש הנציגות אותו הוא מחליף ,יפנה לחשב המשרד בבקשה להסיט את קצובת הייצוג מהממונה הקבוע לממונה הזמני ."}, {"p": 191, "t": "ב .מובהר כי בתקופה זו ,הממונה הקבוע אינו זכאי לדמי ייצוג כלל . ג .בכל מקרה ,ממונה זמני לא יהיה זכאי לקצובת הייצוג הקבועה שקיבל טרם מינויו כממונה זמני. .3קבלת פנים בסיום השירות א .ראש נציגות המסיים את שירותו רשאי לבקש תקציב מיוחד לעריכת קבלת פנים לסיום שירותו."}, {"p": 191, "t": "ב .חשב המשרד רשאי לאשר את הבקשה בכפוף לקבלת פנייה המפרטת את מספר המוזמנים ועלות האירוע . ג .ההשתתפות באירוע לא תעלה על גובה קצובת ייצוג חודשית אחת ותוחזרנה רק כנגד קבלות."}, {"p": 191, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 192, "t": "פרק מס'  – 21תנאי שירות ייחודיים לר' נציגות/נספחות כללי: בכל מקום במסמך זה ,שבו מצוין המונח\" :מנהל כ\"א  /קצ\"מ הנציגות\" ,הכוונה היא לגורם המטפל במנהלות השליחים והעובדים (בנספחויות הקטנות ,יהא זה הנספח עצמו או עובד האית\"ן האחראי על הניהול הכספי של הנספחות)."}, {"p": 192, "t": "ראשי משלחות ונספחי הגנה (להלן\" :ר' נציגות\") ,זכאים לתנאי שירות ייחודיים מתוקף תפקידם ומעמדם. דירת ראש נציגות .1ראש נציגות יתגורר ב\"דירת ראש נציגות\" .הדירה מיועדת לתת מענה לצרכי הייצוג והאירוח ,הנדרשים מאופי תפקידו של ראש הנציגות .בעת בחירת הדירה ,יושם דגש על ייצוגיותה והתאמתה לאירוח."}, {"p": 192, "t": ".2ר' היחידה למשאבי אנוש ומנהל בחו\"ל ,תקבע לר' הנציגות מסגרת תקציבית לשכירת הדירה .חריגה מהמסגרת שנקבעה ,מחייבת אישור חשב המשרד. במקרה שיש לשלם לבעל הדירה שכ\"ד מראש ,יש לקבל על-כך אישור מר' היחידה למשאבי אנוש ומנהל בחו\"ל (לפני חתימת החוזה)."}, {"p": 192, "t": "נושאים שיש לקחת בחשבון בעת שכירת דירת ראש נציגות .1עמידה במסגרת התקציבית :יש לאתר דירה  /בית העומדים במסגרת התקציבית שהוקצתה .במקרים חריגים ,יש לפנות לר' היחידה למשאבי אנוש ומנהל בחו\"ל ,מראש וטרם חתימת החוזה ,לקבלת אישור."}, {"p": 192, "t": "א .גודל הדירה :גודל הדירה יהיה תואם את מספר בני המשפחה המצטרפים לשליחות בהתאם לאסמכתא.מספר החדרים בדירת ר' הנציגות יקבע לפי הקריטריונים הבאים חדר קבלת אורחים לרבות פינת אוכל."}, {"p": 192, "t": "ב .חדר שינה להורים. ג .חדר שינה לכל שני ילדים ד .כשמדובר בילדים ממינים שונים ,זכאי ילד לחדר נפרד ,אם גילו מעל .10 ה .כשמדובר בילדים בני אותו מין ,זכאי ילד לחדר נפרד ,אם אחד מהילדים הינו מעל גיל .10 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 193, "t": "ו .מטבח. .2תיקונים בדירה :יש לבצע בדיקה מקיפה של הדירה ולבקש לצרף לחוזה רשימת פגמים או נזקים המצויים בה ,על-מנת שבתום תקופת השכירות ,בעל הבית לא ישית עלות בדירה)."}, {"p": 193, "t": "הפגמים את לצלם (מומלץ המשרד על התיקונים תיקונים בדירה ,הנובעים מבלאי עקב שימוש סביר ,יהיו ע\"ח בעל הדירה (צנרת ,חשמל, מבנה) .יש להגדיר בחוזה פרק זמן מינימאלי ,שבו מתחייב בעל הדירה לבצע התיקונים ולפרט נוהל במקרה של תיקון דחוף ,כגון פיצוץ צנרת ,שבו יהיה רשאי המשרד לבצע התיקון ולהגיש לבעל הדירה קבלה.יש לשאוף כי בעל הדירה יבטח את הדירה (ביטוח מבנה)."}, {"p": 193, "t": ".3היבטים ביטחוניים בשכירת דירה: יש לקבל תדרוך מקב\"ט השגרירות  /הקונסוליה לגבי הנחיות ביטחון ייחודיות: א .אין לחתום על חוזה דירה ללא קבלת אישור ביטחוני. ב .הדירה תהייה בבית מגורים לא קומת קרקע או קומת גג."}, {"p": 193, "t": "ג .לא תהיה אפשרויות הגעה לפתחי הדירה מדירות סמוכות ,גגות סמוכים או בעזרת מתקנים חיצוניים כגון :סולם ,צנרת ,עצים גבוהים וכו'. ד .עדיפות לדירה הנמצאת בבניין בו קיים פיקוח של שוער המסנן את הנכנסים."}, {"p": 193, "t": "ה .עדיפות לדירה בבניין בו מתגוררים אנשים קבועים ואין בו משרדים ציבוריים המאפשרים לכל אדם להסתובב במקום באופן חופשי. ו .תועדף חניית רכב בחניה סגורה של הבניין. ז .עדיפות לדירה בה דלת כניסה מאסיבית."}, {"p": 193, "t": "ח .הקב\"ט יוודא כי אזור המגורים איננו בעייתי מבחינה פלילית ואופי האוכלוסייה במקום (קרבה למסגד ,מרכז תרבות של בני מיעוטים ,שגרירות של אחת ממדינות ערב וכו'). ט .יש לבדוק מיהם השכנים .האם מתגוררים בבניין בני מיעוטים ,במקומות בהן ניתן (דרך שמות בתיבת דואר דלתות וכו)."}, {"p": 193, "t": "י .ככלל לא יאושר בית קרקעי ,אלא במקומות בהם אין ברירה אחרת .במקרים חריגים תועבר בקשה לאישור בית קרקעי לגורמי מטה בארץ. .4דרישות נוספות מבעל הדירה א .מומלץ לדרוש מבעל הדירה חיבור לכבלים ,קו טלפון נוסף לאינטרנט."}, {"p": 193, "t": "ב .בבית צמוד קרקע ,מומלץ לנסות להטיל על בעל הדירה עלות אחזקה שוטפת לגינה ,על-חשבונו. .5ביטוח דירת ר' נציגות א .הנציגות אינה נדרשת לרכוש ביטוח מבנה (היה וסרב בעל הדירה לבצע זאת) או ביטוח לתכולת ציוד המשרד (אינוונטר) או ביטוח צד ג' .במקרה של נזק חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 194, "t": "סביר אשר המשרד או השליח ומשפחתו אחראים בגינו על פי דין ,יישא המשרד בנזק מתקציבו. ב .ביטוח לרכושו הפרטי של ר' הנציגות בדירת ר' הנציגות – ייעשה על חשבונו של ר' הנציגות."}, {"p": 194, "t": ".6תשלום שכר הדירה והוצאות הבית דמי השכירות ,הוצאות אחזקת הדירה (חשמל ,מים ,מסים ,גז וכד') יכוסו מכתובת תקציבית \"שכירויות\" של הנציגות .המשרד מממן את כל הוצאות הטלפון בקו הטלפון הנייח בדירת ר' הנציגות (למעט שיחות טלפון פרטיות בינלאומיות) וכן חיבור לאינטרנט."}, {"p": 194, "t": "כמו כן ,מממן המשרד עלות חיבור לכבלים בדירת ר' הנציגות ,למעט אם עלות זו לא חלה במסגרת החוזה על בעל הדירה .במקרה זה ,יממן המשרד עלות חבילת כבלים בסיסית כולל ערוץ ילדים ,אם נדרש ,ו\"ערוץ ישראלי\" במידה וקיים .ר' נציגות המבקש להרחיב את החבילה מעבר לאמור לעיל ,ישלם את העלות הנוספת מכספו."}, {"p": 194, "t": "תכולת הדירה – \"אינוונטר\" תכולת דירת ר' הנציגות (\"אינוונטר\") ,כוללת ריהוט וציוד בבעלות משהב\"ט ובבעלות פרטית. התכולה בבעלות משהב\"ט משמשת את ר' הנציגות במסגרת תפקידו הייצוגי."}, {"p": 194, "t": "התכולה שבבעלות פרטית משמשת את ר' הנציגות ומשפחתו ,לשימוש פרטי ואין לה קשר עם תפקידו הייצוגי של הנספח. ייעודו של ציוד האינוונטר בבית ר' הנציגות ,הינו לתמוך בכל הקשור לייצוג ואירוח."}, {"p": 194, "t": "כל ציוד אחר ,גם אם קיים באינוונטר הנוכחי ,לא יוחלף ולא יחודש. להלן רשימת אינוונטר תקנית ,שאמורה להימצא בדירת ר' נציגות: יצוין כי רשימה זו מהווה מסגרת כללית לציוד המשרד בדירת ר' נציגות ואין חובה שכל פריטי הרשימה יימצאו בה ,הנ\"ל בהתאם לצורכי הדירה ,התאמה למבנה וכד'."}, {"p": 194, "t": "מבואה א .מראה ב .מתקן לתליית מעילים ג .קולבים למעילים ד .מתקן למטריות ה .שטיחון כניסה סלון א .ספות (שני מושבים ו 3 -מושבים) חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 195, "t": "ב .כורסאות ,כהשלמה לפינת הישיבה שבסעיף א' ג .שולחן נמוך לפינת הישיבה ד .שטיח ה .מנורות לפי הצורך (חללים חשוכים) ו .תמונות ז .ווילונות לפי הצורך פינת אוכל לאורחים א .שולחן אוכל ל  12 -איש ,כולל כיסאות תואמים ב .ארון ויטרינה או מזנון סגור לכלי אוכל ,המיועדים לכלי אירוח רשמי ג .שטיח ד .סט כלי אוכל מלא ל 12-איש (הכולל צלחות וכוסות בגדלים שונים ,סכו\"מ וכלי"}, {"p": 195, "t": "הגשה) ה .מפות בד המתאימות לגודל השולחן ומפיות בד תואמות מטבח א .מקרר ב .מקפיא עמוק ג .תנור בישול ואפיה (או כיריים ותנור אפיה נפרדים) ד .מיקרוגל ה .מדיח כלים ו .מיקסר ז .מכונת קפה ח .מעבד מזון ט .שולחן עבודה  -אם איננו כלול בריהוט הצמוד למטבח רכישת כל פריט ציוד נוסף  /אחר ,תיעשה לאחר קבלת אישור מראש מהיחידה למשאבי אנוש ומנהל בחו\"ל המשרד קבע תקופות מינימום של  10שנים להחלפת פרטי ציוד וריהוט."}, {"p": 195, "t": "ציוד אחר יוחלף לפי העניין. החלפת ציוד וריהוט החלפת ציוד וריהוט בסכום של עד  ,500$תבוצע לפי העניין בכפוף ליתרה א. התקציבית בכתובת תקציבית \"רכישות שוטפות\" או \"שכירויות\" של הנציגות."}, {"p": 195, "t": "יש לתעד  3הצעות מחיר ולהעבירן לאישור החשב האזורי בטרם רכישה. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 196, "t": "כל החלפת ציוד וריהוט מעל סכום זה מחייבת אישור ר' היחידה למשאבי אנוש ב. ומנהל בחו\"ל ושיתוף החשב האזורי בתהליך. כל פריט באינוונטר אשר יצא מכלל שימוש לחלוטין ואשר תמורתו אושר פריט ג."}, {"p": 196, "t": "אחר ,יימכר במחיר הגבוה ביותר שניתן לקבל בתנאי השוק של זמן המכירה. הסכום ,שיתקבל יוכנס לרישומים החשבונאים עפ\"י הוראות אכ\"ס. כאשר נוצר מצב שלא ניתן למכור פריט מסיבות של ביטחון או מסיבות אחרות, ד."}, {"p": 196, "t": "תבוצע \"השמדה\" של פריט .על-פי הכללים הבאים: )1בנציגות תמונה \"ועדה לגריעת אינוונטר\" אשר תאשר ביצוע ההשמדה. )2הרכב הוועדה :ר' הנציגות ,איש כספים/מנהלה וגורם נוסף מהשגרירות (או מהקונסוליה) .פרוטוקול והמלצת הוועדה יועברו לר' היחידה למשאבי אנוש ומנהל בחו\"ל להחלטה סופית."}, {"p": 196, "t": "ניהול האינוונטר אינוונטר דירת ר' הנציגות יתועד ברשימות אינוונטר בהתאם להנחיית אכ\"ס .הרשימות יועברו לחשב האזורי האחראי על הנציגות במסגרת הדיווחים הכספים החודשיים .רישום ובקרת ציוד האינוונטר יבוצעו כלהלן:"}, {"p": 196, "t": "בעת רכישת פריט חדש .1פריט שנרכש בעלות הנמוכה מ ,150$-לא יירשם ברשימת האינוונטר ,למעט אם קיבלר' הנציגות הנחיה אחרת מהחשב האזורי בהתבסס על יוקר המחיה במדינת השירות."}, {"p": 196, "t": ".2פריט שנרכש ועלותו מעל  150$יבוצע רישום ברשימת האינוונטר ,שיכלול את הגדרת הפריט ותאור קצר ומזהה שלו (תוצרת ,מידות ,צבע וכד') .בנוסף יש לרשום את מועד הרכישה של הפריט והמחיר ששולם עבורו .מומלץ לצרף תמונה של הפריט לצורך הקלה בזיהויו."}, {"p": 196, "t": ".3ר' הנציגות אחראי לאישור ביצוע הרישום והדיווח. ספירת מלאי אחת לשנה ,בסוף שנת הכספים ,יספר המלאי ע\"י צוות כמפורט: .1במשלחת -נציג מנהלה/כ\"א ונציג החשב. .2בנספחות -הנספח עצמו ,או עוזר מטעמו .כ\"כ יש לשאוף כי יהיה נוכח בספירה גם נציג מהשגרירות הישראלית במקום."}, {"p": 196, "t": ".3תוצאות הספירה תרשמנה בדו\"ח האינוונטר הממוחשב .הדו\"ח ישלח לחשב האזורי. בעת חילופי ר' נציגות .1בעת חילופי ר' נציגות יש לבצע ספירת מלאי לפי דו\"ח האינוונטר ולשלוח אותו לחשב האזורי."}, {"p": 196, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 197, "t": ".2בכל ספירת מלאי יוקפד על השוואת הנתונים למספרם ומצבם בדו\"ח שקדם למועד ספירת המלאי ,תוך רישום ההפרשים  -אם היו. .3חברי הצוות יחתמו על הדו\"ח המעודכן. .4אם יתגלה חוסר בפריט מסוים ,יש לדווח על כך מידית לחשב האזורי ולר' היחידה למשאבי אנוש ומנהל בחו\"ל ולפעול לפי הנחייתם."}, {"p": 197, "t": "גריעת פריטים מרשימת המלאי כל פריט מהמלאי שיימכר או יושמד באישור כאמור לעיל ,יגרע מרשימות המלאי תוך ציון סיבת הגריעה ,התאריך והאישור למכירתו או להשמדתו .כמו כן יצורף פרוטוקול הוועדה לגריעת אינוונטר."}, {"p": 197, "t": "תוספות כספיות לראשי הנציגות .1דמי ייצוג א .ר' נציגות זכאי לדמי ייצוג בהתאם לתפקידו .ראה הסבר והרחבה בפרק דמי ייצוג וקצובת אחזקת בית ב .לקצובת אחזקת הבית זכאים ר' המשלחות בניו יורק ובברלין וכן נספחי ההגנה בוושינגטון ,הודו וסינגפור .הנ\"ל ע\"פ קביעת משרד האוצר ובעקבות החלטת הממשלה משנת  2010על מעמד ר' הנציגויות של מדינת ישראל בעולם."}, {"p": 197, "t": "ג .ר' הנציגויות כמפורט לעיל ,זכאים לדמי אחזקת בית בהתאם ל\"נוהל הייצוגיים\" החדש של משרד האוצר. .2אחזקה שוטפת של דירת ר' הנציגות (מתייחס לכל ר' הנציגויות). .3שכרם של עובדי הבית (עוזרת ,גננים) ,הוצאות כלכלתם וכן חומרי ניקוי  -ישולמו ע\"י ר' הנציגות ועל חשבונו.למרות זאת ,מכיר המשרד בצורך בניקיון בית /דירת ר' נציגות לאחר שמתקיים אירוח רב משתתפים .במקרה דנן ,יתבצע הניקיון לאחר קיום האירוח .הניקיון"}, {"p": 197, "t": "יכלול את החדרים והאזורים ששימשו לאירוח בלבד (לא כולל חדרי שינה) .ההחזר הכספי עבור הניקיון ייעשה כברירת מחדל ,תמורת קבלה .במקרה בו לא ניתן להמציא קבלה, יעביר ר' הנציגות לחשב האזורי הצהרה על העלות אותה שילם בגין הניקיון."}, {"p": 197, "t": "א .הוצאות אחזקה קבועות (חשמל ,מים ,גז ,חימום ,קירור וכד') תשולמנה במלואן מכתובת תקציבית \"שכירויות\". ב .מודגש כי חיוב הכתובת התקציבית \"שכירויות\" ,בגין אחזקת בית יכול להיעשות אך ורק בגין הוצאות האחזקה הקבועות כאמור לעיל."}, {"p": 197, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 198, "t": "רכב ר' נציגות .1ר' נציגות זכאי לרכב צמוד (שירות) בעת שירותו בחו\"ל .הרכב יירשם כרכוש מדינת ישראל כחלק מאינוונטר הנציגות .הרכב יבוטח במקום השירות בביטוח מקיף כנגד כל הסיכונים."}, {"p": 198, "t": ".2בתחילת השליחות ,בתקופה שבה ר' הנציגות שוהה במקום השירות במקביל לר' הנציגות אותו הוא עומד להחליף ,יקבל ר' הנציגות החדש רכב שכור ע\"ח המשרד. .3ברכב יהיו רשאים לנהוג:"}, {"p": 198, "t": "א .ראש הנציגות ובלבד שיש לו רישיון נהיגה מקומי בתוקף. ב .נהג הנציגות (אם קיים בתקן). .4תנאים לנהיגת בן משפחה ברכב: א .ראש הנציגות חתום על טופס \"התחייבות לצורך קבלת רכב ממשלתי צמוד\" הכולל תצהיר בדבר נהיגת בני משפחה."}, {"p": 198, "t": "ב .לנוהג רישיון נהיגה בתוקף ,ובעל ותק של שנתיים לכל הפחות. ג .גילו של הנוהג הינו מעל .21 ד .הנוהג לא ביצע ברכב ממשלתי תאונה חמורה או תאונה שנייה בפרק זמן של שנתיים ,באשר להן נקבע על ידי קצין הבטיחות של מינהל הרכב ובאישור מנהל מינהל הרכב ,כי התאונות נגרמו באחריותו."}, {"p": 198, "t": "ה .מסגרת הזמנים המותרת לנהיגת בני משפחה: )1בנוכחות ר' הנציגות. )2ללא נוכחות ר' הנציגות – בשעות שמחוץ לעבודה (החל מ 16:30ועד 7:00 בבוקר למחרת). )3במהלך סופי שבוע ובימי חג ומועד ובלבד שראש הנציגות אכן שוהה בחופשה במועדים אלו."}, {"p": 198, "t": ")4במהלך שהות ראש הנציגות בימי חופשה. )5במהלך שהות ראש הנציגות בימי מחלה. )6במהלך שהות ראש הנציגות בחופשת אבל. )7במהלך שהות ראש הנציגות בחוץ לארץ בתפקיד. )8השתתפות עצמית בגין תאונה ברכב הנציגות בעת נהיגת בן משפחה תחול באופן מלא על ראש הנציגות."}, {"p": 198, "t": "ו .דו\"חות וקנסות שיוטלו על רכב ראש הנציגות יוסבו על שם ראש הנציגות. .5רכישת רכב ר' נציגות או החלפתו תיעשה באישור ראש היחידה למשאבי אנוש ומינהל בחו\"ל ,ר' היחידה לפרוייקטים ובקרת תהליכים בגית\"ם וחשב המשרד ולמטרה זו יועמד תקציב ייעודי ע\"י יחידת התקציבים במשהב\"ת – אג\"ת א .המשרד מאשר בדר\"כ רכישת רכב ברמת אבזור סטנדרטית."}, {"p": 198, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 199, "t": "ב .אם קיימת דרישת ביטחון לפיה ר' הנציגות מחויב במאבטח צמוד ונהג ,יירכש רכב בעל  7מקומות ישיבה. ג .סוג הרכב והדגם ,יאושרו בכפוף לאישור הקב\"ט המקומי על כך שהרכב אינו בולט בייחודיותו."}, {"p": 199, "t": "ד .הרכב יירכש בשיטת הליסינג או ברכישה מלאה ,בהתאם למבחן כדאיות כלכלית וביצוע תחשיב לגובה זקיפת ההטבה שיהיה על ראש הנציגות לשלם בשכרו בגין השימוש ברכב .כל זאת ,בשיתוף החשב האזורי."}, {"p": 199, "t": "ה .ר' נציגות ,יחוייב במס עבור השימוש ברכב בהתאם לכללי המיסוי על שכר חו\"ל. ו. הוצאות שוטפות ,דלק ,תיקונים ,ביטוח ,רישוי וכד'  -יכוסו מכתובת תקציבית \"רכישות שוטפות של הנציגות."}, {"p": 199, "t": "ז .לטיפולים/תיקונים חריגים ברכב ר' הנציגות ,להם לא ניתן לתת מענה במסגרת התקציב .השוטף מפאת עלותם הגבוהה ,יאושר תקציב ייעודי ע\"י ר' היחידה למשאבי אנוש ומנהל בחו\"ל לאחר שראש הנציגות/הנספחות יוודא קיום תקציב ייעודי ע\"י יח' התקציבים במשהב\"ט."}, {"p": 199, "t": "ח .ככלל יוחלף רכב ר' נציגות אחת ל  5 -עד  6שנים ,בהתאם להחלטת המשרד ובכפוף למצב הרכב ודרישות הביטחון. כללים וזכאויות לראש נציגות האמון על מדינות נוספות (מדינות אמנה) הצטרפות הרעיה לנסיעה למדינת אמנה המשרד מכיר בכך שלרעיה תפקיד (לא רשמי) לצד ר' הנציגות וכי הצטרפותה לנסיעותיו למדינות האמנה היא צורך מקצועי ,המשרת את צרכי המערכת."}, {"p": 199, "t": "המסגרת המאושרת להצטרפות הרעיות לנסיעות למדינות אמנה תהיה כמפורט להלן: .1אירוע רשמי הנערך ע\"י השגרירות לציון יום העצמאות של מדינת ישראל – מאושרת נסיעה אחת בשליחות של הרעיה ולא יותר מלשתי מדינות אמנה."}, {"p": 199, "t": ".2סיורי נספחים – אם קיימת עלות כספית בהצטרפות הרעיה לסיור ,תאושר הצטרפותה פעם אחת בשליחות של  3שנים ופעמיים בשליחות של ארבע שנים ,ללא תלות במספר מדינות האמנה עליהן אמון הנספח .לא מאושרת הצטרפות ילדים על חשבון המשרד לנסיעות סיורי נספחים .במקרה של סיורי נספחים בתוך המדינה וככל שקיימת עלות להצטרפות הרעיה והילדים ייבחן הנושא לגופו של עניין למול ר' היחידה למשאבי אנוש"}, {"p": 199, "t": "ומנהל בחו\"ל. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 200, "t": ".3הוצאות ייצוג ואירוח במדינות אמנה נספח הגנה ,המואמן למדינות נוספות ,זכאי להחזר הוצאות ואירוח בכל נסיעה בתפקיד למדינות האמנה בכפוף לכללים שבנוהל הייצוגים .הוצאות אלה הן בנוסף למסגרת הייצוג הקבועה של הנספח ותוחזרנה כנגד קבלות בלבד ,על פי ההוצאה הממשית ולא יותר מ 150$-או שווה ערך במטבע מקומי לכל נסיעה ולא יותר מ 12-פעמים בשנה."}, {"p": 200, "t": "אם האירוח כולל הזמנה לארוחה ,תקוזז לנספח ארוחה זו מדמי השהייה להם זכאי בנסיעתו למדינת האמנה. אירועים רבי משתתפים כלל האירועים השוטפים ימומנו מתוך מסגרת התקציב האישי לדמי הייצוג ואחזקת הבית של הנספח."}, {"p": 200, "t": "מעבר לכך ,הוגדרו מספר אירועים בשנה שימומנו ע\"ח תקציב המשרד כתקציב ייעודי לטובת \"אירוח רב משתתפים\" כלהלן: .1יום הזיכרון לחללי מערכות ישראל ופעולות האיבה – אירוע שהובלתו הינה באחריות הנציגות."}, {"p": 200, "t": ".2השתתפות בעלות אירוע יום העצמאות שעורכת השגרירות. .3אירוח אירועים רבי משתתפים בבית ראש הנציגות או במתקני אירוח חיצוניים, המאופיינים על בסיס הפרמטרים הבאים: א .הנציגות תקיים עד  2אירועים גדולים בשנה."}, {"p": 200, "t": "ב .בכל אירוע ישתתפו לפחות  20משתתפים זרים. ג .עדיפות לקיום אירוע בבית ראש הנציגות. ד .האירועים יחוברו למועדים על פני השנה ,כגון חגי ישראל ,חגים מקומיים, פרידה מראש נציגות יוצא וקבלת פנים לראש נציגות נכנס וכד'."}, {"p": 200, "t": "ה .כלל האירועים רבי המשתתפים ,יכללו ע\"י הנציגות בבקשה לתקציב המוגשת לקראת העמדת התקציב השנתי ובמסגרת תוכנית העבודה ויתומחרו בהערכה כללית לצורך השריון התקציבי .כחלק מההכנות לאירוע ,באחריות הנציגות לאשר מבעוד מועד את העלויות למול החשב האזורי."}, {"p": 200, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 201, "t": "פרק  - 22טפסים /מסמכים חיוניים שימסרו לשליח במסגרת התדרוך .1אישור שליחות - א .אישור בו יפורטו מדינת השירות ,תקופת השירות . ב .אישור השליחות הינו מסמך רשמי לכל דבר ועניין והינכם רשאים להשתמש בו ולהציגו בכל דרישה ו/או בירור לגבי יציאתכם לשליחות ,ניתן לצלמו למס' עותקים עפ\"י הנדרש."}, {"p": 201, "t": "ג .אישור השליחות ניתן לתקופת האסמכתא – מינוי לתפקיד ללא תקופת האופציה להארכה. לשליחי המשרד – תקופת האסמכתא הינה ל 3 -שנים ,הארכה לתקופה נוספת (שנה רביעית) ניתנת בכפוף לאישור מנכ\"ל."}, {"p": 201, "t": "לשליחי צה\"ל  -הארכה לשנה נוספת (שלישית) ניתנת בכפוף לאישור הרמטכ\"ל. לשליחי צה\"ל לומדים האסמכתא הינה לתקופה של שנת הלימודים ( 12חודשים) או יותר בהתאם לתוכנית הלימודים."}, {"p": 201, "t": "ד .האישור הינו לצורך הצגתו למוסדות רשמיים כגון; בתי ספר ,מקום עבודה של בן/בת הזוג וכיוצ\"ב. .2טופס \"וויתור על סודיות רפואית\" לפני היציאה לשליחות ,יחתמו השליח ובן/ת הזוג על טופס \"וויתור על סודיות רפואית\" על שמם ועבור ילדיהם ,וימלאו שאלונים רפואיים, אותם יקבלו במהלך התדרוך ביחידה למשאבי אנוש ומנהל בחו\"ל או אצל קצין הנסיעות הזרועי."}, {"p": 201, "t": "המידע הרפואי הנמסר במסגרת השאלונים ,מועבר לרופא האמון של המשרד ונשמר בסודיות .יש הכרח במידע זה לשם סיוע בבעיות רפואיות ,שעלולות להתעורר במהלך השליחות או לצורך טיפול בבעיות רפואיות שניתן לטפל בהן כבר בארץ."}, {"p": 201, "t": ".3טופס הפניה ליחידות המשרד לבעלי תפקידים ,לצורך תיאום פגישת תדרוך ע\"י השליח (נציגת יח' השכר ,נציגת אכס בנושא ניהול כספי הנספחות/ביטוח מטענים ,נציגת מנה\"ר הדרכה לגבי שינוע המטען בהתאם להרכב המשפחתי ,נציג תקשו\"ב לגבי ניהול כספי דמי הייצוג במערכות מחשוב ,קב\"ט לצורך תדרוך ביטחוני לקראת שליחות)."}, {"p": 201, "t": ".4טופס הכשר ביטחוני למילוי בן/בת הזוג אשר מעוניין לעבוד בשגרירות כאית\"ן . מובהר כי ,אין לראות באמור כהתחייבות להעסקת בן/בת הזוג במסגרת השגרירות או כל מוסד/חברה וכי יתכן ובן/בת הזוג לא יעבוד כלל במהלך השירות."}, {"p": 201, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 202, "t": "לבן/בת הזוג שמורה הזכות לאתר עבודה באופן עצמאי ובלבד שהנושא יאושר ע\"י קב\"ט השגרירות והיועמ\"ש במקרה של ניגוד עניינים. .5הפניה ללימוד השפה לכל בני המשפחה בביה\"ס אשר נמצא בהתקשרות עם המשרד/צה\"ל בכל הקשור ללימודי שפה."}, {"p": 202, "t": ".6לראש נציגות/נספחות א .נוהל דמי ייצוג  -מידע על מסגרת דמי ייצוג כולל רכישת תשורות. ב .רשימת אינוונטר (ציוד ,ריהוט הנמצא בביתו והשייך למשרד) חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 203, "t": "טלפונים חיוניים במשהב\"ט משהב\"ט /אמ\"ש -היחידה למשאבי אנוש ומינהל בחו\"ל שם תפקיד טלפון נייד קמי אוקונסקי ר' היחידה למשאבי אנוש ומנהל בחו\"ל Kamy_okonski@mod.gov.il Stephanie_olevsky@mod.gov.il אריאל ספירו ראש המערכה למשא\"נ ומינהל בחו\"ל סטודנטית לסיוע ביח' משאבי אנוש ומינהל בחו''ל נגדת שליחי צה\"ל Michal_shiloch@mod.gov.il Ariel_spiro@mod.gov.il נועה שטרן"}, {"p": 203, "t": "מוריה איבגי מיתר תורג'מן לשכת משא\"נ ומינהל בחו\"ל שם תפקיד ר' תחום הסדרי נסיעות חו\"ל מיכל שלוח סטפני אולבסקי כתובת אי -מייל משרד משהב\"ט\\ אכ\"ס טלי גרינפלד שם נגה אטלס שם תמר מזרחי נחמה פיירוזמן שם תפקיד מנמ\"ח תביעות תפקיד מנמ\"ח שכר חו\"ל ר' מע' כספים נספחויות ונציגויות טלפון נייד משרד avital_greenfeld@mod.gov.il משהב\"ט\\ היועמ\"ש למעהב\"ט משרד טלפון נייד משהב\"ט\\ אכ\"ס"}, {"p": 203, "t": "משרד טלפון נייד כתובת אי -מייל tamar_mizrachi@mod.gov.il כתובת אי -מייל Noga_A@mod.gov.il Nechama_firouzman@mod.gov.il 03-6976803 מנה\"ר\\ יחידת הממונה על שינוע מכס משרד טלפון נייד תפקיד ר' תחום משגורי פרט יבוא יצוא שם תפקיד טלפון נייד משרד דודי שדה מב\"ט איזורי בכיר נאוה ליברמן כתובת אי -מייל כתובת אי -מייל nava_liberman@mod.gov.il אבטחת מידע כתובת אי -מייל"}, {"p": 203, "t": "DAVID_SADE@mod.gov.il חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 204, "t": "טלפונים קציני נסיעות זרועיים  /אגפיים אגפים וזרועות דרגה ושם טלפון הגדרת תפקיד אגאס/קש\"ח רס\"ן חן שלמה רמ\"ד מעבר חו\"ל חה\"א רס\"ן עינב שף רמ\"ד חו\"ל מז\"י סא\"ל הילה בויים רע\"ן קש\"ח ז\"י רס\"ן אורנית אביטן רמ\"ד פרוטוקול קש\"ח פקע\"ר סגן אורי ניר קמ\"ד פקע\"ר/קש\"ח אמ\"ן מיטל עמרני רמ\"ד כספים וחשבונות- אחראית נסיעות חו\"ל חה\"י סא\"ל מורן בלחנס רע\"ן תב\"ל פרקליטות רס\"ן ארז רג'ואן"}, {"p": 204, "t": "רמ\"ד חו\"ל/פרקליטות צבאית צבאית מפא\"ת ליאת שאול מנת\"ק דליה ביתן ע' בכיר לניהול נסיעות מו\"פ לחו\"ל קמ\"ב ארגון חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 205, "t": "מילון מונחים וקיצורים •אכ\"ס :אגף הכספים במשרד הביטחון. •אסמכתא :מסמך רשמי ממוחשב המכיל נתונים לגבי פרטי השליח ,פרטי הנסיעה והכתובת התקציבית. •אש\"ל :אוכל ,שתיה ,לינה."}, {"p": 205, "t": "•ביקור הורים :ביקור ילדים שנשארו בארץ אצל הוריהם בחו\"ל. •בונוס :תוספת הוצאות נלוות לשכר דירה לשליח שגובה שכ\"ד שלו נמוך מהקצובה שאושרה לו ובתנאי שלא קבל תוספת ייצוגית."}, {"p": 205, "t": "•בן  -זוג :בן ,או בת זוג של שליח/ה ,הנלווה /הנלוות אליו/אליה לשליחותו/שליחותה בחוץ לארץ. •דולר :דולר אמריקאי (אלא אם צוין אחרת). •הורה :אב או אם של שליח או של בן/בת זוגו."}, {"p": 205, "t": "•הורה נלווה :הורה ,שבשל נסיבות מיוחדות ,העובד מבקש לצרפו למקום שירותו בחו\"ל. •הורה סמוך :הורה סמוך על שולחן ילדו .הורה ,שהעובד הינו ילדו היחיד ואין לו הכנסות למעט קצבת זקנה."}, {"p": 205, "t": "•המ\"ב :הוראת משרד הביטחון •המשרד :משרד הביטחון. •ועדה בין-משרדית :ועדה בראשות הממונה על השכר באוצר הקובעת את תנאי השכר והשירות של שליחי המדינה בחו\"ל. •ועדת חריגים :ועדה בראשותו של סמנכ\"ל ור' אגף משאבי אנוש ,הדנה בבעיות ת\"ש חריגות של שליחים ,שאינם מוצאות פתרון בהוראות."}, {"p": 205, "t": "•חופשת הבראה :תשלום הוצאות נסיעה לשם הבראה במדינות או בערים בהן תנאי השירות קשים במיוחד .חופשת הבראה נקראת גם \"חופשת הבראה\". •חל\"ד :חופשת לידה. •חופשת מולדת :תשלום הוצאות נסיעה לחופשה בישראל."}, {"p": 205, "t": "•חופשת מחלה :חופשה ,לה העובד זכאי כאשר הוא סובל ממחלה או מצב בריאותי לקוי, הנוטל ממנו את כושר העבודה. •חופשה פרטית :חופשה המגיעה לשליח במסגרת ימי החופשה העומדים לזכותו."}, {"p": 205, "t": "•חינוך עברי משלים :השתתפות כספית של המשרד בהוצאות בגין לימוד ילדים מגיל טרום חובה בנושאי עברית ,יהדות היסטוריה וכד'. חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 206, "t": "•מטען :חפצי שליח ובני משפחתו המועברים ממקום מגוריו בארץ למקום שירותו בחו\"ל. • מ\"ק :מטר מעוקב. •מקום עבודה :העיר ,בה נמצאת הנציגות או מקום עבודתו הקבוע של השליח בחו\"ל."}, {"p": 206, "t": "•נציגות :מקום העבודה בחו\"ל  -אחת ממשלחות או נספחויות ההגנה של משרד הביטחון בחו\"ל. •נש\"מ :נציבות שירות המדינה. •סיום תפקיד :היום האחרון לתפקידו של השליח בחו\"ל .אין זה בהכרח היום האחרון לשהותו במקום השירות ואין זה בהכרח היום האחרון לשכר חו\"ל."}, {"p": 206, "t": "• עמ\"י :עובד מקומי ישראלי .סוג ההעסקה שהיה תקף בנציגויות בחו\"ל עד לשנת .2018 •רמ\"ע :רגל מעוקב. •שות\"ש :קובץ הוראות שכר ותנאי שירות בחו\"ל ,של הועדה הבין-משרדית. •שליח :מי ,שמועסק על  -ידי המדינה על  -פי כתב מינוי ,או על  -פי חוזה מיוחד ,לרבות :חייל בשירות קבע בצה\"ל ,ואשר המדינה שולחת לחוץ לארץ למלא תפקיד מטעמה."}, {"p": 206, "t": "•שליחות/שירות :נסיעת עובד לחו\"ל בלווי משפחתו (אם הוא בעל משפחה) ,לצורך מילוי תפקיד מטעם המדינה. •שנת שירות  /שליחות :תקופה של שנה שלמה מיום יציאת השליח לחו\"ל. • שנה קלנדארית :שנת עבודה המתחילה ב 1לינואר ומסתיימת ב 31לדצמבר באותה שנה."}, {"p": 206, "t": "•תחילת תפקיד :היום שבו השליח טס למדינת השירות (טיסה ארוכה). •  : ECAחברה בינלאומית המספקת שירותי מידע לבניית מנגנוני שכר בחו\"ל. שות\"ש – הגדרות -מילון מונחים .1אחראי – סמנכ\"ל וראש אגף משאבי אנוש או מי מטעמו."}, {"p": 206, "t": ".2בן זוג – בן או בת זוג של שליח/ה ,לרבות ידוע בציבור ,הנלווה/ית אליו/ה לשליחות מטעם המדינה בחוץ-לארץ. .3דולר – דולר אמריקאי. .4די\"פ – דואר דיפלומטי .5דיפלומט – נציג דיפלומטי ,כאמור באמנת וינה בדבר יחסים דיפלומטיים משנת  ,1961או פקיד קונסולרי כאמור באמנת וינה בדבר יחסים קונסולריים משנת  1963או בעל מעמד דומה בנציגות ישראלית לארגון בינלאומי ,שמעמדו ודרגתו אושרו על-ידי משרד החוץ."}, {"p": 206, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 207, "t": ".6הוצאות נלוות – תשלומים לאחזקת הדירה הנלווים לשכירות ,כדוגמת ארנונה /מיסים, ועד בית ,חשמל ,מים ,טלפון ,גז ,חימום ,שירותי אינטרנט וכד' ,אשר חיובם חל על העובד וששולמו על-ידו בפועל."}, {"p": 207, "t": ".7הורה – אב או אם של שליח או של בן/בת הזוג. .8הורה במשפחת אומנה – עובד שהינו הורה במשפחה שאושרה בידי מי ששר הרווחה והשירותים החברתיים הסמיכו לכך לשמש כמשפחה אומנה ,המקבל לביתו ילד שגילו אינו עולה על עשר ,למטרת אומנה ,לתקופה העולה על שישה חודשים; יום הלידה ייחשב כיום קבלת הילד לביתו של ההורה במשפחת האומנה."}, {"p": 207, "t": ".9הורה מאמץ – עובד המקבל לביתו ילד שגילו אינו עולה על עשר ,למטרת אימוץ לפי הוראות חוק אימוץ ילדים; יום הלידה ייחשב כיום קבלת הילד לביתו של ההורה המאמץ. .10הורה מיועד (הורה המקבל ילד מאם פונדקאית)– עובד המקבל למשמורתו ילד ,כהורה מיועד ,לפי הוראות סעיף  10לחוק הסכמים לנשיאת עוברים; יום הלידה ייחשב כיום שבו נולד הילד."}, {"p": 207, "t": ".11הורה סמוך – הורה סמוך על שולחן ילדו ,ואין לו הכנסות למעט קצבת זקנה. .12הוועדה הבין משרדית – הוועדה הבין-משרדית לשכר ותנאי שירות בחוץ-לארץ הקובעת את שכרם ותנאי שירותם של עובדים המועסקים בנציגויות ישראל בחוץ-לארץ :שליחים, בני זוג של שליחים ,עובדי אית\"ן וכן אזרחים זרים שנציגויות ישראל מעסיקות כעובדים מקומיים."}, {"p": 207, "t": ".13חג מקומי – חג דתי או לאומי שבו נהוג שבתון רשמי וכללי בארץ השירות .לצורך זה יש לראות רק את אותם הימים בהם סגורים כל משרדי הממשלה המקומיים ,מוסדות ציבור ותעשייה."}, {"p": 207, "t": ".14יום טוב שני של גלויות – כינוי לימים השניים של כל אחד מהחגים ,אותו חוגגים בחוץ- לארץ בלבד. .15יום מועד – הכוונה למועדי ישראל הבאים בלבד :יום א' ויום ב' של ראש השנה ,יום כיפורים ,יום א' של סוכות ,שמיני עצרת (שמחת תורה) ,יום א' ויום השביעי של פסח ,חג שבועות ויום העצמאות של מדינת ישראל."}, {"p": 207, "t": ".16יום מנוחה שבועי – וגם \"יום מועד\" – פרק הזמן המתחיל מכניסת השבת/מועד או בשעה 18:00של ערב שבת ,הכל לפי המוקדם יותר ,והמסתיים בשעה  6:00למחרת השבת/מועד. .17מבחני  I.Bאו  – A.P.בגרות בינלאומית המוכרת על ידי המועצה להשכלה גבוהה בישראל."}, {"p": 207, "t": ".18מדינה קשת שירות – מדינה מרמה  Cומעלה ,שהוועדה הבין משרדית קבעה כמדינה קשת שירות והגדירה עבורה את אורך תקופת השירות וחופשות ההבראה. .19מטען אישי נוסף – לעניין החזר הוצאות מעבר ,מטען נוסף על המטען המורשה בכרטיס הטיסה ,עד משקל של  23ק\"ג."}, {"p": 207, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 208, "t": ".20מטען בלתי מלווה – מטען בלתי מלווה להבדיל ממטען אוויר רגיל ,הוא מטען ,שכל נוסע במטוס זכאי לו ,לאחר שהוכיח כי בידו כרטיס טיסה בקו מסוים .זאת בניגוד למטען אוויר רגיל ,הנשלח לכל יעד שהוא מבלי שיהיה צמוד לכרטיס טיסה."}, {"p": 208, "t": ".21ממלא מקום ראש נציגות  -שליח אשר הוטל עליו מטעם המשרד או יחידת סמך לפעול כממלא מקום ראש הנציגות בחוץ-לארץ בהיעדרו לתקופה קצרת מועד. .22נציגות – שלוחה של משרד ממשלתי ישראלי או יחידת סמך בחוץ-לארץ."}, {"p": 208, "t": ".23קצובת לינה – ההוצאה בפועל בגין לינה הכוללת מיסים והוצאות אחרות בגין הזמנת המלון ועד לתקרה כמפורט בהודעת תכ\"ם .13.10.0.2.2 .24קצובת שהייה – קצובה הכוללת הוצאות הקשורות במילוי תפקידו הנובעות מהיעדרו של העובד מביתו ועד לתקרה כמפורט בהודעת תכ\"ם .13.10.0.2.2 .25קרוב משפחה – בן או בת זוג ,לרבות ידוע בציבור ,הורה ,הורי הורה ,בן ,בת ,אח ,אחות, גיס ,גיסה ,דוד ,דודה ,אחיין ,אחיינית ,חותנת ,חם ,חמות ,חתן ,כלה ,נכד או נכדה ,לרבות"}, {"p": 208, "t": "קרבה משפחתית חורגת או קרבה הנוצרת עקב אימוץ. .26קרוב משפחה (לעניין הוראת שות\"ש \" 1.2.9.10ימי אבל\"). א .ליהודי – אב ,אם ,בן ,בת ,אח ,אחות בעל או אישה [קרבה ראשונה]."}, {"p": 208, "t": "ב .למוסלמי ולנוצרי – אב ,אם ,בן ,בת ,אח ,אחות ,בעל או אישה [קרבה ראשונה]; סבא ,סבתא ,נכד ,נכדה ,דוד או דודה (קרובי דם ולא קרובי חיתון) [קרבה שניה]. ג .לדרוזי – אב ,אם ,בן ,בת ,סבא ,סבתא ,אח ,אחות ,נכד ,נכדה ,חותן ,חתן ,גיס, גיסה ,אחיין ,אחיינית ,דוד ,דודה ,בן-דוד ,בעל ,אישה."}, {"p": 208, "t": "\" )1בעל או אישה\" -לרבות ידוע\\ה בציבור כמשמעו בחוק שירות המדינה גמלאות (נוסח משולב) ,התש\"ל ,1970 -ס' ( 4א)(.))2()1 \" )2בן או בת\" -לרבות ילד חורג או שאומץ כדין כמשמעו כמשמעו בחוק שירות המדינה (גמלאות) [נוסח משולב] ,התש\"ל ,1970-ס' (4א)(;))2()1 https://www.nevo.co.il/law_html/law01/p221_001.htm#Seif1 \" )3אח או אחות\" -לרבות אח או אחות מצד הורה אחד בלבד .קרבה"}, {"p": 208, "t": "חורגת או בדרך אימוץ אינה נחשבת לקרבת משפחה. .27ראש נציגות – שליח אשר הוטל עליו מטעם המשרד לפעול כראש הנציגות בחוץ-לארץ. .28שכר דירה – שכר הדירה המשולם בפועל על-ידי העובד במקום ההעסקה ,בכפוף לחוזה שכירות על שמו ,כשהוא לא כולל הוצאות נלוות."}, {"p": 208, "t": ".29שנת שירות – כל תקופה של שנה שלמה החל מיום תחילת השירות בחוץ-לארץ בהתאם לכתב המינוי או החל מיום התחלת תשלום משכורת חוץ-לארץ ,לפי התאריך המוקדם יותר. .30שעות \"שהייה\" או \"מנוחה\"– שעות בהן עובד אית\"ן אבטחה מבצע משימות צמודות לישות המאובטחת בנציגויות ישראל בחוץ לארץ בבית הישות המאובטחת ומעבר לשעות העבודה בנציגויות."}, {"p": 208, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 209, "t": ".31תושבות – תושב ישראל הוא מי שמוכר ככזה על-ידי המוסד לביטוח לאומי. שליחים – הגדרות ומילון מונחים .1בני משפחה נלווים – בן/בת זוג ,ילדים והורים שהמשרד אישר הצטרפותם לשליחות ושוהים עם העובד בחו\"ל."}, {"p": 209, "t": ".2דירת שרד – דירת מגורים ייצוגית של נושא משרה ציבורית .הדירה שייכת למדינה או למוסד המעסיקים את נושא המשרה והם מממנים את העלויות הקשורות להחזקתה. .3חברת השירותים – חברה בינלאומית המספקת שירותי מידע לבניית מנגנוני שכר בחו\"ל, עימה תתקשר הממשלה .כיום חברת השירותים היא חברת .ECA International .4חופשה חסומה – חשבון חופשת המנוחה של העובד ,המועסק בחוץ-לארץ ערב צאתו"}, {"p": 209, "t": "לחוץ-לארץ ,נחסם בעת יציאתו לשליחות .כמפורט בתקש\"יר: https://archive.csc.gov.il/Takshir/Pages/chap.aspx?Link=33140&amp;searchParam=33.140#33.140 .5חופשת ארץ – החופשה שנצברה בישראל טרם יציאתו לשליחות בחוץ-לארץ."}, {"p": 209, "t": ".6חופשת חוץ-לארץ -עם צאתו של השליח לחוץ-לארץ ,יתנהל חשבון מיוחד ונפרד של חופשת המנוחה לה הוא זכאי בתקופת שירותו בחוץ-לארץ ,כמפורט בתקש\"יר: https://archive.csc.gov.il/Takshir/Pages/chap.aspx?Link=33141&amp;searchParam=33.141#33.141 .7חינוך עברי משלים – מקצועות לימוד עבריים/ישראליים שאינם נלמדים בבתי הספר במקומות השירות בחו\"ל .לדוגמא :יהדות ,הבעה ,לשון ,אזרחות ,מורשת ,ספרות עברית"}, {"p": 209, "t": "וכיו\"ב. .8ידועים בציבור – שליח ובן/בת זוגו לחיים ,אשר הוכרו ע\"י ביטוח לאומי לעניין זה. .9ילד הסמוך לשולחן השליח – ילד מעל גיל  18הסמוך לשולחנו בחוץ-לארץ ,בתנאי שהוכח על-פי תעודה רפואית המאושרת על ידי לשכת הבריאות המחוזית של משרד הבריאות בארץ ,כי הילד אינו מסוגל לעבוד באופן תמידי מטעמי בריאות."}, {"p": 209, "t": ".10ילד השליח – ילד עד גיל .18 .11ילד השליח מעל גיל  – 18ילד שמלאו לו  18וטרם מלאו לו  19שנים וזאת בתנאי שילדו טרם סיים את לימודיו בכיתה י\"ב בארץ השירות ו/או ילד שנדחה גיוסו לצה\"ל וזאת כנגד אישור דחיית שירות."}, {"p": 209, "t": ".12ילדי בן זוג שליח מנישואיו הקודמים – שליח ,אשר לבן זוגו ילדים מנישואיו הקודמים ואשר לפי פסק דין מוסמך הילדים נמצאים בחזקתו והוא לא מקבל בגינם דמי מזונות ,או כל סכום אחר שהוא זכאי לקבל להחזקתם ,והילדים שוהים יחד עם השליח ומשפחתו בחוץ-לארץ."}, {"p": 209, "t": ".13ילדי בן זוג שליח מנישואיו הקודמים והם יתומים – שליח ,אשר לבן זוגו ילדים יתומים מנישואיו הקודמים ואשר עבורם הוא מקבל תגמולים ממשרד הביטחון ,או קצבה בין מכוח החוק ובין מקרן פנסיה אחרת ,והילדים נמצאים בחזקתו והוא אחראי לפרנסתם."}, {"p": 209, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 210, "t": ".14ילדי שליח אלמן – ילדי שליח הנמצאים בחזקתו על-פי פסק דין מוסמך. .15ילדי שליח גרוש – ילדי שליח הנמצאים בחזקתו על-פי פסק דין מוסמך ,או ילדי שליח גרוש ,אשר בגינם חייב לשלם מזונות לאשתו מנישואיו הקודמים וילדיו נמצאים בחזקתה על-פי פסק דין מוסמך ושוהים עמו בחוץ-לארץ."}, {"p": 210, "t": ".16מדד – מדד המחירים לצרכן המתפרסם על ידי הלשכה המרכזית לסטטיסטיקה. .17המדד החדש – מדד חודש דצמבר של השנה שקדמה לחודש העדכון של הסכום הבסיסי במודל שכר שליחים. .18המדד הקודם – מדד חודש דצמבר של השנה שקדמה לחודש העדכון הקודם של הסכום הבסיסי במודל שכר שליחים."}, {"p": 210, "t": ".19מועד עדכון השכר – מועד עדכון השכר יהיה ב 1 -בינואר של כל שנה. .20מנגנון השכר הישן – כללי תשלום השכר של שליחים בחו\"ל עד ליום .31.12.2017 .21משכורת קובעת – כמוגדר בחוק שירות המדינה (גמלאות) [נוסח משולב] ,התש\"ל.1970- .22מצבו המשפחתי של שליח – בן /בת זוגו וילדיו עד גיל .18 .23נספח הגנה – שליח מטעם משרד הביטחון (איש צבא או עובד מדינה) העומד בראש נספחות."}, {"p": 210, "t": ".24ספיגת מטבע –קניית מטבע מקומי של המשרד מהשליח. .25עובד קיים – שליח שהיה בשליחות בחו\"ל ביום  31.12.2017וכל עוד הוא משרת באותו המקום (ברצף). .26ענבל – חברה לביטוח בע\"מ ,מנהלת הקרן הפנימית לביטוחי הממשלה .אתר הבית של חברת ענבלhttps://www.inbal.co.il:"}, {"p": 210, "t": ".27פסק דין מוסמך – פסק דין של בית דין מוסמך ,או הסכם בין הצדדים ,שנחתם לפחות 12 חודשים לפני תאריך יציאת השליח או בן/בת זוגו לשליחות בחוץ-לארץ .לא יובאו בחשבון הסכמים ,המשנים פסקי דין ,או הסכמים קודמים ,שנחתמו במועד מאוחר מ 12-חודשים קודם ליציאת השליח או בן/בת זוגו לחוץ-לארץ ,או במהלך תקופת השירות בחוץ-לארץ."}, {"p": 210, "t": ".28קצובת דיור בסיסית  -סכום ההשתתפות בשכר הדירה שנקבע למדינת השירות לפי דרגה והסטאטוס המשפחתי של השליח. .29קצובת דיור מרבית – סכום ההשתתפות בשכר דירה לו זכאי העובד בהתאם להוראות פרק זה ועל-פי העלות בפועל."}, {"p": 210, "t": ".30קרן הריפוי – קרן הדדית לעובדי המשרדים הממשלתיים ועובדי המדינה המשרתים בחוץ-לארץ ,המקנה ביטוח רפואי לשליחים ובני משפחת הנלווים אליהם לחוץ-לארץ .סל הביטוח של הקרן הינו הסל שבחוק ביטוח בריאות ממלכתי ,התשנ\"ד.1994- https://www.health.gov.il/Subjects/UninsuredRights/HealthInsuranceLaw/Pages/default.aspx .31קרן פנסיה צוברת ותיקה – קופת גמל לקצבה שאינה קופת ביטוח שאושרה לראשונה לפני"}, {"p": 210, "t": "יום ה 1-בינואר .1995 חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 211, "t": ".32קרן פנסיה צוברת חדשה – קופת גמל לקצבה שאינה קופת ביטוח שאושרה לראשונה אחרי יום ה 1-בינואר .1995 .33רופא אמון – רופא ברמה מקצועית גבוהה שנבחר בארץ על ידי הנהלת קרן הריפוי ,ובחוץ- לארץ נבחר על ידי הנציגויות .הרופא מטפל בכל העובדים בנציגות ובני משפחותיהם ,ובכל אותם מקרים הדורשים טיפול רפואי ונמצאים בתחום התמחותו הרפואית .רופא האמון משמש גם יועץ רפואי להנהלת קרן הריפוי."}, {"p": 211, "t": ".34רכב שרד – רכב בבעלות המשרד העומד לרשות העובד דרך קבע. .35שליח – עובד מדינה שנשלח על ידי המדינה לחוץ-לארץ למלא תפקיד מטעמה ,וערב מינויו היה עובד מדינה ,או שמונה בהתאם לפסקה  11.962בתקשי\"ר ,והוא דיפלומט או ששכרו ותנאי העסקתי הוקבלו לאלה של דיפלומט ,על ידי הוועדה הבין משרדית."}, {"p": 211, "t": ".36שכר ישראלי – שכר משולב ורכיבי שכר המרכיבים את המשכורת הקובעת בארץ ,ואשר משולמים לעובד בארץ בהתאם לדירוגו ולדרגתו של העובד בארץ .מקצת מהשליחים באים מחוץ לשירות המדינה ומועסקים על פי חוזה מיוחד .לגבי עובדים אלה הדרוג והדרגה של החלק הישראלי של המשכורת מקבילים לדרוג ולדרגה של המשרה בחוץ- לארץ לפי לוח התאומים המופיע בסעיף  3.3בהוראה ,או ככל שיקבע אחרת על ידי נציבות"}, {"p": 211, "t": "שירות המדינה. .37שכר נטו חדש – שכרו של עובד קיים בהתאם להחלטות הוועדה הבין משרדית ,בניכוי מס הכנסה ,דמי ביטוח לאומי וביטוח בריאות .לעניין סעיף זה ,שכרו של עובד קיים לא יכלול קצובת שכ\"ד ,דמי ייצוג לסוגיו ,השתתפות בהוצאות חינוך והחזרי הוצאות אחרים."}, {"p": 211, "t": ".38שכר נטו ישן – שכרו של עובד קיים לפי מנגנון השכר הישן עבור חודש דצמבר  ,2017בניכוי מס הכנסה ,דמי ביטוח לאומי וביטוח בריאות ,על פי כללי מס הכנסה (בעלי הכנסה מעבודה בחוץ-לארץ) ,תשמ\"ב( 1982-להלן\" :כללי המס\") ,כנוסחם ביום  .1.1.2017לעניין סעיף זה ,שכרו של עובד קיים לא יכלול קצובת שכ\"ד ,דמי ייצוג לסוגיו ,השתתפות בהוצאות חינוך והחזרי הוצאות אחרים."}, {"p": 211, "t": ".39שליח המשרת בגפו  -שליח המשרת בחוץ-לארץ ,אשר לו לפחות ילד אחד ו/או בן זוג (נשוי או ידוע בציבור) שנשאר בארץ. .40שערי חליפין – שערי החליפין המדווחים מדי חודש. .41תשלום דמי מניה – תשלום חד פעמי המשולם עם הרישום למוסד הלימודים מגן חובה עד לכיתה י\"ב."}, {"p": 211, "t": "חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 212, "t": "רשימות _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________"}, {"p": 212, "t": "_____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________"}, {"p": 212, "t": "_____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________"}, {"p": 212, "t": "_____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________"}, {"p": 212, "t": "_____________________________________________________________________ _____________________________________________________________________ חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}, {"p": 213, "t": "_____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________"}, {"p": 213, "t": "_____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________"}, {"p": 213, "t": "_____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________"}, {"p": 213, "t": "_____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________ _____________________________________________________________________"}, {"p": 213, "t": "_____________________________________________________________________ חוברת לשליח מהדורה  - 2022כתיבה ועריכה :קמי אוקונסקי -ראש היחידה למשא\"נ ומינהל בחו\"ל"}];
